    #[test]
    fn exact_edge_split_updates_affine_pcurves_and_wire_topology() {
        let mut builder = ArenaModelBuilder::new();
        let points = [p(0, 0, 0), p(2, 0, 0), p(2, 2, 0), p(0, 2, 0)];
        let vertices = points
            .iter()
            .cloned()
            .map(|point| builder.vertex((point).into()))
            .collect::<Result<Vec<_>, _>>()
            .unwrap();
        let mut uses = Vec::new();
        for index in 0..4 {
            let next = (index + 1) % 4;
            let curve = builder
                .curve(Curve3::line(points[index].clone(), points[next].clone()).unwrap())
                .unwrap();
            let edge = builder
                .edge(
                    vertices[index],
                    vertices[next],
                    curve,
                    (ParameterDomain::unit()).into(),
                )
                .unwrap();
            let pcurve = builder
                .pcurve(Pcurve::new(Curve2::from(
                    LineSeg2::try_new(
                        CurvePoint2::new(points[index].x.clone(), points[index].y.clone()),
                        CurvePoint2::new(points[next].x.clone(), points[next].y.clone()),
                    )
                    .unwrap(),
                )))
                .unwrap();
            uses.push(
                builder
                    .edge_use(
                        edge,
                        Direction::Forward,
                        pcurve,
                        ParameterCorrespondence::identity(),
                    )
                    .unwrap(),
            );
        }
        let wire = builder.wire(uses).unwrap();
        let surface = builder
            .surface(Surface::plane(Point3::origin(), Vector3::x(), Vector3::y()).unwrap())
            .unwrap();
        let face = builder
            .face(surface, Orientation::Forward, wire, Vec::new())
            .unwrap();
        builder.shell(vec![face]).unwrap();
        let model = builder.finish().unwrap();

        let half = (Real::one() / r(2)).unwrap();
        let (split_model, split) = model
            .split_edge(EdgeId::from_index(0).unwrap(), (half.clone()).into())
            .unwrap();
        assert_eq!(split.vertex.index(), 4);
        assert_eq!(split.first.index(), 0);
        assert_eq!(split.second.index(), 4);
        assert_eq!(split.edge_uses.len(), 1);
        assert_eq!(split_model.wire(wire).unwrap().edge_uses().len(), 5);
        assert_eq!(
            compare_reals(
                &split_model
                    .vertex(split.vertex)
                    .unwrap()
                    .represented_point()
                    .unwrap()
                    .x,
                &Real::one(),
                crate::STRICT_PREDICATES
            )
            .value(),
            Some(std::cmp::Ordering::Equal)
        );
        let (first_use, second_use) = split.edge_uses[0];
        assert_eq!(
            compare_reals(
                split_model
                    .edge_parameter_at(first_use, &crate::Parameter::from_real(Real::one()))
                    .unwrap()
                    .try_real()
                    .unwrap(),
                &half,
                crate::STRICT_PREDICATES
            )
            .value(),
            Some(std::cmp::Ordering::Equal)
        );
        assert_eq!(
            compare_reals(
                split_model
                    .edge_parameter_at(second_use, &crate::Parameter::from_real(Real::zero()))
                    .unwrap()
                    .try_real()
                    .unwrap(),
                &half,
                crate::STRICT_PREDICATES
            )
            .value(),
            Some(std::cmp::Ordering::Equal)
        );
        assert_eq!(
            compare_reals(
                &split_model.face_area(face).unwrap(),
                &r(4),
                crate::STRICT_PREDICATES
            )
            .value(),
            Some(std::cmp::Ordering::Equal)
        );
        crate::ImportedModel::from_json(
            &split_model.to_json().unwrap(),
            &crate::ArchiveLimits::default(),
        )
        .unwrap()
        .validate()
        .unwrap();

        let reflected = model
            .transformed(&crate::Matrix4::affine_nonuniform_scale([
                -Real::one(),
                Real::one(),
                Real::one(),
            ]))
            .unwrap();
        assert_eq!(
            reflected
                .edge_use(EdgeUseId::from_index(0).unwrap())
                .unwrap()
                .direction(),
            Direction::Reversed
        );
        let (reversed_split, reversed_ids) = reflected
            .split_edge(EdgeId::from_index(0).unwrap(), (half).into())
            .unwrap();
        assert_eq!(reversed_split.wire(wire).unwrap().edge_uses().len(), 5);
        assert_eq!(
            reversed_split
                .edge_use(reversed_ids.edge_uses[0].0)
                .unwrap()
                .edge(),
            reversed_ids.second
        );
        assert_eq!(
            reversed_split
                .edge_use(reversed_ids.edge_uses[0].1)
                .unwrap()
                .edge(),
            reversed_ids.first
        );
        assert_eq!(
            compare_reals(
                &reversed_split.face_area(face).unwrap(),
                &r(4),
                crate::STRICT_PREDICATES
            )
            .value(),
            Some(std::cmp::Ordering::Equal)
        );
    }

