            (p(0, 0, 2), SolidPointLocation::Outside),
        ] {
            assert_eq!(model.classify_point(solid, &point).unwrap(), expected);
        }
        let reflected = model
            .transformed(&crate::Matrix4::affine_nonuniform_scale([
                -Real::one(),
                Real::one(),
                Real::one(),
            ]))
            .unwrap();
        assert_eq!(
            reflected.classify_point(solid, &p(-4, 0, 2)).unwrap(),
