    #[test]
    fn curved_sweep_retains_exact_fixed_frame_path_and_certificate() {
        let profile = [p2(0, 0), p2(2, 0), p2(2, 2), p2(0, 2)];
        let path = Curve3::rational_bezier(
            vec![p(0, 0, 0), p(1, 0, 1), p(0, 0, 4)],
            vec![Real::one(), r(2), r(3)],
        )
        .unwrap();
        let (model, solid) = sweep_curve(&profile, Vector3::x(), Vector3::y(), path).unwrap();
        assert_eq!(
            model.counts(),
            ModelCounts {
                vertices: 8,
                curves: 12,
                pcurves: 24,
                surfaces: 6,
                edges: 12,
                edge_uses: 24,
                wires: 6,
                faces: 6,
                shells: 1,
                solids: 1,
            }
        );
        assert_eq!(
            model
                .faces()
                .filter(|(_, face)| {
                    model.surface(face.surface()).unwrap().kind()
                        == crate::SurfaceKind::RationalBezier
                })
                .count(),
            4
        );
        assert_eq!(
            compare_reals(
                &model.solid_volume(solid).unwrap(),
                &r(16),
                crate::STRICT_PREDICATES
            )
            .value(),
            Some(std::cmp::Ordering::Equal)
        );
        let half = (Real::one() / r(2)).unwrap();
        for (point, expected) in [
            (
                Point3::new(r(1) + &half, Real::one(), r(2)),
                SolidPointLocation::Inside,
            ),
            (
                Point3::new(half.clone(), Real::one(), r(2)),
                SolidPointLocation::Boundary,
            ),
            (p(3, 1, 2), SolidPointLocation::Outside),
            (p(1, 1, 0), SolidPointLocation::Boundary),
        ] {
            assert_eq!(model.classify_point(solid, &point).unwrap(), expected);
        }

        let scaled = model
            .transformed(&crate::Matrix4::affine_nonuniform_scale([r(2), r(3), r(4)]))
            .unwrap();
        assert_eq!(
            compare_reals(
                &scaled.solid_volume(solid).unwrap(),
                &r(384),
                crate::STRICT_PREDICATES
            )
            .value(),
            Some(std::cmp::Ordering::Equal)
        );
        assert_eq!(
            scaled
                .classify_point(solid, &Point3::new(r(3), r(3), r(8)),)
                .unwrap(),
            SolidPointLocation::Inside
        );
        let reflected = scaled
            .transformed(&crate::Matrix4::affine_nonuniform_scale([
                -Real::one(),
                Real::one(),
                Real::one(),
            ]))
            .unwrap();
        assert_eq!(
            compare_reals(
                &reflected.solid_volume(solid).unwrap(),
                &r(384),
                crate::STRICT_PREDICATES
            )
            .value(),
            Some(std::cmp::Ordering::Equal)
        );
        let json = reflected.to_json().unwrap();
        let rebuilt = crate::ImportedModel::from_json(&json, &crate::ArchiveLimits::default())
            .unwrap()
            .validate()
            .unwrap();
        assert_eq!(rebuilt.to_json().unwrap(), json);
        assert_eq!(
            compare_reals(
                &rebuilt.solid_volume(solid).unwrap(),
                &r(384),
                crate::STRICT_PREDICATES
            )
            .value(),
            Some(std::cmp::Ordering::Equal)
        );

        // z = 2t + 2t² is not affine but rises at every parameter, so its
        // sections are the same profile and the volume is unchanged.
        let nonlinear_progress = Curve3::rational_bezier(
            vec![p(0, 0, 0), p(1, 0, 1), p(0, 0, 4)],
            vec![Real::one(), Real::one(), Real::one()],
        )
        .unwrap();
        let (monotone, monotone_solid) =
            sweep_curve(&profile, Vector3::x(), Vector3::y(), nonlinear_progress).unwrap();
        assert_eq!(
            compare_reals(
                &monotone.solid_volume(monotone_solid).unwrap(),
                &r(16),
                crate::STRICT_PREDICATES
            )
            .value(),
            Some(std::cmp::Ordering::Equal)
        );
        // z = 3/2 is reached at t = 1/2, where the path is at x = 1/2.
        let level = (r(3) / r(2)).unwrap();
        for (x, expected) in [
            (r(1) + &half, SolidPointLocation::Inside),
            (half.clone(), SolidPointLocation::Boundary),
            ((r(5) / r(2)).unwrap(), SolidPointLocation::Boundary),
            ((r(13) / r(5)).unwrap(), SolidPointLocation::Outside),
            ((r(2) / r(5)).unwrap(), SolidPointLocation::Outside),
        ] {
            assert_eq!(
                monotone
                    .classify_point(monotone_solid, &Point3::new(x, Real::one(), level.clone()))
                    .unwrap(),
                expected
            );
        }
        // z = 12t - 8t² ends above its start but descends after t = 3/4.
        let backtracking = Curve3::rational_bezier(
            vec![p(0, 0, 0), p(1, 0, 6), p(0, 0, 4)],
            vec![Real::one(), Real::one(), Real::one()],
        )
        .unwrap();
        assert_eq!(
            sweep_curve(&profile, Vector3::x(), Vector3::y(), backtracking).unwrap_err(),
            ConstructionError::NonMonotoneSweepPath
        );
        assert_eq!(
            sweep_curve(
                &profile,
                Vector3::x(),
                Vector3::y(),
                Curve3::line(p(0, 0, 0), p(0, 0, 4)).unwrap(),
            )
            .unwrap_err(),
            ConstructionError::UnsupportedSweepPath
        );
    }

    #[test]
    fn straight_sweeps_along_degree_elevated_paths_keep_exact_queries() {
        // Straight affine paths written with elevated degree make every side
        // a planar tensor patch whose chart is not the canonical plane frame.
        let profile = [p2(0, 0), p2(2, 0), p2(2, 2), p2(0, 2)];
        let third = (Real::one() / r(3)).unwrap();
        let two_thirds = (r(2) / r(3)).unwrap();
        let half = (Real::one() / r(2)).unwrap();
        for (controls, slope) in [
            (vec![p(0, 0, 0), p(0, 0, 2), p(0, 0, 4)], Real::zero()),
            (
                vec![
                    p(0, 0, 0),
                    Point3::new(Real::zero(), Real::zero(), r(4) * &third),
                    Point3::new(Real::zero(), Real::zero(), r(4) * &two_thirds),
                    p(0, 0, 4),
                ],
                Real::zero(),
            ),
            (vec![p(0, 0, 0), p(1, 0, 2), p(2, 0, 4)], half.clone()),
        ] {
            let count = controls.len();
            let path = Curve3::rational_bezier(controls, vec![Real::one(); count]).unwrap();
            let (model, solid) = sweep_curve(&profile, Vector3::x(), Vector3::y(), path).unwrap();
            let rebuilt = crate::ImportedModel::from_json(
                &model.to_json().unwrap(),
                &crate::ArchiveLimits::default(),
            )
            .unwrap()
            .validate()
            .unwrap();
            for model in [&model, &rebuilt] {
                assert_eq!(
                    compare_reals(
                        &model.solid_volume(solid).unwrap(),
                        &r(16),
                        crate::STRICT_PREDICATES
                    )
                    .value(),
                    Some(std::cmp::Ordering::Equal)
                );
                // The section at z = 2 starts at x = 2 * slope.
                let start = r(2) * &slope;
                for (x, expected) in [
                    (&start + Real::one(), SolidPointLocation::Inside),
                    (start.clone(), SolidPointLocation::Boundary),
                    (&start + r(2), SolidPointLocation::Boundary),
                    (&start - &half, SolidPointLocation::Outside),
                    (&start + r(3), SolidPointLocation::Outside),
                ] {
                    assert_eq!(
                        model
                            .classify_point(solid, &Point3::new(x, Real::one(), r(2)))
                            .unwrap(),
                        expected
                    );
                }
            }
        }
    }

