    #[test]
    fn prism_rejects_small_and_self_intersecting_profiles() {
        assert_eq!(
            extrude(&[p2(0, 0), p2(1, 0)], Real::zero(), Real::one()).unwrap_err(),
            ConstructionError::ProfileTooSmall
        );
