    #[test]
    fn exact_solid_point_classification_covers_interior_exterior_and_boundary() {
        let (box_model, box_solid) = cuboid(p(0, 0, 0), p(4, 6, 8)).unwrap();
        assert_eq!(
            box_model.classify_point(box_solid, &p(1, 2, 3)).unwrap(),
            SolidPointLocation::Inside
        );
        assert_eq!(
            box_model.classify_point(box_solid, &p(5, 2, 3)).unwrap(),
            SolidPointLocation::Outside
        );
        for boundary in [p(0, 2, 3), p(0, 0, 3), p(0, 0, 0)] {
            assert_eq!(
                box_model.classify_point(box_solid, &boundary).unwrap(),
                SolidPointLocation::Boundary
            );
        }

        let profile = [p2(0, 0), p2(8, 0), p2(8, 2), p2(2, 2), p2(2, 8), p2(0, 8)];
        let (concave, solid) = extrude(&profile, Real::zero(), Real::from(3)).unwrap();
        assert_eq!(
            concave.classify_point(solid, &p(1, 6, 1)).unwrap(),
            SolidPointLocation::Inside
        );
        assert_eq!(
            concave.classify_point(solid, &p(6, 6, 1)).unwrap(),
            SolidPointLocation::Outside
        );
    }
    #[test]
    fn planar_path_nesting_preserves_generated_offset_endpoints() {
        let point = |x, y| CurvePoint2::new(r(x), r(y));
        let line = |first, second| Curve2::from(LineSeg2::try_new(first, second).unwrap());
        let cap = CurvePath2::try_new(vec![
            hypercurve::QuadraticBezier2::new(point(-1, 1), point(0, -1), point(1, 1)).into(),
            line(point(1, 1), point(-1, 1)),
        ])
        .unwrap();
        let region =
            CurveRegion2::try_from_boundary_paths(&[cap], hypercurve::FillRule::EvenOdd).unwrap();
        let offset = region
            .offset(
                (Real::one() / r(4)).unwrap(),
                &hypercurve::OffsetCornerStyle2::Round,
            )
            .unwrap();
        let mut paths = offset
            .boundary_paths()
            .expect("the exact offset retains its boundary paths");
        assert_eq!(paths.len(), 1);
        let mut curves = paths.pop().unwrap().curves().to_vec();
        let retained_start = curves
            .iter()
            .position(|curve| curve.start().coordinates().is_none())
            .expect("the offset has a generated endpoint");
        curves.rotate_left(retained_start);
        let hole = CurvePath2::try_new(curves).unwrap();
        assert!(hole.start().coordinates().is_none());
        let rectangle = |low, high| {
            let points = [
                point(low, low),
                point(high, low),
                point(high, high),
                point(low, high),
            ];
            CurvePath2::try_new(
                (0..4)
                    .map(|i| line(points[i].clone(), points[(i + 1) % 4].clone()))
                    .collect(),
            )
            .unwrap()
        };
        assert!(
            validate_planar_path_nesting(&rectangle(-3, 3), std::slice::from_ref(&hole)).is_ok()
        );
        assert!(matches!(
            validate_planar_path_nesting(&rectangle(5, 8), &[hole]),
            Err(ConstructionError::HoleOutside)
        ));
    }
}

