#[derive(Clone, Debug)]
enum SurfaceIntersectionPcurveMapping {
    Unsupported,
    RetainedCurve {
        curve: Curve2,
    },
    PlaneProjection {
        spatial: Curve3,
        origin: Point3,
        u: Vector3,
        v: Vector3,
    },
    LinearPlaneSection {
        profile: Curve3,
        plane_origin: Point3,
        plane_normal: Vector3,
        denominator: Real,
        profile_axis: TensorAxis,
        coefficient_scale: Real,
        coefficient_offset: Real,
    },
    TensorIsoV {
        constant: Real,
    },
    TensorIsoU {
        constant: Real,
    },
}

#[derive(Clone, Copy, Debug)]
enum TensorAxis {
    U,
    V,
}

impl SurfaceIntersectionCurve {
    /// Moves one iso pcurve into an equivalent periodic surface chart. The
    /// caller proves that each nonzero displacement is a whole surface period.
    pub(crate) fn translated_iso_pcurve(
        &self,
        operand: SurfaceIntersectionOperand,
        u: &Real,
        v: &Real,
    ) -> GeometryResult<Self> {
        let mut result = self.clone();
        let pcurve = match operand {
            SurfaceIntersectionOperand::First => &mut result.first_pcurve,
            SurfaceIntersectionOperand::Second => &mut result.second_pcurve,
        };
        match &mut pcurve.mapping {
            SurfaceIntersectionPcurveMapping::TensorIsoU { constant } => {
                *constant += u;
                pcurve.source_offset += v;
            }
            SurfaceIntersectionPcurveMapping::TensorIsoV { constant } => {
                *constant += v;
                pcurve.source_offset += u;
            }
            _ => return Err(GeometryError::UnsupportedIntersection),
        }
        Ok(result)
    }

    pub(crate) fn new(
        curve: Curve3,
        first_pcurve: SurfaceIntersectionPcurve,
        second_pcurve: SurfaceIntersectionPcurve,
    ) -> Self {
        Self {
            curve,
            first_pcurve,
            second_pcurve,
            image_certificates: [true, true],
            polynomial_contact_exponent: None,
            first_boundary_contacts: SurfaceIntersectionBoundaryContacts::default(),
            second_boundary_contacts: SurfaceIntersectionBoundaryContacts::default(),
        }
    }

    pub(crate) fn on_plane(curve: Curve3, surface: &Surface) -> GeometryResult<Self> {
        Self::on_coincident_planes(curve, surface, surface)
    }

    /// Retains both charts after the caller proves coincident planes and that
    /// the curve lies on their common support.
    pub(crate) fn on_coincident_planes(
        curve: Curve3,
        first: &Surface,
        second: &Surface,
    ) -> GeometryResult<Self> {
        let (SurfaceGeometry::Plane(first), SurfaceGeometry::Plane(second)) =
            (&first.data.geometry, &second.data.geometry)
        else {
            return Err(GeometryError::UnsupportedIntersection);
        };
        Ok(Self::new(
            curve.clone(),
            SurfaceIntersectionPcurve::plane_projection(curve.clone(), first),
            SurfaceIntersectionPcurve::plane_projection(curve, second),
        ))
    }

    pub(crate) fn on_single_plane(
        curve: Curve3,
        surface: &Surface,
        operand: SurfaceIntersectionOperand,
    ) -> GeometryResult<Self> {
        let SurfaceGeometry::Plane(plane) = &surface.data.geometry else {
            return Err(GeometryError::UnsupportedIntersection);
        };
        let plane_pcurve = SurfaceIntersectionPcurve::plane_projection(curve.clone(), plane);
        let unavailable = SurfaceIntersectionPcurve::unsupported(curve.domain().clone());
        let mut intersection = match operand {
            SurfaceIntersectionOperand::First => Self::new(curve, plane_pcurve, unavailable),
            SurfaceIntersectionOperand::Second => Self::new(curve, unavailable, plane_pcurve),
        };
        intersection.image_certificates = match operand {
            SurfaceIntersectionOperand::First => [true, false],
            SurfaceIntersectionOperand::Second => [false, true],
        };
        Ok(intersection)
    }

    #[cfg(test)]
    pub(crate) fn from_exact_pcurves(
        curve: Curve3,
        first_pcurve: Curve2,
        second_pcurve: Curve2,
    ) -> GeometryResult<Self> {
        let mut intersection = Self::new(
            curve,
            SurfaceIntersectionPcurve::retained_curve(first_pcurve)?,
            SurfaceIntersectionPcurve::retained_curve(second_pcurve)?,
        );
        intersection.image_certificates = [false, false];
        Ok(intersection)
    }

    pub(crate) fn from_certified_exact_pcurves(
        curve: Curve3,
        first_pcurve: Curve2,
        second_pcurve: Curve2,
    ) -> GeometryResult<Self> {
        Ok(Self::new(
            curve,
            SurfaceIntersectionPcurve::retained_curve(first_pcurve)?,
            SurfaceIntersectionPcurve::retained_curve(second_pcurve)?,
        ))
    }

    pub(crate) fn from_iso_v_pcurves(
        curve: Curve3,
        first_constant: Real,
        second_constant: Real,
    ) -> Self {
        let domain = curve.domain().clone();
        Self::new(
            curve,
            SurfaceIntersectionPcurve::tensor_iso_v(domain.clone(), first_constant),
            SurfaceIntersectionPcurve::tensor_iso_v(domain, second_constant),
        )
    }

    /// Retains a validated edge's affine iso-parameter pcurve on two surfaces
    /// already proved to have the same complete parameterization.
    pub(crate) fn from_certified_iso_boundary(
        curve: Curve3,
        pcurve: &Pcurve,
        edge_scale: &Real,
        edge_offset: &Real,
    ) -> GeometryResult<Option<Self>> {
        let Some(line) = pcurve.line_segment() else {
            return Ok(None);
        };
        let dx = line.end().x() - line.start().x();
        let dy = line.end().y() - line.start().y();
        let (constant, axis, delta, start) =
            if decided_order(compare_reals(&dx, &Real::zero(), crate::STRICT_PREDICATES))?
                == Ordering::Equal
            {
                (
                    line.start().x().clone(),
                    TensorAxis::U,
                    dy,
                    line.start().y(),
                )
            } else if decided_order(compare_reals(&dy, &Real::zero(), crate::STRICT_PREDICATES))?
                == Ordering::Equal
            {
                (
                    line.start().y().clone(),
                    TensorAxis::V,
                    dx,
                    line.start().x(),
                )
            } else {
                return Ok(None);
            };
        let scale = (delta / edge_scale).map_err(GeometryError::Numeric)?;
        let offset = start - &scale * edge_offset;
        let pcurve = SurfaceIntersectionPcurve::tensor_iso(
            curve.domain().clone(),
            constant,
            axis,
            scale,
            offset,
        );
        Ok(Some(Self::new(curve, pcurve.clone(), pcurve)))
    }

    fn swapped(mut self) -> Self {
        std::mem::swap(&mut self.first_pcurve, &mut self.second_pcurve);
        self.image_certificates.swap(0, 1);
        std::mem::swap(
            &mut self.first_boundary_contacts,
            &mut self.second_boundary_contacts,
        );
        self
    }

    pub(crate) fn with_boundary_contacts(
        mut self,
        operand: SurfaceIntersectionOperand,
        start: Vec<SurfaceIntersectionBoundaryContact>,
        end: Vec<SurfaceIntersectionBoundaryContact>,
    ) -> Self {
        let contacts = match operand {
            SurfaceIntersectionOperand::First => &mut self.first_boundary_contacts,
            SurfaceIntersectionOperand::Second => &mut self.second_boundary_contacts,
        };
        contacts.start = start;
        contacts.end = end;
        self
    }

    /// Returns the exact model-space intersection curve.
    pub const fn curve(&self) -> &Curve3 {
        &self.curve
    }

    /// Returns the exact pcurve on the first surface operand.
    pub const fn first_pcurve(&self) -> &SurfaceIntersectionPcurve {
        &self.first_pcurve
    }

    /// Returns the exact pcurve on the second surface operand.
    pub const fn second_pcurve(&self) -> &SurfaceIntersectionPcurve {
        &self.second_pcurve
    }

    /// Returns the retained pcurve for one surface operand.
    pub const fn pcurve(&self, operand: SurfaceIntersectionOperand) -> &SurfaceIntersectionPcurve {
        match operand {
            SurfaceIntersectionOperand::First => &self.first_pcurve,
            SurfaceIntersectionOperand::Second => &self.second_pcurve,
        }
    }

    pub(crate) const fn has_image_certificate(&self, operand: SurfaceIntersectionOperand) -> bool {
        match operand {
            SurfaceIntersectionOperand::First => self.image_certificates[0],
            SurfaceIntersectionOperand::Second => self.image_certificates[1],
        }
    }

    pub(crate) fn start_boundary_contacts(
        &self,
        operand: SurfaceIntersectionOperand,
    ) -> &[SurfaceIntersectionBoundaryContact] {
        match operand {
            SurfaceIntersectionOperand::First => &self.first_boundary_contacts.start,
            SurfaceIntersectionOperand::Second => &self.second_boundary_contacts.start,
        }
    }

    pub(crate) fn end_boundary_contacts(
        &self,
        operand: SurfaceIntersectionOperand,
    ) -> &[SurfaceIntersectionBoundaryContact] {
        match operand {
            SurfaceIntersectionOperand::First => &self.first_boundary_contacts.end,
            SurfaceIntersectionOperand::Second => &self.second_boundary_contacts.end,
        }
    }

    /// Restricts a retained planar section in its original common parameter
    /// chart, including selected endpoints. No coordinate reconstruction or
    /// unit-interval rebasing occurs. Other spatial families remain typed.
    pub fn restrict_source(&self, range: ParameterRange) -> GeometryResult<Self> {
        crate::context::strict(|| {
            let curve = self.curve.restrict_source(range.clone())?;
            let start = range.start().compare(self.curve.domain().start())? == Ordering::Equal;
            let end = range.end().compare(self.curve.domain().end())? == Ordering::Equal;
            let contacts = |source: &SurfaceIntersectionBoundaryContacts| {
                SurfaceIntersectionBoundaryContacts {
                    start: if start {
                        source.start.clone()
                    } else {
                        Vec::new()
                    },
                    end: if end { source.end.clone() } else { Vec::new() },
                }
            };
            Ok(Self {
                curve,
                first_pcurve: self.first_pcurve.subcurve(range.start(), range.end())?,
                second_pcurve: self.second_pcurve.subcurve(range.start(), range.end())?,
                image_certificates: self.image_certificates,
                polynomial_contact_exponent: self.polynomial_contact_exponent,
                first_boundary_contacts: contacts(&self.first_boundary_contacts),
                second_boundary_contacts: contacts(&self.second_boundary_contacts),
            })
        })
    }

    /// Restricts the spatial curve and both exact pcurve mappings to one
    /// increasing represented parameter interval.
    pub fn subcurve(&self, start: &Real, end: &Real) -> GeometryResult<Self> {
        crate::context::strict(|| {
            let curve = self.curve.subcurve(start, end)?;
            let first_pcurve = self.first_pcurve.reparameterized_subcurve(
                start,
                end,
                &curve.domain().represented_domain()?,
            )?;
            let second_pcurve = self.second_pcurve.reparameterized_subcurve(
                start,
                end,
                &curve.domain().represented_domain()?,
            )?;
            let retain_start = decided_order(compare_reals(
                start,
                self.curve.domain().represented_start()?,
                crate::STRICT_PREDICATES,
            ))? == Ordering::Equal;
            let retain_end = decided_order(compare_reals(
                end,
                self.curve.domain().represented_end()?,
                crate::STRICT_PREDICATES,
            ))? == Ordering::Equal;
            Ok(Self {
                curve,
                first_pcurve,
                second_pcurve,
                image_certificates: self.image_certificates,
                polynomial_contact_exponent: self.polynomial_contact_exponent,
                first_boundary_contacts: SurfaceIntersectionBoundaryContacts {
                    start: if retain_start {
                        self.first_boundary_contacts.start.clone()
                    } else {
                        Vec::new()
                    },
                    end: if retain_end {
                        self.first_boundary_contacts.end.clone()
                    } else {
                        Vec::new()
                    },
                },
                second_boundary_contacts: SurfaceIntersectionBoundaryContacts {
                    start: if retain_start {
                        self.second_boundary_contacts.start.clone()
                    } else {
                        Vec::new()
                    },
                    end: if retain_end {
                        self.second_boundary_contacts.end.clone()
                    } else {
                        Vec::new()
                    },
                },
            })
        })
    }

    /// Returns the same exact spatial and two-operand parameter-space images
    /// with one common reversed traversal.
    pub fn reversed(&self) -> GeometryResult<Self> {
        crate::context::strict(|| {
            Ok(Self {
                curve: self.curve.reversed()?,
                first_pcurve: self.first_pcurve.reversed()?,
                second_pcurve: self.second_pcurve.reversed()?,
                image_certificates: self.image_certificates,
                polynomial_contact_exponent: self.polynomial_contact_exponent,
                first_boundary_contacts: SurfaceIntersectionBoundaryContacts {
                    start: self.first_boundary_contacts.end.clone(),
                    end: self.first_boundary_contacts.start.clone(),
                },
                second_boundary_contacts: SurfaceIntersectionBoundaryContacts {
                    start: self.second_boundary_contacts.end.clone(),
                    end: self.second_boundary_contacts.start.clone(),
                },
            })
        })
    }
}

fn orient_affine_surface_pcurve(
    mut curve: Curve2,
    mut scale: Real,
    mut offset: Real,
    target: &ParameterRange,
) -> GeometryResult<MaterializedSurfacePcurve> {
    let (first, last) = curve.parameter_endpoints();
    let mapped_first = Parameter::from_curve(first)?.affine_image(&scale, &offset)?;
    let mapped_last = Parameter::from_curve(last)?.affine_image(&scale, &offset)?;
    if mapped_first.compare(target.end())? == Ordering::Equal
        && mapped_last.compare(target.start())? == Ordering::Equal
    {
        // Authored reversal changes coefficients in a reflected chart;
        // generated and source-restricted curves keep their existing chart.
        if curve.geometry().is_some() {
            let pivot = first
                .scalar()
                .ok_or(GeometryError::UnrepresentableParameter)?
                + last
                    .scalar()
                    .ok_or(GeometryError::UnrepresentableParameter)?;
            offset += &scale * pivot;
            scale = -scale;
        }
        curve = curve.reversed()?;
    } else if mapped_first.compare(target.start())? != Ordering::Equal
        || mapped_last.compare(target.end())? != Ordering::Equal
    {
        return Err(GeometryError::InvalidParameterDomain);
    }
    Ok(MaterializedSurfacePcurve {
        curve,
        correspondence: SurfacePcurveCorrespondence::Affine { scale, offset },
    })
}

fn materialized_surface_pcurve_from_matching_domains(
    curve: Curve2,
    target_domain: &ParameterDomain,
) -> GeometryResult<MaterializedSurfacePcurve> {
    // Retained curves reverse traversal in their original parameter chart.
    // Match directed endpoints so the affine map preserves that orientation.
    let (first, last) = curve.parameter_endpoints();
    let curve_domain_start = first
        .scalar()
        .ok_or(GeometryError::UnsupportedPcurveContour)?;
    let curve_domain_end = last
        .scalar()
        .ok_or(GeometryError::UnsupportedPcurveContour)?;
    let curve_start = curve_domain_start.clone();
    let curve_span = curve_domain_end - &curve_start;
    let target_span = target_domain.end() - target_domain.start();
    let spatial_scale = (target_span / curve_span).map_err(GeometryError::Numeric)?;
    let spatial_offset = target_domain.start() - &spatial_scale * curve_start;
    Ok(MaterializedSurfacePcurve {
        curve,
        correspondence: SurfacePcurveCorrespondence::Affine {
            scale: spatial_scale,
            offset: spatial_offset,
        },
    })
}

/// Exact unbounded line produced by a surface/surface intersection.
#[derive(Clone, Debug)]
pub struct SurfaceIntersectionLine {
    /// One exact point on the line.
    pub point: Point3,
    /// Exact nonzero line direction.
    pub direction: Vector3,
}

/// Exact lower-bounded ray produced by a surface/surface intersection.
#[derive(Clone, Debug)]
pub struct SurfaceIntersectionRay {
    /// Exact point at ray parameter zero.
    pub point: Point3,
    /// Exact nonzero direction for increasing parameters.
    pub direction: Vector3,
    /// Authoritative lower bound of the ray parameter.
    pub minimum: Real,
    first_pcurve: SurfaceIntersectionParameterRay,
    second_pcurve: SurfaceIntersectionParameterRay,
}

/// Exact affine surface-parameter image of an intersection ray.
#[derive(Clone, Debug)]
pub struct SurfaceIntersectionParameterRay {
    origin: Point2,
    direction: Vector2,
}

impl SurfaceIntersectionRay {
    fn new(
        point: Point3,
        direction: Vector3,
        minimum: Real,
        first_pcurve: SurfaceIntersectionParameterRay,
        second_pcurve: SurfaceIntersectionParameterRay,
    ) -> Self {
        Self {
            point,
            direction,
            minimum,
            first_pcurve,
            second_pcurve,
        }
    }

    fn swapped(mut self) -> Self {
        std::mem::swap(&mut self.first_pcurve, &mut self.second_pcurve);
        self
    }

    /// Returns the exact affine parameter ray on one surface operand.
    pub const fn pcurve(
        &self,
        operand: SurfaceIntersectionOperand,
    ) -> &SurfaceIntersectionParameterRay {
        match operand {
            SurfaceIntersectionOperand::First => &self.first_pcurve,
            SurfaceIntersectionOperand::Second => &self.second_pcurve,
        }
    }
}

impl SurfaceIntersectionParameterRay {
    fn new(origin: Point2, direction: Vector2) -> Self {
        Self { origin, direction }
    }

    /// Returns the surface parameter at one authoritative ray parameter.
    pub fn point_at(&self, parameter: &Real) -> Point2 {
        self.origin.clone() + self.direction.clone() * parameter
    }

    /// Returns the exact surface-parameter origin.
    pub const fn origin(&self) -> &Point2 {
        &self.origin
    }

    /// Returns the exact surface-parameter direction.
    pub const fn direction(&self) -> &Vector2 {
        &self.direction
    }
}

impl SurfacePartials {
    /// Returns the partial derivative in the surface `u` direction.
    pub const fn u(&self) -> &GeometricVector3 {
        &self.u
    }

    /// Returns the partial derivative in the surface `v` direction.
    pub const fn v(&self) -> &GeometricVector3 {
        &self.v
    }

    fn from_coordinates(u: Vector3, v: Vector3) -> Self {
        Self {
            u: GeometricVector3::from_coordinates(u),
            v: GeometricVector3::from_coordinates(v),
        }
    }

    /// Applies the Jacobian to an exact velocity in this surface's UV chart.
    /// Shared source fields remain correlated; unavailable field joins or
    /// radical derivative magnitudes return a typed blocker.
    pub fn apply_direction(
        &self,
        direction: &hypercurve::CurveVector2,
    ) -> GeometryResult<GeometricVector3> {
        crate::context::strict(|| GeometricVector3::chain_rule(&self.u, &self.v, direction))
    }

    /// The unit normal induced by the authored u/v order. Positive speed
    /// factors may cancel during normalization, but orientation never does.
    pub fn normal(&self) -> GeometryResult<GeometricVector3> {
        crate::context::strict(|| {
            let normal = self
                .u
                .normal_direction()?
                .cross(&self.v.normal_direction()?)?;
            if normal.is_zero()? {
                return Err(GeometryError::SingularSurfaceParameter);
            }
            normal.normalized()
        })
    }
}

/// Immutable exact parametric surface.
#[derive(Clone, Debug)]
pub struct Surface {
    data: Arc<SurfaceData>,
}

#[derive(Debug)]
struct SurfaceData {
    geometry: SurfaceGeometry,
    domain: SurfaceDomain,
    bounds: OnceLock<SurfaceBounds>,
}

#[derive(Debug)]
enum SurfaceGeometry {
    Plane(PlaneSurface),
    Cylinder(CylinderSurface),
    Sphere(SphereSurface),
    Cone(ConeSurface),
    Torus(TorusSurface),
    Extrusion(ExtrusionSurface),
    Revolution(RevolutionSurface),
    RationalBezier(RationalBezierSurface),
    Nurbs(NurbsSurface),
}

#[derive(Debug)]
struct PlaneSurface {
    origin: Point3,
    u: Vector3,
    v: Vector3,
}

#[derive(Debug)]
struct OrthonormalFrame3 {
    x: Vector3,
    y: Vector3,
    z: Vector3,
}

#[derive(Debug)]
struct CylinderSurface {
    origin: Point3,
    frame: OrthonormalFrame3,
    radius: Real,
}

#[derive(Debug)]
struct SphereSurface {
    center: Point3,
    frame: OrthonormalFrame3,
    radius: Real,
}

#[derive(Debug)]
struct ConeSurface {
    apex: Point3,
    frame: OrthonormalFrame3,
    semi_angle: Real,
}

#[derive(Debug)]
struct TorusSurface {
    center: Point3,
    frame: OrthonormalFrame3,
    major_radius: Real,
    minor_radius: Real,
}

#[derive(Debug)]
struct ExtrusionSurface {
    profile: Curve3,
    direction: Vector3,
}

#[derive(Debug)]
struct RevolutionSurface {
    profile: Curve3,
    axis_origin: Point3,
    axis: Vector3,
}

#[derive(Debug)]
struct RationalBezierSurface {
    control_points: Vec<Vec<Point3>>,
    weights: Vec<Vec<Real>>,
    homogeneous_controls: OnceLock<Vec<Vec<HomogeneousPoint3>>>,
}

#[derive(Debug)]
struct NurbsSurface {
    u_degree: usize,
    v_degree: usize,
    control_points: Vec<Vec<Point3>>,
    weights: Vec<Vec<Real>>,
    u_knots: Vec<Real>,
    v_knots: Vec<Real>,
    homogeneous_controls: OnceLock<Vec<Vec<HomogeneousPoint3>>>,
}

impl Surface {
    /// Constructs an unbounded exact plane with an authored parameter frame.
    pub fn plane(origin: Point3, u: Vector3, v: Vector3) -> GeometryResult<Self> {
        crate::context::strict(|| {
            let normal_norm = u.cross(&v).norm_squared();
            match compare_reals(&normal_norm, &Real::zero(), crate::STRICT_PREDICATES) {
                PredicateOutcome::Decided {
                    value: Ordering::Greater,
                    ..
                } => Ok(Self::from_parts(
                    SurfaceGeometry::Plane(PlaneSurface { origin, u, v }),
                    SurfaceDomain {
                        u: SurfaceParameterDomain::Unbounded,
                        v: SurfaceParameterDomain::Unbounded,
                    },
                )),
                PredicateOutcome::Decided { .. } => Err(GeometryError::DegeneratePlaneBasis),
                PredicateOutcome::Unknown { needed, stage } => {
                    Err(GeometryError::PredicateUnresolved { needed, stage })
                }
            }
        })
    }

    /// Constructs a circular cylinder with periodic angle `u` and axial `v`.
    pub fn cylinder(
        origin: Point3,
        x: Vector3,
        y: Vector3,
        axis: Vector3,
        radius: Real,
    ) -> GeometryResult<Self> {
        crate::context::strict(|| {
            let frame = validate_orthonormal_frame(x, y, axis)?;
            require_positive(&radius, GeometryError::InvalidRadius)?;
            Ok(Self::from_parts(
                SurfaceGeometry::Cylinder(CylinderSurface {
                    origin,
                    frame,
                    radius,
                }),
                angle_unbounded_domain(),
            ))
        })
    }

    /// Constructs a sphere with longitude `u` and latitude `v`.
    pub fn sphere(
        center: Point3,
        x: Vector3,
        y: Vector3,
        axis: Vector3,
        radius: Real,
    ) -> GeometryResult<Self> {
        crate::context::strict(|| {
            let frame = validate_orthonormal_frame(x, y, axis)?;
            require_positive(&radius, GeometryError::InvalidRadius)?;
            let half_pi = (Real::pi() / Real::from(2)).map_err(GeometryError::Numeric)?;
            Ok(Self::from_parts(
                SurfaceGeometry::Sphere(SphereSurface {
                    center,
                    frame,
                    radius,
                }),
                SurfaceDomain {
                    u: angle_domain(),
                    v: SurfaceParameterDomain::Closed(
                        ParameterDomain::new(-half_pi.clone(), half_pi)?.into(),
                    ),
                },
            ))
        })
    }

    /// Constructs a right circular cone with nonnegative slant distance `v`.
    ///
    /// The exact parameterization is
    /// `apex + v*(sin(semi_angle)*(x*cos(u) + y*sin(u)) + cos(semi_angle)*axis)`.
    /// The apex at `v=0` is a parameter singularity.
    pub fn cone(
        apex: Point3,
        x: Vector3,
        y: Vector3,
        axis: Vector3,
        semi_angle: Real,
    ) -> GeometryResult<Self> {
        crate::context::strict(|| {
            let frame = validate_orthonormal_frame(x, y, axis)?;
            let half_pi = (Real::pi() / Real::from(2)).map_err(GeometryError::Numeric)?;
            if decided_order(compare_reals(
                &semi_angle,
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))? != Ordering::Greater
                || decided_order(compare_reals(
                    &semi_angle,
                    &half_pi,
                    crate::STRICT_PREDICATES,
                ))? != Ordering::Less
            {
                return Err(GeometryError::InvalidConeAngle);
            }
            Ok(Self::from_parts(
                SurfaceGeometry::Cone(ConeSurface {
                    apex,
                    frame,
                    semi_angle,
                }),
                SurfaceDomain {
                    u: angle_domain(),
                    v: SurfaceParameterDomain::LowerBounded {
                        start: Real::zero(),
                    },
                },
            ))
        })
    }

    /// Constructs a non-self-intersecting ring torus.
    pub fn torus(
        center: Point3,
        x: Vector3,
        y: Vector3,
        axis: Vector3,
        major_radius: Real,
        minor_radius: Real,
    ) -> GeometryResult<Self> {
        crate::context::strict(|| {
            let frame = validate_orthonormal_frame(x, y, axis)?;
            require_positive(&minor_radius, GeometryError::InvalidTorusRadii)?;
            if decided_order(compare_reals(
                &major_radius,
                &minor_radius,
                crate::STRICT_PREDICATES,
            ))? != Ordering::Greater
            {
                return Err(GeometryError::InvalidTorusRadii);
            }
            Ok(Self::from_parts(
                SurfaceGeometry::Torus(TorusSurface {
                    center,
                    frame,
                    major_radius,
                    minor_radius,
                }),
                SurfaceDomain {
                    u: angle_domain(),
                    v: angle_domain(),
                },
            ))
        })
    }

    /// Constructs the unbounded linear extrusion of a finite profile curve.
    ///
    /// `u` is the profile parameter and `v` is the signed coefficient of the
    /// authored direction: `S(u, v) = profile(u) + v * direction`.
    pub fn extrusion(profile: Curve3, direction: Vector3) -> GeometryResult<Self> {
        crate::context::strict(|| {
            if decided_order(compare_reals(
                &direction.norm_squared(),
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))? != Ordering::Greater
            {
                return Err(GeometryError::DegenerateExtrusionDirection);
            }
            let u_domain = profile.domain().clone();
            Ok(Self::from_parts(
                SurfaceGeometry::Extrusion(ExtrusionSurface { profile, direction }),
                SurfaceDomain {
                    u: SurfaceParameterDomain::Closed(u_domain),
                    v: SurfaceParameterDomain::Unbounded,
                },
            ))
        })
    }

    /// Constructs the full revolution of a finite profile around a unit axis.
    ///
    /// `u` is the periodic revolution angle and `v` is the profile parameter.
    /// Profile points on the axis remain explicit parameter singularities.
    pub fn revolution(profile: Curve3, axis_origin: Point3, axis: Vector3) -> GeometryResult<Self> {
        crate::context::strict(|| {
            if decided_order(compare_reals(
                &axis.norm_squared(),
                &Real::one(),
                crate::STRICT_PREDICATES,
            ))? != Ordering::Equal
            {
                return Err(GeometryError::InvalidRevolutionAxis);
            }
            let v_domain = profile.domain().clone();
            Ok(Self::from_parts(
                SurfaceGeometry::Revolution(RevolutionSurface {
                    profile,
                    axis_origin,
                    axis,
                }),
                SurfaceDomain {
                    u: angle_domain(),
                    v: SurfaceParameterDomain::Closed(v_domain),
                },
            ))
        })
    }

    /// Constructs a tensor-product rational Bézier surface over `[0, 1]²`.
    ///
    /// The outer vectors are rows in increasing `v`; each row contains control
    /// points in increasing `u`. Both axes must contain at least two controls.
    pub fn rational_bezier(
        control_points: Vec<Vec<Point3>>,
        weights: Vec<Vec<Real>>,
    ) -> GeometryResult<Self> {
        crate::context::strict(|| {
            let (u_count, _) = validate_surface_control_net(&control_points, &weights)?;
            validate_positive_surface_weights(&weights)?;
            debug_assert!(u_count >= 2);
            Ok(Self::from_parts(
                SurfaceGeometry::RationalBezier(RationalBezierSurface {
                    control_points,
                    weights,
                    homogeneous_controls: OnceLock::new(),
                }),
                SurfaceDomain {
                    u: SurfaceParameterDomain::Closed(ParameterRange::unit()),
                    v: SurfaceParameterDomain::Closed(ParameterRange::unit()),
                },
            ))
        })
    }

    /// Constructs a finite non-periodic tensor-product NURBS surface.
    ///
    /// The outer vectors are rows in increasing `v`; each row contains control
    /// points in increasing `u`. Knot vectors are clamped and nondecreasing.
    pub fn nurbs(
        u_degree: usize,
        v_degree: usize,
        control_points: Vec<Vec<Point3>>,
        weights: Vec<Vec<Real>>,
        u_knots: Vec<Real>,
        v_knots: Vec<Real>,
    ) -> GeometryResult<Self> {
        crate::context::strict(|| {
            let (u_count, v_count) = validate_surface_control_net(&control_points, &weights)?;
            validate_positive_surface_weights(&weights)?;
            validate_nurbs_axis(u_degree, u_count, &u_knots)?;
            validate_nurbs_axis(v_degree, v_count, &v_knots)?;
            let u_domain =
                ParameterDomain::new(u_knots[u_degree].clone(), u_knots[u_count].clone())?;
            let v_domain =
                ParameterDomain::new(v_knots[v_degree].clone(), v_knots[v_count].clone())?;
            Ok(Self::from_parts(
                SurfaceGeometry::Nurbs(NurbsSurface {
                    u_degree,
                    v_degree,
                    control_points,
                    weights,
                    u_knots,
                    v_knots,
                    homogeneous_controls: OnceLock::new(),
                }),
                SurfaceDomain {
                    u: SurfaceParameterDomain::Closed(u_domain.into()),
                    v: SurfaceParameterDomain::Closed(v_domain.into()),
                },
            ))
        })
    }

    fn from_parts(geometry: SurfaceGeometry, domain: SurfaceDomain) -> Self {
        Self {
            data: Arc::new(SurfaceData {
                geometry,
                domain,
                bounds: OnceLock::new(),
            }),
        }
    }

    /// Returns the surface family.
    pub fn kind(&self) -> SurfaceKind {
        match &self.data.geometry {
            SurfaceGeometry::Plane(_) => SurfaceKind::Plane,
            SurfaceGeometry::Cylinder(_) => SurfaceKind::Cylinder,
            SurfaceGeometry::Sphere(_) => SurfaceKind::Sphere,
            SurfaceGeometry::Cone(_) => SurfaceKind::Cone,
            SurfaceGeometry::Torus(_) => SurfaceKind::Torus,
            SurfaceGeometry::Extrusion(_) => SurfaceKind::Extrusion,
            SurfaceGeometry::Revolution(_) => SurfaceKind::Revolution,
            SurfaceGeometry::RationalBezier(_) => SurfaceKind::RationalBezier,
            SurfaceGeometry::Nurbs(_) => SurfaceKind::Nurbs,
        }
    }

    /// Proves equality of authored periodic analytic parameterizations, including
    /// frame orientation. Coincidence of their unparameterized images alone
    /// is insufficient for reusing face-local boundary curves.
    pub(crate) fn same_periodic_analytic_parameterization(
        &self,
        other: &Self,
    ) -> GeometryResult<bool> {
        let (first_origin, first_frame, second_origin, second_frame, equal_parameters) =
            match (&self.data.geometry, &other.data.geometry) {
                (SurfaceGeometry::Cylinder(first), SurfaceGeometry::Cylinder(second)) => (
                    &first.origin,
                    &first.frame,
                    &second.origin,
                    &second.frame,
                    decided_order(compare_reals(
                        &first.radius,
                        &second.radius,
                        crate::STRICT_PREDICATES,
                    ))? == Ordering::Equal,
                ),
                (SurfaceGeometry::Cone(first), SurfaceGeometry::Cone(second)) => (
                    &first.apex,
                    &first.frame,
                    &second.apex,
                    &second.frame,
                    decided_order(compare_reals(
                        &first.semi_angle,
                        &second.semi_angle,
                        crate::STRICT_PREDICATES,
                    ))? == Ordering::Equal,
                ),
                (SurfaceGeometry::Torus(first), SurfaceGeometry::Torus(second)) => (
                    &first.center,
                    &first.frame,
                    &second.center,
                    &second.frame,
                    decided_order(compare_reals(
                        &first.major_radius,
                        &second.major_radius,
                        crate::STRICT_PREDICATES,
                    ))? == Ordering::Equal
                        && decided_order(compare_reals(
                            &first.minor_radius,
                            &second.minor_radius,
                            crate::STRICT_PREDICATES,
                        ))? == Ordering::Equal,
                ),
                _ => return Ok(false),
            };
        if !equal_parameters || !orthonormal_frames_equal(first_frame, second_frame)? {
            return Ok(false);
        }
        match point3_equal(first_origin, second_origin, crate::STRICT_PREDICATES) {
            PredicateOutcome::Decided { value, .. } => Ok(value),
            PredicateOutcome::Unknown { needed, stage } => {
                Err(GeometryError::PredicateUnresolved { needed, stage })
            }
        }
    }

    pub(crate) fn canonical_plane(&self) -> GeometryResult<Option<Self>> {
        let controls = match &self.data.geometry {
            SurfaceGeometry::Plane(_) => return Ok(Some(self.clone())),
            SurfaceGeometry::RationalBezier(surface) => {
                surface.control_points.iter().flatten().collect::<Vec<_>>()
            }
            SurfaceGeometry::Nurbs(surface) => {
                surface.control_points.iter().flatten().collect::<Vec<_>>()
            }
            SurfaceGeometry::Sphere(_)
            | SurfaceGeometry::Cylinder(_)
            | SurfaceGeometry::Cone(_)
            | SurfaceGeometry::Torus(_)
            | SurfaceGeometry::Extrusion(_)
            | SurfaceGeometry::Revolution(_) => return Ok(None),
        };
        let Some(&origin) = controls.first() else {
            return Ok(None);
        };
        let mut u = None;
        for &point in controls.iter().skip(1) {
            let candidate = point - origin;
            if decided_order(compare_reals(
                &candidate.norm_squared(),
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))? == Ordering::Greater
            {
                u = Some(candidate);
                break;
            }
        }
        let Some(u) = u else {
            return Ok(None);
        };
        let mut v = None;
        for &point in controls.iter().skip(1) {
            let candidate = point - origin;
            if decided_order(compare_reals(
                &u.cross(&candidate).norm_squared(),
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))? == Ordering::Greater
            {
                v = Some(candidate);
                break;
            }
        }
        let Some(v) = v else {
            return Ok(None);
        };
        let normal = u.cross(&v);
        for &point in &controls {
            if decided_order(compare_reals(
                &normal.dot(&(point - origin)),
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))? != Ordering::Equal
            {
                return Ok(None);
            }
        }
        Ok(Some(Self::plane(origin.clone(), u, v)?))
    }

    /// Returns the exact plane whose authored coordinates are this tensor's
    /// native parameters when the tensor is a constant-weight affine image.
    ///
    /// The certificate checks every rational Bézier control against its
    /// Bernstein lattice, or every NURBS control against its normalized
    /// Greville lattice. Nonconstant projective weights and non-affine control
    /// nets remain explicit unsupported cases.
    pub(crate) fn affine_parameter_plane(&self) -> GeometryResult<Option<Self>> {
        let (
            control_points,
            weights,
            u_coordinates,
            v_coordinates,
            u_start,
            u_span,
            v_start,
            v_span,
        ) = match &self.data.geometry {
            SurfaceGeometry::RationalBezier(surface) => {
                let u_count = surface.control_points[0].len();
                let v_count = surface.control_points.len();
                let u_denominator = Real::from(
                    u128::try_from(u_count - 1).expect("usize is representable as u128"),
                );
                let v_denominator = Real::from(
                    u128::try_from(v_count - 1).expect("usize is representable as u128"),
                );
                let coordinates = |count: usize, denominator: &Real| -> GeometryResult<Vec<Real>> {
                    (0..count)
                        .map(|index| {
                            (Real::from(
                                u128::try_from(index).expect("usize is representable as u128"),
                            ) / denominator)
                                .map_err(GeometryError::Numeric)
                        })
                        .collect()
                };
                (
                    &surface.control_points,
                    &surface.weights,
                    coordinates(u_count, &u_denominator)?,
                    coordinates(v_count, &v_denominator)?,
                    Real::zero(),
                    Real::one(),
                    Real::zero(),
                    Real::one(),
                )
            }
            SurfaceGeometry::Nurbs(surface) => {
                let u_count = surface.control_points[0].len();
                let v_count = surface.control_points.len();
                let u_start = surface.u_knots[surface.u_degree].clone();
                let u_end = surface.u_knots[u_count].clone();
                let v_start = surface.v_knots[surface.v_degree].clone();
                let v_end = surface.v_knots[v_count].clone();
                let u_span = &u_end - &u_start;
                let v_span = &v_end - &v_start;
                (
                    &surface.control_points,
                    &surface.weights,
                    normalized_greville_coordinates(
                        u_count,
                        surface.u_degree,
                        &surface.u_knots,
                        &u_start,
                        &u_span,
                    )?,
                    normalized_greville_coordinates(
                        v_count,
                        surface.v_degree,
                        &surface.v_knots,
                        &v_start,
                        &v_span,
                    )?,
                    u_start,
                    u_span,
                    v_start,
                    v_span,
                )
            }
            SurfaceGeometry::Plane(_)
            | SurfaceGeometry::Cylinder(_)
            | SurfaceGeometry::Sphere(_)
            | SurfaceGeometry::Cone(_)
            | SurfaceGeometry::Torus(_)
            | SurfaceGeometry::Extrusion(_)
            | SurfaceGeometry::Revolution(_) => return Ok(None),
        };
        let first_weight = &weights[0][0];
        for weight in weights.iter().flatten().skip(1) {
            if decided_order(compare_reals(
                weight,
                first_weight,
                crate::STRICT_PREDICATES,
            ))? != Ordering::Equal
            {
                return Ok(None);
            }
        }
        let image_origin = &control_points[0][0];
        let image_u = &control_points[0][control_points[0].len() - 1] - image_origin;
        let image_v = &control_points[control_points.len() - 1][0] - image_origin;
        if decided_order(compare_reals(
            &image_u.cross(&image_v).norm_squared(),
            &Real::zero(),
            crate::STRICT_PREDICATES,
        ))? != Ordering::Greater
        {
            return Ok(None);
        }
        for (row, v_coordinate) in control_points.iter().zip(&v_coordinates) {
            for (point, u_coordinate) in row.iter().zip(&u_coordinates) {
                let expected = image_origin.clone()
                    + image_u.clone() * u_coordinate
                    + image_v.clone() * v_coordinate;
                if !points_equal(point, &expected)? {
                    return Ok(None);
                }
            }
        }
        let parameter_u = divide_vector_by_real(image_u, &u_span)?;
        let parameter_v = divide_vector_by_real(image_v, &v_span)?;
        let parameter_origin =
            image_origin.clone() - parameter_u.clone() * &u_start - parameter_v.clone() * &v_start;
        Ok(Some(Self::plane(
            parameter_origin,
            parameter_u,
            parameter_v,
        )?))
    }

    /// Pulls one rational Bézier image curve back through an exact affine
    /// bilinear tensor whose two native axes are independently Möbius
    /// reparameterized.
    ///
    /// This deliberately recognizes only a degree-one `2×2` affine control
    /// lattice with a positive rank-one weight matrix. Rational Bézier unit
    /// domains and arbitrary active NURBS knot domains share the same
    /// normalized fractional-linear inverse; its result is mapped back into
    /// the authored native domain before the two denominators are multiplied
    /// in homogeneous Bernstein form. Higher-degree projective tensor
    /// inverses are generally algebraic rather than rational and remain
    /// unsupported.
    pub(crate) fn affine_bilinear_inverse_pcurve(
        &self,
        curve: &Curve3,
    ) -> GeometryResult<Option<Curve2>> {
        let (control_points, surface_weights, u_start, u_span, v_start, v_span) =
            match &self.data.geometry {
                SurfaceGeometry::RationalBezier(surface)
                    if surface.control_points.len() == 2
                        && surface.weights.len() == 2
                        && surface
                            .control_points
                            .iter()
                            .zip(&surface.weights)
                            .all(|(points, weights)| points.len() == 2 && weights.len() == 2) =>
                {
                    (
                        &surface.control_points,
                        &surface.weights,
                        Real::zero(),
                        Real::one(),
                        Real::zero(),
                        Real::one(),
                    )
                }
                SurfaceGeometry::Nurbs(surface)
                    if surface.u_degree == 1
                        && surface.v_degree == 1
                        && surface.control_points.len() == 2
                        && surface.weights.len() == 2
                        && surface
                            .control_points
                            .iter()
                            .zip(&surface.weights)
                            .all(|(points, weights)| points.len() == 2 && weights.len() == 2) =>
                {
                    let u_start = surface.u_knots[1].clone();
                    let u_end = surface.u_knots[2].clone();
                    let v_start = surface.v_knots[1].clone();
                    let v_end = surface.v_knots[2].clone();
                    (
                        &surface.control_points,
                        &surface.weights,
                        u_start.clone(),
                        u_end - u_start,
                        v_start.clone(),
                        v_end - v_start,
                    )
                }
                _ => return Ok(None),
            };
        let first_weight = &surface_weights[0][0];
        let mut nonconstant_weights = false;
        for weight in surface_weights.iter().flatten().skip(1) {
            if decided_order(compare_reals(
                weight,
                first_weight,
                crate::STRICT_PREDICATES,
            ))? != Ordering::Equal
            {
                nonconstant_weights = true;
                break;
            }
        }
        if !nonconstant_weights {
            return Ok(None);
        }
        let origin = &control_points[0][0];
        let u = &control_points[0][1] - origin;
        let v = &control_points[1][0] - origin;
        if decided_order(compare_reals(
            &u.cross(&v).norm_squared(),
            &Real::zero(),
            crate::STRICT_PREDICATES,
        ))? != Ordering::Greater
            || !points_equal(
                &control_points[1][1],
                &(origin.clone() + u.clone() + v.clone()),
            )?
            || decided_order(compare_reals(
                &(&surface_weights[0][0] * &surface_weights[1][1]),
                &(&surface_weights[0][1] * &surface_weights[1][0]),
                crate::STRICT_PREDICATES,
            ))? != Ordering::Equal
        {
            return Ok(None);
        }
        let Some(projected) = project_curve_to_plane_frame(curve, origin, &u, &v)? else {
            return Ok(None);
        };
        let Some(CurveGeometry2::RationalBezier(projected)) = projected.geometry() else {
            return Ok(None);
        };
        let x = projected
            .homogeneous_controls()
            .iter()
            .map(|control| control.x().clone())
            .collect::<Vec<_>>();
        let y = projected
            .homogeneous_controls()
            .iter()
            .map(|control| control.y().clone())
            .collect::<Vec<_>>();
        let weights = projected.weights();
        let u_numerator = x
            .iter()
            .map(|value| &surface_weights[0][0] * value)
            .collect::<Vec<_>>();
        let u_denominator = weights
            .iter()
            .zip(&x)
            .map(|(weight, value)| {
                &surface_weights[0][1] * (weight - value) + &surface_weights[0][0] * value
            })
            .collect::<Vec<_>>();
        let v_numerator = y
            .iter()
            .map(|value| &surface_weights[0][0] * value)
            .collect::<Vec<_>>();
        let v_denominator = weights
            .iter()
            .zip(&y)
            .map(|(weight, value)| {
                &surface_weights[1][0] * (weight - value) + &surface_weights[0][0] * value
            })
            .collect::<Vec<_>>();
        let u_native_numerator = u_denominator
            .iter()
            .zip(&u_numerator)
            .map(|(denominator, numerator)| &u_start * denominator + &u_span * numerator)
            .collect::<Vec<_>>();
        let v_native_numerator = v_denominator
            .iter()
            .zip(&v_numerator)
            .map(|(denominator, numerator)| &v_start * denominator + &v_span * numerator)
            .collect::<Vec<_>>();
        let common_weights = bernstein_product(&u_denominator, &v_denominator)?;
        for weight in &common_weights {
            if decided_order(compare_reals(
                weight,
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))? != Ordering::Greater
            {
                return Ok(None);
            }
        }
        let u_homogeneous = bernstein_product(&u_native_numerator, &v_denominator)?;
        let v_homogeneous = bernstein_product(&v_native_numerator, &u_denominator)?;
        let controls = u_homogeneous
            .iter()
            .zip(&v_homogeneous)
            .zip(&common_weights)
            .map(|((u, v), weight)| {
                Ok(CurvePoint2::new(
                    (u / weight).map_err(GeometryError::Numeric)?,
                    (v / weight).map_err(GeometryError::Numeric)?,
                ))
            })
            .collect::<GeometryResult<Vec<_>>>()?;
        Ok(Some(Curve2::from(RationalBezier2::try_new(
            controls,
            common_weights,
        )?)))
    }

    /// Extracts one exact tensor-product iso-curve.
    ///
    /// Rational Bézier surfaces collapse the orthogonal homogeneous control
    /// direction with de Casteljau. NURBS surfaces use homogeneous de Boor and
    /// retain the varying direction's authored degree and knot vector.
    pub fn iso_curve(&self, axis: SurfaceIsoAxis, constant: &Real) -> GeometryResult<Curve3> {
        crate::context::strict(|| {
            let homogeneous_to_curve_data = |controls: Vec<HomogeneousPoint3>| {
                let mut points = Vec::with_capacity(controls.len());
                let mut weights = Vec::with_capacity(controls.len());
                for control in controls {
                    weights.push(control.w.clone());
                    points.push(control.project()?);
                }
                Ok::<_, GeometryError>((points, weights))
            };
            match &self.data.geometry {
                SurfaceGeometry::RationalBezier(surface) => {
                    if !ParameterDomain::unit().contains(constant)? {
                        return Err(GeometryError::ParameterOutsideDomain);
                    }
                    let controls = surface.homogeneous_controls();
                    let iso_controls = match axis {
                        SurfaceIsoAxis::U => (0..controls[0].len())
                            .map(|column| {
                                evaluate_homogeneous_bezier_value(
                                    &controls
                                        .iter()
                                        .map(|row| row[column].clone())
                                        .collect::<Vec<_>>(),
                                    constant,
                                )
                                .ok_or(GeometryError::InvalidControlNetShape)
                            })
                            .collect::<GeometryResult<Vec<_>>>()?,
                        SurfaceIsoAxis::V => controls
                            .iter()
                            .map(|row| {
                                evaluate_homogeneous_bezier_value(row, constant)
                                    .ok_or(GeometryError::InvalidControlNetShape)
                            })
                            .collect::<GeometryResult<Vec<_>>>()?,
                    };
                    let (points, weights) = homogeneous_to_curve_data(iso_controls)?;
                    Curve3::rational_bezier(points, weights)
                }
                SurfaceGeometry::Nurbs(surface) => {
                    let (domain, degree, knots, control_count) = match axis {
                        SurfaceIsoAxis::U => (
                            match &self.data.domain.v {
                                SurfaceParameterDomain::Closed(domain) => domain,
                                _ => return Err(GeometryError::InvalidParameterDomain),
                            },
                            surface.v_degree,
                            &surface.v_knots,
                            surface.control_points.len(),
                        ),
                        SurfaceIsoAxis::V => (
                            match &self.data.domain.u {
                                SurfaceParameterDomain::Closed(domain) => domain,
                                _ => return Err(GeometryError::InvalidParameterDomain),
                            },
                            surface.u_degree,
                            &surface.u_knots,
                            surface.control_points[0].len(),
                        ),
                    };
                    if !domain.contains_real(constant)? {
                        return Err(GeometryError::ParameterOutsideDomain);
                    }
                    let span = find_span(
                        constant,
                        &domain.represented_domain()?,
                        degree,
                        control_count,
                        knots,
                    )?;
                    let controls = surface.homogeneous_controls();
                    let iso_controls = match axis {
                        SurfaceIsoAxis::U => (0..controls[0].len())
                            .map(|column| {
                                evaluate_homogeneous_de_boor_jet(
                                    &controls
                                        .iter()
                                        .map(|row| row[column].clone())
                                        .collect::<Vec<_>>(),
                                    &surface.v_knots,
                                    surface.v_degree,
                                    span,
                                    constant,
                                )
                                .map(|(value, _)| value)
                            })
                            .collect::<GeometryResult<Vec<_>>>()?,
                        SurfaceIsoAxis::V => controls
                            .iter()
                            .map(|row| {
                                evaluate_homogeneous_de_boor_jet(
                                    row,
                                    &surface.u_knots,
                                    surface.u_degree,
                                    span,
                                    constant,
                                )
                                .map(|(value, _)| value)
                            })
                            .collect::<GeometryResult<Vec<_>>>()?,
                    };
                    let (points, weights) = homogeneous_to_curve_data(iso_controls)?;
                    match axis {
                        SurfaceIsoAxis::U => Curve3::nurbs(
                            surface.u_degree,
                            points,
                            weights,
                            surface.u_knots.clone(),
                        ),
                        SurfaceIsoAxis::V => Curve3::nurbs(
                            surface.v_degree,
                            points,
                            weights,
                            surface.v_knots.clone(),
                        ),
                    }
                }
                _ => Err(GeometryError::UnsupportedSubdivision),
            }
        })
    }

    /// Returns the canonical exact parameter domain.
    pub fn domain(&self) -> &SurfaceDomain {
        &self.data.domain
    }

    /// Returns conservative exact model-space bounds.
    ///
    /// Positive-weight tensor-product spline surfaces lie in the convex hull
    /// of their affine control net. Infinite analytic families are reported as
    /// unbounded; bounded analytic families use an exact enclosing cube. Only
    /// successful bounds are cached; unresolved comparisons remain retryable.
    pub fn bounds(&self) -> GeometryResult<SurfaceBounds> {
        crate::context::strict(|| {
            crate::cache::get_or_try_init(&self.data.bounds, || match &self.data.geometry {
                SurfaceGeometry::Plane(_)
                | SurfaceGeometry::Cylinder(_)
                | SurfaceGeometry::Cone(_)
                | SurfaceGeometry::Extrusion(_) => Ok(SurfaceBounds::Unbounded),
                SurfaceGeometry::Sphere(surface) => Ok(SurfaceBounds::Bounded(Box::new(
                    centered_cube_bounds(&surface.center, &surface.radius),
                ))),
                SurfaceGeometry::Torus(surface) => {
                    Ok(SurfaceBounds::Bounded(Box::new(centered_cube_bounds(
                        &surface.center,
                        &(&surface.major_radius + &surface.minor_radius),
                    ))))
                }
                SurfaceGeometry::Revolution(surface) => Ok(SurfaceBounds::Bounded(Box::new(
                    revolution_bounds(surface)?,
                ))),
                SurfaceGeometry::RationalBezier(surface) => Ok(SurfaceBounds::Bounded(Box::new(
                    exact_surface_control_bounds(&surface.control_points)?,
                ))),
                SurfaceGeometry::Nurbs(surface) => Ok(SurfaceBounds::Bounded(Box::new(
                    exact_surface_control_bounds(&surface.control_points)?,
                ))),
            })
            .cloned()
        })
    }

    /// Evaluates represented coefficients for internal surface algorithms.
    pub(crate) fn evaluate_real(&self, parameter: &Point2) -> GeometryResult<Point3> {
        crate::context::strict(|| {
            validate_surface_parameter(&self.data.domain, parameter)?;
            match &self.data.geometry {
                SurfaceGeometry::Plane(plane) => {
                    let displacement =
                        plane.u.clone() * &parameter.x + plane.v.clone() * &parameter.y;
                    Ok(plane.origin.clone() + displacement)
                }
                SurfaceGeometry::Cylinder(surface) => {
                    let (sin_u, cos_u) = (parameter.x.clone().sin(), parameter.x.clone().cos());
                    Ok(surface.origin.clone()
                        + surface.frame.x.clone() * (&surface.radius * cos_u)
                        + surface.frame.y.clone() * (&surface.radius * sin_u)
                        + surface.frame.z.clone() * &parameter.y)
                }
                SurfaceGeometry::Sphere(surface) => {
                    let (sin_u, cos_u) = (parameter.x.clone().sin(), parameter.x.clone().cos());
                    let (sin_v, cos_v) = (parameter.y.clone().sin(), parameter.y.clone().cos());
                    Ok(surface.center.clone()
                        + surface.frame.x.clone() * (&surface.radius * &cos_v * cos_u)
                        + surface.frame.y.clone() * (&surface.radius * cos_v * sin_u)
                        + surface.frame.z.clone() * (&surface.radius * sin_v))
                }
                SurfaceGeometry::Cone(surface) => {
                    let (sin_u, cos_u) = (parameter.x.clone().sin(), parameter.x.clone().cos());
                    let sin_angle = surface.semi_angle.clone().sin();
                    let cos_angle = surface.semi_angle.clone().cos();
                    Ok(surface.apex.clone()
                        + surface.frame.z.clone() * (&parameter.y * cos_angle)
                        + surface.frame.x.clone() * (&parameter.y * &sin_angle * cos_u)
                        + surface.frame.y.clone() * (&parameter.y * sin_angle * sin_u))
                }
                SurfaceGeometry::Torus(surface) => {
                    let (sin_u, cos_u) = (parameter.x.clone().sin(), parameter.x.clone().cos());
                    let (sin_v, cos_v) = (parameter.y.clone().sin(), parameter.y.clone().cos());
                    let radial_distance = &surface.major_radius + &surface.minor_radius * &cos_v;
                    Ok(surface.center.clone()
                        + surface.frame.x.clone() * (&radial_distance * cos_u)
                        + surface.frame.y.clone() * (&radial_distance * sin_u)
                        + surface.frame.z.clone() * (&surface.minor_radius * sin_v))
                }
                SurfaceGeometry::Extrusion(surface) => {
                    Ok(surface.profile.evaluate_real(&parameter.x)?
                        + surface.direction.clone() * &parameter.y)
                }
                SurfaceGeometry::Revolution(surface) => {
                    let profile_point = surface.profile.evaluate_real(&parameter.y)?;
                    Ok(rotate_point_about_axis(
                        &profile_point,
                        &surface.axis_origin,
                        &surface.axis,
                        &parameter.x,
                    ))
                }
                SurfaceGeometry::RationalBezier(surface) => {
                    evaluate_tensor_bezier(surface.homogeneous_controls(), parameter)
                }
                SurfaceGeometry::Nurbs(surface) => {
                    evaluate_tensor_nurbs(surface, &self.data.domain, parameter)
                }
            }
        })
    }

    fn represented_partials(&self, parameter: &Point2) -> GeometryResult<SurfacePartials> {
        crate::context::strict(|| {
            validate_surface_parameter(&self.data.domain, parameter)?;
            match &self.data.geometry {
                SurfaceGeometry::Plane(plane) => Ok(SurfacePartials::from_coordinates(
                    plane.u.clone(),
                    plane.v.clone(),
                )),
                SurfaceGeometry::Cylinder(surface) => {
                    let (sin_u, cos_u) = (parameter.x.clone().sin(), parameter.x.clone().cos());
                    Ok(SurfacePartials::from_coordinates(
                        surface.frame.x.clone() * (-&surface.radius * sin_u)
                            + surface.frame.y.clone() * (&surface.radius * cos_u),
                        surface.frame.z.clone(),
                    ))
                }
                SurfaceGeometry::Sphere(surface) => {
                    let (sin_u, cos_u) = (parameter.x.clone().sin(), parameter.x.clone().cos());
                    let (sin_v, cos_v) = (parameter.y.clone().sin(), parameter.y.clone().cos());
                    Ok(SurfacePartials::from_coordinates(
                        surface.frame.x.clone() * (-&surface.radius * &cos_v * &sin_u)
                            + surface.frame.y.clone() * (&surface.radius * &cos_v * &cos_u),
                        surface.frame.x.clone() * (-&surface.radius * &sin_v * &cos_u)
                            + surface.frame.y.clone() * (-&surface.radius * &sin_v * &sin_u)
                            + surface.frame.z.clone() * (&surface.radius * cos_v),
                    ))
                }
                SurfaceGeometry::Cone(surface) => {
                    let (sin_u, cos_u) = (parameter.x.clone().sin(), parameter.x.clone().cos());
                    let sin_angle = surface.semi_angle.clone().sin();
                    let cos_angle = surface.semi_angle.clone().cos();
                    Ok(SurfacePartials::from_coordinates(
                        surface.frame.x.clone() * (-&parameter.y * &sin_angle * &sin_u)
                            + surface.frame.y.clone() * (&parameter.y * &sin_angle * &cos_u),
                        surface.frame.x.clone() * (&sin_angle * cos_u)
                            + surface.frame.y.clone() * (&sin_angle * sin_u)
                            + surface.frame.z.clone() * cos_angle,
                    ))
                }
                SurfaceGeometry::Torus(surface) => {
                    let (sin_u, cos_u) = (parameter.x.clone().sin(), parameter.x.clone().cos());
                    let (sin_v, cos_v) = (parameter.y.clone().sin(), parameter.y.clone().cos());
                    let radial_distance = &surface.major_radius + &surface.minor_radius * &cos_v;
                    Ok(SurfacePartials::from_coordinates(
                        surface.frame.x.clone() * (-&radial_distance * &sin_u)
                            + surface.frame.y.clone() * (&radial_distance * &cos_u),
                        surface.frame.x.clone() * (-&surface.minor_radius * &sin_v * &cos_u)
                            + surface.frame.y.clone() * (-&surface.minor_radius * &sin_v * &sin_u)
                            + surface.frame.z.clone() * (&surface.minor_radius * cos_v),
                    ))
                }
                SurfaceGeometry::Extrusion(surface) => Ok(SurfacePartials {
                    u: surface
                        .profile
                        .derivative_at(&parameter.x.clone().into(), 1)?,
                    v: GeometricVector3::from_coordinates(surface.direction.clone()),
                }),
                SurfaceGeometry::Revolution(surface) => {
                    let profile_point = surface.profile.evaluate_real(&parameter.y)?;
                    let profile_derivative = surface
                        .profile
                        .derivative_at(&parameter.y.clone().into(), 1)?
                        .require_coordinates()?
                        .clone();
                    let relative = &profile_point - &surface.axis_origin;
                    let axial = surface.axis.clone() * surface.axis.dot(&relative);
                    let radial = relative - axial;
                    let sin = parameter.x.clone().sin();
                    let cos = parameter.x.clone().cos();
                    let u = radial.clone() * -sin + surface.axis.cross(&radial) * cos;
                    let v =
                        rotate_vector_about_axis(&profile_derivative, &surface.axis, &parameter.x);
                    Ok(SurfacePartials::from_coordinates(u, v))
                }
                SurfaceGeometry::RationalBezier(surface) => {
                    evaluate_tensor_bezier_partials(surface.homogeneous_controls(), parameter)
                }
                SurfaceGeometry::Nurbs(surface) => {
                    evaluate_tensor_nurbs_partials(surface, &self.data.domain, parameter)
                }
            }
        })
    }

    /// Returns the exact unit normal induced by the authored parameter order.
    ///
    /// Poles, cone apices, revolution-axis contacts, and other rank-deficient
    /// parameters return [`GeometryError::SingularSurfaceParameter`].
    pub fn normal_at(
        &self,
        parameter: &hypercurve::CurvePoint2,
    ) -> GeometryResult<GeometricVector3> {
        crate::context::strict(|| self.partials_at(parameter)?.normal())
    }

    /// Splits a supported finite tensor-product surface along interior `u`.
    pub fn split_u_at(&self, parameter: &Real) -> GeometryResult<(Self, Self)> {
        crate::context::strict(|| {
            let SurfaceParameterDomain::Closed(domain) = self.domain().u() else {
                return Err(GeometryError::UnsupportedSubdivision);
            };
            require_interior_parameter(&domain.represented_domain()?, parameter)?;
            match &self.data.geometry {
                SurfaceGeometry::RationalBezier(surface) => {
                    split_rational_bezier_surface_u(surface, parameter)
                }
                SurfaceGeometry::Nurbs(surface) => split_nurbs_surface_u(surface, parameter),
                _ => Err(GeometryError::UnsupportedSubdivision),
            }
        })
    }

    /// Splits a supported finite tensor-product surface along interior `v`.
    pub fn split_v_at(&self, parameter: &Real) -> GeometryResult<(Self, Self)> {
        crate::context::strict(|| {
            let SurfaceParameterDomain::Closed(domain) = self.domain().v() else {
                return Err(GeometryError::UnsupportedSubdivision);
            };
            require_interior_parameter(&domain.represented_domain()?, parameter)?;
            match &self.data.geometry {
                SurfaceGeometry::RationalBezier(surface) => {
                    split_rational_bezier_surface_v(surface, parameter)
                }
                SurfaceGeometry::Nurbs(surface) => split_nurbs_surface_v(surface, parameter),
                _ => Err(GeometryError::UnsupportedSubdivision),
            }
        })
    }

    /// Returns the authored plane origin when this is a plane.
    pub fn plane_origin(&self) -> Option<&Point3> {
        match &self.data.geometry {
            SurfaceGeometry::Plane(plane) => Some(&plane.origin),
            SurfaceGeometry::Cylinder(_)
            | SurfaceGeometry::Sphere(_)
            | SurfaceGeometry::Cone(_)
            | SurfaceGeometry::Torus(_)
            | SurfaceGeometry::Extrusion(_)
            | SurfaceGeometry::Revolution(_)
            | SurfaceGeometry::RationalBezier(_)
            | SurfaceGeometry::Nurbs(_) => None,
        }
    }

    /// Returns the authored plane parameter directions when this is a plane.
    pub fn plane_directions(&self) -> Option<(&Vector3, &Vector3)> {
        match &self.data.geometry {
            SurfaceGeometry::Plane(plane) => Some((&plane.u, &plane.v)),
            SurfaceGeometry::Cylinder(_)
            | SurfaceGeometry::Sphere(_)
            | SurfaceGeometry::Cone(_)
            | SurfaceGeometry::Torus(_)
            | SurfaceGeometry::Extrusion(_)
            | SurfaceGeometry::Revolution(_)
            | SurfaceGeometry::RationalBezier(_)
            | SurfaceGeometry::Nurbs(_) => None,
        }
    }

    pub(crate) fn exact_data(&self) -> SurfaceExactData {
        match &self.data.geometry {
            SurfaceGeometry::Plane(surface) => SurfaceExactData::Plane {
                origin: surface.origin.clone(),
                u: surface.u.clone(),
                v: surface.v.clone(),
            },
            SurfaceGeometry::Cylinder(surface) => SurfaceExactData::Cylinder {
                origin: surface.origin.clone(),
                x: surface.frame.x.clone(),
                y: surface.frame.y.clone(),
                axis: surface.frame.z.clone(),
                radius: surface.radius.clone(),
            },
            SurfaceGeometry::Sphere(surface) => SurfaceExactData::Sphere {
                center: surface.center.clone(),
                x: surface.frame.x.clone(),
                y: surface.frame.y.clone(),
                axis: surface.frame.z.clone(),
                radius: surface.radius.clone(),
            },
            SurfaceGeometry::Cone(surface) => SurfaceExactData::Cone {
                apex: surface.apex.clone(),
                x: surface.frame.x.clone(),
                y: surface.frame.y.clone(),
                axis: surface.frame.z.clone(),
                semi_angle: surface.semi_angle.clone(),
            },
            SurfaceGeometry::Torus(surface) => SurfaceExactData::Torus {
                center: surface.center.clone(),
                x: surface.frame.x.clone(),
                y: surface.frame.y.clone(),
                axis: surface.frame.z.clone(),
                major_radius: surface.major_radius.clone(),
                minor_radius: surface.minor_radius.clone(),
            },
            SurfaceGeometry::Extrusion(surface) => SurfaceExactData::Extrusion {
                profile: Box::new(surface.profile.exact_data()),
                direction: surface.direction.clone(),
            },
            SurfaceGeometry::Revolution(surface) => SurfaceExactData::Revolution {
                profile: Box::new(surface.profile.exact_data()),
                axis_origin: surface.axis_origin.clone(),
                axis: surface.axis.clone(),
            },
            SurfaceGeometry::RationalBezier(surface) => SurfaceExactData::RationalBezier {
                control_points: surface.control_points.clone(),
                weights: surface.weights.clone(),
            },
            SurfaceGeometry::Nurbs(surface) => SurfaceExactData::Nurbs {
                u_degree: surface.u_degree,
                v_degree: surface.v_degree,
                control_points: surface.control_points.clone(),
                weights: surface.weights.clone(),
                u_knots: surface.u_knots.clone(),
                v_knots: surface.v_knots.clone(),
            },
        }
    }

    /// Borrows a native extrusion's exact profile and authored direction.
    ///
    /// Its chart is `S(u, v) = profile(u) + v * direction`; the direction need
    /// not have unit length. Other surface families return `None`. This does
    /// not fit or recognize another carrier as an extrusion.
    pub fn extrusion_profile_and_direction(&self) -> Option<(&Curve3, &Vector3)> {
        match &self.data.geometry {
            SurfaceGeometry::Extrusion(surface) => Some((&surface.profile, &surface.direction)),
            _ => None,
        }
    }

    pub(crate) fn revolution_meridian_curve(&self, angle: &Real) -> GeometryResult<Curve3> {
        let SurfaceGeometry::Revolution(surface) = &self.data.geometry else {
            return Err(GeometryError::UnsupportedSubdivision);
        };
        let rotate_point = |point: &Point3| {
            rotate_point_about_axis(point, &surface.axis_origin, &surface.axis, angle)
        };
        let rotate_vector =
            |vector: &Vector3| rotate_vector_about_axis(vector, &surface.axis, angle);
        match surface.profile.exact_data() {
            Curve3ExactData::AffineImage(_)
            | Curve3ExactData::Rotation(_)
            | Curve3ExactData::Translation(_) => surface.profile.transformed(&rotation_transform(
                &surface.axis_origin,
                &surface.axis,
                angle,
            )),
            Curve3ExactData::PlanarImage(mut image) => {
                image.origin = rotate_point(&image.origin);
                image.u = rotate_vector(&image.u);
                image.v = rotate_vector(&image.v);
                Curve3::from_planar_image(*image)
            }
            Curve3ExactData::Line(line) => {
                Curve3::line(rotate_point(&line.start), rotate_point(&line.end))
            }
            Curve3ExactData::RationalBezier {
                control_points,
                weights,
            } => Curve3::rational_bezier(
                control_points.iter().map(rotate_point).collect::<Vec<_>>(),
                weights,
            ),
            Curve3ExactData::Nurbs {
                degree,
                control_points,
                weights,
                knots,
            } => Curve3::nurbs(
                degree,
                control_points.iter().map(rotate_point).collect::<Vec<_>>(),
                weights,
                knots,
            ),
            Curve3ExactData::EllipseArc(data) => Curve3::from_exact_data(
                Curve3ExactData::EllipseArc(Box::new(EllipseArcExactData {
                    circle: data.circle,
                    center: rotate_point(&data.center),
                    x: rotate_vector(&data.x),
                    y: rotate_vector(&data.y),
                    x_radius: data.x_radius,
                    y_radius: data.y_radius,
                    domain_start: data.domain_start,
                    domain_end: data.domain_end,
                    angle_at_start: data.angle_at_start,
                    direction: data.direction,
                })),
            ),
        }
    }

    pub(crate) fn revolution_profile_is_strictly_off_axis(&self) -> GeometryResult<bool> {
        let SurfaceGeometry::Revolution(surface) = &self.data.geometry else {
            return Err(GeometryError::UnsupportedSubdivision);
        };
        surface
            .profile
            .is_strictly_off_axis(&surface.axis_origin, &surface.axis)
    }

    pub(crate) fn revolution_rotation_curve(
        &self,
        profile_parameter: &Parameter,
        domain: ParameterDomain,
        angle_direction: i8,
        angle_offset: Real,
    ) -> GeometryResult<Curve3> {
        let SurfaceGeometry::Revolution(surface) = &self.data.geometry else {
            return Err(GeometryError::UnsupportedSubdivision);
        };
        Curve3::from_rotation(RotationCurve3 {
            origin: surface.profile.point_at(profile_parameter)?,
            axis_origin: surface.axis_origin.clone(),
            axis: surface.axis.clone(),
            domain,
            angle_direction,
            angle_offset,
        })
    }

    pub(crate) fn revolution_latitude_curve(
        &self,
        profile_parameter: &Real,
        angle_start: Real,
        angle_end: Real,
    ) -> GeometryResult<Curve3> {
        let SurfaceGeometry::Revolution(surface) = &self.data.geometry else {
            return Err(GeometryError::UnsupportedSubdivision);
        };
        let profile_point = surface.profile.evaluate_real(profile_parameter)?;
        let relative = &profile_point - &surface.axis_origin;
        let axial = surface.axis.clone() * surface.axis.dot(&relative);
        let radial = relative - &axial;
        if decided_order(compare_reals(
            &radial.norm_squared(),
            &Real::zero(),
            crate::STRICT_PREDICATES,
        ))? != Ordering::Greater
        {
            return Err(GeometryError::SingularSurfaceParameter);
        }
        let radius = radial
            .norm_squared()
            .sqrt()
            .map_err(GeometryError::Numeric)?;
        let x = (radial / &radius).map_err(GeometryError::Numeric)?;
        let y = surface.axis.cross(&x);
        Curve3::circle_arc(
            surface.axis_origin.clone() + axial,
            x,
            y,
            radius,
            angle_start,
            angle_end,
        )
    }

    pub(crate) fn from_exact_data(data: SurfaceExactData) -> GeometryResult<Self> {
        match data {
            SurfaceExactData::Plane { origin, u, v } => Self::plane(origin, u, v),
            SurfaceExactData::Cylinder {
                origin,
                x,
                y,
                axis,
                radius,
            } => Self::cylinder(origin, x, y, axis, radius),
            SurfaceExactData::Sphere {
                center,
                x,
                y,
                axis,
                radius,
            } => Self::sphere(center, x, y, axis, radius),
            SurfaceExactData::Cone {
                apex,
                x,
                y,
                axis,
                semi_angle,
            } => Self::cone(apex, x, y, axis, semi_angle),
            SurfaceExactData::Torus {
                center,
                x,
                y,
                axis,
                major_radius,
                minor_radius,
            } => Self::torus(center, x, y, axis, major_radius, minor_radius),
            SurfaceExactData::Extrusion { profile, direction } => {
                Self::extrusion(Curve3::from_exact_data(*profile)?, direction)
            }
            SurfaceExactData::Revolution {
                profile,
                axis_origin,
                axis,
            } => Self::revolution(Curve3::from_exact_data(*profile)?, axis_origin, axis),
            SurfaceExactData::RationalBezier {
                control_points,
                weights,
            } => Self::rational_bezier(control_points, weights),
            SurfaceExactData::Nurbs {
                u_degree,
                v_degree,
                control_points,
                weights,
                u_knots,
                v_knots,
            } => Self::nurbs(
                u_degree,
                v_degree,
                control_points,
                weights,
                u_knots,
                v_knots,
            ),
        }
    }

    /// Intersects this surface with a finite spatial curve.
    pub fn intersect_curve(&self, curve: &Curve3) -> GeometryResult<CurveSurfaceIntersection> {
        crate::context::strict(|| {
            if let (
                SurfaceGeometry::Plane(plane),
                CurveGeometry3::CircleArc(arc) | CurveGeometry3::EllipseArc(arc),
            ) = (&self.data.geometry, &curve.data.geometry)
            {
                return intersect_ellipse_arc_plane(curve, arc, plane);
            }
            if let (SurfaceGeometry::Plane(plane), CurveGeometry3::RationalBezier(bezier)) =
                (&self.data.geometry, &curve.data.geometry)
            {
                return intersect_rational_bezier_plane(curve, bezier, plane);
            }
            if let (SurfaceGeometry::Plane(plane), CurveGeometry3::Nurbs(nurbs)) =
                (&self.data.geometry, &curve.data.geometry)
            {
                return intersect_nurbs_plane(curve, nurbs, plane);
            }
            if let (SurfaceGeometry::Plane(plane), CurveGeometry3::PlanarImage(image)) =
                (&self.data.geometry, &curve.data.geometry)
            {
                return intersect_planar_image_plane(curve, image, plane);
            }
            if let (SurfaceGeometry::Sphere(sphere), CurveGeometry3::CircleArc(arc)) =
                (&self.data.geometry, &curve.data.geometry)
            {
                return intersect_circle_arc_sphere(curve, arc, sphere);
            }
            if let (SurfaceGeometry::Cylinder(cylinder), CurveGeometry3::CircleArc(arc)) =
                (&self.data.geometry, &curve.data.geometry)
            {
                return intersect_transverse_circle_arc_cylinder(curve, arc, cylinder);
            }
            if let (SurfaceGeometry::Cone(cone), CurveGeometry3::CircleArc(arc)) =
                (&self.data.geometry, &curve.data.geometry)
            {
                return intersect_transverse_circle_arc_cone(curve, arc, cone);
            }
            if let (SurfaceGeometry::Torus(torus), CurveGeometry3::CircleArc(arc)) =
                (&self.data.geometry, &curve.data.geometry)
            {
                return intersect_transverse_circle_arc_torus(curve, arc, torus);
            }
            let Some((start, end)) = curve.line_endpoints() else {
                return Err(GeometryError::UnsupportedIntersection);
            };
            match &self.data.geometry {
                SurfaceGeometry::Plane(plane) => {
                    let normal = plane.u.cross(&plane.v);
                    let direction = end - start;
                    let denominator = normal.dot(&direction);
                    let start_value = normal.dot(&(start - &plane.origin));
                    match decided_order(compare_reals(
                        &denominator,
                        &Real::zero(),
                        crate::STRICT_PREDICATES,
                    ))? {
                        Ordering::Equal => {
                            if decided_order(compare_reals(
                                &start_value,
                                &Real::zero(),
                                crate::STRICT_PREDICATES,
                            ))? == Ordering::Equal
                            {
                                Ok(CurveSurfaceIntersection::Contained)
                            } else {
                                Ok(CurveSurfaceIntersection::None)
                            }
                        }
                        Ordering::Less | Ordering::Greater => {
                            let parameter =
                                ((-start_value) / denominator).map_err(GeometryError::Numeric)?;
                            isolated_line_parameters(
                                curve,
                                [(parameter, CurveSurfaceContactKind::Simple)],
                            )
                        }
                    }
                }
                SurfaceGeometry::Sphere(surface) => {
                    let offset = start - &surface.center;
                    quadratic_line_intersection(curve, &offset, &(end - start), &surface.radius)
                }
                SurfaceGeometry::Cylinder(surface) => {
                    let offset = start - &surface.origin;
                    let direction = end - start;
                    let radial_offset =
                        &offset - &(surface.frame.z.clone() * offset.dot(&surface.frame.z));
                    let radial_direction =
                        &direction - &(surface.frame.z.clone() * direction.dot(&surface.frame.z));
                    quadratic_line_intersection(
                        curve,
                        &radial_offset,
                        &radial_direction,
                        &surface.radius,
                    )
                }
                SurfaceGeometry::Cone(surface) => intersect_line_cone(curve, start, end, surface),
                SurfaceGeometry::Torus(_)
                | SurfaceGeometry::Extrusion(_)
                | SurfaceGeometry::Revolution(_)
                | SurfaceGeometry::RationalBezier(_)
                | SurfaceGeometry::Nurbs(_) => Err(GeometryError::UnsupportedIntersection),
            }
        })
    }

    /// Intersects this surface with another supported surface.
    ///
    /// Rational Bézier/plane sections include complete interior loops,
    /// isolated points and singular branches when the homogeneous pullback is
    /// admitted by Hypersolve's default finite-fiber topology controls and a
    /// whole-rectangle injectivity proof certifies its planar spatial image.
    /// Both pcurves keep the original source parameters. Folded images and
    /// unsupported vertical, repeated or boundary components fail typed;
    /// no incomplete trace is returned as a complete section. The configured
    /// solver work context participates where instrumented, but these limits
    /// do not bound all coefficient growth, heap use, elapsed time or cancellation.
    pub fn intersect_surface(&self, other: &Self) -> GeometryResult<SurfaceSurfaceIntersection> {
        crate::context::strict(|| match (&self.data.geometry, &other.data.geometry) {
            (SurfaceGeometry::Plane(first), SurfaceGeometry::Plane(second)) => {
                intersect_planes(first, second)
            }
            (SurfaceGeometry::Plane(plane), SurfaceGeometry::Sphere(sphere)) => {
                intersect_plane_sphere(plane, sphere)
            }
            (SurfaceGeometry::Sphere(sphere), SurfaceGeometry::Plane(plane)) => {
                intersect_plane_sphere(plane, sphere).map(swapped_curve_intersection)
            }
            (SurfaceGeometry::Plane(plane), SurfaceGeometry::Cylinder(cylinder)) => {
                intersect_plane_cylinder(plane, cylinder)
            }
            (SurfaceGeometry::Cylinder(cylinder), SurfaceGeometry::Plane(plane)) => {
                intersect_plane_cylinder(plane, cylinder).map(swapped_curve_intersection)
            }
            (SurfaceGeometry::Plane(plane), SurfaceGeometry::Cone(cone)) => {
                intersect_plane_cone(plane, cone)
            }
            (SurfaceGeometry::Cone(cone), SurfaceGeometry::Plane(plane)) => {
                intersect_plane_cone(plane, cone).map(swapped_curve_intersection)
            }
            (SurfaceGeometry::Plane(plane), SurfaceGeometry::Torus(torus)) => {
                intersect_plane_torus(plane, torus)
            }
            (SurfaceGeometry::Torus(torus), SurfaceGeometry::Plane(plane)) => {
                intersect_plane_torus(plane, torus).map(swapped_curve_intersection)
            }
            (SurfaceGeometry::Plane(plane), SurfaceGeometry::Extrusion(surface)) => {
                intersect_plane_extrusion(plane, surface)
            }
            (SurfaceGeometry::Extrusion(surface), SurfaceGeometry::Plane(plane)) => {
                intersect_plane_extrusion(plane, surface).map(swapped_curve_intersection)
            }
            (SurfaceGeometry::Plane(plane), SurfaceGeometry::Revolution(surface)) => {
                intersect_plane_revolution(plane, surface)
            }
            (SurfaceGeometry::Revolution(surface), SurfaceGeometry::Plane(plane)) => {
                intersect_plane_revolution(plane, surface).map(swapped_curve_intersection)
            }
            (SurfaceGeometry::Revolution(first), SurfaceGeometry::Revolution(second)) => {
                intersect_coaxial_revolutions(first, second)
            }
            (SurfaceGeometry::Plane(plane), SurfaceGeometry::RationalBezier(surface)) => {
                intersect_plane_rational_bezier_surface(plane, surface)
            }
            (SurfaceGeometry::RationalBezier(surface), SurfaceGeometry::Plane(plane)) => {
                intersect_plane_rational_bezier_surface(plane, surface)
                    .map(swapped_curve_intersection)
            }
            (SurfaceGeometry::Plane(plane), SurfaceGeometry::Nurbs(surface)) => {
                intersect_plane_nurbs_surface(plane, surface)
            }
            (SurfaceGeometry::Nurbs(surface), SurfaceGeometry::Plane(plane)) => {
                intersect_plane_nurbs_surface(plane, surface).map(swapped_curve_intersection)
            }
            (SurfaceGeometry::Cylinder(first), SurfaceGeometry::Cylinder(second)) => {
                intersect_parallel_cylinders(first, second)
            }
            (SurfaceGeometry::Cone(first), SurfaceGeometry::Cone(second)) => {
                intersect_coaxial_cones(first, second)
            }
            (SurfaceGeometry::Torus(first), SurfaceGeometry::Torus(second)) => {
                intersect_coaxial_tori(first, second)
            }
            (SurfaceGeometry::Sphere(sphere), SurfaceGeometry::Torus(torus)) => {
                intersect_coaxial_sphere_torus(sphere, torus)
            }
            (SurfaceGeometry::Torus(torus), SurfaceGeometry::Sphere(sphere)) => {
                intersect_coaxial_sphere_torus(sphere, torus).map(swapped_curve_intersection)
            }
            (SurfaceGeometry::Cylinder(cylinder), SurfaceGeometry::Torus(torus)) => {
                intersect_coaxial_cylinder_torus(cylinder, torus)
            }
            (SurfaceGeometry::Torus(torus), SurfaceGeometry::Cylinder(cylinder)) => {
                intersect_coaxial_cylinder_torus(cylinder, torus).map(swapped_curve_intersection)
            }
            (SurfaceGeometry::Cone(cone), SurfaceGeometry::Torus(torus)) => {
                intersect_coaxial_cone_torus(cone, torus)
            }
            (SurfaceGeometry::Torus(torus), SurfaceGeometry::Cone(cone)) => {
                intersect_coaxial_cone_torus(cone, torus).map(swapped_curve_intersection)
            }
            (SurfaceGeometry::Cylinder(cylinder), SurfaceGeometry::Cone(cone)) => {
                intersect_coaxial_cylinder_cone(cylinder, cone)
            }
            (SurfaceGeometry::Cone(cone), SurfaceGeometry::Cylinder(cylinder)) => {
                intersect_coaxial_cylinder_cone(cylinder, cone).map(swapped_curve_intersection)
            }
            (SurfaceGeometry::Sphere(sphere), SurfaceGeometry::Cylinder(cylinder)) => {
                intersect_coaxial_sphere_cylinder(sphere, cylinder)
            }
            (SurfaceGeometry::Cylinder(cylinder), SurfaceGeometry::Sphere(sphere)) => {
                intersect_coaxial_sphere_cylinder(sphere, cylinder).map(swapped_curve_intersection)
            }
            (SurfaceGeometry::Sphere(sphere), SurfaceGeometry::Cone(cone)) => {
                intersect_coaxial_sphere_cone(sphere, cone)
            }
            (SurfaceGeometry::Cone(cone), SurfaceGeometry::Sphere(sphere)) => {
                intersect_coaxial_sphere_cone(sphere, cone).map(swapped_curve_intersection)
            }
            (SurfaceGeometry::Sphere(first), SurfaceGeometry::Sphere(second)) => {
                intersect_spheres(first, second)
            }
            _ => Err(GeometryError::UnsupportedIntersection),
        })
    }

    pub(crate) fn transformed(
        &self,
        metric: &TransformMetric<'_>,
        reflect_parameters: bool,
    ) -> GeometryResult<Self> {
        let transform = metric.matrix();
        match &self.data.geometry {
            SurfaceGeometry::Plane(plane) => {
                let mut u = transform.transform_direction3(&plane.u);
                if reflect_parameters {
                    u = -u;
                }
                Self::plane(
                    transform_point(transform, &plane.origin)?,
                    u,
                    transform.transform_direction3(&plane.v),
                )
            }
            SurfaceGeometry::Cylinder(surface) => {
                let x = metric.unit_direction(&surface.frame.x)?;
                let mut y = metric.unit_direction(&surface.frame.y)?;
                if reflect_parameters {
                    y = -y;
                }
                Self::cylinder(
                    transform_point(transform, &surface.origin)?,
                    x,
                    y,
                    metric.unit_direction(&surface.frame.z)?,
                    metric.length(&surface.radius)?,
                )
            }
            SurfaceGeometry::Torus(surface) => {
                let x = metric.unit_direction(&surface.frame.x)?;
                let mut y = metric.unit_direction(&surface.frame.y)?;
                if reflect_parameters {
                    y = -y;
                }
                Self::torus(
                    transform_point(transform, &surface.center)?,
                    x,
                    y,
                    metric.unit_direction(&surface.frame.z)?,
                    metric.length(&surface.major_radius)?,
                    metric.length(&surface.minor_radius)?,
                )
            }
            SurfaceGeometry::Cone(surface) => {
                let x = metric.unit_direction(&surface.frame.x)?;
                let mut y = metric.unit_direction(&surface.frame.y)?;
                if reflect_parameters {
                    y = -y;
                }
                Self::cone(
                    transform_point(transform, &surface.apex)?,
                    x,
                    y,
                    metric.unit_direction(&surface.frame.z)?,
                    surface.semi_angle.clone(),
                )
            }
            SurfaceGeometry::Sphere(surface) => {
                let x = metric.unit_direction(&surface.frame.x)?;
                let mut y = metric.unit_direction(&surface.frame.y)?;
                if reflect_parameters {
                    y = -y;
                }
                Self::sphere(
                    transform_point(transform, &surface.center)?,
                    x,
                    y,
                    metric.unit_direction(&surface.frame.z)?,
                    metric.length(&surface.radius)?,
                )
            }
            SurfaceGeometry::Revolution(surface) => Self::revolution(
                surface.profile.transformed_with_metric(metric)?,
                transform_point(transform, &surface.axis_origin)?,
                metric.unit_direction(&surface.axis)?,
            ),
            SurfaceGeometry::Extrusion(surface) => {
                let profile = surface.profile.transformed_with_metric(metric)?;
                // Topology reflects u and reverses wire orientation. Here u is
                // the profile parameter, so reverse its exact parameterization;
                // v remains the coefficient of the transformed direction.
                let profile = if reflect_parameters {
                    profile.reversed()?
                } else {
                    profile
                };
                Self::extrusion(profile, transform.transform_direction3(&surface.direction))
            }
            SurfaceGeometry::RationalBezier(surface) => {
                let mut control_points =
                    transform_surface_control_points(transform, &surface.control_points)?;
                let mut weights = surface.weights.clone();
                if reflect_parameters {
                    reverse_surface_u(&mut control_points);
                    reverse_surface_u(&mut weights);
                }
                Self::rational_bezier(control_points, weights)
            }
            SurfaceGeometry::Nurbs(surface) => {
                let mut control_points =
                    transform_surface_control_points(transform, &surface.control_points)?;
                let mut weights = surface.weights.clone();
                let mut u_knots = surface.u_knots.clone();
                if reflect_parameters {
                    reverse_surface_u(&mut control_points);
                    reverse_surface_u(&mut weights);
                    reverse_knot_axis(&mut u_knots);
                }
                Self::nurbs(
                    surface.u_degree,
                    surface.v_degree,
                    control_points,
                    weights,
                    u_knots,
                    surface.v_knots.clone(),
                )
            }
        }
    }
}

fn intersect_ellipse_arc_plane(
    curve: &Curve3,
    arc: &EllipseArc3,
    plane: &PlaneSurface,
) -> GeometryResult<CurveSurfaceIntersection> {
    let normal = plane.u.cross(&plane.v);
    let center_value = normal.dot(&(&arc.center - &plane.origin));
    let cosine_coefficient = normal.dot(&(arc.x.clone() * &arc.x_radius));
    let sine_coefficient = normal.dot(&(arc.y.clone() * &arc.y_radius));
    intersect_ellipse_arc_scalar_equation(
        curve,
        arc,
        cosine_coefficient,
        sine_coefficient,
        center_value,
    )
}

fn intersect_circle_arc_sphere(
    curve: &Curve3,
    arc: &EllipseArc3,
    sphere: &SphereSurface,
) -> GeometryResult<CurveSurfaceIntersection> {
    intersect_circle_arc_center_radius(curve, arc, &sphere.center, &sphere.radius)
}

fn intersect_circle_arc_center_radius(
    curve: &Curve3,
    arc: &EllipseArc3,
    center: &Point3,
    radius: &Real,
) -> GeometryResult<CurveSurfaceIntersection> {
    let offset = &arc.center - center;
    let twice_radius = Real::from(2) * &arc.x_radius;
    let cosine_coefficient = &twice_radius * arc.x.dot(&offset);
    let sine_coefficient = &twice_radius * arc.y.dot(&offset);
    let center_value = offset.norm_squared() + &arc.x_radius * &arc.x_radius - radius * radius;
    intersect_ellipse_arc_scalar_equation(
        curve,
        arc,
        cosine_coefficient,
        sine_coefficient,
        center_value,
    )
}

fn intersect_transverse_circle_arc_cylinder(
    curve: &Curve3,
    arc: &EllipseArc3,
    cylinder: &CylinderSurface,
) -> GeometryResult<CurveSurfaceIntersection> {
    let circle_axis = arc.x.cross(&arc.y);
    if decided_order(compare_reals(
        &circle_axis.cross(&cylinder.frame.z).norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? != Ordering::Equal
    {
        return Err(GeometryError::UnsupportedIntersection);
    }
    intersect_transverse_circle_arc_radius(
        curve,
        arc,
        &cylinder.origin,
        &cylinder.frame.z,
        &cylinder.radius,
    )
}

fn intersect_transverse_circle_arc_cone(
    curve: &Curve3,
    arc: &EllipseArc3,
    cone: &ConeSurface,
) -> GeometryResult<CurveSurfaceIntersection> {
    let circle_axis = arc.x.cross(&arc.y);
    if decided_order(compare_reals(
        &circle_axis.cross(&cone.frame.z).norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? != Ordering::Equal
    {
        return Err(GeometryError::UnsupportedIntersection);
    }
    let center_offset = &arc.center - &cone.apex;
    let height = center_offset.dot(&cone.frame.z);
    if decided_order(compare_reals(
        &height,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? == Ordering::Less
    {
        return Ok(CurveSurfaceIntersection::None);
    }
    let (_, cone_radius) = cone_section_parameters(cone, &height)?;
    intersect_transverse_circle_arc_radius(curve, arc, &cone.apex, &cone.frame.z, &cone_radius)
}

fn intersect_transverse_circle_arc_torus(
    curve: &Curve3,
    arc: &EllipseArc3,
    torus: &TorusSurface,
) -> GeometryResult<CurveSurfaceIntersection> {
    let circle_axis = arc.x.cross(&arc.y);
    if decided_order(compare_reals(
        &circle_axis.cross(&torus.frame.z).norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? != Ordering::Equal
    {
        return intersect_axial_circle_arc_torus(curve, arc, torus, &circle_axis);
    }
    let center_offset = &arc.center - &torus.center;
    let height = center_offset.dot(&torus.frame.z);
    let height_squared = &height * &height;
    let minor_squared = &torus.minor_radius * &torus.minor_radius;
    if decided_order(compare_reals(
        &height_squared,
        &minor_squared,
        crate::STRICT_PREDICATES,
    ))? == Ordering::Greater
    {
        return Ok(CurveSurfaceIntersection::None);
    }
    let radial_delta = (minor_squared - height_squared)
        .sqrt()
        .map_err(GeometryError::Numeric)?;
    let mut radii = vec![&torus.major_radius + &radial_delta];
    if decided_order(compare_reals(
        &radial_delta,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? != Ordering::Equal
    {
        radii.push(&torus.major_radius - radial_delta);
    }
    let mut combined = Vec::<CurveSurfacePoint>::new();
    for radius in radii {
        match intersect_transverse_circle_arc_radius(
            curve,
            arc,
            &torus.center,
            &torus.frame.z,
            &radius,
        )? {
            CurveSurfaceIntersection::None => {}
            CurveSurfaceIntersection::Points(points) => {
                for point in points {
                    let mut duplicate = false;
                    for existing in &combined {
                        if existing.parameter.compare(&point.parameter)? == Ordering::Equal {
                            duplicate = true;
                            break;
                        }
                    }
                    if !duplicate {
                        combined.push(point);
                    }
                }
            }
            CurveSurfaceIntersection::Contained => {
                return Ok(CurveSurfaceIntersection::Contained);
            }
            CurveSurfaceIntersection::Overlap(_) | CurveSurfaceIntersection::Components(_) => {
                unreachable!("exact circle relation has no proper overlap")
            }
        }
    }
    for index in 1..combined.len() {
        let mut position = index;
        while position > 0
            && combined[position]
                .parameter
                .compare(&combined[position - 1].parameter)?
                == Ordering::Less
        {
            combined.swap(position, position - 1);
            position -= 1;
        }
    }
    if combined.is_empty() {
        Ok(CurveSurfaceIntersection::None)
    } else {
        Ok(CurveSurfaceIntersection::Points(combined))
    }
}

fn intersect_axial_circle_arc_torus(
    curve: &Curve3,
    arc: &EllipseArc3,
    torus: &TorusSurface,
    circle_axis: &Vector3,
) -> GeometryResult<CurveSurfaceIntersection> {
    let center_offset = &arc.center - &torus.center;
    if decided_order(compare_reals(
        &circle_axis.dot(&torus.frame.z),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? != Ordering::Equal
        || decided_order(compare_reals(
            &circle_axis.dot(&center_offset),
            &Real::zero(),
            crate::STRICT_PREDICATES,
        ))? != Ordering::Equal
    {
        return Err(GeometryError::UnsupportedIntersection);
    }
    let height = center_offset.dot(&torus.frame.z);
    let radial = &center_offset - &(torus.frame.z.clone() * height);
    let radial_squared = radial.norm_squared();
    if decided_order(compare_reals(
        &radial_squared,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? == Ordering::Equal
    {
        return Err(GeometryError::UnsupportedIntersection);
    }
    let major_squared = &torus.major_radius * &torus.major_radius;
    let (first_center, second_center) = if radial_squared == major_squared
        || decided_order(compare_reals(
            &radial_squared,
            &major_squared,
            crate::STRICT_PREDICATES,
        ))? == Ordering::Equal
    {
        (
            torus.center.clone() + radial.clone(),
            torus.center.clone() - radial,
        )
    } else {
        let radial = radial.normalize().map_err(GeometryError::Numeric)?;
        (
            torus.center.clone() + radial.clone() * &torus.major_radius,
            torus.center.clone() - radial * &torus.major_radius,
        )
    };
    let mut combined = Vec::<CurveSurfacePoint>::new();
    for center in [&first_center, &second_center] {
        match intersect_circle_arc_center_radius(curve, arc, center, &torus.minor_radius)? {
            CurveSurfaceIntersection::None => {}
            CurveSurfaceIntersection::Points(points) => {
                for point in points {
                    let mut duplicate = false;
                    for existing in &combined {
                        if existing.parameter.compare(&point.parameter)? == Ordering::Equal {
                            duplicate = true;
                            break;
                        }
                    }
                    if !duplicate {
                        combined.push(point);
                    }
                }
            }
            CurveSurfaceIntersection::Contained => {
                return Ok(CurveSurfaceIntersection::Contained);
            }
            CurveSurfaceIntersection::Overlap(_) | CurveSurfaceIntersection::Components(_) => {
                unreachable!("exact circle relation has no proper overlap")
            }
        }
    }
    for index in 1..combined.len() {
        let mut position = index;
        while position > 0
            && combined[position]
                .parameter
                .compare(&combined[position - 1].parameter)?
                == Ordering::Less
        {
            combined.swap(position, position - 1);
            position -= 1;
        }
    }
    if combined.is_empty() {
        Ok(CurveSurfaceIntersection::None)
    } else {
        Ok(CurveSurfaceIntersection::Points(combined))
    }
}

fn intersect_transverse_circle_arc_radius(
    curve: &Curve3,
    arc: &EllipseArc3,
    axis_origin: &Point3,
    axis: &Vector3,
    target_radius: &Real,
) -> GeometryResult<CurveSurfaceIntersection> {
    let center_offset = &arc.center - axis_origin;
    let radial_offset = &center_offset - &(axis.clone() * center_offset.dot(axis));
    let twice_radius = Real::from(2) * &arc.x_radius;
    let cosine_coefficient = &twice_radius * arc.x.dot(&radial_offset);
    let sine_coefficient = &twice_radius * arc.y.dot(&radial_offset);
    let center_value = radial_offset.norm_squared() + &arc.x_radius * &arc.x_radius
        - target_radius * target_radius;
    intersect_ellipse_arc_scalar_equation(
        curve,
        arc,
        cosine_coefficient,
        sine_coefficient,
        center_value,
    )
}

fn intersect_ellipse_arc_scalar_equation(
    curve: &Curve3,
    arc: &EllipseArc3,
    cosine_coefficient: Real,
    sine_coefficient: Real,
    center_value: Real,
) -> GeometryResult<CurveSurfaceIntersection> {
    let amplitude_squared =
        &cosine_coefficient * &cosine_coefficient + &sine_coefficient * &sine_coefficient;
    if decided_order(compare_reals(
        &amplitude_squared,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? == Ordering::Equal
    {
        return if decided_order(compare_reals(
            &center_value,
            &Real::zero(),
            crate::STRICT_PREDICATES,
        ))? == Ordering::Equal
        {
            Ok(CurveSurfaceIntersection::Contained)
        } else {
            Ok(CurveSurfaceIntersection::None)
        };
    }
    let center_squared = &center_value * &center_value;
    let relation = decided_order(compare_reals(
        &center_squared,
        &amplitude_squared,
        crate::STRICT_PREDICATES,
    ))?;
    if relation == Ordering::Greater {
        return Ok(CurveSurfaceIntersection::None);
    }
    let amplitude = amplitude_squared.sqrt().map_err(GeometryError::Numeric)?;
    let phase = certified_atan2(sine_coefficient, cosine_coefficient)?;
    let ratio = ((-center_value) / amplitude).map_err(GeometryError::Numeric)?;
    let offset = ratio.acos().map_err(GeometryError::Numeric)?;
    let angles = if relation == Ordering::Equal {
        vec![phase + offset]
    } else {
        vec![&phase + &offset, phase - offset]
    };
    let kind = if relation == Ordering::Equal {
        CurveSurfaceContactKind::Repeated
    } else {
        CurveSurfaceContactKind::Simple
    };
    let mut points = Vec::<CurveSurfacePoint>::new();
    for angle in angles {
        let point = arc.center.clone()
            + arc.x.clone() * (&arc.x_radius * angle.clone().cos())
            + arc.y.clone() * (&arc.y_radius * angle.clone().sin());
        let parameters = ellipse_arc_parameters_at_angle(curve, arc, angle)?;
        if parameters.is_empty() {
            continue;
        }
        for parameter in parameters {
            let mut duplicate = false;
            for existing in &points {
                if existing.parameter.compare(&parameter.clone().into())? == Ordering::Equal {
                    duplicate = true;
                    break;
                }
            }
            if duplicate {
                continue;
            }
            points.push(CurveSurfacePoint {
                parameter: parameter.into(),
                point: point.clone().into(),
                kind,
            });
        }
    }
    for index in 1..points.len() {
        let mut position = index;
        while position > 0
            && points[position]
                .parameter
                .compare(&points[position - 1].parameter)?
                == Ordering::Less
        {
            points.swap(position, position - 1);
            position -= 1;
        }
    }
    if points.is_empty() {
        Ok(CurveSurfaceIntersection::None)
    } else {
        Ok(CurveSurfaceIntersection::Points(points))
    }
}

fn ellipse_arc_parameters_at_angle(
    curve: &Curve3,
    arc: &EllipseArc3,
    angle: Real,
) -> GeometryResult<Vec<Real>> {
    let delta = if arc.direction < 0 {
        &arc.angle_at_start - &angle
    } else {
        &angle - &arc.angle_at_start
    };
    let result = angular_parameter_lifts(
        &(curve.domain().represented_start()? + delta),
        &curve.domain().represented_domain()?,
    );
    if !matches!(
        result,
        Err(GeometryError::PredicateUnresolved { .. }
            | GeometryError::Numeric(hyperreal::Problem::Exhausted))
    ) {
        return result;
    }
    // A scalar equation can produce an acos phase for a contact already at an
    // atan-authored endpoint. Equality of both unit-circle coordinates proves
    // congruence modulo tau without an unproved inverse-trig identity. In an
    // at-most-one-turn chart this retains precisely the endpoint lift(s).
    // Only a positive exact certificate replaces the original typed failure.
    let sine = angle.clone().sin();
    let cosine = angle.cos();
    for endpoint in [
        curve.domain().represented_start()?,
        curve.domain().represented_end()?,
    ] {
        let offset = endpoint - curve.domain().represented_start()?;
        let phase = if arc.direction < 0 {
            &arc.angle_at_start - offset
        } else {
            &arc.angle_at_start + offset
        };
        if compare_reals(&sine, &phase.clone().sin(), crate::STRICT_PREDICATES).value()
            == Some(Ordering::Equal)
            && compare_reals(&cosine, &phase.cos(), crate::STRICT_PREDICATES).value()
                == Some(Ordering::Equal)
        {
            return angular_parameter_lifts(endpoint, &curve.domain().represented_domain()?);
        }
    }
    result
}

/// All equivalent unit-speed conic parameters in a validated at-most-one-turn
/// domain. The integer quotient selects the first possible lift directly, so
/// enumeration does not grow with the chart's turn number. Scalar quotient and
/// coefficient costs retain their existing resource contract.
/// The two ends of a complete period retain distinct parameter identities.
pub(crate) fn angular_parameter_lifts(
    parameter: &Real,
    domain: &ParameterDomain,
) -> GeometryResult<Vec<Real>> {
    let tau = Real::tau();
    // Reuse these certified orders for both membership and endpoint identity.
    let endpoint_orderings = |value: &Real| {
        crate::context::strict(|| {
            let from_start = decided_order(compare_reals(
                value,
                domain.start(),
                crate::STRICT_PREDICATES,
            ))?;
            let to_end =
                decided_order(compare_reals(value, domain.end(), crate::STRICT_PREDICATES))?;
            Ok::<_, GeometryError>((from_start, to_end))
        })
    };
    let (from_start, to_end) = endpoint_orderings(parameter)?;
    let (first, from_start, to_end) = if from_start != Ordering::Less && to_end != Ordering::Greater
    {
        (parameter.clone(), from_start, to_end)
    } else {
        let turns = ((domain.start() - parameter) / &tau)
            .map_err(GeometryError::Numeric)?
            .ceil_certified()
            .map_err(GeometryError::Numeric)?;
        let first = parameter + Real::new(hyperreal::Rational::from_bigint(turns)) * &tau;
        let (from_start, to_end) = endpoint_orderings(&first)?;
        (first, from_start, to_end)
    };
    if from_start == Ordering::Less || to_end == Ordering::Greater {
        return Ok(Vec::new());
    }
    let at_start = from_start == Ordering::Equal;
    let at_end = to_end == Ordering::Equal;
    if (at_start || at_end)
        && decided_order(compare_reals(
            &(domain.end() - domain.start()),
            &tau,
            crate::STRICT_PREDICATES,
        ))? == Ordering::Equal
    {
        return Ok(vec![domain.start().clone(), domain.end().clone()]);
    }
    Ok(vec![if at_start {
        domain.start().clone()
    } else if at_end {
        domain.end().clone()
    } else {
        first
    }])
}

fn angle_domain() -> SurfaceParameterDomain {
    SurfaceParameterDomain::Periodic {
        start: Real::zero(),
        period: Real::from(2) * Real::pi(),
    }
}

fn angle_unbounded_domain() -> SurfaceDomain {
    SurfaceDomain {
        u: angle_domain(),
        v: SurfaceParameterDomain::Unbounded,
    }
}

fn validate_surface_parameter(domain: &SurfaceDomain, parameter: &Point2) -> GeometryResult<()> {
    if surface_axis_contains(&domain.u, &parameter.x)?
        && surface_axis_contains(&domain.v, &parameter.y)?
    {
        Ok(())
    } else {
        Err(GeometryError::SurfaceParameterOutsideDomain)
    }
}

fn surface_axis_contains(
    domain: &SurfaceParameterDomain,
    parameter: &Real,
) -> GeometryResult<bool> {
    match domain {
        SurfaceParameterDomain::Unbounded | SurfaceParameterDomain::Periodic { .. } => Ok(true),
        SurfaceParameterDomain::Closed(domain) => domain.contains_real(parameter),
        SurfaceParameterDomain::LowerBounded { start } => Ok(matches!(
            decided_order(compare_reals(parameter, start, crate::STRICT_PREDICATES))?,
            Ordering::Equal | Ordering::Greater
        )),
    }
}

fn require_positive(value: &Real, error: GeometryError) -> GeometryResult<()> {
    if decided_order(compare_reals(
        value,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? == Ordering::Greater
    {
        Ok(())
    } else {
        Err(error)
    }
}

fn validate_orthonormal_frame(
    x: Vector3,
    y: Vector3,
    z: Vector3,
) -> GeometryResult<OrthonormalFrame3> {
    let zero = Real::zero();
    let one = Real::one();
    let scalar_checks = [
        (x.norm_squared(), &one),
        (y.norm_squared(), &one),
        (z.norm_squared(), &one),
        (x.dot(&y), &zero),
        (y.dot(&z), &zero),
        (z.dot(&x), &zero),
    ];
    for (actual, expected) in scalar_checks {
        if decided_order(compare_reals(&actual, expected, crate::STRICT_PREDICATES))?
            != Ordering::Equal
        {
            return Err(GeometryError::InvalidSurfaceFrame);
        }
    }
    let handedness = x.cross(&y).dot(&z);
    if decided_order(compare_reals(&handedness, &one, crate::STRICT_PREDICATES))? != Ordering::Equal
    {
        return Err(GeometryError::InvalidSurfaceFrame);
    }
    Ok(OrthonormalFrame3 { x, y, z })
}

pub(crate) fn affine_transform_orientation(transform: &Matrix4) -> GeometryResult<Ordering> {
    for (entry, expected) in
        transform.0[3]
            .iter()
            .zip([Real::zero(), Real::zero(), Real::zero(), Real::one()])
    {
        if decided_order(compare_reals(entry, &expected, crate::STRICT_PREDICATES))?
            != Ordering::Equal
        {
            return Err(GeometryError::NonAffineTransform);
        }
    }
    let m = &transform.0;
    let determinant = &m[0][0] * (&m[1][1] * &m[2][2] - &m[1][2] * &m[2][1])
        - &m[0][1] * (&m[1][0] * &m[2][2] - &m[1][2] * &m[2][0])
        + &m[0][2] * (&m[1][0] * &m[2][1] - &m[1][1] * &m[2][0]);
    match decided_order(compare_reals(
        &determinant,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? {
        Ordering::Greater => Ok(Ordering::Greater),
        Ordering::Equal => Err(GeometryError::SingularTransform),
        Ordering::Less => Ok(Ordering::Less),
    }
}

fn transform_point(transform: &Matrix4, point: &Point3) -> GeometryResult<Point3> {
    transform
        .transform_point3(point)
        .map_err(GeometryError::Numeric)
}

fn transform_points(transform: &Matrix4, points: &[Point3]) -> GeometryResult<Vec<Point3>> {
    transform
        .transform_point3_batch(points)
        .map_err(GeometryError::Numeric)
}

fn transform_surface_control_points(
    transform: &Matrix4,
    control_points: &[Vec<Point3>],
) -> GeometryResult<Vec<Vec<Point3>>> {
    control_points
        .iter()
        .map(|row| transform_points(transform, row))
        .collect()
}

fn reverse_surface_u<T>(rows: &mut [Vec<T>]) {
    for row in rows {
        row.reverse();
    }
}

fn reverse_knot_axis(knots: &mut [Real]) {
    let sum = &knots[0] + &knots[knots.len() - 1];
    knots.reverse();
    for knot in knots {
        *knot = &sum - &*knot;
    }
}

fn swapped_curve_intersection(
    intersection: SurfaceSurfaceIntersection,
) -> SurfaceSurfaceIntersection {
    match intersection {
        SurfaceSurfaceIntersection::Curve(curve) => {
            SurfaceSurfaceIntersection::Curve(Box::new((*curve).swapped()))
        }
        SurfaceSurfaceIntersection::Curves(curves) => SurfaceSurfaceIntersection::Curves(
            curves
                .into_iter()
                .map(SurfaceIntersectionCurve::swapped)
                .collect(),
        ),
        SurfaceSurfaceIntersection::Ray(ray) => {
            SurfaceSurfaceIntersection::Ray(Box::new((*ray).swapped()))
        }
        SurfaceSurfaceIntersection::Rays(rays) => SurfaceSurfaceIntersection::Rays(
            rays.into_iter()
                .map(SurfaceIntersectionRay::swapped)
                .collect(),
        ),
        SurfaceSurfaceIntersection::Components(components) => {
            SurfaceSurfaceIntersection::Components(Box::new((*components).swapped()))
        }
        SurfaceSurfaceIntersection::ContainedSurface(operand) => {
            SurfaceSurfaceIntersection::ContainedSurface(operand.swapped())
        }
        other => other,
    }
}

pub(crate) fn project_point_to_plane_frame(
    origin: &Point3,
    u: &Vector3,
    v: &Vector3,
    point: &Point3,
) -> GeometryResult<Point2> {
    let displacement = point - origin;
    let uu = u.dot(u);
    let uv = u.dot(v);
    let vv = v.dot(v);
    let du = displacement.dot(u);
    let dv = displacement.dot(v);
    let determinant = &uu * &vv - &uv * &uv;
    let x = ((&du * &vv - &dv * &uv) / &determinant).map_err(GeometryError::Numeric)?;
    let y = ((&dv * &uu - &du * &uv) / determinant).map_err(GeometryError::Numeric)?;
    // Replayed endpoints feed native circle-radius and area proofs. Keep each
    // coordinate compact before those consumers multiply repeated projection
    // expressions, using only the scalar-owned bounded exact normal form.
    Ok(Point2::new(
        x.compact_pi_laurent().unwrap_or(x),
        y.compact_pi_laurent().unwrap_or(y),
    ))
}

pub(crate) fn project_curve_to_plane_frame(
    curve: &Curve3,
    origin: &Point3,
    u: &Vector3,
    v: &Vector3,
) -> GeometryResult<Option<Curve2>> {
    let project = |point: &Point3| {
        project_point_to_plane_frame(origin, u, v, point)
            .map(|point| CurvePoint2::new(point.x, point.y))
    };
    match curve.exact_data() {
        Curve3ExactData::Line(line) => Ok(Some(Curve2::from(LineSeg2::try_new(
            project(&line.start)?,
            project(&line.end)?,
        )?))),
        Curve3ExactData::RationalBezier {
            control_points,
            weights,
        } => Ok(Some(Curve2::from(RationalBezier2::try_new(
            control_points
                .iter()
                .map(project)
                .collect::<GeometryResult<Vec<_>>>()?,
            weights,
        )?))),
        Curve3ExactData::Nurbs {
            degree,
            control_points,
            weights,
            knots,
        } => Ok(Some(Curve2::try_nurbs(
            degree,
            control_points
                .iter()
                .map(project)
                .collect::<GeometryResult<Vec<_>>>()?,
            weights,
            knots,
        )?)),
        Curve3ExactData::EllipseArc(data) if data.circle => {
            let center = project(&data.center)?;
            let projected_x =
                project(&(data.center.clone() + data.x.clone() * data.x_radius.clone()))?;
            let projected_y =
                project(&(data.center.clone() + data.y.clone() * data.y_radius.clone()))?;
            let x = (projected_x.x() - center.x(), projected_x.y() - center.y());
            let y = (projected_y.x() - center.x(), projected_y.y() - center.y());
            let xy = &x.0 * &y.0 + &x.1 * &y.1;
            let x_squared = &x.0 * &x.0 + &x.1 * &x.1;
            let y_squared = &y.0 * &y.0 + &y.1 * &y.1;
            if decided_order(compare_reals(&xy, &Real::zero(), crate::STRICT_PREDICATES))?
                != Ordering::Equal
                || decided_order(compare_reals(
                    &x_squared,
                    &y_squared,
                    crate::STRICT_PREDICATES,
                ))? != Ordering::Equal
            {
                return Ok(None);
            }
            let start = project(&curve.start()?)?;
            let end = project(&curve.end()?)?;
            let tangent_point = data.center.clone()
                + curve
                    .derivative_at(&curve.domain().represented_start()?.clone().into(), 1)?
                    .require_coordinates()?;
            let projected_tangent_point = project(&tangent_point)?;
            let projected_tangent = (
                projected_tangent_point.x() - center.x(),
                projected_tangent_point.y() - center.y(),
            );
            let radial = (start.x() - center.x(), start.y() - center.y());
            let orientation = &radial.0 * &projected_tangent.1 - &radial.1 * &projected_tangent.0;
            let clockwise = decided_order(compare_reals(
                &orientation,
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))? == Ordering::Less;
            Ok(Some(Curve2::from(CircularArc2::try_from_center(
                start, end, center, clockwise,
            )?)))
        }
        Curve3ExactData::AffineImage(_)
        | Curve3ExactData::Rotation(_)
        | Curve3ExactData::Translation(_)
        | Curve3ExactData::EllipseArc(_)
        | Curve3ExactData::PlanarImage(_) => Ok(None),
    }
}

pub(crate) fn lift_curve_from_plane_frame(
    curve: &Curve2,
    origin: &Point3,
    u: &Vector3,
    v: &Vector3,
) -> GeometryResult<Option<Curve3>> {
    let lift = |point: &CurvePoint2| origin.clone() + u.clone() * point.x() + v.clone() * point.y();
    match curve.geometry() {
        None => Ok(None),
        Some(CurveGeometry2::Line(line)) => {
            Ok(Some(Curve3::line(lift(line.start()), lift(line.end()))?))
        }
        Some(CurveGeometry2::RationalBezier(curve)) => Ok(Some(Curve3::rational_bezier(
            curve
                .affine_control_points()
                .ok_or(GeometryError::UnsupportedIntersection)?
                .iter()
                .map(lift)
                .collect(),
            curve.weights().to_vec(),
        )?)),
        Some(CurveGeometry2::Nurbs(curve)) => Ok(Some(Curve3::nurbs(
            curve.degree(),
            curve
                .affine_control_points()
                .ok_or(GeometryError::UnsupportedIntersection)?
                .iter()
                .map(lift)
                .collect(),
            curve.weights().to_vec(),
            curve.knots().to_vec(),
        )?)),
        Some(CurveGeometry2::CircularArc(_))
        | Some(CurveGeometry2::QuadraticBezier(_))
        | Some(CurveGeometry2::CubicBezier(_))
        | Some(CurveGeometry2::RationalQuadraticBezier(_))
        | Some(CurveGeometry2::PolynomialBSpline(_)) => Ok(None),
    }
}

pub(crate) fn lift_curve_from_plane_frame_with_affine_parameter(
    curve: &Curve2,
    origin: &Point3,
    u: &Vector3,
    v: &Vector3,
    scale: &Real,
    offset: &Real,
) -> GeometryResult<Option<Curve3>> {
    let order = decided_order(compare_reals(
        scale,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))?;
    if order == Ordering::Equal {
        return Err(GeometryError::InvalidParameterDomain);
    }
    let reversed = order == Ordering::Less;
    let lift = |point: &CurvePoint2| origin.clone() + u.clone() * point.x() + v.clone() * point.y();
    match curve.geometry() {
        None => Ok(None),
        Some(CurveGeometry2::Line(line)) => {
            let (start, end) = if reversed {
                (line.end(), line.start())
            } else {
                (line.start(), line.end())
            };
            Ok(Some(Curve3::line(lift(start), lift(end))?))
        }
        Some(CurveGeometry2::RationalBezier(curve)) => {
            let mut control_points = curve
                .affine_control_points()
                .ok_or(GeometryError::UnsupportedIntersection)?
                .to_vec();
            let mut weights = curve.weights().to_vec();
            if reversed {
                control_points.reverse();
                weights.reverse();
            }
            Ok(Some(Curve3::rational_bezier(
                control_points.iter().map(lift).collect(),
                weights,
            )?))
        }
        Some(CurveGeometry2::RationalQuadraticBezier(curve)) => {
            let mut controls = curve.control_points();
            let mut weights = curve.weights().map(Clone::clone);
            if reversed {
                controls.reverse();
                weights.reverse();
            }
            Ok(Some(Curve3::rational_bezier(
                controls.into_iter().map(lift).collect(),
                weights.to_vec(),
            )?))
        }
        Some(CurveGeometry2::Nurbs(curve)) => {
            let mut control_points = curve
                .affine_control_points()
                .ok_or(GeometryError::UnsupportedIntersection)?
                .to_vec();
            let mut weights = curve.weights().to_vec();
            let mut knots = curve.knots().to_vec();
            if reversed {
                control_points.reverse();
                weights.reverse();
                knots.reverse();
            }
            for knot in &mut knots {
                *knot = scale * &*knot + offset;
            }
            Ok(Some(Curve3::nurbs(
                curve.degree(),
                control_points.iter().map(lift).collect(),
                weights,
                knots,
            )?))
        }
        Some(CurveGeometry2::CircularArc(_))
        | Some(CurveGeometry2::QuadraticBezier(_))
        | Some(CurveGeometry2::CubicBezier(_))
        | Some(CurveGeometry2::PolynomialBSpline(_)) => Ok(None),
    }
}

fn linear_section_pcurve_carriers(
    profile: &Curve3,
    plane_origin: &Point3,
    plane_normal: &Vector3,
    denominator: &Real,
    profile_axis: TensorAxis,
    coefficient_scale: &Real,
    coefficient_offset: &Real,
) -> GeometryResult<Option<Vec<MaterializedSurfacePcurve>>> {
    let coefficient = |point: &Point3| {
        let normalized = (plane_normal.dot(&(plane_origin - point)) / denominator)
            .map_err(GeometryError::Numeric)?;
        Ok(coefficient_offset + coefficient_scale * normalized)
    };
    let span = profile.domain().represented_end()? - profile.domain().represented_start()?;
    match &profile.data.geometry {
        CurveGeometry3::Line(line) => Ok(Some(vec![MaterializedSurfacePcurve {
            curve: Curve2::from(LineSeg2::try_new(
                section_parameter_point(
                    profile.domain().represented_start()?.clone(),
                    coefficient(&line.start)?,
                    profile_axis,
                ),
                section_parameter_point(
                    profile.domain().represented_end()?.clone(),
                    coefficient(&line.end)?,
                    profile_axis,
                ),
            )?),
            correspondence: SurfacePcurveCorrespondence::Affine {
                scale: span,
                offset: profile.domain().represented_start()?.clone(),
            },
        }])),
        CurveGeometry3::RationalBezier(curve) => Ok(Some(vec![rational_linear_section_carrier(
            curve,
            profile.domain().represented_start()?,
            &span,
            &coefficient,
            profile_axis,
        )?])),
        CurveGeometry3::Nurbs(nurbs) => {
            let mut carriers = Vec::new();
            for (segment, domain) in decompose_nurbs_into_bezier_segments(nurbs)? {
                let CurveGeometry3::RationalBezier(curve) = &segment.data.geometry else {
                    unreachable!("NURBS decomposition produces rational Bézier segments");
                };
                carriers.push(rational_linear_section_carrier(
                    curve,
                    domain.start(),
                    &(domain.end() - domain.start()),
                    &coefficient,
                    profile_axis,
                )?);
            }
            Ok(Some(carriers))
        }
        CurveGeometry3::CircleArc(_)
        | CurveGeometry3::EllipseArc(_)
        | CurveGeometry3::AffineImage(_)
        | CurveGeometry3::Rotation(_)
        | CurveGeometry3::Translation(_)
        | CurveGeometry3::PlanarImage(_) => Ok(None),
    }
}

pub(crate) fn concatenate_rational_bezier_spans_as_nurbs(
    curves: &[Curve2],
    boundaries: &[Real],
) -> GeometryResult<Curve2> {
    if curves.len() < 2 || boundaries.len() != curves.len() + 1 {
        return Err(GeometryError::UnsupportedIntersection);
    }
    let Some(CurveGeometry2::RationalBezier(first)) = curves[0].geometry() else {
        return Err(GeometryError::UnsupportedIntersection);
    };
    let degree = first.degree();
    if degree == 0 {
        return Err(GeometryError::InvalidDegree);
    }
    let mut control_points = first
        .affine_control_points()
        .ok_or(GeometryError::UnsupportedIntersection)?
        .to_vec();
    let mut weights = first.weights().to_vec();
    for curve in &curves[1..] {
        let Some(CurveGeometry2::RationalBezier(curve)) = curve.geometry() else {
            return Err(GeometryError::UnsupportedIntersection);
        };
        if curve.degree() != degree
            || decided_order(compare_reals(
                control_points
                    .last()
                    .expect("first rational span has controls")
                    .x(),
                curve.start().x(),
                crate::STRICT_PREDICATES,
            ))? != Ordering::Equal
            || decided_order(compare_reals(
                control_points
                    .last()
                    .expect("first rational span has controls")
                    .y(),
                curve.start().y(),
                crate::STRICT_PREDICATES,
            ))? != Ordering::Equal
        {
            return Err(GeometryError::UnsupportedIntersection);
        }
        let scale = (weights
            .last()
            .expect("first rational span has weights")
            .clone()
            / &curve.weights()[0])
            .map_err(GeometryError::Numeric)?;
        control_points.extend(
            curve
                .affine_control_points()
                .ok_or(GeometryError::UnsupportedIntersection)?
                .iter()
                .skip(1)
                .cloned(),
        );
        weights.extend(curve.weights().iter().skip(1).map(|weight| weight * &scale));
    }
    let mut knots = Vec::with_capacity(control_points.len() + degree + 1);
    knots.extend(std::iter::repeat_n(boundaries[0].clone(), degree + 1));
    for boundary in &boundaries[1..boundaries.len() - 1] {
        knots.extend(std::iter::repeat_n(boundary.clone(), degree));
    }
    knots.extend(std::iter::repeat_n(
        boundaries.last().expect("at least two boundaries").clone(),
        degree + 1,
    ));
    Curve2::try_nurbs(degree, control_points, weights, knots).map_err(GeometryError::from)
}

pub(crate) fn materialize_nurbs_parameter_graph(
    degree: usize,
    coefficients: &[Real],
    weights: &[Real],
    knots: &[Real],
    profile_axis: SurfaceIsoAxis,
) -> GeometryResult<Curve2> {
    if coefficients.len() != weights.len() {
        return Err(GeometryError::WeightCountMismatch);
    }
    let synthetic = Curve3::nurbs(
        degree,
        coefficients
            .iter()
            .map(|coefficient| Point3::new(coefficient.clone(), Real::zero(), Real::zero()))
            .collect(),
        weights.to_vec(),
        knots.to_vec(),
    )?;
    let CurveGeometry3::Nurbs(nurbs) = &synthetic.data.geometry else {
        unreachable!("synthetic NURBS graph source retains NURBS geometry");
    };
    let profile_axis = match profile_axis {
        SurfaceIsoAxis::U => TensorAxis::U,
        SurfaceIsoAxis::V => TensorAxis::V,
    };
    let mut curves = Vec::new();
    let mut boundaries = Vec::new();
    for (segment, domain) in decompose_nurbs_into_bezier_segments(nurbs)? {
        let CurveGeometry3::RationalBezier(curve) = &segment.data.geometry else {
            unreachable!("NURBS decomposition produces rational Bézier segments");
        };
        if boundaries.is_empty() {
            boundaries.push(domain.start().clone());
        }
        boundaries.push(domain.end().clone());
        curves.push(
            rational_linear_section_carrier(
                curve,
                domain.start(),
                &(domain.end() - domain.start()),
                &|point| Ok(point.x.clone()),
                profile_axis,
            )?
            .curve,
        );
    }
    match curves.as_slice() {
        [curve] => Ok(curve.clone()),
        _ => concatenate_rational_bezier_spans_as_nurbs(&curves, &boundaries),
    }
}

fn section_parameter_point(
    profile_parameter: Real,
    coefficient: Real,
    profile_axis: TensorAxis,
) -> CurvePoint2 {
    match profile_axis {
        TensorAxis::U => CurvePoint2::new(profile_parameter, coefficient),
        TensorAxis::V => CurvePoint2::new(coefficient, profile_parameter),
    }
}

fn rational_linear_section_carrier(
    curve: &RationalBezier3,
    parameter_start: &Real,
    parameter_span: &Real,
    coefficient: &impl Fn(&Point3) -> GeometryResult<Real>,
    profile_axis: TensorAxis,
) -> GeometryResult<MaterializedSurfacePcurve> {
    let degree_plus_one = curve.weights.len();
    let denominator_degree =
        Real::from(i64::try_from(degree_plus_one).map_err(|_| GeometryError::InvalidDegree)?);
    let section_homogeneous = curve
        .control_points
        .iter()
        .zip(&curve.weights)
        .map(|(point, weight)| Ok::<_, GeometryError>(weight * coefficient(point)?))
        .collect::<Result<Vec<_>, _>>()?;
    let mut elevated_weights = Vec::with_capacity(degree_plus_one + 1);
    let mut elevated_points = Vec::with_capacity(degree_plus_one + 1);
    for index in 0..=degree_plus_one {
        let alpha = (Real::from(i64::try_from(index).map_err(|_| GeometryError::InvalidDegree)?)
            / &denominator_degree)
            .map_err(GeometryError::Numeric)?;
        let one_minus_alpha = Real::one() - &alpha;
        let previous_weight = (index > 0).then(|| curve.weights[index - 1].clone());
        let next_weight = (index < degree_plus_one).then(|| curve.weights[index].clone());
        let elevated_weight = previous_weight
            .as_ref()
            .map_or_else(Real::zero, |weight| &alpha * weight)
            + next_weight
                .as_ref()
                .map_or_else(Real::zero, |weight| &one_minus_alpha * weight);
        let local_parameter_homogeneous = previous_weight
            .as_ref()
            .map_or_else(Real::zero, |weight| &alpha * weight);
        let x_homogeneous =
            parameter_start * &elevated_weight + parameter_span * local_parameter_homogeneous;
        let previous_y = if index > 0 {
            &alpha * &section_homogeneous[index - 1]
        } else {
            Real::zero()
        };
        let next_y = if index < degree_plus_one {
            &one_minus_alpha * &section_homogeneous[index]
        } else {
            Real::zero()
        };
        let y_homogeneous = previous_y + next_y;
        elevated_points.push(section_parameter_point(
            (x_homogeneous / &elevated_weight).map_err(GeometryError::Numeric)?,
            (y_homogeneous / &elevated_weight).map_err(GeometryError::Numeric)?,
            profile_axis,
        ));
        elevated_weights.push(elevated_weight);
    }
    Ok(MaterializedSurfacePcurve {
        curve: Curve2::from(RationalBezier2::try_new(elevated_points, elevated_weights)?),
        correspondence: SurfacePcurveCorrespondence::Affine {
            scale: parameter_span.clone(),
            offset: parameter_start.clone(),
        },
    })
}

fn intersect_plane_rational_bezier_surface(
    plane: &PlaneSurface,
    surface: &RationalBezierSurface,
) -> GeometryResult<SurfaceSurfaceIntersection> {
    if let Some(direction) = linear_tensor_u_direction(&surface.control_points, &surface.weights)? {
        let profile_controls = surface
            .control_points
            .iter()
            .map(|row| row[0].clone())
            .collect::<Vec<_>>();
        let profile_weights = surface
            .weights
            .iter()
            .map(|row| row[0].clone())
            .collect::<Vec<_>>();
        let profile = Curve3::rational_bezier(profile_controls.clone(), profile_weights)?;
        match intersect_plane_linear_tensor_graph(
            plane,
            profile,
            &profile_controls,
            direction,
            TensorAxis::V,
            Real::one(),
            Real::zero(),
        ) {
            Ok(intersection) => return Ok(intersection),
            Err(GeometryError::UnsupportedIntersection) => {}
            Err(error) => return Err(error),
        }
    }
    if let Some(direction) = linear_tensor_v_direction(&surface.control_points, &surface.weights)? {
        let profile = Curve3::rational_bezier(
            surface.control_points[0].clone(),
            surface.weights[0].clone(),
        )?;
        match intersect_plane_v_linear_tensor_iso(
            plane,
            profile,
            &surface.control_points[0],
            direction,
            Real::one(),
            Real::zero(),
        ) {
            Ok(intersection) => return Ok(intersection),
            Err(GeometryError::UnsupportedIntersection) => {}
            Err(error) => return Err(error),
        }
    }
    match intersect_plane_rational_bilinear(plane, surface) {
        Err(GeometryError::UnsupportedIntersection) => plane_tensor::intersect(plane, surface),
        result => result,
    }
}

fn intersect_plane_rational_bilinear(
    plane: &PlaneSurface,
    surface: &RationalBezierSurface,
) -> GeometryResult<SurfaceSurfaceIntersection> {
    if surface.control_points.len() != 2
        || surface.weights.len() != 2
        || surface
            .control_points
            .iter()
            .zip(&surface.weights)
            .any(|(points, weights)| points.len() != 2 || weights.len() != 2)
    {
        return Err(GeometryError::UnsupportedIntersection);
    }

    let normal = plane.u.cross(&plane.v);
    let signed_value = |point: &Point3| normal.dot(&(point - &plane.origin));
    let values = [
        [
            signed_value(&surface.control_points[0][0]) * &surface.weights[0][0],
            signed_value(&surface.control_points[0][1]) * &surface.weights[0][1],
        ],
        [
            signed_value(&surface.control_points[1][0]) * &surface.weights[1][0],
            signed_value(&surface.control_points[1][1]) * &surface.weights[1][1],
        ],
    ];
    let orders = values
        .iter()
        .flatten()
        .map(|value| {
            decided_order(compare_reals(
                value,
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))
        })
        .collect::<GeometryResult<Vec<_>>>()?;
    if orders.iter().all(|order| *order == Ordering::Greater)
        || orders.iter().all(|order| *order == Ordering::Less)
    {
        return Ok(SurfaceSurfaceIntersection::None);
    }
    if orders.iter().all(|order| *order == Ordering::Equal) {
        return Ok(SurfaceSurfaceIntersection::ContainedSurface(
            SurfaceIntersectionOperand::Second,
        ));
    }
    if let Some(intersection) =
        sign_definite_bilinear_boundary_intersection(plane, surface, &orders)?
    {
        return Ok(intersection);
    }

    for parameter_axis in [TensorAxis::V, TensorAxis::U] {
        let Some(pcurve) = bilinear_plane_parameter_graph(&values, parameter_axis)? else {
            continue;
        };
        if rational_curve_bounds_inside_unit_square(&pcurve)? {
            return Ok(SurfaceSurfaceIntersection::Curve(Box::new(
                rational_bilinear_section(plane, surface, pcurve)?,
            )));
        }
        return clip_rational_bilinear_parameter_graph(plane, surface, &pcurve);
    }
    intersect_plane_bilinear_pole_branches(plane, surface, &values)
}

fn sign_definite_bilinear_boundary_intersection(
    plane: &PlaneSurface,
    surface: &RationalBezierSurface,
    orders: &[Ordering],
) -> GeometryResult<Option<SurfaceSurfaceIntersection>> {
    let has_positive = orders.contains(&Ordering::Greater);
    let has_negative = orders.contains(&Ordering::Less);
    if has_positive && has_negative {
        return Ok(None);
    }

    let zeros = [
        orders[0] == Ordering::Equal,
        orders[1] == Ordering::Equal,
        orders[2] == Ordering::Equal,
        orders[3] == Ordering::Equal,
    ];
    let zero_count = zeros.iter().filter(|zero| **zero).count();
    debug_assert!((1..=3).contains(&zero_count));
    match zero_count {
        1 => {
            let index = zeros
                .iter()
                .position(|zero| *zero)
                .expect("one sign-definite bilinear zero");
            Ok(Some(SurfaceSurfaceIntersection::Point(Box::new(
                (bilinear_corner(surface, index)).into(),
            ))))
        }
        2 if zeros[0] && zeros[1] => Ok(Some(SurfaceSurfaceIntersection::Curve(Box::new(
            rational_bilinear_iso_section(plane, surface, SurfaceIsoAxis::U, &Real::zero())?,
        )))),
        2 if zeros[2] && zeros[3] => Ok(Some(SurfaceSurfaceIntersection::Curve(Box::new(
            rational_bilinear_iso_section(plane, surface, SurfaceIsoAxis::U, &Real::one())?,
        )))),
        2 if zeros[0] && zeros[2] => Ok(Some(SurfaceSurfaceIntersection::Curve(Box::new(
            rational_bilinear_iso_section(plane, surface, SurfaceIsoAxis::V, &Real::zero())?,
        )))),
        2 if zeros[1] && zeros[3] => Ok(Some(SurfaceSurfaceIntersection::Curve(Box::new(
            rational_bilinear_iso_section(plane, surface, SurfaceIsoAxis::V, &Real::one())?,
        )))),
        2 => Ok(Some(SurfaceSurfaceIntersection::Points(
            zeros
                .iter()
                .enumerate()
                .filter(|(_, zero)| **zero)
                .map(|(index, _)| bilinear_corner(surface, index).into())
                .collect(),
        ))),
        3 => {
            let nonzero = zeros
                .iter()
                .position(|zero| !*zero)
                .expect("one nonzero sign-definite bilinear corner");
            let constant = if nonzero < 2 {
                Real::one()
            } else {
                Real::zero()
            };
            let horizontal =
                rational_bilinear_iso_section(plane, surface, SurfaceIsoAxis::U, &constant)?;
            let constant = if nonzero % 2 == 0 {
                Real::one()
            } else {
                Real::zero()
            };
            let vertical =
                rational_bilinear_iso_section(plane, surface, SurfaceIsoAxis::V, &constant)?;
            Ok(Some(SurfaceSurfaceIntersection::Curves(vec![
                horizontal, vertical,
            ])))
        }
        _ => unreachable!("all-zero bilinear relations are handled as overlap"),
    }
}

fn bilinear_corner(surface: &RationalBezierSurface, index: usize) -> Point3 {
    surface.control_points[index / 2][index % 2].clone()
}

fn rational_bilinear_section(
    plane: &PlaneSurface,
    surface: &RationalBezierSurface,
    pcurve: Curve2,
) -> GeometryResult<SurfaceIntersectionCurve> {
    let spatial =
        rational_bilinear_parameter_curve(&surface.control_points, &surface.weights, &pcurve)?
            .ok_or(GeometryError::UnsupportedIntersection)?;
    Ok(SurfaceIntersectionCurve::new(
        spatial.clone(),
        SurfaceIntersectionPcurve::plane_projection(spatial, plane),
        SurfaceIntersectionPcurve::retained_curve(pcurve)?,
    ))
}

fn clip_rational_bilinear_parameter_graph(
    plane: &PlaneSurface,
    surface: &RationalBezierSurface,
    pcurve: &Curve2,
) -> GeometryResult<SurfaceSurfaceIntersection> {
    let region = tensor_parameter_region(
        TensorAxis::V,
        &Real::zero(),
        &Real::one(),
        &Real::zero(),
        &Real::one(),
    )?;
    let trimmed = pcurve.trim_inside_region_with_parameters(&region)?;
    let mut intervals: Vec<(Real, Real)> = Vec::with_capacity(trimmed.len());
    for fragment in trimmed {
        let Some((start, end)) = fragment.represented_parameter_range() else {
            return Err(GeometryError::UnrepresentableParameter);
        };
        if let Some((_, previous_end)) = intervals.last_mut()
            && decided_order(compare_reals(
                previous_end,
                &start,
                crate::STRICT_PREDICATES,
            ))? == Ordering::Equal
        {
            *previous_end = end;
        } else {
            intervals.push((start, end));
        }
    }
    let mut sections = intervals
        .into_iter()
        .map(|(start, end)| {
            rational_bilinear_section(
                plane,
                surface,
                pcurve.clone().subcurve(start.into(), end.into())?,
            )
        })
        .collect::<GeometryResult<Vec<_>>>()?;
    match sections.len() {
        0 => Err(GeometryError::UnsupportedIntersection),
        1 => Ok(SurfaceSurfaceIntersection::Curve(Box::new(
            sections.pop().expect("one retained bilinear fragment"),
        ))),
        _ => Ok(SurfaceSurfaceIntersection::Curves(sections)),
    }
}

fn bilinear_plane_parameter_graph(
    values: &[[Real; 2]; 2],
    parameter_axis: TensorAxis,
) -> GeometryResult<Option<Curve2>> {
    let coefficients = bilinear_graph_coefficients(values, parameter_axis);
    bilinear_parameter_graph_from_endpoints(
        coefficients.first_offset,
        coefficients.second_offset,
        coefficients.first_denominator,
        coefficients.second_denominator,
        &Real::zero(),
        &Real::one(),
        parameter_axis,
    )
}

struct BilinearGraphCoefficients {
    first_offset: Real,
    second_offset: Real,
    first_denominator: Real,
    second_denominator: Real,
}

fn bilinear_graph_coefficients(
    values: &[[Real; 2]; 2],
    parameter_axis: TensorAxis,
) -> BilinearGraphCoefficients {
    match parameter_axis {
        TensorAxis::V => BilinearGraphCoefficients {
            first_offset: values[0][0].clone(),
            second_offset: values[1][0].clone(),
            first_denominator: &values[0][1] - &values[0][0],
            second_denominator: &values[1][1] - &values[1][0],
        },
        TensorAxis::U => BilinearGraphCoefficients {
            first_offset: values[0][0].clone(),
            second_offset: values[0][1].clone(),
            first_denominator: &values[1][0] - &values[0][0],
            second_denominator: &values[1][1] - &values[0][1],
        },
    }
}

fn bilinear_parameter_graph_from_endpoints(
    first_offset: Real,
    second_offset: Real,
    first_denominator: Real,
    second_denominator: Real,
    first_parameter: &Real,
    second_parameter: &Real,
    parameter_axis: TensorAxis,
) -> GeometryResult<Option<Curve2>> {
    let first_order = decided_order(compare_reals(
        &first_denominator,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))?;
    let second_order = decided_order(compare_reals(
        &second_denominator,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))?;
    let sign = match (first_order, second_order) {
        (Ordering::Greater, Ordering::Greater) => Real::one(),
        (Ordering::Less, Ordering::Less) => -Real::one(),
        _ => return Ok(None),
    };
    let denominator_sum = &first_denominator + &second_denominator;
    let middle_denominator = (&denominator_sum / Real::from(2)).map_err(GeometryError::Numeric)?;
    let numerators = [-first_offset, -second_offset];
    let solved_controls = [
        (&numerators[0] / &first_denominator).map_err(GeometryError::Numeric)?,
        ((&numerators[0] + &numerators[1]) / &denominator_sum).map_err(GeometryError::Numeric)?,
        (&numerators[1] / &second_denominator).map_err(GeometryError::Numeric)?,
    ];
    let middle_parameter = ((first_parameter * &second_denominator
        + second_parameter * &first_denominator)
        / &denominator_sum)
        .map_err(GeometryError::Numeric)?;
    let controls = match parameter_axis {
        TensorAxis::V => vec![
            CurvePoint2::new(solved_controls[0].clone(), first_parameter.clone()),
            CurvePoint2::new(solved_controls[1].clone(), middle_parameter),
            CurvePoint2::new(solved_controls[2].clone(), second_parameter.clone()),
        ],
        TensorAxis::U => vec![
            CurvePoint2::new(first_parameter.clone(), solved_controls[0].clone()),
            CurvePoint2::new(middle_parameter, solved_controls[1].clone()),
            CurvePoint2::new(second_parameter.clone(), solved_controls[2].clone()),
        ],
    };
    let weights = vec![
        &sign * first_denominator,
        &sign * middle_denominator,
        sign * second_denominator,
    ];
    Ok(Some(Curve2::from(RationalBezier2::try_new(
        controls, weights,
    )?)))
}

fn intersect_plane_bilinear_pole_branches(
    plane: &PlaneSurface,
    surface: &RationalBezierSurface,
    values: &[[Real; 2]; 2],
) -> GeometryResult<SurfaceSurfaceIntersection> {
    for parameter_axis in [TensorAxis::V, TensorAxis::U] {
        let coefficients = bilinear_graph_coefficients(values, parameter_axis);
        let first_offset = &coefficients.first_offset;
        let second_offset = &coefficients.second_offset;
        let first_denominator = &coefficients.first_denominator;
        let second_denominator = &coefficients.second_denominator;
        let first_denominator_order = decided_order(compare_reals(
            first_denominator,
            &Real::zero(),
            crate::STRICT_PREDICATES,
        ))?;
        let second_denominator_order = decided_order(compare_reals(
            second_denominator,
            &Real::zero(),
            crate::STRICT_PREDICATES,
        ))?;
        if first_denominator_order == Ordering::Equal && second_denominator_order == Ordering::Equal
        {
            continue;
        }
        if let Some(pole) = linear_root_in_unit_interval(first_denominator, second_denominator)?
            && decided_order(compare_reals(
                &linear_value(first_offset, second_offset, &pole),
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))? == Ordering::Equal
        {
            return factorized_bilinear_sections(
                plane,
                surface,
                parameter_axis,
                &pole,
                &coefficients,
            );
        }

        let mut boundaries = vec![Real::zero(), Real::one()];
        for (first, second) in [
            (first_offset, second_offset),
            (
                &(first_offset + first_denominator),
                &(second_offset + second_denominator),
            ),
            (first_denominator, second_denominator),
        ] {
            if let Some(root) = linear_root_in_unit_interval(first, second)? {
                insert_sorted_real_unique(&mut boundaries, root)?;
            }
        }

        let mut sections = Vec::new();
        for interval in boundaries.windows(2) {
            let start = &interval[0];
            let end = &interval[1];
            if decided_order(compare_reals(start, end, crate::STRICT_PREDICATES))? != Ordering::Less
            {
                continue;
            }
            let midpoint = ((start + end) / Real::from(2)).map_err(GeometryError::Numeric)?;
            let midpoint_denominator =
                linear_value(first_denominator, second_denominator, &midpoint);
            if decided_order(compare_reals(
                &midpoint_denominator,
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))? == Ordering::Equal
            {
                continue;
            }
            let midpoint_solved = (-linear_value(first_offset, second_offset, &midpoint)
                / midpoint_denominator)
                .map_err(GeometryError::Numeric)?;
            if decided_order(compare_reals(
                &midpoint_solved,
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))? == Ordering::Less
                || decided_order(compare_reals(
                    &midpoint_solved,
                    &Real::one(),
                    crate::STRICT_PREDICATES,
                ))? == Ordering::Greater
            {
                continue;
            }

            let start_denominator = linear_value(first_denominator, second_denominator, start);
            let end_denominator = linear_value(first_denominator, second_denominator, end);
            let Some(pcurve) = bilinear_parameter_graph_from_endpoints(
                linear_value(first_offset, second_offset, start),
                linear_value(first_offset, second_offset, end),
                start_denominator,
                end_denominator,
                start,
                end,
                parameter_axis,
            )?
            else {
                return Err(GeometryError::UnsupportedIntersection);
            };
            sections.push(rational_bilinear_section(plane, surface, pcurve)?);
        }
        if !sections.is_empty() {
            return match sections.len() {
                1 => Ok(SurfaceSurfaceIntersection::Curve(Box::new(
                    sections.pop().expect("one retained bilinear pole branch"),
                ))),
                _ => Ok(SurfaceSurfaceIntersection::Curves(sections)),
            };
        }
    }
    Err(GeometryError::UnsupportedIntersection)
}

fn factorized_bilinear_sections(
    plane: &PlaneSurface,
    surface: &RationalBezierSurface,
    parameter_axis: TensorAxis,
    pole: &Real,
    coefficients: &BilinearGraphCoefficients,
) -> GeometryResult<SurfaceSurfaceIntersection> {
    let pole_iso_axis = match parameter_axis {
        TensorAxis::V => SurfaceIsoAxis::U,
        TensorAxis::U => SurfaceIsoAxis::V,
    };
    let mut sections = vec![rational_bilinear_iso_section(
        plane,
        surface,
        pole_iso_axis,
        pole,
    )?];

    let sample = if decided_order(compare_reals(pole, &Real::zero(), crate::STRICT_PREDICATES))?
        == Ordering::Equal
    {
        Real::one()
    } else {
        Real::zero()
    };
    let sample_denominator = linear_value(
        &coefficients.first_denominator,
        &coefficients.second_denominator,
        &sample,
    );
    if decided_order(compare_reals(
        &sample_denominator,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? != Ordering::Equal
    {
        let solved = (-linear_value(
            &coefficients.first_offset,
            &coefficients.second_offset,
            &sample,
        ) / sample_denominator)
            .map_err(GeometryError::Numeric)?;
        if decided_order(compare_reals(
            &solved,
            &Real::zero(),
            crate::STRICT_PREDICATES,
        ))? != Ordering::Less
            && decided_order(compare_reals(
                &solved,
                &Real::one(),
                crate::STRICT_PREDICATES,
            ))? != Ordering::Greater
        {
            let solved_iso_axis = match parameter_axis {
                TensorAxis::V => SurfaceIsoAxis::V,
                TensorAxis::U => SurfaceIsoAxis::U,
            };
            sections.push(rational_bilinear_iso_section(
                plane,
                surface,
                solved_iso_axis,
                &solved,
            )?);
        }
    }
    match sections.len() {
        1 => Ok(SurfaceSurfaceIntersection::Curve(Box::new(
            sections.pop().expect("one retained factorized iso-line"),
        ))),
        _ => Ok(SurfaceSurfaceIntersection::Curves(sections)),
    }
}

fn rational_bilinear_iso_section(
    plane: &PlaneSurface,
    surface: &RationalBezierSurface,
    axis: SurfaceIsoAxis,
    constant: &Real,
) -> GeometryResult<SurfaceIntersectionCurve> {
    let carrier =
        Surface::rational_bezier(surface.control_points.clone(), surface.weights.clone())?;
    let spatial = carrier.iso_curve(axis, constant)?;
    let pcurve = match axis {
        SurfaceIsoAxis::U => Curve2::from(LineSeg2::try_new(
            CurvePoint2::new(Real::zero(), constant.clone()),
            CurvePoint2::new(Real::one(), constant.clone()),
        )?),
        SurfaceIsoAxis::V => Curve2::from(LineSeg2::try_new(
            CurvePoint2::new(constant.clone(), Real::zero()),
            CurvePoint2::new(constant.clone(), Real::one()),
        )?),
    };
    Ok(SurfaceIntersectionCurve::new(
        spatial.clone(),
        SurfaceIntersectionPcurve::plane_projection(spatial, plane),
        SurfaceIntersectionPcurve::retained_curve(pcurve)?,
    ))
}

fn linear_root_in_unit_interval(first: &Real, second: &Real) -> GeometryResult<Option<Real>> {
    let delta = second - first;
    if decided_order(compare_reals(
        &delta,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? == Ordering::Equal
    {
        return Ok(None);
    }
    let root = (-first / delta).map_err(GeometryError::Numeric)?;
    if decided_order(compare_reals(
        &root,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? == Ordering::Less
        || decided_order(compare_reals(&root, &Real::one(), crate::STRICT_PREDICATES))?
            == Ordering::Greater
    {
        Ok(None)
    } else {
        Ok(Some(root))
    }
}

fn linear_value(first: &Real, second: &Real, parameter: &Real) -> Real {
    first + (second - first) * parameter
}

fn insert_sorted_real_unique(values: &mut Vec<Real>, value: Real) -> GeometryResult<()> {
    let mut insertion = 0;
    while insertion < values.len() {
        match decided_order(compare_reals(
            &value,
            &values[insertion],
            crate::STRICT_PREDICATES,
        ))? {
            Ordering::Less => break,
            Ordering::Equal => return Ok(()),
            Ordering::Greater => insertion += 1,
        }
    }
    values.insert(insertion, value);
    Ok(())
}

fn rational_curve_bounds_inside_unit_square(curve: &Curve2) -> GeometryResult<bool> {
    let Some(CurveGeometry2::RationalBezier(curve)) = curve.geometry() else {
        return Ok(false);
    };
    let Ok(bounds) = curve.certified_bounds() else {
        return Ok(false);
    };
    for point in [bounds.min(), bounds.max()] {
        for coordinate in [point.x(), point.y()] {
            if decided_order(compare_reals(
                coordinate,
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))? == Ordering::Less
                || decided_order(compare_reals(
                    coordinate,
                    &Real::one(),
                    crate::STRICT_PREDICATES,
                ))? == Ordering::Greater
            {
                return Ok(false);
            }
        }
    }
    Ok(true)
}

pub(crate) fn rational_bilinear_parameter_curve(
    surface_points: &[Vec<Point3>],
    surface_weights: &[Vec<Real>],
    pcurve: &Curve2,
) -> GeometryResult<Option<Curve3>> {
    if surface_points.len() != 2
        || surface_weights.len() != 2
        || surface_points
            .iter()
            .zip(surface_weights)
            .any(|(points, weights)| points.len() != 2 || weights.len() != 2)
    {
        return Ok(None);
    }
    let Some(CurveGeometry2::RationalBezier(graph)) = pcurve.geometry() else {
        return Ok(None);
    };
    if graph.degree() != 2 {
        return Ok(None);
    }
    let u: [Real; 3] = std::array::from_fn(|index| graph.homogeneous_controls()[index].x().clone());
    let v: [Real; 3] = std::array::from_fn(|index| graph.homogeneous_controls()[index].y().clone());
    let w: [Real; 3] = std::array::from_fn(|index| graph.weights()[index].clone());
    let w_minus_u = std::array::from_fn(|index| &w[index] - &u[index]);
    let w_minus_v = std::array::from_fn(|index| &w[index] - &v[index]);
    let coefficients = [
        quadratic_bernstein_product(&w_minus_u, &w_minus_v)?,
        quadratic_bernstein_product(&u, &w_minus_v)?,
        quadratic_bernstein_product(&w_minus_u, &v)?,
        quadratic_bernstein_product(&u, &v)?,
    ];
    let corners = [
        &surface_points[0][0],
        &surface_points[0][1],
        &surface_points[1][0],
        &surface_points[1][1],
    ];
    let corner_weights = [
        &surface_weights[0][0],
        &surface_weights[0][1],
        &surface_weights[1][0],
        &surface_weights[1][1],
    ];
    let curve_weights: [Real; 5] = std::array::from_fn(|index| {
        corner_weights
            .iter()
            .zip(&coefficients)
            .fold(Real::zero(), |sum, (weight, coefficients)| {
                sum + *weight * &coefficients[index]
            })
    });
    let mut controls = Vec::with_capacity(5);
    for index in 0..5 {
        let numerator = corners.iter().zip(corner_weights).zip(&coefficients).fold(
            Vector3::zero(),
            |sum, ((point, weight), coefficients)| {
                sum + Vector3::from((*point).clone()) * (weight * &coefficients[index])
            },
        );
        controls.push(Point3::new(
            (&numerator.0[0] / &curve_weights[index]).map_err(GeometryError::Numeric)?,
            (&numerator.0[1] / &curve_weights[index]).map_err(GeometryError::Numeric)?,
            (&numerator.0[2] / &curve_weights[index]).map_err(GeometryError::Numeric)?,
        ));
    }
    Ok(Some(Curve3::rational_bezier(
        controls,
        curve_weights.to_vec(),
    )?))
}

fn quadratic_bernstein_product(first: &[Real; 3], second: &[Real; 3]) -> GeometryResult<[Real; 5]> {
    Ok([
        &first[0] * &second[0],
        ((&first[0] * &second[1] + &first[1] * &second[0]) / Real::from(2))
            .map_err(GeometryError::Numeric)?,
        ((&first[0] * &second[2]
            + Real::from(4) * &first[1] * &second[1]
            + &first[2] * &second[0])
            / Real::from(6))
        .map_err(GeometryError::Numeric)?,
        ((&first[1] * &second[2] + &first[2] * &second[1]) / Real::from(2))
            .map_err(GeometryError::Numeric)?,
        &first[2] * &second[2],
    ])
}

fn bernstein_product(first: &[Real], second: &[Real]) -> GeometryResult<Vec<Real>> {
    let Some(first_degree) = first.len().checked_sub(1) else {
        return Err(GeometryError::InvalidDegree);
    };
    let Some(second_degree) = second.len().checked_sub(1) else {
        return Err(GeometryError::InvalidDegree);
    };
    let product_degree = first_degree
        .checked_add(second_degree)
        .ok_or(GeometryError::InvalidDegree)?;
    let mut product = Vec::with_capacity(product_degree + 1);
    for product_index in 0..=product_degree {
        let first_min = product_index.saturating_sub(second_degree);
        let first_max = first_degree.min(product_index);
        let denominator = binomial_real(product_degree, product_index)?;
        let mut coefficient = Real::zero();
        for (first_index, first_value) in
            first.iter().enumerate().take(first_max + 1).skip(first_min)
        {
            let second_index = product_index - first_index;
            let numerator = binomial_real(first_degree, first_index)?
                * binomial_real(second_degree, second_index)?;
            coefficient += (numerator * first_value * &second[second_index] / &denominator)
                .map_err(GeometryError::Numeric)?;
        }
        product.push(coefficient);
    }
    Ok(product)
}

fn intersect_plane_extrusion(
    plane: &PlaneSurface,
    surface: &ExtrusionSurface,
) -> GeometryResult<SurfaceSurfaceIntersection> {
    let normal = plane.u.cross(&plane.v);
    let denominator = normal.dot(&surface.direction);
    if decided_order(compare_reals(
        &denominator,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? == Ordering::Equal
    {
        let plane_surface = Surface::plane(plane.origin.clone(), plane.u.clone(), plane.v.clone())?;
        return match plane_surface.intersect_curve(&surface.profile)? {
            CurveSurfaceIntersection::None => Ok(SurfaceSurfaceIntersection::None),
            CurveSurfaceIntersection::Contained
            | CurveSurfaceIntersection::Overlap(_)
            | CurveSurfaceIntersection::Components(_) => {
                Err(GeometryError::UnsupportedIntersection)
            }
            CurveSurfaceIntersection::Points(points) => {
                let mut lines = points
                    .into_iter()
                    .map(|point| {
                        Ok(SurfaceIntersectionLine {
                            point: point
                                .point
                                .try_coordinates()
                                .cloned()
                                .ok_or(GeometryError::UnrepresentablePoint)?,
                            direction: surface.direction.clone(),
                        })
                    })
                    .collect::<GeometryResult<Vec<_>>>()?;
                if lines.len() == 1 {
                    Ok(SurfaceSurfaceIntersection::Line(Box::new(
                        lines.pop().expect("one retained extrusion line"),
                    )))
                } else {
                    Ok(SurfaceSurfaceIntersection::Lines(lines))
                }
            }
        };
    }
    if !matches!(
        surface.profile.kind(),
        Curve3Kind::Line | Curve3Kind::RationalBezier | Curve3Kind::Nurbs
    ) {
        return Err(GeometryError::UnsupportedIntersection);
    }
    let curve = project_curve_onto_plane_along_direction(
        &surface.profile,
        plane,
        &surface.direction,
        &denominator,
    )?;
    Ok(SurfaceSurfaceIntersection::Curve(Box::new(
        SurfaceIntersectionCurve::new(
            curve.clone(),
            SurfaceIntersectionPcurve::plane_projection(curve, plane),
            SurfaceIntersectionPcurve::linear_plane_section(
                surface.profile.clone(),
                plane,
                denominator,
                TensorAxis::U,
                Real::one(),
                Real::zero(),
            ),
        ),
    )))
}

fn intersect_plane_revolution(
    plane: &PlaneSurface,
    surface: &RevolutionSurface,
) -> GeometryResult<SurfaceSurfaceIntersection> {
    let normal = plane.u.cross(&plane.v);
    if decided_order(compare_reals(
        &normal.cross(&surface.axis).norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? != Ordering::Equal
    {
        return Err(GeometryError::UnsupportedIntersection);
    }
    let plane_surface = Surface::plane(plane.origin.clone(), plane.u.clone(), plane.v.clone())?;
    let points = match plane_surface.intersect_curve(&surface.profile)? {
        CurveSurfaceIntersection::None => return Ok(SurfaceSurfaceIntersection::None),
        CurveSurfaceIntersection::Contained
        | CurveSurfaceIntersection::Overlap(_)
        | CurveSurfaceIntersection::Components(_) => {
            return Err(GeometryError::UnsupportedIntersection);
        }
        CurveSurfaceIntersection::Points(points) => points,
    };
    let mut sections = Vec::with_capacity(points.len());
    let mut singular = None;
    let mut radii = Vec::<Real>::with_capacity(points.len());
    for point in points {
        let relative = point
            .point
            .try_coordinates()
            .ok_or(GeometryError::UnrepresentablePoint)?
            - &surface.axis_origin;
        let axial_parameter = relative.dot(&surface.axis);
        let center = surface.axis_origin.clone() + surface.axis.clone() * axial_parameter.clone();
        let radial = relative - surface.axis.clone() * axial_parameter;
        let radius_squared = radial.norm_squared();
        if decided_order(compare_reals(
            &radius_squared,
            &Real::zero(),
            crate::STRICT_PREDICATES,
        ))? == Ordering::Equal
        {
            if singular.replace(center).is_some() {
                return Err(GeometryError::UnsupportedIntersection);
            }
            continue;
        }
        let radius = radius_squared.sqrt().map_err(GeometryError::Numeric)?;
        for existing in &radii {
            if decided_order(compare_reals(existing, &radius, crate::STRICT_PREDICATES))?
                == Ordering::Equal
            {
                return Err(GeometryError::UnsupportedIntersection);
            }
        }
        radii.push(radius.clone());
        let radial_direction = (radial / &radius).map_err(GeometryError::Numeric)?;
        let curve = Curve3::circle_arc(
            center,
            radial_direction.clone(),
            surface.axis.cross(&radial_direction),
            radius,
            Real::zero(),
            Real::tau(),
        )?;
        let domain = curve.domain().clone();
        sections.push(SurfaceIntersectionCurve::new(
            curve.clone(),
            SurfaceIntersectionPcurve::plane_projection(curve, plane),
            SurfaceIntersectionPcurve::tensor_iso_v(
                domain,
                point
                    .parameter
                    .try_real()
                    .cloned()
                    .ok_or(GeometryError::UnrepresentableParameter)?,
            ),
        ));
    }
    if let Some(point) = singular {
        if sections.is_empty() {
            return Ok(SurfaceSurfaceIntersection::Point(Box::new((point).into())));
        }
        return Err(GeometryError::UnsupportedIntersection);
    }
    Ok(match sections.len() {
        0 => SurfaceSurfaceIntersection::None,
        1 => SurfaceSurfaceIntersection::Curve(Box::new(
            sections.pop().expect("one revolution section"),
        )),
        _ => SurfaceSurfaceIntersection::Curves(sections),
    })
}

struct ProjectedRevolutionMeridian {
    curve: Curve2,
    radial_direction: Vector3,
}

fn project_revolution_meridian(
    surface: &RevolutionSurface,
    common_axis_origin: &Point3,
    common_axis: &Vector3,
) -> GeometryResult<ProjectedRevolutionMeridian> {
    let controls = match surface.profile.exact_data() {
        Curve3ExactData::Line(line) => vec![line.start, line.end],
        Curve3ExactData::RationalBezier { control_points, .. }
        | Curve3ExactData::Nurbs { control_points, .. } => control_points,
        Curve3ExactData::AffineImage(_)
        | Curve3ExactData::Rotation(_)
        | Curve3ExactData::Translation(_)
        | Curve3ExactData::EllipseArc(_)
        | Curve3ExactData::PlanarImage(_) => {
            return Err(GeometryError::UnsupportedIntersection);
        }
    };
    let radials = controls
        .iter()
        .map(|control| {
            let relative = control - common_axis_origin;
            &relative - &(common_axis.clone() * relative.dot(common_axis))
        })
        .collect::<Vec<_>>();
    let mut first_nonzero_radial = None;
    for radial in &radials {
        if decided_order(compare_reals(
            &radial.norm_squared(),
            &Real::zero(),
            crate::STRICT_PREDICATES,
        ))? != Ordering::Equal
        {
            first_nonzero_radial = Some(radial);
            break;
        }
    }
    let radial = first_nonzero_radial.ok_or(GeometryError::UnsupportedIntersection)?;
    let radial_length = radial
        .norm_squared()
        .sqrt()
        .map_err(GeometryError::Numeric)?;
    let radial_direction = (radial.clone() / &radial_length).map_err(GeometryError::Numeric)?;
    for radial in &radials {
        if decided_order(compare_reals(
            &radial.cross(&radial_direction).norm_squared(),
            &Real::zero(),
            crate::STRICT_PREDICATES,
        ))? != Ordering::Equal
            || decided_order(compare_reals(
                &radial.dot(&radial_direction),
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))? != Ordering::Greater
        {
            return Err(GeometryError::UnsupportedIntersection);
        }
    }
    let curve = project_curve_to_plane_frame(
        &surface.profile,
        common_axis_origin,
        &radial_direction,
        common_axis,
    )?
    .ok_or(GeometryError::UnsupportedIntersection)?;
    Ok(ProjectedRevolutionMeridian {
        curve,
        radial_direction,
    })
}

fn intersect_coaxial_revolutions(
    first: &RevolutionSurface,
    second: &RevolutionSurface,
) -> GeometryResult<SurfaceSurfaceIntersection> {
    if decided_order(compare_reals(
        &first.axis.cross(&second.axis).norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? != Ordering::Equal
    {
        return Err(GeometryError::UnsupportedIntersection);
    }
    let axis_offset = &second.axis_origin - &first.axis_origin;
    let radial_axis_offset = &axis_offset - &(first.axis.clone() * axis_offset.dot(&first.axis));
    if decided_order(compare_reals(
        &radial_axis_offset.norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? != Ordering::Equal
    {
        return Err(GeometryError::UnsupportedIntersection);
    }
    let axis_dot = first.axis.dot(&second.axis);
    let frames_mirrored = if decided_order(compare_reals(
        &axis_dot,
        &Real::one(),
        crate::STRICT_PREDICATES,
    ))? == Ordering::Equal
    {
        false
    } else if decided_order(compare_reals(
        &axis_dot,
        &-Real::one(),
        crate::STRICT_PREDICATES,
    ))? == Ordering::Equal
    {
        true
    } else {
        return Err(GeometryError::UnsupportedIntersection);
    };

    let first_meridian = project_revolution_meridian(first, &first.axis_origin, &first.axis)?;
    let second_meridian = project_revolution_meridian(second, &first.axis_origin, &first.axis)?;
    if first_meridian.curve == second_meridian.curve
        || first_meridian.curve == second_meridian.curve.reversed()?
    {
        return Ok(SurfaceSurfaceIntersection::Coincident);
    }

    let intersections = first_meridian
        .curve
        .intersect_curve(&second_meridian.curve)?;
    if !intersections.is_complete() || !intersections.overlaps().is_empty() {
        return Err(GeometryError::UnsupportedIntersection);
    }
    if intersections.is_disjoint() {
        return Ok(SurfaceSurfaceIntersection::None);
    }

    let radial_frames_equal = decided_order(compare_reals(
        &(&first_meridian.radial_direction - &second_meridian.radial_direction).norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? == Ordering::Equal;
    let retain_pcurves = radial_frames_equal;
    let mut circles = Vec::with_capacity(intersections.contacts().len());
    let mut retained = Vec::with_capacity(intersections.contacts().len());
    let mut locations = Vec::<(Real, Real)>::with_capacity(intersections.contacts().len());
    for contact in intersections.contacts() {
        let first_parameter =
            resolve_planar_classification(crate::error::classified(contact.first().parameter())?)?;
        let second_parameter =
            resolve_planar_classification(crate::error::classified(contact.second().parameter())?)?;
        // Spatial isoparametric pcurves currently require scalar parameters.
        let first_parameter = first_parameter
            .scalar()
            .cloned()
            .ok_or(GeometryError::UnrepresentableParameter)?;
        let second_parameter = second_parameter
            .scalar()
            .cloned()
            .ok_or(GeometryError::UnrepresentableParameter)?;
        let first_point = first_meridian
            .curve
            .point_at(&first_parameter.clone().into())?;
        let second_point = second_meridian
            .curve
            .point_at(&second_parameter.clone().into())?;
        let first_point = first_point
            .coordinates()
            .ok_or(GeometryError::UnrepresentableParameter)?;
        let second_point = second_point
            .coordinates()
            .ok_or(GeometryError::UnrepresentableParameter)?;
        if decided_order(compare_reals(
            first_point.x(),
            second_point.x(),
            crate::STRICT_PREDICATES,
        ))? != Ordering::Equal
            || decided_order(compare_reals(
                first_point.y(),
                second_point.y(),
                crate::STRICT_PREDICATES,
            ))? != Ordering::Equal
        {
            return Err(GeometryError::UnsupportedIntersection);
        }
        for (radius, height) in &locations {
            if decided_order(compare_reals(
                radius,
                first_point.x(),
                crate::STRICT_PREDICATES,
            ))? == Ordering::Equal
                && decided_order(compare_reals(
                    height,
                    first_point.y(),
                    crate::STRICT_PREDICATES,
                ))? == Ordering::Equal
            {
                return Err(GeometryError::UnsupportedIntersection);
            }
        }
        locations.push((first_point.x().clone(), first_point.y().clone()));
        let center = first.axis_origin.clone() + first.axis.clone() * first_point.y().clone();
        let curve = Curve3::circle_arc(
            center,
            first_meridian.radial_direction.clone(),
            first.axis.cross(&first_meridian.radial_direction),
            first_point.x().clone(),
            Real::zero(),
            Real::tau(),
        )?;
        if retain_pcurves {
            let domain = curve.domain().clone();
            retained.push(SurfaceIntersectionCurve::new(
                curve,
                SurfaceIntersectionPcurve::tensor_iso_v(domain.clone(), first_parameter),
                angular_iso_v_pcurve(domain, second_parameter, frames_mirrored),
            ));
        } else {
            circles.push(curve);
        }
    }
    if retain_pcurves {
        Ok(match retained.len() {
            1 => SurfaceSurfaceIntersection::Curve(Box::new(
                retained.pop().expect("one revolution/revolution circle"),
            )),
            _ => SurfaceSurfaceIntersection::Curves(retained),
        })
    } else {
        Ok(match circles.len() {
            1 => SurfaceSurfaceIntersection::Circle(
                circles.pop().expect("one revolution/revolution circle"),
            ),
            _ => SurfaceSurfaceIntersection::Circles(circles),
        })
    }
}

fn intersect_plane_nurbs_surface(
    plane: &PlaneSurface,
    surface: &NurbsSurface,
) -> GeometryResult<SurfaceSurfaceIntersection> {
    if surface.u_degree == 1
        && let Some(direction) =
            linear_tensor_u_direction(&surface.control_points, &surface.weights)?
    {
        let profile_controls = surface
            .control_points
            .iter()
            .map(|row| row[0].clone())
            .collect::<Vec<_>>();
        let profile_weights = surface
            .weights
            .iter()
            .map(|row| row[0].clone())
            .collect::<Vec<_>>();
        let profile = Curve3::nurbs(
            surface.v_degree,
            profile_controls.clone(),
            profile_weights,
            surface.v_knots.clone(),
        )?;
        let coefficient_offset = surface.u_knots[surface.u_degree].clone();
        let coefficient_scale =
            &surface.u_knots[surface.control_points[0].len()] - &coefficient_offset;
        match intersect_plane_linear_tensor_graph(
            plane,
            profile,
            &profile_controls,
            direction,
            TensorAxis::V,
            coefficient_scale,
            coefficient_offset,
        ) {
            Ok(intersection) => return Ok(intersection),
            Err(GeometryError::UnsupportedIntersection) => {}
            Err(error) => return Err(error),
        }
    }
    if surface.v_degree == 1
        && let Some(direction) =
            linear_tensor_v_direction(&surface.control_points, &surface.weights)?
    {
        let profile = Curve3::nurbs(
            surface.u_degree,
            surface.control_points[0].clone(),
            surface.weights[0].clone(),
            surface.u_knots.clone(),
        )?;
        let coefficient_offset = surface.v_knots[surface.v_degree].clone();
        let coefficient_scale =
            &surface.v_knots[surface.control_points.len()] - &coefficient_offset;
        return intersect_plane_v_linear_tensor_iso(
            plane,
            profile,
            &surface.control_points[0],
            direction,
            coefficient_scale,
            coefficient_offset,
        );
    }
    intersect_plane_projective_bilinear_nurbs(plane, surface)
}

fn intersect_plane_projective_bilinear_nurbs(
    plane: &PlaneSurface,
    surface: &NurbsSurface,
) -> GeometryResult<SurfaceSurfaceIntersection> {
    if surface.u_degree != 1
        || surface.v_degree != 1
        || surface.control_points.len() != 2
        || surface.weights.len() != 2
        || surface
            .control_points
            .iter()
            .zip(&surface.weights)
            .any(|(points, weights)| points.len() != 2 || weights.len() != 2)
    {
        return Err(GeometryError::UnsupportedIntersection);
    }
    let bezier = RationalBezierSurface {
        control_points: surface.control_points.clone(),
        weights: surface.weights.clone(),
        homogeneous_controls: OnceLock::new(),
    };
    let intersection = intersect_plane_rational_bilinear(plane, &bezier)?;
    let u_start = surface.u_knots[surface.u_degree].clone();
    let u_span = &surface.u_knots[surface.control_points[0].len()] - &u_start;
    let v_start = surface.v_knots[surface.v_degree].clone();
    let v_span = &surface.v_knots[surface.control_points.len()] - &v_start;
    let remap = |mut section: SurfaceIntersectionCurve| -> GeometryResult<_> {
        section.second_pcurve =
            remap_unit_tensor_pcurve(section.second_pcurve, &u_start, &u_span, &v_start, &v_span)?;
        Ok(section)
    };
    Ok(match intersection {
        SurfaceSurfaceIntersection::Curve(section) => {
            SurfaceSurfaceIntersection::Curve(Box::new(remap(*section)?))
        }
        SurfaceSurfaceIntersection::Curves(sections) => SurfaceSurfaceIntersection::Curves(
            sections
                .into_iter()
                .map(remap)
                .collect::<GeometryResult<Vec<_>>>()?,
        ),
        other => other,
    })
}

fn remap_unit_tensor_pcurve(
    pcurve: SurfaceIntersectionPcurve,
    u_start: &Real,
    u_span: &Real,
    v_start: &Real,
    v_span: &Real,
) -> GeometryResult<SurfaceIntersectionPcurve> {
    let SurfaceIntersectionPcurve {
        domain,
        source_scale,
        source_offset,
        mapping,
    } = pcurve;
    let SurfaceIntersectionPcurveMapping::RetainedCurve { curve } = mapping else {
        return Err(GeometryError::UnsupportedIntersection);
    };
    let map = |point: &CurvePoint2| {
        CurvePoint2::new(u_start + u_span * point.x(), v_start + v_span * point.y())
    };
    let curve = match curve.geometry() {
        Some(CurveGeometry2::Line(line)) => {
            Curve2::from(LineSeg2::try_new(map(line.start()), map(line.end()))?)
        }
        Some(CurveGeometry2::RationalBezier(curve)) => {
            let controls = curve
                .homogeneous_controls()
                .iter()
                .map(|control| {
                    hypercurve::HomogeneousControl2::new(
                        u_start * control.weight() + u_span * control.x(),
                        v_start * control.weight() + v_span * control.y(),
                        control.weight().clone(),
                    )
                })
                .collect();
            let Classification::Decided(curve) =
                crate::error::classified(RationalBezier2::from_homogeneous_controls(controls))?
            else {
                return Err(GeometryError::UnsupportedIntersection);
            };
            Curve2::from(curve)
        }
        _ => return Err(GeometryError::UnsupportedIntersection),
    };
    Ok(SurfaceIntersectionPcurve {
        domain,
        source_scale,
        source_offset,
        mapping: SurfaceIntersectionPcurveMapping::RetainedCurve { curve },
    })
}

fn linear_tensor_u_direction(
    control_points: &[Vec<Point3>],
    weights: &[Vec<Real>],
) -> GeometryResult<Option<Vector3>> {
    if control_points.is_empty()
        || control_points.len() != weights.len()
        || control_points
            .iter()
            .zip(weights)
            .any(|(points, row_weights)| points.len() != 2 || row_weights.len() != 2)
    {
        return Ok(None);
    }
    for row in weights {
        if decided_order(compare_reals(&row[0], &row[1], crate::STRICT_PREDICATES))?
            != Ordering::Equal
        {
            return Ok(None);
        }
    }
    let direction = &control_points[0][1] - &control_points[0][0];
    if decided_order(compare_reals(
        &direction.norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? != Ordering::Greater
    {
        return Ok(None);
    }
    for row in control_points {
        if !points_equal(&(row[0].clone() + direction.clone()), &row[1])? {
            return Ok(None);
        }
    }
    Ok(Some(direction))
}

fn linear_tensor_v_direction(
    control_points: &[Vec<Point3>],
    weights: &[Vec<Real>],
) -> GeometryResult<Option<Vector3>> {
    if control_points.len() != 2
        || weights.len() != 2
        || control_points[0].len() != control_points[1].len()
        || weights[0].len() != weights[1].len()
    {
        return Ok(None);
    }
    for (first, second) in weights[0].iter().zip(&weights[1]) {
        if decided_order(compare_reals(first, second, crate::STRICT_PREDICATES))? != Ordering::Equal
        {
            return Ok(None);
        }
    }
    let direction = &control_points[1][0] - &control_points[0][0];
    if decided_order(compare_reals(
        &direction.norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? != Ordering::Greater
    {
        return Ok(None);
    }
    for (first, second) in control_points[0].iter().zip(&control_points[1]) {
        if !points_equal(&(first.clone() + direction.clone()), second)? {
            return Ok(None);
        }
    }
    Ok(Some(direction))
}

fn intersect_plane_linear_tensor_graph(
    plane: &PlaneSurface,
    profile: Curve3,
    profile_controls: &[Point3],
    direction: Vector3,
    profile_axis: TensorAxis,
    coefficient_scale: Real,
    coefficient_offset: Real,
) -> GeometryResult<SurfaceSurfaceIntersection> {
    let normal = plane.u.cross(&plane.v);
    let signed_plane_value = |point: &Point3| normal.dot(&(point - &plane.origin));
    let values = profile_controls
        .iter()
        .map(signed_plane_value)
        .collect::<Vec<_>>();
    let denominator = normal.dot(&direction);
    if decided_order(compare_reals(
        &denominator,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? == Ordering::Equal
    {
        if curve_is_strictly_on_one_plane_side(&profile, &signed_plane_value)? {
            return Ok(SurfaceSurfaceIntersection::None);
        }
        let plane_surface = Surface::plane(plane.origin.clone(), plane.u.clone(), plane.v.clone())?;
        return match plane_surface.intersect_curve(&profile)? {
            CurveSurfaceIntersection::None => Ok(SurfaceSurfaceIntersection::None),
            CurveSurfaceIntersection::Contained
            | CurveSurfaceIntersection::Overlap(_)
            | CurveSurfaceIntersection::Components(_) => {
                Err(GeometryError::UnsupportedIntersection)
            }
            CurveSurfaceIntersection::Points(points) => {
                let mut curves = points
                    .into_iter()
                    .map(|point| {
                        let coordinates = point
                            .point
                            .try_coordinates()
                            .ok_or(GeometryError::UnrepresentablePoint)?;
                        let curve = Curve3::line(
                            coordinates.clone(),
                            coordinates.clone() + direction.clone(),
                        )?;
                        Ok(SurfaceIntersectionCurve::new(
                            curve.clone(),
                            SurfaceIntersectionPcurve::plane_projection(curve.clone(), plane),
                            SurfaceIntersectionPcurve::tensor_iso(
                                curve.domain().clone(),
                                point
                                    .parameter
                                    .try_real()
                                    .cloned()
                                    .ok_or(GeometryError::UnrepresentableParameter)?,
                                profile_axis,
                                coefficient_scale.clone(),
                                coefficient_offset.clone(),
                            ),
                        ))
                    })
                    .collect::<GeometryResult<Vec<_>>>()?;
                Ok(match curves.as_mut_slice() {
                    [curve] => SurfaceSurfaceIntersection::Curve(Box::new(curve.clone())),
                    _ => SurfaceSurfaceIntersection::Curves(curves),
                })
            }
        };
    }

    let coefficients = values
        .into_iter()
        .map(|value| ((-value) / &denominator).map_err(GeometryError::Numeric))
        .collect::<GeometryResult<Vec<_>>>()?;
    let coefficient_orders = coefficients
        .iter()
        .map(|coefficient| {
            Ok((
                decided_order(compare_reals(
                    coefficient,
                    &Real::zero(),
                    crate::STRICT_PREDICATES,
                ))?,
                decided_order(compare_reals(
                    coefficient,
                    &Real::one(),
                    crate::STRICT_PREDICATES,
                ))?,
            ))
        })
        .collect::<GeometryResult<Vec<_>>>()?;
    if coefficient_orders
        .iter()
        .all(|(zero, _)| *zero == Ordering::Less)
        || coefficient_orders
            .iter()
            .all(|(_, one)| *one == Ordering::Greater)
    {
        return Ok(SurfaceSurfaceIntersection::None);
    }
    let complete = coefficient_orders.iter().all(|(zero, one)| {
        matches!(zero, Ordering::Equal | Ordering::Greater)
            && matches!(one, Ordering::Equal | Ordering::Less)
    });

    let curve =
        project_curve_onto_plane_along_direction(&profile, plane, &direction, &denominator)?;
    let section = SurfaceIntersectionCurve::new(
        curve.clone(),
        SurfaceIntersectionPcurve::plane_projection(curve, plane),
        SurfaceIntersectionPcurve::linear_plane_section(
            profile,
            plane,
            denominator,
            profile_axis,
            coefficient_scale.clone(),
            coefficient_offset.clone(),
        ),
    );
    if complete {
        return Ok(SurfaceSurfaceIntersection::Curve(Box::new(section)));
    }
    clip_linear_tensor_section(
        &section,
        profile_axis,
        &coefficient_offset,
        &(&coefficient_offset + coefficient_scale),
    )
}

fn curve_is_strictly_on_one_plane_side(
    curve: &Curve3,
    signed_plane_value: &impl Fn(&Point3) -> Real,
) -> GeometryResult<bool> {
    let controls_are_strictly_one_sided = |controls: &[Point3]| -> GeometryResult<bool> {
        let orders = controls
            .iter()
            .map(|point| {
                decided_order(compare_reals(
                    &signed_plane_value(point),
                    &Real::zero(),
                    crate::STRICT_PREDICATES,
                ))
            })
            .collect::<GeometryResult<Vec<_>>>()?;
        let endpoints_are = |side| orders.first() == Some(&side) && orders.last() == Some(&side);
        Ok((endpoints_are(Ordering::Greater)
            && orders
                .iter()
                .all(|order| matches!(order, Ordering::Greater | Ordering::Equal)))
            || (endpoints_are(Ordering::Less)
                && orders
                    .iter()
                    .all(|order| matches!(order, Ordering::Less | Ordering::Equal))))
    };

    match &curve.data.geometry {
        CurveGeometry3::Line(line) => {
            controls_are_strictly_one_sided(&[line.start.clone(), line.end.clone()])
        }
        CurveGeometry3::RationalBezier(curve) => {
            controls_are_strictly_one_sided(&curve.control_points)
        }
        CurveGeometry3::Nurbs(curve) => {
            for (span, _) in decompose_nurbs_into_bezier_segments(curve)? {
                let CurveGeometry3::RationalBezier(span) = &span.data.geometry else {
                    unreachable!("NURBS decomposition produces rational Bézier spans");
                };
                if !controls_are_strictly_one_sided(&span.control_points)? {
                    return Ok(false);
                }
            }
            Ok(true)
        }
        CurveGeometry3::CircleArc(_)
        | CurveGeometry3::EllipseArc(_)
        | CurveGeometry3::AffineImage(_)
        | CurveGeometry3::Rotation(_)
        | CurveGeometry3::Translation(_)
        | CurveGeometry3::PlanarImage(_) => Ok(false),
    }
}

fn clip_linear_tensor_section(
    section: &SurfaceIntersectionCurve,
    profile_axis: TensorAxis,
    coefficient_start: &Real,
    coefficient_end: &Real,
) -> GeometryResult<SurfaceSurfaceIntersection> {
    let profile_start = section.curve.domain().represented_start()?;
    let profile_end = section.curve.domain().represented_end()?;
    let region = tensor_parameter_region(
        profile_axis,
        profile_start,
        profile_end,
        coefficient_start,
        coefficient_end,
    )?;
    let materialized = section.second_pcurve.materialize()?;
    let trimmed = materialized
        .curve()
        .trim_inside_region_with_parameters(&region)?;
    let mut intervals: Vec<(Real, Real)> = Vec::with_capacity(trimmed.len());
    for fragment in trimmed {
        let Some((pcurve_start, pcurve_end)) = fragment.represented_parameter_range() else {
            return Err(GeometryError::UnrepresentableParameter);
        };
        let spatial_start = materialized
            .spatial_parameter_at(&pcurve_start.into())?
            .try_real()
            .cloned()
            .ok_or(GeometryError::UnrepresentableParameter)?;
        let spatial_end = materialized
            .spatial_parameter_at(&pcurve_end.into())?
            .try_real()
            .cloned()
            .ok_or(GeometryError::UnrepresentableParameter)?;
        if let Some((_, previous_end)) = intervals.last_mut()
            && decided_order(compare_reals(
                previous_end,
                &spatial_start,
                crate::STRICT_PREDICATES,
            ))? == Ordering::Equal
        {
            *previous_end = spatial_end;
        } else {
            intervals.push((spatial_start, spatial_end));
        }
    }
    let mut fragments = intervals
        .into_iter()
        .map(|(start, end)| section.subcurve(&start, &end))
        .collect::<GeometryResult<Vec<_>>>()?;
    match fragments.len() {
        0 => Err(GeometryError::UnsupportedIntersection),
        1 => Ok(SurfaceSurfaceIntersection::Curve(Box::new(
            fragments.pop().expect("one retained fragment"),
        ))),
        _ => Ok(SurfaceSurfaceIntersection::Curves(fragments)),
    }
}

fn tensor_parameter_region(
    profile_axis: TensorAxis,
    profile_start: &Real,
    profile_end: &Real,
    coefficient_start: &Real,
    coefficient_end: &Real,
) -> GeometryResult<CurveRegion2> {
    let points = match profile_axis {
        TensorAxis::U => [
            CurvePoint2::new(profile_start.clone(), coefficient_start.clone()),
            CurvePoint2::new(profile_end.clone(), coefficient_start.clone()),
            CurvePoint2::new(profile_end.clone(), coefficient_end.clone()),
            CurvePoint2::new(profile_start.clone(), coefficient_end.clone()),
        ],
        TensorAxis::V => [
            CurvePoint2::new(coefficient_start.clone(), profile_start.clone()),
            CurvePoint2::new(coefficient_end.clone(), profile_start.clone()),
            CurvePoint2::new(coefficient_end.clone(), profile_end.clone()),
            CurvePoint2::new(coefficient_start.clone(), profile_end.clone()),
        ],
    };
    let contour = Contour2::try_new(
        (0..points.len())
            .map(|index| {
                LineSeg2::try_new(
                    points[index].clone(),
                    points[(index + 1) % points.len()].clone(),
                )
                .map(Segment2::Line)
            })
            .collect::<Result<Vec<_>, _>>()?,
    )?;
    Ok(CurveRegion2::try_from_native_material_contours(vec![
        contour,
    ])?)
}

fn project_curve_onto_plane_along_direction(
    curve: &Curve3,
    plane: &PlaneSurface,
    direction: &Vector3,
    denominator: &Real,
) -> GeometryResult<Curve3> {
    let normal = plane.u.cross(&plane.v);
    let constant = normal.dot(&Vector3::from(plane.origin.clone()));
    let ratio = |row: usize, column: usize| {
        ((&direction.0[row] * &normal.0[column]) / denominator).map_err(GeometryError::Numeric)
    };
    let translation = |row: usize| {
        ((&direction.0[row] * &constant) / denominator).map_err(GeometryError::Numeric)
    };
    let projection = Matrix4::from_row_major([
        Real::one() - ratio(0, 0)?,
        -ratio(0, 1)?,
        -ratio(0, 2)?,
        translation(0)?,
        -ratio(1, 0)?,
        Real::one() - ratio(1, 1)?,
        -ratio(1, 2)?,
        translation(1)?,
        -ratio(2, 0)?,
        -ratio(2, 1)?,
        Real::one() - ratio(2, 2)?,
        translation(2)?,
        Real::zero(),
        Real::zero(),
        Real::zero(),
        Real::one(),
    ]);
    curve.transformed(&projection)
}

fn intersect_plane_v_linear_tensor_iso(
    plane: &PlaneSurface,
    profile: Curve3,
    profile_controls: &[Point3],
    direction: Vector3,
    coefficient_scale: Real,
    coefficient_offset: Real,
) -> GeometryResult<SurfaceSurfaceIntersection> {
    let normal = plane.u.cross(&plane.v);
    let plane_value = |point: &Point3| normal.dot(&(point - &plane.origin));
    let offset = plane_value(&profile_controls[0]);
    for control in profile_controls.iter().skip(1) {
        if decided_order(compare_reals(
            &plane_value(control),
            &offset,
            crate::STRICT_PREDICATES,
        ))? != Ordering::Equal
        {
            return intersect_plane_linear_tensor_graph(
                plane,
                profile,
                profile_controls,
                direction,
                TensorAxis::U,
                coefficient_scale,
                coefficient_offset,
            );
        }
    }
    let denominator = normal.dot(&direction);
    if decided_order(compare_reals(
        &denominator,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? == Ordering::Equal
    {
        return if decided_order(compare_reals(
            &offset,
            &Real::zero(),
            crate::STRICT_PREDICATES,
        ))? == Ordering::Equal
        {
            Err(GeometryError::UnsupportedIntersection)
        } else {
            Ok(SurfaceSurfaceIntersection::None)
        };
    }
    let normalized_fraction = ((-offset) / denominator).map_err(GeometryError::Numeric)?;
    if decided_order(compare_reals(
        &normalized_fraction,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? == Ordering::Less
        || decided_order(compare_reals(
            &normalized_fraction,
            &Real::one(),
            crate::STRICT_PREDICATES,
        ))? == Ordering::Greater
    {
        return Ok(SurfaceSurfaceIntersection::None);
    }
    let translated = profile.transformed(&Matrix4::affine_translation([
        direction.0[0].clone() * &normalized_fraction,
        direction.0[1].clone() * &normalized_fraction,
        direction.0[2].clone() * &normalized_fraction,
    ]))?;
    let surface_parameter = coefficient_offset + coefficient_scale * normalized_fraction;
    Ok(SurfaceSurfaceIntersection::Curve(Box::new(
        SurfaceIntersectionCurve::new(
            translated.clone(),
            SurfaceIntersectionPcurve::plane_projection(translated, plane),
            SurfaceIntersectionPcurve::tensor_iso_v(profile.domain().clone(), surface_parameter),
        ),
    )))
}

fn intersect_plane_sphere(
    plane: &PlaneSurface,
    sphere: &SphereSurface,
) -> GeometryResult<SurfaceSurfaceIntersection> {
    let normal = plane.u.cross(&plane.v);
    let normal_squared = normal.norm_squared();
    let axial = decided_order(compare_reals(
        &normal.cross(&sphere.frame.z).norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? == Ordering::Equal;
    let separation = normal.dot(&(&sphere.center - &plane.origin));
    let distance_squared =
        ((&separation * &separation) / &normal_squared).map_err(GeometryError::Numeric)?;
    let radius_squared = &sphere.radius * &sphere.radius;
    match decided_order(compare_reals(
        &distance_squared,
        &radius_squared,
        crate::STRICT_PREDICATES,
    ))? {
        Ordering::Greater => Ok(SurfaceSurfaceIntersection::None),
        Ordering::Equal | Ordering::Less => {
            let projection_scale =
                (&separation / &normal_squared).map_err(GeometryError::Numeric)?;
            let center = sphere.center.clone() - normal.clone() * projection_scale;
            if decided_order(compare_reals(
                &distance_squared,
                &radius_squared,
                crate::STRICT_PREDICATES,
            ))? == Ordering::Equal
            {
                return Ok(SurfaceSurfaceIntersection::Point(Box::new((center).into())));
            }
            let radius = (radius_squared - distance_squared)
                .sqrt()
                .map_err(GeometryError::Numeric)?;
            if axial {
                let height = ((-&separation) / normal.dot(&sphere.frame.z))
                    .map_err(GeometryError::Numeric)?;
                let center = sphere.center.clone() + sphere.frame.z.clone() * &height;
                let curve = Curve3::circle_arc(
                    center,
                    sphere.frame.x.clone(),
                    sphere.frame.y.clone(),
                    radius,
                    Real::zero(),
                    Real::tau(),
                )?;
                let latitude = (height / &sphere.radius)
                    .map_err(GeometryError::Numeric)?
                    .asin()
                    .map_err(GeometryError::Numeric)?;
                let domain = curve.domain().clone();
                return Ok(SurfaceSurfaceIntersection::Curve(Box::new(
                    SurfaceIntersectionCurve::new(
                        curve.clone(),
                        SurfaceIntersectionPcurve::plane_projection(curve, plane),
                        SurfaceIntersectionPcurve::tensor_iso_v(domain, latitude),
                    ),
                )));
            }
            let unit_normal = normal.normalize().map_err(GeometryError::Numeric)?;
            let x = plane.u.normalize().map_err(GeometryError::Numeric)?;
            let y = unit_normal.cross(&x);
            Ok(SurfaceSurfaceIntersection::Circle(Curve3::circle_arc(
                center,
                x,
                y,
                radius,
                Real::zero(),
                Real::from(2) * Real::pi(),
            )?))
        }
    }
}

fn intersect_plane_cylinder(
    plane: &PlaneSurface,
    cylinder: &CylinderSurface,
) -> GeometryResult<SurfaceSurfaceIntersection> {
    let normal = plane.u.cross(&plane.v);
    let normal_squared = normal.norm_squared();
    let axis_cross_normal = cylinder.frame.z.cross(&normal);
    if decided_order(compare_reals(
        &axis_cross_normal.norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? == Ordering::Equal
    {
        let denominator = normal.dot(&cylinder.frame.z);
        let numerator = normal.dot(&(&plane.origin - &cylinder.origin));
        let axial_parameter = (numerator / denominator).map_err(GeometryError::Numeric)?;
        let center = cylinder.origin.clone() + cylinder.frame.z.clone() * axial_parameter.clone();
        let curve = Curve3::circle_arc(
            center,
            cylinder.frame.x.clone(),
            cylinder.frame.y.clone(),
            cylinder.radius.clone(),
            Real::zero(),
            Real::from(2) * Real::pi(),
        )?;
        let domain = curve.domain().clone();
        return Ok(SurfaceSurfaceIntersection::Curve(Box::new(
            SurfaceIntersectionCurve::new(
                curve.clone(),
                SurfaceIntersectionPcurve::plane_projection(curve, plane),
                SurfaceIntersectionPcurve::tensor_iso_v(domain, axial_parameter),
            ),
        )));
    }

    let axis_dot_normal = cylinder.frame.z.dot(&normal);
    if decided_order(compare_reals(
        &axis_dot_normal,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? != Ordering::Equal
    {
        let separation = normal.dot(&(&plane.origin - &cylinder.origin));
        let axial_center = (separation / &axis_dot_normal).map_err(GeometryError::Numeric)?;
        let center = cylinder.origin.clone() + cylinder.frame.z.clone() * axial_center;
        let radial_normal = normal.clone() - cylinder.frame.z.clone() * axis_dot_normal.clone();
        let radial_normal_length = radial_normal
            .norm_squared()
            .sqrt()
            .map_err(GeometryError::Numeric)?;
        let radial_parallel =
            (radial_normal / &radial_normal_length).map_err(GeometryError::Numeric)?;
        let radial_perpendicular = cylinder.frame.z.cross(&radial_parallel);
        let slope = (&radial_normal_length / &axis_dot_normal).map_err(GeometryError::Numeric)?;
        let sloped_axis = radial_parallel - cylinder.frame.z.clone() * slope;
        let sloped_length = sloped_axis
            .norm_squared()
            .sqrt()
            .map_err(GeometryError::Numeric)?;
        let sloped_direction = (sloped_axis / &sloped_length).map_err(GeometryError::Numeric)?;
        return Ok(SurfaceSurfaceIntersection::Ellipse(Curve3::ellipse_arc(
            center,
            radial_perpendicular,
            sloped_direction,
            cylinder.radius.clone(),
            cylinder.radius.clone() * sloped_length,
            Real::zero(),
            Real::from(2) * Real::pi(),
        )?));
    }
    let separation = normal.dot(&(&plane.origin - &cylinder.origin));
    let distance_squared =
        ((&separation * &separation) / &normal_squared).map_err(GeometryError::Numeric)?;
    let radius_squared = &cylinder.radius * &cylinder.radius;
    match decided_order(compare_reals(
        &distance_squared,
        &radius_squared,
        crate::STRICT_PREDICATES,
    ))? {
        Ordering::Greater => Ok(SurfaceSurfaceIntersection::None),
        Ordering::Equal | Ordering::Less => {
            let projection_scale =
                (separation / &normal_squared).map_err(GeometryError::Numeric)?;
            let radial_projection = normal.clone() * projection_scale;
            let line_offset_squared = &radius_squared - &distance_squared;
            let tangent = cylinder
                .frame
                .z
                .cross(&normal)
                .normalize()
                .map_err(GeometryError::Numeric)?;
            if decided_order(compare_reals(
                &line_offset_squared,
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))? == Ordering::Equal
            {
                return Ok(SurfaceSurfaceIntersection::Line(Box::new(
                    SurfaceIntersectionLine {
                        point: cylinder.origin.clone() + radial_projection,
                        direction: cylinder.frame.z.clone(),
                    },
                )));
            }
            let line_offset = line_offset_squared.sqrt().map_err(GeometryError::Numeric)?;
            Ok(SurfaceSurfaceIntersection::Lines(vec![
                SurfaceIntersectionLine {
                    point: cylinder.origin.clone()
                        + radial_projection.clone()
                        + tangent.clone() * &line_offset,
                    direction: cylinder.frame.z.clone(),
                },
                SurfaceIntersectionLine {
                    point: cylinder.origin.clone() + radial_projection - tangent * line_offset,
                    direction: cylinder.frame.z.clone(),
                },
            ]))
        }
    }
}

fn intersect_plane_cone(
    plane: &PlaneSurface,
    cone: &ConeSurface,
) -> GeometryResult<SurfaceSurfaceIntersection> {
    let normal = plane.u.cross(&plane.v);
    let axis_cross_normal = decided_order(compare_reals(
        &cone.frame.z.cross(&normal).norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))?;
    if axis_cross_normal != Ordering::Equal {
        let axis_dot_normal = cone.frame.z.dot(&normal);
        let apex_separation = normal.dot(&(&cone.apex - &plane.origin));
        if decided_order(compare_reals(
            &axis_dot_normal,
            &Real::zero(),
            crate::STRICT_PREDICATES,
        ))? != Ordering::Equal
            || decided_order(compare_reals(
                &apex_separation,
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))? != Ordering::Equal
        {
            return Err(GeometryError::UnsupportedIntersection);
        }
        let radial = normal
            .cross(&cone.frame.z)
            .normalize()
            .map_err(GeometryError::Numeric)?;
        let sine = cone.semi_angle.clone().sin();
        let cosine = cone.semi_angle.clone().cos();
        let ray = |radial: Vector3| -> GeometryResult<SurfaceIntersectionRay> {
            let direction = radial.clone() * &sine + cone.frame.z.clone() * &cosine;
            let plane_origin =
                project_point_to_plane_frame(&plane.origin, &plane.u, &plane.v, &cone.apex)?;
            let plane_end = project_point_to_plane_frame(
                &plane.origin,
                &plane.u,
                &plane.v,
                &(cone.apex.clone() + direction.clone()),
            )?;
            let mut u = certified_atan2(radial.dot(&cone.frame.y), radial.dot(&cone.frame.x))?;
            if decided_order(compare_reals(&u, &Real::zero(), crate::STRICT_PREDICATES))?
                == Ordering::Less
            {
                u += Real::tau();
            }
            Ok(SurfaceIntersectionRay::new(
                cone.apex.clone(),
                direction,
                Real::zero(),
                SurfaceIntersectionParameterRay::new(
                    plane_origin.clone(),
                    Vector2::from_xy(
                        &plane_end.x - &plane_origin.x,
                        &plane_end.y - &plane_origin.y,
                    ),
                ),
                SurfaceIntersectionParameterRay::new(Point2::new(u, Real::zero()), Vector2::y()),
            ))
        };
        return Ok(SurfaceSurfaceIntersection::Rays(vec![
            ray(radial.clone())?,
            ray(-radial)?,
        ]));
    }
    let axial_height = (normal.dot(&(&plane.origin - &cone.apex)) / normal.dot(&cone.frame.z))
        .map_err(GeometryError::Numeric)?;
    match decided_order(compare_reals(
        &axial_height,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? {
        Ordering::Less => Ok(SurfaceSurfaceIntersection::None),
        Ordering::Equal => Ok(SurfaceSurfaceIntersection::Point(Box::new(
            (cone.apex.clone()).into(),
        ))),
        Ordering::Greater => {
            let (v, radius) = cone_section_parameters(cone, &axial_height)?;
            let center = cone.apex.clone() + cone.frame.z.clone() * axial_height.clone();
            let curve = Curve3::circle_arc(
                center,
                cone.frame.x.clone(),
                cone.frame.y.clone(),
                radius,
                Real::zero(),
                Real::from(2) * Real::pi(),
            )?;
            let domain = curve.domain().clone();
            Ok(SurfaceSurfaceIntersection::Curve(Box::new(
                SurfaceIntersectionCurve::new(
                    curve.clone(),
                    SurfaceIntersectionPcurve::plane_projection(curve, plane),
                    SurfaceIntersectionPcurve::tensor_iso_v(domain, v),
                ),
            )))
        }
    }
}

/// A transverse section uses the cone's own meridian parameter and radial
/// image. Share this representation between curve and surface intersections,
/// so their witnesses compose with the authored cone pcurves.
fn cone_section_parameters(
    cone: &ConeSurface,
    axial_height: &Real,
) -> GeometryResult<(Real, Real)> {
    let parameter =
        (axial_height / cone.semi_angle.clone().cos()).map_err(GeometryError::Numeric)?;
    let radius = &parameter * cone.semi_angle.clone().sin();
    Ok((parameter, radius))
}

fn intersect_plane_torus(
    plane: &PlaneSurface,
    torus: &TorusSurface,
) -> GeometryResult<SurfaceSurfaceIntersection> {
    let normal = plane.u.cross(&plane.v);
    let axis_cross_normal_order = decided_order(compare_reals(
        &torus.frame.z.cross(&normal).norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))?;
    if axis_cross_normal_order != Ordering::Equal {
        let axis_dot_normal = torus.frame.z.dot(&normal);
        let center_separation = normal.dot(&(&torus.center - &plane.origin));
        if decided_order(compare_reals(
            &axis_dot_normal,
            &Real::zero(),
            crate::STRICT_PREDICATES,
        ))? != Ordering::Equal
        {
            return Err(GeometryError::UnsupportedIntersection);
        }
        if decided_order(compare_reals(
            &center_separation,
            &Real::zero(),
            crate::STRICT_PREDICATES,
        ))? != Ordering::Equal
        {
            let distance_squared = ((&center_separation * &center_separation)
                / normal.norm_squared())
            .map_err(GeometryError::Numeric)?;
            let outer_radius = &torus.major_radius + &torus.minor_radius;
            match decided_order(compare_reals(
                &distance_squared,
                &(&outer_radius * &outer_radius),
                crate::STRICT_PREDICATES,
            ))? {
                Ordering::Greater => return Ok(SurfaceSurfaceIntersection::None),
                Ordering::Equal => {
                    let projection_scale = (center_separation / normal.norm_squared())
                        .map_err(GeometryError::Numeric)?;
                    return Ok(SurfaceSurfaceIntersection::Point(Box::new(
                        (torus.center.clone() - normal.clone() * projection_scale).into(),
                    )));
                }
                Ordering::Less => {}
            }
            return Err(GeometryError::UnsupportedIntersection);
        }

        let radial = normal
            .cross(&torus.frame.z)
            .normalize()
            .map_err(GeometryError::Numeric)?;
        let normalize_angle = |angle: Real| -> GeometryResult<Real> {
            Ok(
                if decided_order(compare_reals(
                    &angle,
                    &Real::zero(),
                    crate::STRICT_PREDICATES,
                ))? == Ordering::Less
                {
                    angle + Real::tau()
                } else {
                    angle
                },
            )
        };
        let section = |radial: Vector3| -> GeometryResult<SurfaceIntersectionCurve> {
            let u = normalize_angle(certified_atan2(
                radial.dot(&torus.frame.y),
                radial.dot(&torus.frame.x),
            )?)?;
            let curve = Curve3::circle_arc(
                torus.center.clone() + radial.clone() * &torus.major_radius,
                radial,
                torus.frame.z.clone(),
                torus.minor_radius.clone(),
                Real::zero(),
                Real::tau(),
            )?;
            let domain = curve.domain().clone();
            Ok(SurfaceIntersectionCurve::new(
                curve.clone(),
                SurfaceIntersectionPcurve::plane_projection(curve, plane),
                SurfaceIntersectionPcurve::tensor_iso(
                    domain,
                    u,
                    TensorAxis::U,
                    Real::one(),
                    Real::zero(),
                ),
            ))
        };
        return Ok(SurfaceSurfaceIntersection::Curves(vec![
            section(radial.clone())?,
            section(-radial)?,
        ]));
    }
    let axial_height = (normal.dot(&(&plane.origin - &torus.center)) / normal.dot(&torus.frame.z))
        .map_err(GeometryError::Numeric)?;
    let axial_squared = &axial_height * &axial_height;
    let minor_squared = &torus.minor_radius * &torus.minor_radius;
    match decided_order(compare_reals(
        &axial_squared,
        &minor_squared,
        crate::STRICT_PREDICATES,
    ))? {
        Ordering::Greater => Ok(SurfaceSurfaceIntersection::None),
        Ordering::Equal | Ordering::Less => {
            let radial_offset = (minor_squared - axial_squared)
                .sqrt()
                .map_err(GeometryError::Numeric)?;
            let center = torus.center.clone() + torus.frame.z.clone() * axial_height.clone();
            let normalize_angle = |angle: Real| -> GeometryResult<Real> {
                Ok(
                    if decided_order(compare_reals(
                        &angle,
                        &Real::zero(),
                        crate::STRICT_PREDICATES,
                    ))? == Ordering::Less
                    {
                        angle + Real::tau()
                    } else {
                        angle
                    },
                )
            };
            let section = |radius: Real, v: Real| -> GeometryResult<SurfaceIntersectionCurve> {
                let curve = Curve3::circle_arc(
                    center.clone(),
                    torus.frame.x.clone(),
                    torus.frame.y.clone(),
                    radius,
                    Real::zero(),
                    Real::tau(),
                )?;
                let domain = curve.domain().clone();
                Ok(SurfaceIntersectionCurve::new(
                    curve.clone(),
                    SurfaceIntersectionPcurve::plane_projection(curve, plane),
                    SurfaceIntersectionPcurve::tensor_iso_v(domain, v),
                ))
            };
            if decided_order(compare_reals(
                &radial_offset,
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))? == Ordering::Equal
            {
                let v = normalize_angle(certified_atan2(axial_height, radial_offset)?)?;
                return Ok(SurfaceSurfaceIntersection::Curve(Box::new(section(
                    torus.major_radius.clone(),
                    v,
                )?)));
            }
            let outer_v = normalize_angle(certified_atan2(
                axial_height.clone(),
                radial_offset.clone(),
            )?)?;
            let inner_v = normalize_angle(certified_atan2(axial_height, -radial_offset.clone())?)?;
            Ok(SurfaceSurfaceIntersection::Curves(vec![
                section(&torus.major_radius + &radial_offset, outer_v)?,
                section(&torus.major_radius - radial_offset, inner_v)?,
            ]))
        }
    }
}

fn intersect_parallel_cylinders(
    first: &CylinderSurface,
    second: &CylinderSurface,
) -> GeometryResult<SurfaceSurfaceIntersection> {
    if decided_order(compare_reals(
        &first.frame.z.cross(&second.frame.z).norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? != Ordering::Equal
    {
        return Err(GeometryError::UnsupportedIntersection);
    }
    let displacement = &second.origin - &first.origin;
    let radial_displacement =
        &displacement - &(first.frame.z.clone() * displacement.dot(&first.frame.z));
    let distance_squared = radial_displacement.norm_squared();
    if decided_order(compare_reals(
        &distance_squared,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? == Ordering::Equal
    {
        return if decided_order(compare_reals(
            &first.radius,
            &second.radius,
            crate::STRICT_PREDICATES,
        ))? == Ordering::Equal
        {
            Ok(SurfaceSurfaceIntersection::Coincident)
        } else {
            Ok(SurfaceSurfaceIntersection::None)
        };
    }
    let distance = distance_squared
        .clone()
        .sqrt()
        .map_err(GeometryError::Numeric)?;
    let radius_sum = &first.radius + &second.radius;
    let radius_difference = match decided_order(compare_reals(
        &first.radius,
        &second.radius,
        crate::STRICT_PREDICATES,
    ))? {
        Ordering::Less => &second.radius - &first.radius,
        Ordering::Equal | Ordering::Greater => &first.radius - &second.radius,
    };
    if decided_order(compare_reals(
        &distance,
        &radius_sum,
        crate::STRICT_PREDICATES,
    ))? == Ordering::Greater
        || decided_order(compare_reals(
            &distance,
            &radius_difference,
            crate::STRICT_PREDICATES,
        ))? == Ordering::Less
    {
        return Ok(SurfaceSurfaceIntersection::None);
    }
    let along = ((&first.radius * &first.radius - &second.radius * &second.radius
        + &distance_squared)
        / (Real::from(2) * &distance))
        .map_err(GeometryError::Numeric)?;
    let unit_displacement = (radial_displacement / &distance).map_err(GeometryError::Numeric)?;
    let base = first.origin.clone() + unit_displacement.clone() * &along;
    let height_squared = &first.radius * &first.radius - &along * &along;
    if decided_order(compare_reals(
        &height_squared,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? == Ordering::Equal
    {
        return Ok(SurfaceSurfaceIntersection::Line(Box::new(
            SurfaceIntersectionLine {
                point: base,
                direction: first.frame.z.clone(),
            },
        )));
    }
    let height = height_squared.sqrt().map_err(GeometryError::Numeric)?;
    let transverse = first.frame.z.cross(&unit_displacement);
    Ok(SurfaceSurfaceIntersection::Lines(vec![
        SurfaceIntersectionLine {
            point: base.clone() + transverse.clone() * &height,
            direction: first.frame.z.clone(),
        },
        SurfaceIntersectionLine {
            point: base - transverse * height,
            direction: first.frame.z.clone(),
        },
    ]))
}

fn intersect_coaxial_sphere_cylinder(
    sphere: &SphereSurface,
    cylinder: &CylinderSurface,
) -> GeometryResult<SurfaceSurfaceIntersection> {
    let center_offset = &sphere.center - &cylinder.origin;
    let axial_offset = center_offset.dot(&cylinder.frame.z);
    let radial_offset = center_offset - cylinder.frame.z.clone() * &axial_offset;
    if decided_order(compare_reals(
        &radial_offset.norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? != Ordering::Equal
    {
        return Err(GeometryError::UnsupportedIntersection);
    }
    let sphere_radius_squared = &sphere.radius * &sphere.radius;
    let cylinder_radius_squared = &cylinder.radius * &cylinder.radius;
    let frames_match = orthonormal_frames_equal(&sphere.frame, &cylinder.frame)?;
    let frames_mirrored = orthonormal_frames_mirrored(&sphere.frame, &cylinder.frame)?;
    let retain_pcurves = frames_match || frames_mirrored;
    let retained_circle = |height: Real| -> GeometryResult<SurfaceIntersectionCurve> {
        let center = sphere.center.clone() + cylinder.frame.z.clone() * &height;
        let curve = Curve3::circle_arc(
            center.clone(),
            sphere.frame.x.clone(),
            sphere.frame.y.clone(),
            cylinder.radius.clone(),
            Real::zero(),
            Real::tau(),
        )?;
        let sphere_height = (&center - &sphere.center).dot(&sphere.frame.z);
        let latitude = (sphere_height / &sphere.radius)
            .map_err(GeometryError::Numeric)?
            .asin()
            .map_err(GeometryError::Numeric)?;
        let cylinder_height = &axial_offset + height;
        let domain = curve.domain().clone();
        Ok(SurfaceIntersectionCurve::new(
            curve,
            SurfaceIntersectionPcurve::tensor_iso_v(domain.clone(), latitude),
            angular_iso_v_pcurve(domain, cylinder_height, frames_mirrored),
        ))
    };
    match decided_order(compare_reals(
        &sphere_radius_squared,
        &cylinder_radius_squared,
        crate::STRICT_PREDICATES,
    ))? {
        Ordering::Less => Ok(SurfaceSurfaceIntersection::None),
        Ordering::Equal => {
            if retain_pcurves {
                Ok(SurfaceSurfaceIntersection::Curve(Box::new(
                    retained_circle(Real::zero())?,
                )))
            } else {
                Ok(SurfaceSurfaceIntersection::Circle(Curve3::circle_arc(
                    sphere.center.clone(),
                    cylinder.frame.x.clone(),
                    cylinder.frame.y.clone(),
                    cylinder.radius.clone(),
                    Real::zero(),
                    Real::tau(),
                )?))
            }
        }
        Ordering::Greater => {
            let axial_distance = (sphere_radius_squared - cylinder_radius_squared)
                .sqrt()
                .map_err(GeometryError::Numeric)?;
            if retain_pcurves {
                return Ok(SurfaceSurfaceIntersection::Curves(vec![
                    retained_circle(axial_distance.clone())?,
                    retained_circle(-axial_distance)?,
                ]));
            }
            Ok(SurfaceSurfaceIntersection::Circles(vec![
                Curve3::circle_arc(
                    sphere.center.clone() + cylinder.frame.z.clone() * &axial_distance,
                    cylinder.frame.x.clone(),
                    cylinder.frame.y.clone(),
                    cylinder.radius.clone(),
                    Real::zero(),
                    Real::from(2) * Real::pi(),
                )?,
                Curve3::circle_arc(
                    sphere.center.clone() - cylinder.frame.z.clone() * axial_distance,
                    cylinder.frame.x.clone(),
                    cylinder.frame.y.clone(),
                    cylinder.radius.clone(),
                    Real::zero(),
                    Real::from(2) * Real::pi(),
                )?,
            ]))
        }
    }
}

fn intersect_coaxial_sphere_cone(
    sphere: &SphereSurface,
    cone: &ConeSurface,
) -> GeometryResult<SurfaceSurfaceIntersection> {
    let center_offset = &sphere.center - &cone.apex;
    let axial_offset = center_offset.dot(&cone.frame.z);
    let radial_offset = center_offset - cone.frame.z.clone() * &axial_offset;
    if decided_order(compare_reals(
        &radial_offset.norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? != Ordering::Equal
    {
        return Err(GeometryError::UnsupportedIntersection);
    }

    let sine = cone.semi_angle.clone().sin();
    let cosine = cone.semi_angle.clone().cos();
    let discriminant =
        &sphere.radius * &sphere.radius - &axial_offset * &axial_offset * &sine * &sine;
    let discriminant_order = decided_order(compare_reals(
        &discriminant,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))?;
    if discriminant_order == Ordering::Less {
        return Ok(SurfaceSurfaceIntersection::None);
    }
    let root_center = &axial_offset * &cosine;
    let root_parameters = if discriminant_order == Ordering::Equal {
        vec![root_center]
    } else {
        let root_offset = discriminant.sqrt().map_err(GeometryError::Numeric)?;
        vec![&root_center - &root_offset, root_center + root_offset]
    };
    let mut has_apex = false;
    let mut slant_parameters = Vec::with_capacity(root_parameters.len());
    for parameter in root_parameters {
        match decided_order(compare_reals(
            &parameter,
            &Real::zero(),
            crate::STRICT_PREDICATES,
        ))? {
            Ordering::Less => {}
            Ordering::Equal => {
                has_apex = true;
            }
            Ordering::Greater => slant_parameters.push(parameter),
        }
    }
    if has_apex && slant_parameters.is_empty() {
        return Ok(SurfaceSurfaceIntersection::Point(Box::new(
            (cone.apex.clone()).into(),
        )));
    }
    if slant_parameters.is_empty() {
        return Ok(SurfaceSurfaceIntersection::None);
    }

    let frames_match = orthonormal_frames_equal(&sphere.frame, &cone.frame)?;
    let frames_mirrored = orthonormal_frames_mirrored(&sphere.frame, &cone.frame)?;
    let retain_pcurves = frames_match || frames_mirrored;
    let mut circles = Vec::with_capacity(slant_parameters.len());
    let mut retained = Vec::with_capacity(slant_parameters.len());
    for parameter in slant_parameters {
        let axial_height = &parameter * &cosine;
        let radius = &parameter * &sine;
        let center = cone.apex.clone() + cone.frame.z.clone() * &axial_height;
        let curve = Curve3::circle_arc(
            center.clone(),
            cone.frame.x.clone(),
            cone.frame.y.clone(),
            radius,
            Real::zero(),
            Real::tau(),
        )?;
        if retain_pcurves {
            let sphere_height = (&center - &sphere.center).dot(&sphere.frame.z);
            let latitude = (sphere_height / &sphere.radius)
                .map_err(GeometryError::Numeric)?
                .asin()
                .map_err(GeometryError::Numeric)?;
            let domain = curve.domain().clone();
            retained.push(SurfaceIntersectionCurve::new(
                curve,
                angular_iso_v_pcurve(domain.clone(), latitude, frames_mirrored),
                SurfaceIntersectionPcurve::tensor_iso_v(domain, parameter),
            ));
        } else {
            circles.push(curve);
        }
    }
    if has_apex {
        return Ok(SurfaceSurfaceIntersection::Components(Box::new(
            SurfaceIntersectionComponents::new(vec![cone.apex.clone().into()], circles, retained),
        )));
    }
    if retain_pcurves {
        Ok(match retained.len() {
            1 => SurfaceSurfaceIntersection::Curve(Box::new(
                retained.pop().expect("one retained sphere/cone circle"),
            )),
            _ => SurfaceSurfaceIntersection::Curves(retained),
        })
    } else {
        Ok(match circles.len() {
            1 => SurfaceSurfaceIntersection::Circle(circles.pop().expect("one sphere/cone circle")),
            _ => SurfaceSurfaceIntersection::Circles(circles),
        })
    }
}

fn intersect_coaxial_cylinder_cone(
    cylinder: &CylinderSurface,
    cone: &ConeSurface,
) -> GeometryResult<SurfaceSurfaceIntersection> {
    if decided_order(compare_reals(
        &cylinder.frame.z.cross(&cone.frame.z).norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? != Ordering::Equal
    {
        return Err(GeometryError::UnsupportedIntersection);
    }
    let origin_offset = &cylinder.origin - &cone.apex;
    let radial_offset = &origin_offset - &(cone.frame.z.clone() * origin_offset.dot(&cone.frame.z));
    if decided_order(compare_reals(
        &radial_offset.norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? != Ordering::Equal
    {
        return Err(GeometryError::UnsupportedIntersection);
    }

    let sine = cone.semi_angle.clone().sin();
    let cosine = cone.semi_angle.clone().cos();
    let slant_parameter = (&cylinder.radius / &sine).map_err(GeometryError::Numeric)?;
    let axial_height = &slant_parameter * cosine;
    let center = cone.apex.clone() + cone.frame.z.clone() * axial_height;
    let curve = Curve3::circle_arc(
        center.clone(),
        cone.frame.x.clone(),
        cone.frame.y.clone(),
        cylinder.radius.clone(),
        Real::zero(),
        Real::tau(),
    )?;
    let frames_match = orthonormal_frames_equal(&cylinder.frame, &cone.frame)?;
    let frames_mirrored = orthonormal_frames_mirrored(&cylinder.frame, &cone.frame)?;
    if !frames_match && !frames_mirrored {
        return Ok(SurfaceSurfaceIntersection::Circle(curve));
    }
    let cylinder_height = (&center - &cylinder.origin).dot(&cylinder.frame.z);
    let domain = curve.domain().clone();
    Ok(SurfaceSurfaceIntersection::Curve(Box::new(
        SurfaceIntersectionCurve::new(
            curve,
            angular_iso_v_pcurve(domain.clone(), cylinder_height, frames_mirrored),
            SurfaceIntersectionPcurve::tensor_iso_v(domain, slant_parameter),
        ),
    )))
}

fn intersect_coaxial_cones(
    first: &ConeSurface,
    second: &ConeSurface,
) -> GeometryResult<SurfaceSurfaceIntersection> {
    let cooriented = decided_order(compare_reals(
        &(&first.frame.z - &second.frame.z).norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? == Ordering::Equal;
    let counteroriented = decided_order(compare_reals(
        &(&first.frame.z + &second.frame.z).norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? == Ordering::Equal;
    if !cooriented && !counteroriented {
        return Err(GeometryError::UnsupportedIntersection);
    }
    let apex_offset = &second.apex - &first.apex;
    let axial_offset = apex_offset.dot(&first.frame.z);
    let radial_offset = apex_offset - first.frame.z.clone() * &axial_offset;
    if decided_order(compare_reals(
        &radial_offset.norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? != Ordering::Equal
    {
        return Err(GeometryError::UnsupportedIntersection);
    }

    if counteroriented {
        return intersect_counteroriented_coaxial_cones(first, second, axial_offset);
    }

    if decided_order(compare_reals(
        &first.semi_angle,
        &second.semi_angle,
        crate::STRICT_PREDICATES,
    ))? == Ordering::Equal
    {
        return if decided_order(compare_reals(
            &axial_offset,
            &Real::zero(),
            crate::STRICT_PREDICATES,
        ))? == Ordering::Equal
        {
            Ok(SurfaceSurfaceIntersection::Coincident)
        } else {
            Ok(SurfaceSurfaceIntersection::None)
        };
    }

    let first_sine = first.semi_angle.clone().sin();
    let first_cosine = first.semi_angle.clone().cos();
    let second_sine = second.semi_angle.clone().sin();
    let second_cosine = second.semi_angle.clone().cos();
    let determinant = &first_cosine * &second_sine - &first_sine * &second_cosine;
    let first_slant =
        (&axial_offset * &second_sine / &determinant).map_err(GeometryError::Numeric)?;
    let second_slant =
        (&axial_offset * &first_sine / determinant).map_err(GeometryError::Numeric)?;
    let first_order = decided_order(compare_reals(
        &first_slant,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))?;
    let second_order = decided_order(compare_reals(
        &second_slant,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))?;
    if first_order == Ordering::Less || second_order == Ordering::Less {
        return Ok(SurfaceSurfaceIntersection::None);
    }
    if first_order == Ordering::Equal || second_order == Ordering::Equal {
        return Ok(SurfaceSurfaceIntersection::Point(Box::new(
            (first.apex.clone()).into(),
        )));
    }

    let axial_height = &first_slant * &first_cosine;
    let radius = &first_slant * &first_sine;
    let center = first.apex.clone() + first.frame.z.clone() * axial_height;
    let curve = Curve3::circle_arc(
        center,
        first.frame.x.clone(),
        first.frame.y.clone(),
        radius,
        Real::zero(),
        Real::tau(),
    )?;
    if !orthonormal_frames_equal(&first.frame, &second.frame)? {
        return Ok(SurfaceSurfaceIntersection::Circle(curve));
    }
    let domain = curve.domain().clone();
    Ok(SurfaceSurfaceIntersection::Curve(Box::new(
        SurfaceIntersectionCurve::new(
            curve,
            SurfaceIntersectionPcurve::tensor_iso_v(domain.clone(), first_slant),
            SurfaceIntersectionPcurve::tensor_iso_v(domain, second_slant),
        ),
    )))
}

fn intersect_counteroriented_coaxial_cones(
    first: &ConeSurface,
    second: &ConeSurface,
    axial_offset: Real,
) -> GeometryResult<SurfaceSurfaceIntersection> {
    let axial_order = decided_order(compare_reals(
        &axial_offset,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))?;
    if axial_order == Ordering::Less {
        return Ok(SurfaceSurfaceIntersection::None);
    }
    if axial_order == Ordering::Equal {
        return Ok(SurfaceSurfaceIntersection::Point(Box::new(
            (first.apex.clone()).into(),
        )));
    }

    let first_sine = first.semi_angle.clone().sin();
    let first_cosine = first.semi_angle.clone().cos();
    let second_sine = second.semi_angle.clone().sin();
    let second_cosine = second.semi_angle.clone().cos();
    let denominator = &first_cosine * &second_sine + &first_sine * &second_cosine;
    let first_slant =
        (&axial_offset * &second_sine / &denominator).map_err(GeometryError::Numeric)?;
    let second_slant =
        (&axial_offset * &first_sine / denominator).map_err(GeometryError::Numeric)?;
    let axial_height = &first_slant * &first_cosine;
    let radius = &first_slant * &first_sine;
    let center = first.apex.clone() + first.frame.z.clone() * axial_height;
    let curve = Curve3::circle_arc(
        center,
        first.frame.x.clone(),
        first.frame.y.clone(),
        radius,
        Real::zero(),
        Real::tau(),
    )?;
    if !orthonormal_frames_mirrored(&first.frame, &second.frame)? {
        return Ok(SurfaceSurfaceIntersection::Circle(curve));
    }
    let domain = curve.domain().clone();
    Ok(SurfaceSurfaceIntersection::Curve(Box::new(
        SurfaceIntersectionCurve::new(
            curve,
            SurfaceIntersectionPcurve::tensor_iso_v(domain.clone(), first_slant),
            SurfaceIntersectionPcurve::tensor_iso(
                domain,
                second_slant,
                TensorAxis::V,
                -Real::one(),
                Real::tau(),
            ),
        ),
    )))
}

fn orthonormal_frames_equal(
    first: &OrthonormalFrame3,
    second: &OrthonormalFrame3,
) -> GeometryResult<bool> {
    [&first.x, &first.y, &first.z]
        .into_iter()
        .zip([&second.x, &second.y, &second.z])
        .try_fold(true, |matches, (first_axis, second_axis)| {
            Ok(matches
                && decided_order(compare_reals(
                    &(first_axis - second_axis).norm_squared(),
                    &Real::zero(),
                    crate::STRICT_PREDICATES,
                ))? == Ordering::Equal)
        })
}

fn angular_iso_v_pcurve(
    domain: ParameterRange,
    constant: Real,
    reversed: bool,
) -> SurfaceIntersectionPcurve {
    if reversed {
        SurfaceIntersectionPcurve::tensor_iso(
            domain,
            constant,
            TensorAxis::V,
            -Real::one(),
            Real::tau(),
        )
    } else {
        SurfaceIntersectionPcurve::tensor_iso_v(domain, constant)
    }
}

fn orthonormal_frames_mirrored(
    first: &OrthonormalFrame3,
    second: &OrthonormalFrame3,
) -> GeometryResult<bool> {
    [
        (&first.x, &second.x),
        (&first.y, &-second.y.clone()),
        (&first.z, &-second.z.clone()),
    ]
    .into_iter()
    .try_fold(true, |matches, (first_axis, second_axis)| {
        Ok(matches
            && decided_order(compare_reals(
                &(first_axis - second_axis).norm_squared(),
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))? == Ordering::Equal)
    })
}

enum MeridianCircleIntersection {
    Coincident,
    Points(Vec<(Real, Real)>),
}

fn intersect_meridian_circles(
    first_center_x: &Real,
    first_center_y: &Real,
    first_radius: &Real,
    second_center_x: &Real,
    second_center_y: &Real,
    second_radius: &Real,
) -> GeometryResult<MeridianCircleIntersection> {
    let displacement_x = second_center_x - first_center_x;
    let displacement_y = second_center_y - first_center_y;
    let distance_squared = &displacement_x * &displacement_x + &displacement_y * &displacement_y;
    if decided_order(compare_reals(
        &distance_squared,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? == Ordering::Equal
    {
        return if decided_order(compare_reals(
            first_radius,
            second_radius,
            crate::STRICT_PREDICATES,
        ))? == Ordering::Equal
        {
            Ok(MeridianCircleIntersection::Coincident)
        } else {
            Ok(MeridianCircleIntersection::Points(Vec::new()))
        };
    }

    let distance = distance_squared
        .clone()
        .sqrt()
        .map_err(GeometryError::Numeric)?;
    let radius_sum = first_radius + second_radius;
    let radius_difference = match decided_order(compare_reals(
        first_radius,
        second_radius,
        crate::STRICT_PREDICATES,
    ))? {
        Ordering::Less => second_radius - first_radius,
        Ordering::Equal | Ordering::Greater => first_radius - second_radius,
    };
    if decided_order(compare_reals(
        &distance,
        &radius_sum,
        crate::STRICT_PREDICATES,
    ))? == Ordering::Greater
        || decided_order(compare_reals(
            &distance,
            &radius_difference,
            crate::STRICT_PREDICATES,
        ))? == Ordering::Less
    {
        return Ok(MeridianCircleIntersection::Points(Vec::new()));
    }

    let along = ((first_radius * first_radius - second_radius * second_radius + &distance_squared)
        / (Real::from(2) * &distance))
        .map_err(GeometryError::Numeric)?;
    let inverse_distance = (Real::one() / distance).map_err(GeometryError::Numeric)?;
    let unit_x = displacement_x * &inverse_distance;
    let unit_y = displacement_y * inverse_distance;
    let base_x = first_center_x + &unit_x * &along;
    let base_y = first_center_y + &unit_y * &along;
    let transverse_squared = first_radius * first_radius - &along * &along;
    let points = match decided_order(compare_reals(
        &transverse_squared,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? {
        Ordering::Less => Vec::new(),
        Ordering::Equal => vec![(base_x, base_y)],
        Ordering::Greater => {
            let transverse = transverse_squared.sqrt().map_err(GeometryError::Numeric)?;
            vec![
                (
                    &base_x + &unit_y * &transverse,
                    &base_y - &unit_x * &transverse,
                ),
                (base_x - unit_y * &transverse, base_y + unit_x * transverse),
            ]
        }
    };
    Ok(MeridianCircleIntersection::Points(points))
}

fn intersect_coaxial_sphere_torus(
    sphere: &SphereSurface,
    torus: &TorusSurface,
) -> GeometryResult<SurfaceSurfaceIntersection> {
    if decided_order(compare_reals(
        &sphere.frame.z.cross(&torus.frame.z).norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? != Ordering::Equal
    {
        return Err(GeometryError::UnsupportedIntersection);
    }
    let center_offset = &torus.center - &sphere.center;
    let axial_offset = center_offset.dot(&sphere.frame.z);
    let radial_offset = center_offset - sphere.frame.z.clone() * &axial_offset;
    if decided_order(compare_reals(
        &radial_offset.norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? != Ordering::Equal
    {
        return Err(GeometryError::UnsupportedIntersection);
    }

    let profile_points = match intersect_meridian_circles(
        &Real::zero(),
        &Real::zero(),
        &sphere.radius,
        &torus.major_radius,
        &axial_offset,
        &torus.minor_radius,
    )? {
        MeridianCircleIntersection::Coincident => {
            return Err(GeometryError::UnsupportedIntersection);
        }
        MeridianCircleIntersection::Points(points) if points.is_empty() => {
            return Ok(SurfaceSurfaceIntersection::None);
        }
        MeridianCircleIntersection::Points(points) => points,
    };

    let frames_equal = orthonormal_frames_equal(&sphere.frame, &torus.frame)?;
    let frames_mirrored = orthonormal_frames_mirrored(&sphere.frame, &torus.frame)?;
    let retain_pcurves = frames_equal || frames_mirrored;
    let canonical_angle = |angle: Real| -> GeometryResult<Real> {
        Ok(
            if decided_order(compare_reals(
                &angle,
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))? == Ordering::Less
            {
                angle + Real::tau()
            } else {
                angle
            },
        )
    };
    let mut curves = Vec::with_capacity(profile_points.len());
    let mut retained = Vec::with_capacity(profile_points.len());
    for (radial_distance, sphere_height) in profile_points {
        let center = sphere.center.clone() + sphere.frame.z.clone() * &sphere_height;
        let curve = Curve3::circle_arc(
            center.clone(),
            sphere.frame.x.clone(),
            sphere.frame.y.clone(),
            radial_distance.clone(),
            Real::zero(),
            Real::tau(),
        )?;
        if retain_pcurves {
            let sphere_v = certified_atan2(sphere_height, radial_distance.clone())?;
            let torus_v = canonical_angle(certified_atan2(
                (&center - &torus.center).dot(&torus.frame.z),
                radial_distance - &torus.major_radius,
            )?)?;
            let domain = curve.domain().clone();
            retained.push(SurfaceIntersectionCurve::new(
                curve,
                SurfaceIntersectionPcurve::tensor_iso_v(domain.clone(), sphere_v),
                angular_iso_v_pcurve(domain, torus_v, frames_mirrored),
            ));
        } else {
            curves.push(curve);
        }
    }
    if retain_pcurves {
        Ok(match retained.len() {
            1 => SurfaceSurfaceIntersection::Curve(Box::new(
                retained.pop().expect("one retained sphere/torus circle"),
            )),
            _ => SurfaceSurfaceIntersection::Curves(retained),
        })
    } else {
        Ok(match curves.len() {
            1 => SurfaceSurfaceIntersection::Circle(curves.pop().expect("one sphere/torus circle")),
            _ => SurfaceSurfaceIntersection::Circles(curves),
        })
    }
}

fn intersect_coaxial_cylinder_torus(
    cylinder: &CylinderSurface,
    torus: &TorusSurface,
) -> GeometryResult<SurfaceSurfaceIntersection> {
    if decided_order(compare_reals(
        &cylinder.frame.z.cross(&torus.frame.z).norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? != Ordering::Equal
    {
        return Err(GeometryError::UnsupportedIntersection);
    }
    let center_offset = &torus.center - &cylinder.origin;
    let torus_height = center_offset.dot(&cylinder.frame.z);
    let radial_offset = center_offset - cylinder.frame.z.clone() * &torus_height;
    if decided_order(compare_reals(
        &radial_offset.norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? != Ordering::Equal
    {
        return Err(GeometryError::UnsupportedIntersection);
    }

    let radial_delta = &cylinder.radius - &torus.major_radius;
    let height_squared = &torus.minor_radius * &torus.minor_radius - &radial_delta * &radial_delta;
    let heights = match decided_order(compare_reals(
        &height_squared,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? {
        Ordering::Less => return Ok(SurfaceSurfaceIntersection::None),
        Ordering::Equal => vec![torus_height],
        Ordering::Greater => {
            let height_offset = height_squared.sqrt().map_err(GeometryError::Numeric)?;
            vec![&torus_height - &height_offset, torus_height + height_offset]
        }
    };

    let frames_equal = orthonormal_frames_equal(&cylinder.frame, &torus.frame)?;
    let frames_mirrored = orthonormal_frames_mirrored(&cylinder.frame, &torus.frame)?;
    let retain_pcurves = frames_equal || frames_mirrored;
    let canonical_angle = |angle: Real| -> GeometryResult<Real> {
        Ok(
            if decided_order(compare_reals(
                &angle,
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))? == Ordering::Less
            {
                angle + Real::tau()
            } else {
                angle
            },
        )
    };
    let mut curves = Vec::with_capacity(heights.len());
    let mut retained = Vec::with_capacity(heights.len());
    for cylinder_height in heights {
        let center = cylinder.origin.clone() + cylinder.frame.z.clone() * &cylinder_height;
        let curve = Curve3::circle_arc(
            center.clone(),
            cylinder.frame.x.clone(),
            cylinder.frame.y.clone(),
            cylinder.radius.clone(),
            Real::zero(),
            Real::tau(),
        )?;
        if retain_pcurves {
            let torus_v = canonical_angle(certified_atan2(
                (&center - &torus.center).dot(&torus.frame.z),
                radial_delta.clone(),
            )?)?;
            let domain = curve.domain().clone();
            retained.push(SurfaceIntersectionCurve::new(
                curve,
                SurfaceIntersectionPcurve::tensor_iso_v(domain.clone(), cylinder_height),
                angular_iso_v_pcurve(domain, torus_v, frames_mirrored),
            ));
        } else {
            curves.push(curve);
        }
    }
    if retain_pcurves {
        Ok(match retained.len() {
            1 => SurfaceSurfaceIntersection::Curve(Box::new(
                retained.pop().expect("one retained cylinder/torus circle"),
            )),
            _ => SurfaceSurfaceIntersection::Curves(retained),
        })
    } else {
        Ok(match curves.len() {
            1 => {
                SurfaceSurfaceIntersection::Circle(curves.pop().expect("one cylinder/torus circle"))
            }
            _ => SurfaceSurfaceIntersection::Circles(curves),
        })
    }
}

fn intersect_coaxial_cone_torus(
    cone: &ConeSurface,
    torus: &TorusSurface,
) -> GeometryResult<SurfaceSurfaceIntersection> {
    if decided_order(compare_reals(
        &cone.frame.z.cross(&torus.frame.z).norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? != Ordering::Equal
    {
        return Err(GeometryError::UnsupportedIntersection);
    }
    let center_offset = &torus.center - &cone.apex;
    let torus_height = center_offset.dot(&cone.frame.z);
    let radial_offset = center_offset - cone.frame.z.clone() * &torus_height;
    if decided_order(compare_reals(
        &radial_offset.norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? != Ordering::Equal
    {
        return Err(GeometryError::UnsupportedIntersection);
    }

    let sine = cone.semi_angle.clone().sin();
    let cosine = cone.semi_angle.clone().cos();
    let projected_center = &torus.major_radius * &sine + &torus_height * &cosine;
    let center_norm_squared =
        &torus.major_radius * &torus.major_radius + &torus_height * &torus_height;
    let transverse_distance_squared = center_norm_squared - &projected_center * &projected_center;
    let discriminant = &torus.minor_radius * &torus.minor_radius - transverse_distance_squared;
    let candidates = match decided_order(compare_reals(
        &discriminant,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? {
        Ordering::Less => return Ok(SurfaceSurfaceIntersection::None),
        Ordering::Equal => vec![projected_center],
        Ordering::Greater => {
            let offset = discriminant.sqrt().map_err(GeometryError::Numeric)?;
            vec![&projected_center - &offset, projected_center + offset]
        }
    };
    let slants = candidates
        .into_iter()
        .map(|slant| {
            Ok((
                decided_order(compare_reals(
                    &slant,
                    &Real::zero(),
                    crate::STRICT_PREDICATES,
                ))? == Ordering::Greater,
                slant,
            ))
        })
        .collect::<GeometryResult<Vec<_>>>()?
        .into_iter()
        .filter_map(|(positive, slant)| positive.then_some(slant))
        .collect::<Vec<_>>();
    if slants.is_empty() {
        return Ok(SurfaceSurfaceIntersection::None);
    }

    let frames_equal = orthonormal_frames_equal(&cone.frame, &torus.frame)?;
    let frames_mirrored = orthonormal_frames_mirrored(&cone.frame, &torus.frame)?;
    let retain_pcurves = frames_equal || frames_mirrored;
    let canonical_angle = |angle: Real| -> GeometryResult<Real> {
        Ok(
            if decided_order(compare_reals(
                &angle,
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))? == Ordering::Less
            {
                angle + Real::tau()
            } else {
                angle
            },
        )
    };
    let mut curves = Vec::with_capacity(slants.len());
    let mut retained = Vec::with_capacity(slants.len());
    for slant in slants {
        let axial_height = &slant * &cosine;
        let radial_distance = &slant * &sine;
        let center = cone.apex.clone() + cone.frame.z.clone() * axial_height;
        let curve = Curve3::circle_arc(
            center.clone(),
            cone.frame.x.clone(),
            cone.frame.y.clone(),
            radial_distance.clone(),
            Real::zero(),
            Real::tau(),
        )?;
        if retain_pcurves {
            let torus_v = canonical_angle(certified_atan2(
                (&center - &torus.center).dot(&torus.frame.z),
                radial_distance - &torus.major_radius,
            )?)?;
            let domain = curve.domain().clone();
            retained.push(SurfaceIntersectionCurve::new(
                curve,
                SurfaceIntersectionPcurve::tensor_iso_v(domain.clone(), slant),
                angular_iso_v_pcurve(domain, torus_v, frames_mirrored),
            ));
        } else {
            curves.push(curve);
        }
    }
    if retain_pcurves {
        Ok(match retained.len() {
            1 => SurfaceSurfaceIntersection::Curve(Box::new(
                retained.pop().expect("one retained cone/torus circle"),
            )),
            _ => SurfaceSurfaceIntersection::Curves(retained),
        })
    } else {
        Ok(match curves.len() {
            1 => SurfaceSurfaceIntersection::Circle(curves.pop().expect("one cone/torus circle")),
            _ => SurfaceSurfaceIntersection::Circles(curves),
        })
    }
}

fn intersect_coaxial_tori(
    first: &TorusSurface,
    second: &TorusSurface,
) -> GeometryResult<SurfaceSurfaceIntersection> {
    if decided_order(compare_reals(
        &first.frame.z.cross(&second.frame.z).norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? != Ordering::Equal
    {
        return Err(GeometryError::UnsupportedIntersection);
    }
    let center_offset = &second.center - &first.center;
    let axial_offset = center_offset.dot(&first.frame.z);
    let radial_offset = center_offset - first.frame.z.clone() * &axial_offset;
    if decided_order(compare_reals(
        &radial_offset.norm_squared(),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? != Ordering::Equal
    {
        return Err(GeometryError::UnsupportedIntersection);
    }

    let profile_points = match intersect_meridian_circles(
        &first.major_radius,
        &Real::zero(),
        &first.minor_radius,
        &second.major_radius,
        &axial_offset,
        &second.minor_radius,
    )? {
        MeridianCircleIntersection::Coincident => {
            return Ok(SurfaceSurfaceIntersection::Coincident);
        }
        MeridianCircleIntersection::Points(points) if points.is_empty() => {
            return Ok(SurfaceSurfaceIntersection::None);
        }
        MeridianCircleIntersection::Points(points) => points,
    };

    let frames_equal = orthonormal_frames_equal(&first.frame, &second.frame)?;
    let frames_mirrored = orthonormal_frames_mirrored(&first.frame, &second.frame)?;
    let retain_pcurves = frames_equal || frames_mirrored;
    let canonical_angle = |angle: Real| -> GeometryResult<Real> {
        Ok(
            if decided_order(compare_reals(
                &angle,
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))? == Ordering::Less
            {
                angle + Real::tau()
            } else {
                angle
            },
        )
    };
    let mut curves = Vec::with_capacity(profile_points.len());
    let mut retained = Vec::with_capacity(profile_points.len());
    for (radial_distance, axial_height) in profile_points {
        let center = first.center.clone() + first.frame.z.clone() * &axial_height;
        let curve = Curve3::circle_arc(
            center.clone(),
            first.frame.x.clone(),
            first.frame.y.clone(),
            radial_distance.clone(),
            Real::zero(),
            Real::tau(),
        )?;
        if retain_pcurves {
            let first_v = canonical_angle(certified_atan2(
                axial_height,
                &radial_distance - &first.major_radius,
            )?)?;
            let second_v = canonical_angle(certified_atan2(
                (&center - &second.center).dot(&second.frame.z),
                radial_distance - &second.major_radius,
            )?)?;
            let domain = curve.domain().clone();
            retained.push(SurfaceIntersectionCurve::new(
                curve,
                SurfaceIntersectionPcurve::tensor_iso_v(domain.clone(), first_v),
                angular_iso_v_pcurve(domain, second_v, frames_mirrored),
            ));
        } else {
            curves.push(curve);
        }
    }
    if retain_pcurves {
        Ok(match retained.len() {
            1 => SurfaceSurfaceIntersection::Curve(Box::new(
                retained.pop().expect("one retained torus/torus circle"),
            )),
            _ => SurfaceSurfaceIntersection::Curves(retained),
        })
    } else {
        Ok(match curves.len() {
            1 => SurfaceSurfaceIntersection::Circle(curves.pop().expect("one torus/torus circle")),
            _ => SurfaceSurfaceIntersection::Circles(curves),
        })
    }
}

fn intersect_spheres(
    first: &SphereSurface,
    second: &SphereSurface,
) -> GeometryResult<SurfaceSurfaceIntersection> {
    match point3_equal(&first.center, &second.center, crate::STRICT_PREDICATES) {
        PredicateOutcome::Decided { value: true, .. } => {
            return if decided_order(compare_reals(
                &first.radius,
                &second.radius,
                crate::STRICT_PREDICATES,
            ))? == Ordering::Equal
            {
                Ok(SurfaceSurfaceIntersection::Coincident)
            } else {
                Ok(SurfaceSurfaceIntersection::None)
            };
        }
        PredicateOutcome::Decided { value: false, .. } => {}
        PredicateOutcome::Unknown { needed, stage } => {
            return Err(GeometryError::PredicateUnresolved { needed, stage });
        }
    }
    let displacement = &second.center - &first.center;
    let distance_squared = displacement.norm_squared();
    let distance = distance_squared
        .clone()
        .sqrt()
        .map_err(GeometryError::Numeric)?;
    let radius_sum = &first.radius + &second.radius;
    let radius_difference = match decided_order(compare_reals(
        &first.radius,
        &second.radius,
        crate::STRICT_PREDICATES,
    ))? {
        Ordering::Less => &second.radius - &first.radius,
        Ordering::Equal | Ordering::Greater => &first.radius - &second.radius,
    };
    if decided_order(compare_reals(
        &distance,
        &radius_sum,
        crate::STRICT_PREDICATES,
    ))? == Ordering::Greater
        || decided_order(compare_reals(
            &distance,
            &radius_difference,
            crate::STRICT_PREDICATES,
        ))? == Ordering::Less
    {
        return Ok(SurfaceSurfaceIntersection::None);
    }

    let denominator = Real::from(2) * &distance;
    let center_distance = ((&first.radius * &first.radius - &second.radius * &second.radius
        + &distance_squared)
        / denominator)
        .map_err(GeometryError::Numeric)?;
    let inverse_distance = (Real::one() / distance).map_err(GeometryError::Numeric)?;
    let normal = displacement * inverse_distance;
    let center = first.center.clone() + normal.clone() * &center_distance;
    let circle_radius_squared = &first.radius * &first.radius - &center_distance * &center_distance;
    match decided_order(compare_reals(
        &circle_radius_squared,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? {
        Ordering::Less => Ok(SurfaceSurfaceIntersection::None),
        Ordering::Equal => Ok(SurfaceSurfaceIntersection::Point(Box::new((center).into()))),
        Ordering::Greater => {
            let radius = circle_radius_squared
                .sqrt()
                .map_err(GeometryError::Numeric)?;
            let first_axial = decided_order(compare_reals(
                &normal.cross(&first.frame.z).norm_squared(),
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))? == Ordering::Equal;
            let second_axial = decided_order(compare_reals(
                &normal.cross(&second.frame.z).norm_squared(),
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))? == Ordering::Equal;
            if first_axial && second_axial {
                let curve = Curve3::circle_arc(
                    center.clone(),
                    first.frame.x.clone(),
                    first.frame.y.clone(),
                    radius,
                    Real::zero(),
                    Real::tau(),
                )?;
                let frames_equal = orthonormal_frames_equal(&first.frame, &second.frame)?;
                let frames_mirrored = orthonormal_frames_mirrored(&first.frame, &second.frame)?;
                if frames_equal || frames_mirrored {
                    let first_height = (&center - &first.center).dot(&first.frame.z);
                    let second_height = (&center - &second.center).dot(&second.frame.z);
                    let first_latitude = (first_height / &first.radius)
                        .map_err(GeometryError::Numeric)?
                        .asin()
                        .map_err(GeometryError::Numeric)?;
                    let second_latitude = (second_height / &second.radius)
                        .map_err(GeometryError::Numeric)?
                        .asin()
                        .map_err(GeometryError::Numeric)?;
                    let domain = curve.domain().clone();
                    let second_pcurve = if frames_equal {
                        SurfaceIntersectionPcurve::tensor_iso_v(domain.clone(), second_latitude)
                    } else {
                        SurfaceIntersectionPcurve::tensor_iso(
                            domain.clone(),
                            second_latitude,
                            TensorAxis::V,
                            -Real::one(),
                            Real::tau(),
                        )
                    };
                    return Ok(SurfaceSurfaceIntersection::Curve(Box::new(
                        SurfaceIntersectionCurve::new(
                            curve,
                            SurfaceIntersectionPcurve::tensor_iso_v(domain, first_latitude),
                            second_pcurve,
                        ),
                    )));
                }
                return Ok(SurfaceSurfaceIntersection::Circle(curve));
            }
            let (x, y) = normal
                .orthonormal_basis_checked()
                .map_err(GeometryError::Numeric)?;
            Ok(SurfaceSurfaceIntersection::Circle(Curve3::circle_arc(
                center,
                x,
                y,
                radius,
                Real::zero(),
                Real::from(2) * Real::pi(),
            )?))
        }
    }
}

enum QuadraticRoots {
    None,
    All,
    Isolated(Vec<(Real, CurveSurfaceContactKind)>),
}

fn quadratic_roots(a: Real, b: Real, c: Real) -> GeometryResult<QuadraticRoots> {
    if decided_order(compare_reals(&a, &Real::zero(), crate::STRICT_PREDICATES))? == Ordering::Equal
    {
        if decided_order(compare_reals(&b, &Real::zero(), crate::STRICT_PREDICATES))?
            == Ordering::Equal
        {
            return if decided_order(compare_reals(&c, &Real::zero(), crate::STRICT_PREDICATES))?
                == Ordering::Equal
            {
                Ok(QuadraticRoots::All)
            } else {
                Ok(QuadraticRoots::None)
            };
        }
        let parameter = ((-c) / b).map_err(GeometryError::Numeric)?;
        return Ok(QuadraticRoots::Isolated(vec![(
            parameter,
            CurveSurfaceContactKind::Simple,
        )]));
    }
    let discriminant = &b * &b - Real::from(4) * &a * &c;
    match decided_order(compare_reals(
        &discriminant,
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? {
        Ordering::Less => Ok(QuadraticRoots::None),
        Ordering::Equal => {
            let parameter = ((-b) / (Real::from(2) * a)).map_err(GeometryError::Numeric)?;
            Ok(QuadraticRoots::Isolated(vec![(
                parameter,
                CurveSurfaceContactKind::Repeated,
            )]))
        }
        Ordering::Greater => {
            let root = discriminant.sqrt().map_err(GeometryError::Numeric)?;
            let denominator = Real::from(2) * a;
            let first = ((-&b - &root) / &denominator).map_err(GeometryError::Numeric)?;
            let second = ((-&b + root) / denominator).map_err(GeometryError::Numeric)?;
            Ok(QuadraticRoots::Isolated(vec![
                (first, CurveSurfaceContactKind::Simple),
                (second, CurveSurfaceContactKind::Simple),
            ]))
        }
    }
}

fn intersect_line_cone(
    curve: &Curve3,
    start: &Point3,
    end: &Point3,
    cone: &ConeSurface,
) -> GeometryResult<CurveSurfaceIntersection> {
    let offset = start - &cone.apex;
    let direction = end - start;
    let axial_offset = cone.frame.z.dot(&offset);
    let axial_direction = cone.frame.z.dot(&direction);
    let radial_offset = &offset - &(cone.frame.z.clone() * &axial_offset);
    let radial_direction = &direction - &(cone.frame.z.clone() * &axial_direction);
    let sin = cone.semi_angle.clone().sin();
    let cos = cone.semi_angle.clone().cos();
    let sin_squared = &sin * &sin;
    let cos_squared = &cos * &cos;
    let a = &cos_squared * radial_direction.norm_squared()
        - &sin_squared * &axial_direction * &axial_direction;
    let b = Real::from(2)
        * (&cos_squared * radial_offset.dot(&radial_direction)
            - &sin_squared * &axial_offset * &axial_direction);
    let c =
        &cos_squared * radial_offset.norm_squared() - &sin_squared * &axial_offset * &axial_offset;
    match quadratic_roots(a, b, c)? {
        QuadraticRoots::None => Ok(CurveSurfaceIntersection::None),
        QuadraticRoots::Isolated(roots) => {
            let mut upper_roots = Vec::new();
            for (parameter, kind) in roots {
                let axial = &axial_offset + &parameter * &axial_direction;
                if decided_order(compare_reals(
                    &axial,
                    &Real::zero(),
                    crate::STRICT_PREDICATES,
                ))? != Ordering::Less
                {
                    upper_roots.push((parameter, kind));
                }
            }
            isolated_line_parameters(curve, upper_roots)
        }
        QuadraticRoots::All => {
            let axial_start = axial_offset;
            let axial_end = &axial_start + &axial_direction;
            let start_order = decided_order(compare_reals(
                &axial_start,
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))?;
            let end_order = decided_order(compare_reals(
                &axial_end,
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))?;
            if start_order != Ordering::Less && end_order != Ordering::Less {
                return Ok(CurveSurfaceIntersection::Contained);
            }
            if start_order == Ordering::Less && end_order == Ordering::Less {
                return Ok(CurveSurfaceIntersection::None);
            }
            let boundary = ((-&axial_start) / &axial_direction).map_err(GeometryError::Numeric)?;
            if start_order == Ordering::Equal || end_order == Ordering::Equal {
                return isolated_line_parameters(
                    curve,
                    [(boundary, CurveSurfaceContactKind::Boundary)],
                );
            }
            let domain = if start_order == Ordering::Greater {
                ParameterDomain::new(curve.domain().represented_start()?.clone(), boundary)?
            } else {
                ParameterDomain::new(boundary, curve.domain().represented_end()?.clone())?
            };
            Ok(CurveSurfaceIntersection::Overlap(domain.into()))
        }
    }
}

fn quadratic_line_intersection(
    curve: &Curve3,
    offset: &Vector3,
    direction: &Vector3,
    radius: &Real,
) -> GeometryResult<CurveSurfaceIntersection> {
    let a = direction.dot(direction);
    let b = Real::from(2) * offset.dot(direction);
    let c = offset.dot(offset) - radius * radius;
    match quadratic_roots(a, b, c)? {
        QuadraticRoots::None => Ok(CurveSurfaceIntersection::None),
        QuadraticRoots::All => Ok(CurveSurfaceIntersection::Contained),
        QuadraticRoots::Isolated(roots) => isolated_line_parameters(curve, roots),
    }
}

fn isolated_line_parameters(
    curve: &Curve3,
    parameters: impl IntoIterator<Item = (Real, CurveSurfaceContactKind)>,
) -> GeometryResult<CurveSurfaceIntersection> {
    let mut points = Vec::new();
    for (parameter, kind) in parameters {
        if curve.domain().contains_real(&parameter)? {
            points.push(CurveSurfacePoint {
                point: curve.evaluate_real(&parameter)?.into(),
                parameter: parameter.into(),
                kind,
            });
        }
    }
    if points.is_empty() {
        Ok(CurveSurfaceIntersection::None)
    } else {
        Ok(CurveSurfaceIntersection::Points(points))
    }
}

fn validate_control_net(control_points: &[Point3], weights: &[Real]) -> GeometryResult<()> {
    if control_points.len() < 2 {
        return Err(GeometryError::TooFewControlPoints);
    }
    if control_points.len() != weights.len() {
        return Err(GeometryError::WeightCountMismatch);
    }
    Ok(())
}

fn decompose_nurbs_into_bezier_segments(
    nurbs: &NurbsCurve3,
) -> GeometryResult<Vec<(Curve3, ParameterDomain)>> {
    let mut breaks = vec![nurbs.knots[nurbs.degree].clone()];
    for knot in &nurbs.knots[(nurbs.degree + 1)..nurbs.control_points.len()] {
        if decided_order(compare_reals(
            knot,
            breaks.last().expect("start break"),
            crate::STRICT_PREDICATES,
        ))? != Ordering::Equal
        {
            breaks.push(knot.clone());
        }
    }
    breaks.push(nurbs.knots[nurbs.control_points.len()].clone());

    let mut controls = nurbs.homogeneous_controls().to_vec();
    let mut knots = nurbs.knots.clone();
    for knot in &breaks[1..breaks.len() - 1] {
        let mut multiplicity = knot_multiplicity(&knots, knot)?;
        while multiplicity < nurbs.degree {
            let span = find_raw_span(knot, nurbs.degree, controls.len(), &knots)?;
            (controls, knots) =
                insert_nurbs_knot_once(&controls, &knots, nurbs.degree, span, multiplicity, knot)?;
            multiplicity += 1;
        }
    }
    let mut segments = Vec::with_capacity(breaks.len() - 1);
    for index in 0..breaks.len() - 1 {
        let control_start = index * nurbs.degree;
        let control_end = control_start + nurbs.degree;
        segments.push((
            rational_bezier_from_homogeneous(controls[control_start..=control_end].to_vec(), None)?,
            ParameterDomain::new(breaks[index].clone(), breaks[index + 1].clone())?,
        ));
    }
    Ok(segments)
}

fn surface_projection_varies(
    control_points: &[Point3],
    axes: (usize, usize),
) -> GeometryResult<bool> {
    for point in &control_points[1..] {
        if decided_order(compare_reals(
            control_coordinate(point, axes.0),
            control_coordinate(&control_points[0], axes.0),
            crate::STRICT_PREDICATES,
        ))? != Ordering::Equal
            || decided_order(compare_reals(
                control_coordinate(point, axes.1),
                control_coordinate(&control_points[0], axes.1),
                crate::STRICT_PREDICATES,
            ))? != Ordering::Equal
        {
            return Ok(true);
        }
    }
    Ok(false)
}

fn control_coordinate(point: &Point3, axis: usize) -> &Real {
    match axis {
        0 => &point.x,
        1 => &point.y,
        2 => &point.z,
        _ => unreachable!("3D coordinate axis"),
    }
}

fn certified_constant_coordinates(control_points: &[Point3]) -> [Option<Real>; 3] {
    std::array::from_fn(|axis| {
        let first = control_coordinate(
            control_points
                .first()
                .expect("validated rational Bezier has control points"),
            axis,
        );
        control_points[1..]
            .iter()
            .all(|point| {
                matches!(
                    compare_reals(
                        control_coordinate(point, axis),
                        first,
                        crate::STRICT_PREDICATES,
                    ),
                    PredicateOutcome::Decided {
                        value: Ordering::Equal,
                        ..
                    }
                )
            })
            .then(|| first.clone())
    })
}

fn restore_constant_coordinates(point: &mut Point3, coordinates: &[Option<Real>; 3]) {
    for (axis, coordinate) in coordinates.iter().enumerate() {
        let Some(coordinate) = coordinate else {
            continue;
        };
        match axis {
            0 => point.x = coordinate.clone(),
            1 => point.y = coordinate.clone(),
            2 => point.z = coordinate.clone(),
            _ => unreachable!("three constant coordinate slots"),
        }
    }
}

fn points_equal(left: &Point3, right: &Point3) -> GeometryResult<bool> {
    match point3_equal(left, right, crate::STRICT_PREDICATES) {
        PredicateOutcome::Decided { value, .. } => Ok(value),
        PredicateOutcome::Unknown { needed, stage } => {
            Err(GeometryError::PredicateUnresolved { needed, stage })
        }
    }
}

fn validate_surface_control_net(
    control_points: &[Vec<Point3>],
    weights: &[Vec<Real>],
) -> GeometryResult<(usize, usize)> {
    if control_points.len() < 2 {
        return Err(GeometryError::InvalidControlNetShape);
    }
    if control_points.len() != weights.len() {
        return Err(GeometryError::SurfaceWeightShapeMismatch);
    }
    let u_count = control_points[0].len();
    if u_count < 2 || control_points.iter().any(|row| row.len() != u_count) {
        return Err(GeometryError::InvalidControlNetShape);
    }
    if weights.iter().any(|row| row.len() != u_count) {
        return Err(GeometryError::SurfaceWeightShapeMismatch);
    }
    Ok((u_count, control_points.len()))
}

fn validate_positive_surface_weights(weights: &[Vec<Real>]) -> GeometryResult<()> {
    for row in weights {
        validate_positive_weights(row)?;
    }
    Ok(())
}

fn validate_nurbs_axis(degree: usize, control_count: usize, knots: &[Real]) -> GeometryResult<()> {
    if degree == 0 || degree >= control_count {
        return Err(GeometryError::InvalidDegree);
    }
    if knots.len() != control_count + degree + 1 {
        return Err(GeometryError::InvalidKnotCount);
    }
    for adjacent in knots.windows(2) {
        if !matches!(
            decided_order(compare_reals(
                &adjacent[0],
                &adjacent[1],
                crate::STRICT_PREDICATES
            ))?,
            Ordering::Less | Ordering::Equal
        ) {
            return Err(GeometryError::InvalidKnotOrder);
        }
    }
    validate_clamped_knot_multiplicities(degree, knots)
}

fn validate_positive_weights(weights: &[Real]) -> GeometryResult<()> {
    for weight in weights {
        match compare_reals(weight, &Real::zero(), crate::STRICT_PREDICATES) {
            PredicateOutcome::Decided {
                value: Ordering::Greater,
                ..
            } => {}
            PredicateOutcome::Decided { .. } => return Err(GeometryError::InvalidWeight),
            PredicateOutcome::Unknown { needed, stage } => {
                return Err(GeometryError::PredicateUnresolved { needed, stage });
            }
        }
    }
    Ok(())
}

fn validate_clamped_knot_multiplicities(degree: usize, knots: &[Real]) -> GeometryResult<()> {
    let endpoint_count = degree + 1;
    for knot in &knots[1..endpoint_count] {
        if decided_order(compare_reals(knot, &knots[0], crate::STRICT_PREDICATES))?
            != Ordering::Equal
        {
            return Err(GeometryError::UnclampedNurbs);
        }
    }
    let last = knots.len() - 1;
    for knot in &knots[(last + 1 - endpoint_count)..last] {
        if decided_order(compare_reals(knot, &knots[last], crate::STRICT_PREDICATES))?
            != Ordering::Equal
        {
            return Err(GeometryError::UnclampedNurbs);
        }
    }
    // An endpoint run must stop after degree + 1 entries. Checking only the
    // interior runs misses extra knots attached to either clamped endpoint.
    if endpoint_count < knots.len() - endpoint_count {
        for (interior, endpoint) in [
            (&knots[endpoint_count], &knots[0]),
            (&knots[last - endpoint_count], &knots[last]),
        ] {
            if decided_order(compare_reals(interior, endpoint, crate::STRICT_PREDICATES))?
                == Ordering::Equal
            {
                return Err(GeometryError::InvalidKnotMultiplicity);
            }
        }
    }
    let mut run = 1_usize;
    for index in endpoint_count..(knots.len() - endpoint_count) {
        if decided_order(compare_reals(
            &knots[index],
            &knots[index - 1],
            crate::STRICT_PREDICATES,
        ))? == Ordering::Equal
        {
            run += 1;
            if run > degree {
                return Err(GeometryError::InvalidKnotMultiplicity);
            }
        } else {
            run = 1;
        }
    }
    Ok(())
}

fn decided_order(outcome: PredicateOutcome<Ordering>) -> GeometryResult<Ordering> {
    match outcome {
        PredicateOutcome::Decided { value, .. } => Ok(value),
        PredicateOutcome::Unknown { needed, stage } => {
            Err(GeometryError::PredicateUnresolved { needed, stage })
        }
    }
}

pub(crate) fn certified_atan2(y: Real, x: Real) -> GeometryResult<Real> {
    let y_order = decided_order(compare_reals(&y, &Real::zero(), crate::STRICT_PREDICATES))?;
    let x_order = decided_order(compare_reals(&x, &Real::zero(), crate::STRICT_PREDICATES))?;
    match (y_order, x_order) {
        (Ordering::Equal, Ordering::Equal | Ordering::Greater) => Ok(Real::zero()),
        (Ordering::Equal, Ordering::Less) => Ok(Real::pi()),
        (Ordering::Greater, Ordering::Equal) => {
            (Real::pi() / Real::from(2)).map_err(GeometryError::Numeric)
        }
        (Ordering::Less, Ordering::Equal) => {
            (-Real::pi() / Real::from(2)).map_err(GeometryError::Numeric)
        }
        (_, Ordering::Greater) => (y / x)
            .map_err(GeometryError::Numeric)?
            .atan()
            .map_err(GeometryError::Numeric),
        (Ordering::Greater, Ordering::Less) => Ok((y / x)
            .map_err(GeometryError::Numeric)?
            .atan()
            .map_err(GeometryError::Numeric)?
            + Real::pi()),
        (Ordering::Less, Ordering::Less) => Ok((y / x)
            .map_err(GeometryError::Numeric)?
            .atan()
            .map_err(GeometryError::Numeric)?
            - Real::pi()),
    }
}

fn validate_arc_axes(x: &Vector3, y: &Vector3) -> GeometryResult<()> {
    let one = Real::one();
    let zero = Real::zero();
    for (actual, expected) in [
        (x.norm_squared(), &one),
        (y.norm_squared(), &one),
        (x.dot(y), &zero),
    ] {
        if decided_order(compare_reals(&actual, expected, crate::STRICT_PREDICATES))?
            != Ordering::Equal
        {
            return Err(GeometryError::InvalidSurfaceFrame);
        }
    }
    Ok(())
}

fn validate_arc_domain(start: Real, end: Real) -> GeometryResult<ParameterDomain> {
    let domain = ParameterDomain::new(start, end)?;
    let sweep = domain.end() - domain.start();
    if decided_order(compare_reals(
        &sweep,
        &(Real::from(2) * Real::pi()),
        crate::STRICT_PREDICATES,
    ))? == Ordering::Greater
    {
        Err(GeometryError::InvalidArcSweep)
    } else {
        Ok(domain)
    }
}

fn ellipse_arc_angle(arc: &EllipseArc3, domain: &ParameterDomain, parameter: &Real) -> Real {
    let delta = parameter - domain.start();
    if arc.direction > 0 {
        &arc.angle_at_start + delta
    } else {
        &arc.angle_at_start - delta
    }
}

fn evaluate_ellipse_arc(arc: &EllipseArc3, domain: &ParameterDomain, parameter: &Real) -> Point3 {
    let angle = ellipse_arc_angle(arc, domain, parameter);
    let sin = angle.clone().sin();
    let cos = angle.cos();
    arc.center.clone()
        + arc.x.clone() * (&arc.x_radius * cos)
        + arc.y.clone() * (&arc.y_radius * sin)
}

fn evaluate_ellipse_arc_derivative(
    arc: &EllipseArc3,
    domain: &ParameterDomain,
    parameter: &Real,
    order: usize,
) -> Vector3 {
    let angle = ellipse_arc_angle(arc, domain, parameter);
    let sin = angle.clone().sin();
    let cos = angle.cos();
    let (cos_derivative, sin_derivative) = match order % 4 {
        0 => (cos, sin),
        1 => (-sin, cos),
        2 => (-cos, -sin),
        3 => (sin, -cos),
        _ => unreachable!("modulo four"),
    };
    let derivative = arc.x.clone() * (&arc.x_radius * cos_derivative)
        + arc.y.clone() * (&arc.y_radius * sin_derivative);
    if arc.direction > 0 || order.is_multiple_of(2) {
        derivative
    } else {
        -derivative
    }
}

fn reversed_ellipse_arc(arc: &EllipseArc3, domain: &ParameterDomain) -> EllipseArc3 {
    EllipseArc3 {
        angle_at_start: ellipse_arc_angle(arc, domain, domain.end()),
        direction: -arc.direction,
        ..arc.clone()
    }
}

fn split_ellipse_arc(
    arc: &EllipseArc3,
    domain: &ParameterDomain,
    parameter: &Real,
    kind: Curve3Kind,
) -> GeometryResult<(Curve3, Curve3)> {
    let right_angle = ellipse_arc_angle(arc, domain, parameter);
    let left_geometry = arc.clone();
    let right_geometry = EllipseArc3 {
        angle_at_start: right_angle,
        ..arc.clone()
    };
    let left_domain = ParameterDomain::new(domain.start().clone(), parameter.clone())?;
    let right_domain = ParameterDomain::new(parameter.clone(), domain.end().clone())?;
    let wrap = |geometry| match kind {
        Curve3Kind::CircleArc => CurveGeometry3::CircleArc(geometry),
        Curve3Kind::EllipseArc => CurveGeometry3::EllipseArc(geometry),
        Curve3Kind::Line
        | Curve3Kind::RationalBezier
        | Curve3Kind::Nurbs
        | Curve3Kind::AffineImage
        | Curve3Kind::Rotation
        | Curve3Kind::Translation
        | Curve3Kind::PlanarImage => {
            unreachable!("ellipse split kind")
        }
    };
    Ok((
        Curve3::from_parts(wrap(left_geometry), left_domain),
        Curve3::from_parts(wrap(right_geometry), right_domain),
    ))
}

fn ellipse_arc_conservative_bounds(arc: &EllipseArc3) -> GeometryResult<Aabb> {
    let radius = if decided_order(compare_reals(
        &arc.x_radius,
        &arc.y_radius,
        crate::STRICT_PREDICATES,
    ))? == Ordering::Greater
    {
        &arc.x_radius
    } else {
        &arc.y_radius
    };
    Ok(Aabb::new(
        Point3::new(
            &arc.center.x - radius,
            &arc.center.y - radius,
            &arc.center.z - radius,
        ),
        Point3::new(
            &arc.center.x + radius,
            &arc.center.y + radius,
            &arc.center.z + radius,
        ),
    ))
}

fn centered_cube_bounds(center: &Point3, radius: &Real) -> Aabb {
    Aabb::new(
        Point3::new(&center.x - radius, &center.y - radius, &center.z - radius),
        Point3::new(&center.x + radius, &center.y + radius, &center.z + radius),
    )
}

fn revolution_bounds(surface: &RevolutionSurface) -> GeometryResult<Aabb> {
    rotation_bounds(
        &surface.profile.bounds()?,
        &surface.axis_origin,
        &surface.axis,
    )
}

fn rotation_bounds(bounds: &Aabb, axis_origin: &Point3, axis: &Vector3) -> GeometryResult<Aabb> {
    let xs = [&bounds.mins.x, &bounds.maxs.x];
    let ys = [&bounds.mins.y, &bounds.maxs.y];
    let zs = [&bounds.mins.z, &bounds.maxs.z];
    let first_offset = Vector3::from_xyz(
        xs[0] - &axis_origin.x,
        ys[0] - &axis_origin.y,
        zs[0] - &axis_origin.z,
    );
    let first_axial = axis.dot(&first_offset);
    let first_radial = first_offset - axis.clone() * first_axial.clone();
    let mut axial_min = first_axial.clone();
    let mut axial_max = first_axial;
    let mut radius_squared = first_radial.norm_squared();
    for x in xs {
        for y in ys {
            for z in zs {
                let offset =
                    Vector3::from_xyz(x - &axis_origin.x, y - &axis_origin.y, z - &axis_origin.z);
                let axial = axis.dot(&offset);
                update_bound_min(&mut axial_min, &axial)?;
                update_bound_max(&mut axial_max, &axial)?;
                let radial = offset - axis.clone() * axial;
                update_bound_max(&mut radius_squared, &radial.norm_squared())?;
            }
        }
    }
    let radius = radius_squared.sqrt().map_err(GeometryError::Numeric)?;
    let coordinate_bounds =
        |origin: &Real, axis_component: &Real| -> GeometryResult<(Real, Real)> {
            let first_axial = axis_component * &axial_min;
            let second_axial = axis_component * &axial_max;
            let (axial_low, axial_high) = if decided_order(compare_reals(
                &first_axial,
                &second_axial,
                crate::STRICT_PREDICATES,
            ))? == Ordering::Greater
            {
                (second_axial, first_axial)
            } else {
                (first_axial, second_axial)
            };
            let radial_factor = (Real::one() - axis_component * axis_component)
                .sqrt()
                .map_err(GeometryError::Numeric)?;
            let radial_extent = &radius * radial_factor;
            Ok((
                origin + axial_low - &radial_extent,
                origin + axial_high + radial_extent,
            ))
        };
    let (min_x, max_x) = coordinate_bounds(&axis_origin.x, &axis.0[0])?;
    let (min_y, max_y) = coordinate_bounds(&axis_origin.y, &axis.0[1])?;
    let (min_z, max_z) = coordinate_bounds(&axis_origin.z, &axis.0[2])?;
    Ok(Aabb::new(
        Point3::new(min_x, min_y, min_z),
        Point3::new(max_x, max_y, max_z),
    ))
}

fn rotate_point_about_axis(
    point: &Point3,
    axis_origin: &Point3,
    axis: &Vector3,
    angle: &Real,
) -> Point3 {
    let relative = point - axis_origin;
    axis_origin.clone() + rotate_vector_about_axis(&relative, axis, angle)
}

fn rotate_vector_about_axis(vector: &Vector3, axis: &Vector3, angle: &Real) -> Vector3 {
    let axial = axis.clone() * axis.dot(vector);
    let radial = vector - &axial;
    let sin = angle.clone().sin();
    let cos = angle.clone().cos();
    axial + radial.clone() * cos + axis.cross(&radial) * sin
}

fn exact_surface_control_bounds(control_points: &[Vec<Point3>]) -> GeometryResult<Aabb> {
    let points = control_points
        .iter()
        .flat_map(|row| row.iter())
        .cloned()
        .collect::<Vec<_>>();
    exact_point_bounds(&points)
}

fn exact_point_bounds(points: &[Point3]) -> GeometryResult<Aabb> {
    let first = &points[0];
    let mut mins = first.clone();
    let mut maxs = first.clone();
    for point in &points[1..] {
        update_bound_min(&mut mins.x, &point.x)?;
        update_bound_min(&mut mins.y, &point.y)?;
        update_bound_min(&mut mins.z, &point.z)?;
        update_bound_max(&mut maxs.x, &point.x)?;
        update_bound_max(&mut maxs.y, &point.y)?;
        update_bound_max(&mut maxs.z, &point.z)?;
    }
    Ok(Aabb::new(mins, maxs))
}

fn update_bound_min(current: &mut Real, candidate: &Real) -> GeometryResult<()> {
    if decided_order(compare_reals(candidate, current, crate::STRICT_PREDICATES))? == Ordering::Less
    {
        *current = candidate.clone();
    }
    Ok(())
}

fn update_bound_max(current: &mut Real, candidate: &Real) -> GeometryResult<()> {
    if decided_order(compare_reals(candidate, current, crate::STRICT_PREDICATES))?
        == Ordering::Greater
    {
        *current = candidate.clone();
    }
    Ok(())
}

fn weighted_controls(points: &[Point3], weights: &[Real]) -> Vec<HomogeneousPoint3> {
    points
        .iter()
        .zip(weights)
        .map(|(point, weight)| HomogeneousPoint3::from_affine(point, weight))
        .collect()
}

fn evaluate_tensor_bezier(
    controls: &[Vec<HomogeneousPoint3>],
    parameter: &Point2,
) -> GeometryResult<Point3> {
    let u_values = controls
        .iter()
        .map(|row| {
            evaluate_homogeneous_bezier_value(row, &parameter.x)
                .ok_or(GeometryError::InvalidControlNetShape)
        })
        .collect::<GeometryResult<Vec<_>>>()?;
    evaluate_homogeneous_bezier_value(&u_values, &parameter.y)
        .ok_or(GeometryError::InvalidControlNetShape)?
        .project()
}

fn evaluate_tensor_bezier_partials(
    controls: &[Vec<HomogeneousPoint3>],
    parameter: &Point2,
) -> GeometryResult<SurfacePartials> {
    let u_values = controls
        .iter()
        .map(|row| {
            evaluate_homogeneous_bezier_value(row, &parameter.x)
                .ok_or(GeometryError::InvalidControlNetShape)
        })
        .collect::<GeometryResult<Vec<_>>>()?;
    let u_derivatives = controls
        .iter()
        .map(|row| {
            evaluate_homogeneous_bezier_derivative_value(row, &parameter.x)
                .ok_or(GeometryError::InvalidControlNetShape)
        })
        .collect::<GeometryResult<Vec<_>>>()?;
    let value = evaluate_homogeneous_bezier_value(&u_values, &parameter.y)
        .ok_or(GeometryError::InvalidControlNetShape)?;
    let u_derivative = evaluate_homogeneous_bezier_value(&u_derivatives, &parameter.y)
        .ok_or(GeometryError::InvalidControlNetShape)?;
    let v_derivative = evaluate_homogeneous_bezier_derivative_value(&u_values, &parameter.y)
        .ok_or(GeometryError::InvalidControlNetShape)?;
    Ok(SurfacePartials::from_coordinates(
        project_homogeneous_derivative(&value, &u_derivative)?,
        project_homogeneous_derivative(&value, &v_derivative)?,
    ))
}

fn evaluate_tensor_nurbs(
    surface: &NurbsSurface,
    domain: &SurfaceDomain,
    parameter: &Point2,
) -> GeometryResult<Point3> {
    let (value, _, _) = evaluate_tensor_nurbs_homogeneous(surface, domain, parameter)?;
    value.project()
}

fn evaluate_tensor_nurbs_partials(
    surface: &NurbsSurface,
    domain: &SurfaceDomain,
    parameter: &Point2,
) -> GeometryResult<SurfacePartials> {
    let (value, u_derivative, v_derivative) =
        evaluate_tensor_nurbs_homogeneous(surface, domain, parameter)?;
    Ok(SurfacePartials::from_coordinates(
        project_homogeneous_derivative(&value, &u_derivative)?,
        project_homogeneous_derivative(&value, &v_derivative)?,
    ))
}

fn evaluate_tensor_nurbs_homogeneous(
    surface: &NurbsSurface,
    domain: &SurfaceDomain,
    parameter: &Point2,
) -> GeometryResult<(HomogeneousPoint3, HomogeneousPoint3, HomogeneousPoint3)> {
    let SurfaceParameterDomain::Closed(u_domain) = &domain.u else {
        return Err(GeometryError::InvalidParameterDomain);
    };
    let SurfaceParameterDomain::Closed(v_domain) = &domain.v else {
        return Err(GeometryError::InvalidParameterDomain);
    };
    let controls = surface.homogeneous_controls();
    let u_count = controls[0].len();
    let v_count = controls.len();
    let u_span = find_span(
        &parameter.x,
        &u_domain.represented_domain()?,
        surface.u_degree,
        u_count,
        &surface.u_knots,
    )?;
    let v_span = find_span(
        &parameter.y,
        &v_domain.represented_domain()?,
        surface.v_degree,
        v_count,
        &surface.v_knots,
    )?;
    let u_jets = controls
        .iter()
        .map(|row| {
            evaluate_homogeneous_de_boor_jet(
                row,
                &surface.u_knots,
                surface.u_degree,
                u_span,
                &parameter.x,
            )
        })
        .collect::<GeometryResult<Vec<_>>>()?;
    let u_values = u_jets
        .iter()
        .map(|(value, _)| value.clone())
        .collect::<Vec<_>>();
    let u_derivatives = u_jets
        .into_iter()
        .map(|(_, derivative)| derivative)
        .collect::<Vec<_>>();
    let (value, v_derivative) = evaluate_homogeneous_de_boor_jet(
        &u_values,
        &surface.v_knots,
        surface.v_degree,
        v_span,
        &parameter.y,
    )?;
    let (u_derivative, _) = evaluate_homogeneous_de_boor_jet(
        &u_derivatives,
        &surface.v_knots,
        surface.v_degree,
        v_span,
        &parameter.y,
    )?;
    Ok((value, u_derivative, v_derivative))
}

fn evaluate_homogeneous_bezier(
    controls: &[HomogeneousPoint3],
    parameter: &Real,
) -> GeometryResult<Point3> {
    evaluate_homogeneous_bezier_value(controls, parameter)
        .ok_or(GeometryError::TooFewControlPoints)?
        .project()
}

fn evaluate_homogeneous_bezier_value(
    controls: &[HomogeneousPoint3],
    parameter: &Real,
) -> Option<HomogeneousPoint3> {
    let mut level = controls.to_vec();
    while level.len() > 1 {
        level = level
            .windows(2)
            .map(|pair| pair[0].lerp(&pair[1], parameter))
            .collect();
    }
    level.pop()
}

fn evaluate_homogeneous_bezier_derivative_value(
    controls: &[HomogeneousPoint3],
    parameter: &Real,
) -> Option<HomogeneousPoint3> {
    if controls.len() < 2 {
        return None;
    }
    let degree = Real::from((controls.len() - 1) as u64);
    let derivative_controls = controls
        .windows(2)
        .map(|pair| HomogeneousPoint3 {
            x: (&pair[1].x - &pair[0].x) * &degree,
            y: (&pair[1].y - &pair[0].y) * &degree,
            z: (&pair[1].z - &pair[0].z) * &degree,
            w: (&pair[1].w - &pair[0].w) * &degree,
        })
        .collect::<Vec<_>>();
    evaluate_homogeneous_bezier_value(&derivative_controls, parameter)
}

fn evaluate_rational_bezier_derivative(
    curve: &RationalBezier3,
    parameter: &Real,
    order: usize,
) -> GeometryResult<Vector3> {
    let mut jets = derivative_jet_buffer(order)?;
    let mut derivative_controls = curve.homogeneous_controls().to_vec();
    let degree = derivative_controls.len() - 1;
    jets.push(
        evaluate_homogeneous_bezier_value(&derivative_controls, parameter)
            .ok_or(GeometryError::TooFewControlPoints)?,
    );
    for derivative_order in 1..=order {
        if derivative_order > degree {
            jets.push(homogeneous_zero());
            continue;
        }
        let factor = Real::from((degree - derivative_order + 1) as u64);
        derivative_controls = derivative_controls
            .windows(2)
            .map(|pair| homogeneous_difference_scaled(&pair[1], &pair[0], &factor))
            .collect();
        jets.push(
            evaluate_homogeneous_bezier_value(&derivative_controls, parameter)
                .ok_or(GeometryError::TooFewControlPoints)?,
        );
    }
    project_homogeneous_derivative_order(&jets, order)
}

fn find_span(
    parameter: &Real,
    domain: &ParameterDomain,
    degree: usize,
    control_count: usize,
    knots: &[Real],
) -> GeometryResult<usize> {
    if decided_order(compare_reals(
        parameter,
        domain.end(),
        crate::STRICT_PREDICATES,
    ))? == Ordering::Equal
    {
        return Ok(control_count - 1);
    }
    for span in degree..control_count {
        let after_start = decided_order(compare_reals(
            &knots[span],
            parameter,
            crate::STRICT_PREDICATES,
        ))?;
        let before_end = decided_order(compare_reals(
            parameter,
            &knots[span + 1],
            crate::STRICT_PREDICATES,
        ))?;
        if matches!(after_start, Ordering::Less | Ordering::Equal) && before_end == Ordering::Less {
            return Ok(span);
        }
    }
    Err(GeometryError::InvalidParameterDomain)
}

fn evaluate_homogeneous_de_boor(
    controls: &[HomogeneousPoint3],
    knots: &[Real],
    degree: usize,
    span: usize,
    parameter: &Real,
) -> GeometryResult<Point3> {
    evaluate_homogeneous_de_boor_jet(controls, knots, degree, span, parameter)?
        .0
        .project()
}

fn evaluate_homogeneous_de_boor_derivative(
    controls: &[HomogeneousPoint3],
    knots: &[Real],
    degree: usize,
    span: usize,
    parameter: &Real,
    order: usize,
) -> GeometryResult<Vector3> {
    let jets = evaluate_homogeneous_de_boor_jets(controls, knots, degree, span, parameter, order)?;
    project_homogeneous_derivative_order(&jets, order)
}

fn evaluate_homogeneous_de_boor_jet(
    controls: &[HomogeneousPoint3],
    knots: &[Real],
    degree: usize,
    span: usize,
    parameter: &Real,
) -> GeometryResult<(HomogeneousPoint3, HomogeneousPoint3)> {
    let jets = evaluate_homogeneous_de_boor_jets(controls, knots, degree, span, parameter, 1)?;
    Ok((jets[0].clone(), jets[1].clone()))
}

fn evaluate_homogeneous_de_boor_jets(
    controls: &[HomogeneousPoint3],
    knots: &[Real],
    degree: usize,
    span: usize,
    parameter: &Real,
    order: usize,
) -> GeometryResult<Vec<HomogeneousPoint3>> {
    let zero = homogeneous_zero();
    let mut level = controls[(span - degree)..=span]
        .iter()
        .cloned()
        .map(|value| {
            let mut jets = derivative_jet_buffer(order)?;
            jets.push(value);
            jets.extend(std::iter::repeat_n(zero.clone(), order));
            Ok(jets)
        })
        .collect::<GeometryResult<Vec<_>>>()?;
    for stage in 1..=degree {
        for local in (stage..=degree).rev() {
            let knot_index = span - degree + local;
            let denominator = &knots[knot_index + degree - stage + 1] - &knots[knot_index];
            let alpha = ((parameter - &knots[knot_index]) / &denominator)
                .map_err(GeometryError::Numeric)?;
            let alpha_derivative = (Real::one() / &denominator).map_err(GeometryError::Numeric)?;
            let left = &level[local - 1];
            let right = &level[local];
            let mut jets = derivative_jet_buffer(order)?;
            jets.push(left[0].lerp(&right[0], &alpha));
            for derivative_order in 1..=order {
                let base = left[derivative_order].lerp(&right[derivative_order], &alpha);
                let factor = Real::from(derivative_order as u64) * &alpha_derivative;
                jets.push(homogeneous_add(
                    &base,
                    &homogeneous_difference_scaled(
                        &right[derivative_order - 1],
                        &left[derivative_order - 1],
                        &factor,
                    ),
                ));
            }
            level[local] = jets;
        }
    }
    Ok(level.pop().expect("a degree-d span has d+1 jet buffers"))
}

/// Reserves one complete derivative buffer before evaluating its entries.
/// Address-space overflow and allocator refusal are distinct typed failures.
/// This does not bound scalar allocations or total work across all buffers.
fn derivative_jet_buffer<T>(order: usize) -> GeometryResult<Vec<T>> {
    let count = order
        .checked_add(1)
        .ok_or(GeometryError::Numeric(hyperreal::Problem::OutOfRange))?;
    std::alloc::Layout::array::<T>(count)
        .map_err(|_| GeometryError::Numeric(hyperreal::Problem::OutOfRange))?;
    let mut values = Vec::new();
    values
        .try_reserve_exact(count)
        .map_err(|_| GeometryError::Numeric(hyperreal::Problem::Exhausted))?;
    Ok(values)
}

fn homogeneous_zero() -> HomogeneousPoint3 {
    HomogeneousPoint3 {
        x: Real::zero(),
        y: Real::zero(),
        z: Real::zero(),
        w: Real::zero(),
    }
}

fn homogeneous_difference_scaled(
    left: &HomogeneousPoint3,
    right: &HomogeneousPoint3,
    factor: &Real,
) -> HomogeneousPoint3 {
    HomogeneousPoint3 {
        x: (&left.x - &right.x) * factor,
        y: (&left.y - &right.y) * factor,
        z: (&left.z - &right.z) * factor,
        w: (&left.w - &right.w) * factor,
    }
}

fn homogeneous_add(left: &HomogeneousPoint3, right: &HomogeneousPoint3) -> HomogeneousPoint3 {
    HomogeneousPoint3 {
        x: &left.x + &right.x,
        y: &left.y + &right.y,
        z: &left.z + &right.z,
        w: &left.w + &right.w,
    }
}

fn project_homogeneous_derivative_order(
    jets: &[HomogeneousPoint3],
    order: usize,
) -> GeometryResult<Vector3> {
    let mut derivatives = derivative_jet_buffer(order)?;
    derivatives.push(divide_vector_by_real(
        Vector3::from_xyz(jets[0].x.clone(), jets[0].y.clone(), jets[0].z.clone()),
        &jets[0].w,
    )?);
    for derivative_order in 1..=order {
        let mut numerator = Vector3::from_xyz(
            jets[derivative_order].x.clone(),
            jets[derivative_order].y.clone(),
            jets[derivative_order].z.clone(),
        );
        for weight_order in 1..=derivative_order {
            let coefficient =
                binomial_real(derivative_order, weight_order)? * &jets[weight_order].w;
            numerator =
                numerator - derivatives[derivative_order - weight_order].clone() * coefficient;
        }
        derivatives.push(divide_vector_by_real(numerator, &jets[0].w)?);
    }
    Ok(derivatives.pop().expect("positive derivative order"))
}

fn divide_vector_by_real(vector: Vector3, denominator: &Real) -> GeometryResult<Vector3> {
    Ok(Vector3::from_xyz(
        (vector.0[0].clone() / denominator).map_err(GeometryError::Numeric)?,
        (vector.0[1].clone() / denominator).map_err(GeometryError::Numeric)?,
        (vector.0[2].clone() / denominator).map_err(GeometryError::Numeric)?,
    ))
}

fn normalized_greville_coordinates(
    count: usize,
    degree: usize,
    knots: &[Real],
    domain_start: &Real,
    domain_span: &Real,
) -> GeometryResult<Vec<Real>> {
    let degree_scalar = Real::from(u128::try_from(degree).expect("usize is representable as u128"));
    (0..count)
        .map(|index| {
            let sum = knots[index + 1..=index + degree]
                .iter()
                .fold(Real::zero(), |sum, knot| sum + knot);
            let greville = (sum / &degree_scalar).map_err(GeometryError::Numeric)?;
            ((greville - domain_start) / domain_span).map_err(GeometryError::Numeric)
        })
        .collect()
}

fn binomial_real(n: usize, k: usize) -> GeometryResult<Real> {
    let k = k.min(n - k);
    let mut result = Real::one();
    for index in 1..=k {
        result = (result * Real::from((n + 1 - index) as u64) / Real::from(index as u64))
            .map_err(GeometryError::Numeric)?;
    }
    Ok(result)
}

fn project_homogeneous_derivative(
    value: &HomogeneousPoint3,
    derivative: &HomogeneousPoint3,
) -> GeometryResult<Vector3> {
    let denominator = &value.w * &value.w;
    Ok(Vector3::from_xyz(
        ((&derivative.x * &value.w - &value.x * &derivative.w) / &denominator)
            .map_err(GeometryError::Numeric)?,
        ((&derivative.y * &value.w - &value.y * &derivative.w) / &denominator)
            .map_err(GeometryError::Numeric)?,
        ((&derivative.z * &value.w - &value.z * &derivative.w) / denominator)
            .map_err(GeometryError::Numeric)?,
    ))
}

fn require_interior_parameter(domain: &ParameterDomain, parameter: &Real) -> GeometryResult<()> {
    let after_start = decided_order(compare_reals(
        parameter,
        domain.start(),
        crate::STRICT_PREDICATES,
    ))?;
    let before_end = decided_order(compare_reals(
        parameter,
        domain.end(),
        crate::STRICT_PREDICATES,
    ))?;
    if after_start == Ordering::Greater && before_end == Ordering::Less {
        Ok(())
    } else {
        Err(GeometryError::SplitAtBoundary)
    }
}

fn split_homogeneous_bezier(
    controls: &[HomogeneousPoint3],
    parameter: &Real,
) -> (Vec<HomogeneousPoint3>, Vec<HomogeneousPoint3>) {
    let mut level = controls.to_vec();
    let mut left = Vec::with_capacity(controls.len());
    let mut right = Vec::with_capacity(controls.len());
    left.push(level[0].clone());
    right.push(level[level.len() - 1].clone());
    while level.len() > 1 {
        level = level
            .windows(2)
            .map(|pair| pair[0].lerp(&pair[1], parameter))
            .collect();
        left.push(level[0].clone());
        right.push(level[level.len() - 1].clone());
    }
    right.reverse();
    (left, right)
}

fn rational_bezier_from_homogeneous(
    controls: Vec<HomogeneousPoint3>,
    constant_coordinates: Option<&[Option<Real>; 3]>,
) -> GeometryResult<Curve3> {
    let mut points = Vec::with_capacity(controls.len());
    let mut weights = Vec::with_capacity(controls.len());
    for control in controls {
        let mut point = control.project()?;
        if let Some(constant_coordinates) = constant_coordinates {
            restore_constant_coordinates(&mut point, constant_coordinates);
        }
        points.push(point);
        weights.push(control.w);
    }
    Curve3::rational_bezier(points, weights)
}

fn split_rational_bezier_surface_u(
    surface: &RationalBezierSurface,
    parameter: &Real,
) -> GeometryResult<(Surface, Surface)> {
    let mut left = Vec::with_capacity(surface.control_points.len());
    let mut right = Vec::with_capacity(surface.control_points.len());
    for row in surface.homogeneous_controls() {
        let (left_row, right_row) = split_homogeneous_bezier(row, parameter);
        left.push(left_row);
        right.push(right_row);
    }
    Ok((
        rational_bezier_surface_from_homogeneous(left)?,
        rational_bezier_surface_from_homogeneous(right)?,
    ))
}

fn split_rational_bezier_surface_v(
    surface: &RationalBezierSurface,
    parameter: &Real,
) -> GeometryResult<(Surface, Surface)> {
    let transposed = transpose_homogeneous_grid(surface.homogeneous_controls());
    let mut left = Vec::with_capacity(transposed.len());
    let mut right = Vec::with_capacity(transposed.len());
    for column in &transposed {
        let (left_column, right_column) = split_homogeneous_bezier(column, parameter);
        left.push(left_column);
        right.push(right_column);
    }
    Ok((
        rational_bezier_surface_from_homogeneous(transpose_homogeneous_grid(&left))?,
        rational_bezier_surface_from_homogeneous(transpose_homogeneous_grid(&right))?,
    ))
}

fn rational_bezier_surface_from_homogeneous(
    controls: Vec<Vec<HomogeneousPoint3>>,
) -> GeometryResult<Surface> {
    let (points, weights) = project_homogeneous_grid(controls)?;
    Surface::rational_bezier(points, weights)
}

fn split_nurbs_surface_u(
    surface: &NurbsSurface,
    parameter: &Real,
) -> GeometryResult<(Surface, Surface)> {
    let mut left = Vec::with_capacity(surface.control_points.len());
    let mut right = Vec::with_capacity(surface.control_points.len());
    let mut left_knots = None;
    let mut right_knots = None;
    for row in surface.homogeneous_controls() {
        let (left_row, row_left_knots, right_row, row_right_knots) = split_nurbs_homogeneous(
            surface.u_degree,
            row.clone(),
            surface.u_knots.clone(),
            parameter,
        )?;
        left.push(left_row);
        right.push(right_row);
        left_knots.get_or_insert(row_left_knots);
        right_knots.get_or_insert(row_right_knots);
    }
    Ok((
        nurbs_surface_from_homogeneous(
            surface.u_degree,
            surface.v_degree,
            left,
            left_knots.expect("nonempty control net"),
            surface.v_knots.clone(),
        )?,
        nurbs_surface_from_homogeneous(
            surface.u_degree,
            surface.v_degree,
            right,
            right_knots.expect("nonempty control net"),
            surface.v_knots.clone(),
        )?,
    ))
}

fn split_nurbs_surface_v(
    surface: &NurbsSurface,
    parameter: &Real,
) -> GeometryResult<(Surface, Surface)> {
    let transposed = transpose_homogeneous_grid(surface.homogeneous_controls());
    let mut left = Vec::with_capacity(transposed.len());
    let mut right = Vec::with_capacity(transposed.len());
    let mut left_knots = None;
    let mut right_knots = None;
    for column in transposed {
        let (left_column, column_left_knots, right_column, column_right_knots) =
            split_nurbs_homogeneous(surface.v_degree, column, surface.v_knots.clone(), parameter)?;
        left.push(left_column);
        right.push(right_column);
        left_knots.get_or_insert(column_left_knots);
        right_knots.get_or_insert(column_right_knots);
    }
    Ok((
        nurbs_surface_from_homogeneous(
            surface.u_degree,
            surface.v_degree,
            transpose_homogeneous_grid(&left),
            surface.u_knots.clone(),
            left_knots.expect("nonempty control net"),
        )?,
        nurbs_surface_from_homogeneous(
            surface.u_degree,
            surface.v_degree,
            transpose_homogeneous_grid(&right),
            surface.u_knots.clone(),
            right_knots.expect("nonempty control net"),
        )?,
    ))
}

fn nurbs_surface_from_homogeneous(
    u_degree: usize,
    v_degree: usize,
    controls: Vec<Vec<HomogeneousPoint3>>,
    u_knots: Vec<Real>,
    v_knots: Vec<Real>,
) -> GeometryResult<Surface> {
    let (points, weights) = project_homogeneous_grid(controls)?;
    Surface::nurbs(u_degree, v_degree, points, weights, u_knots, v_knots)
}

fn project_homogeneous_grid(
    controls: Vec<Vec<HomogeneousPoint3>>,
) -> GeometryResult<AffineControlGrid> {
    let mut points = Vec::with_capacity(controls.len());
    let mut weights = Vec::with_capacity(controls.len());
    for row in controls {
        let mut point_row = Vec::with_capacity(row.len());
        let mut weight_row = Vec::with_capacity(row.len());
        for control in row {
            point_row.push(control.project()?);
            weight_row.push(control.w);
        }
        points.push(point_row);
        weights.push(weight_row);
    }
    Ok((points, weights))
}

fn transpose_homogeneous_grid(controls: &[Vec<HomogeneousPoint3>]) -> Vec<Vec<HomogeneousPoint3>> {
    (0..controls[0].len())
        .map(|u| controls.iter().map(|row| row[u].clone()).collect())
        .collect()
}

fn split_nurbs_curve(curve: &NurbsCurve3, parameter: &Real) -> GeometryResult<(Curve3, Curve3)> {
    let (left_controls, left_knots, right_controls, right_knots) = split_nurbs_homogeneous(
        curve.degree,
        curve.homogeneous_controls().to_vec(),
        curve.knots.clone(),
        parameter,
    )?;
    Ok((
        nurbs_from_homogeneous(curve.degree, left_controls, left_knots)?,
        nurbs_from_homogeneous(curve.degree, right_controls, right_knots)?,
    ))
}

fn split_nurbs_homogeneous(
    degree: usize,
    mut controls: Vec<HomogeneousPoint3>,
    mut knots: Vec<Real>,
    parameter: &Real,
) -> GeometryResult<HomogeneousNurbsSplit> {
    let mut multiplicity = knot_multiplicity(&knots, parameter)?;
    if multiplicity > degree {
        return Err(GeometryError::InvalidKnotMultiplicity);
    }
    while multiplicity < degree {
        let span = find_raw_span(parameter, degree, controls.len(), &knots)?;
        let (next_controls, next_knots) =
            insert_nurbs_knot_once(&controls, &knots, degree, span, multiplicity, parameter)?;
        controls = next_controls;
        knots = next_knots;
        multiplicity += 1;
    }
    let span = find_raw_span(parameter, degree, controls.len(), &knots)?;
    let shared = span - degree;
    let left_controls = controls[..=shared].to_vec();
    let right_controls = controls[shared..].to_vec();
    let mut left_knots = knots[..=span].to_vec();
    left_knots.push(parameter.clone());
    let mut right_knots = Vec::with_capacity(knots.len() - (span - degree));
    right_knots.push(parameter.clone());
    right_knots.extend_from_slice(&knots[(span - degree + 1)..]);
    Ok((left_controls, left_knots, right_controls, right_knots))
}

fn knot_multiplicity(knots: &[Real], parameter: &Real) -> GeometryResult<usize> {
    let mut count = 0;
    for knot in knots {
        if decided_order(compare_reals(knot, parameter, crate::STRICT_PREDICATES))?
            == Ordering::Equal
        {
            count += 1;
        }
    }
    Ok(count)
}

fn find_raw_span(
    parameter: &Real,
    degree: usize,
    control_count: usize,
    knots: &[Real],
) -> GeometryResult<usize> {
    for span in degree..control_count {
        let after_start = decided_order(compare_reals(
            &knots[span],
            parameter,
            crate::STRICT_PREDICATES,
        ))?;
        let before_end = decided_order(compare_reals(
            parameter,
            &knots[span + 1],
            crate::STRICT_PREDICATES,
        ))?;
        if matches!(after_start, Ordering::Less | Ordering::Equal) && before_end == Ordering::Less {
            return Ok(span);
        }
    }
    Err(GeometryError::InvalidParameterDomain)
}

fn insert_nurbs_knot_once(
    controls: &[HomogeneousPoint3],
    knots: &[Real],
    degree: usize,
    span: usize,
    multiplicity: usize,
    parameter: &Real,
) -> GeometryResult<(Vec<HomogeneousPoint3>, Vec<Real>)> {
    let old_last = controls.len() - 1;
    let mut next = Vec::with_capacity(controls.len() + 1);
    for index in 0..=old_last + 1 {
        let value = if index <= span - degree {
            controls[index].clone()
        } else if index > span - multiplicity {
            controls[index - 1].clone()
        } else {
            let denominator = &knots[index + degree] - &knots[index];
            let alpha =
                ((parameter - &knots[index]) / denominator).map_err(GeometryError::Numeric)?;
            controls[index - 1].lerp(&controls[index], &alpha)
        };
        next.push(value);
    }
    let mut next_knots = Vec::with_capacity(knots.len() + 1);
    next_knots.extend_from_slice(&knots[..=span]);
    next_knots.push(parameter.clone());
    next_knots.extend_from_slice(&knots[(span + 1)..]);
    Ok((next, next_knots))
}

fn nurbs_from_homogeneous(
    degree: usize,
    controls: Vec<HomogeneousPoint3>,
    knots: Vec<Real>,
) -> GeometryResult<Curve3> {
    let mut points = Vec::with_capacity(controls.len());
    let mut weights = Vec::with_capacity(controls.len());
    for control in controls {
        points.push(control.project()?);
        weights.push(control.w);
    }
    Curve3::nurbs(degree, points, weights, knots)
}

