        };
        assert_points_equal(&bounds.mins, &p(-2, -2, -1));
        assert_points_equal(&bounds.maxs, &p(2, 2, 1));

        let translated_axis = Surface::revolution(
            Curve3::line(p(0, 4, 3), p(3, 4, 3)).unwrap(),
            p(1, 2, 3),
            Vector3::x(),
        )
        .unwrap();
        let SurfaceBounds::Bounded(bounds) = translated_axis.bounds().unwrap() else {
            panic!("an arbitrarily oriented finite revolution must remain bounded");
        };
        assert_points_equal(&bounds.mins, &p(0, 0, 1));
        assert_points_equal(&bounds.maxs, &p(3, 4, 5));
    }

    #[test]
    fn transverse_planes_retain_exact_revolution_profile_sections() {
        let profile = Curve3::line(p(2, 0, -1), p(4, 0, 1)).unwrap();
        let revolution = Surface::revolution(profile, Point3::origin(), Vector3::z()).unwrap();
        let plane = Surface::plane(Point3::origin(), Vector3::x(), Vector3::y()).unwrap();
        let SurfaceSurfaceIntersection::Curve(section) =
            plane.intersect_surface(&revolution).unwrap()
        else {
            panic!("one transverse profile point must retain one revolution circle");
        };
        assert_points_equal(&section.curve().start().unwrap(), &p(3, 0, 0));
        assert_eq!(
            section
                .first_pcurve()
                .materialize()
                .unwrap()
                .curve()
                .family(),
            CurveFamily2::CircularArc
        );
        assert_eq!(
            section
                .second_pcurve()
                .materialize()
                .unwrap()
                .curve()
                .family(),
            CurveFamily2::Line
        );
        for parameter in [Real::zero(), (Real::pi() / r(2)).unwrap()] {
            let spatial = section.curve().evaluate_real(&parameter).unwrap();
            let plane_parameter = section
                .first_pcurve()
                .point_at(&Real::clone(&parameter).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap();
            let revolution_parameter = section
                .second_pcurve()
                .point_at(&Real::clone(&parameter).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap();
            assert_eq!(
                compare_reals(&revolution_parameter.y, &q(1, 2), crate::STRICT_PREDICATES).value(),
                Some(Ordering::Equal)
            );
            assert_points_equal(&plane.evaluate_real(&plane_parameter).unwrap(), &spatial);
            assert_points_equal(
                &revolution.evaluate_real(&revolution_parameter).unwrap(),
                &spatial,
            );
        }
        let SurfaceSurfaceIntersection::Curve(swapped) =
            revolution.intersect_surface(&plane).unwrap()
        else {
            panic!("operand reversal must retain the revolution section");
        };
        let parameter = (Real::pi() / r(2)).unwrap();
        let spatial = swapped.curve().evaluate_real(&parameter).unwrap();
        assert_points_equal(
            &revolution
                .evaluate_real(
                    &swapped
                        .first_pcurve()
                        .point_at(&Real::clone(&parameter).into())
                        .map(crate::geometry::represented_test_surface_parameter)
                        .unwrap(),
                )
                .unwrap(),
            &spatial,
        );
        assert_points_equal(
            &plane
                .evaluate_real(
                    &swapped
                        .second_pcurve()
                        .point_at(&Real::clone(&parameter).into())
                        .map(crate::geometry::represented_test_surface_parameter)
                        .unwrap(),
                )
                .unwrap(),
            &spatial,
        );

        let semicircle = Curve3::circle_arc(
            p(3, 0, 0),
            Vector3::x(),
            Vector3::z(),
            Real::one(),
            Real::zero(),
            Real::pi(),
        )
        .unwrap();
        let double = Surface::revolution(semicircle, Point3::origin(), Vector3::z()).unwrap();
        let SurfaceSurfaceIntersection::Curves(sections) =
            double.intersect_surface(&plane).unwrap()
        else {
            panic!("two profile contacts must retain two revolution circles");
        };
        assert_eq!(sections.len(), 2);
        assert_points_equal(&sections[0].curve().start().unwrap(), &p(4, 0, 0));
        assert_points_equal(&sections[1].curve().start().unwrap(), &p(2, 0, 0));

        let disjoint = Surface::plane(p(0, 0, 2), Vector3::x(), Vector3::y()).unwrap();
        assert!(matches!(
            revolution.intersect_surface(&disjoint).unwrap(),
            SurfaceSurfaceIntersection::None
        ));
        let singular = Surface::revolution(
            Curve3::line(p(0, 0, -1), p(0, 0, 1)).unwrap(),
            Point3::origin(),
            Vector3::z(),
        )
        .unwrap();
        let SurfaceSurfaceIntersection::Point(point) = singular.intersect_surface(&plane).unwrap()
        else {
            panic!("a transverse revolution-axis contact must retain its singular point");
        };
        assert_points_equal(
            point
                .try_coordinates()
                .expect("represented analytic contact"),
            &Point3::origin(),
        );

        let coincident_profile = Surface::revolution(
            Curve3::line(p(2, 0, 0), p(4, 0, 0)).unwrap(),
            Point3::origin(),
            Vector3::z(),
        )
        .unwrap();
        assert_eq!(
            coincident_profile.intersect_surface(&plane).unwrap_err(),
            GeometryError::UnsupportedIntersection
        );
        let axial = Surface::plane(Point3::origin(), Vector3::x(), Vector3::z()).unwrap();
        assert_eq!(
            revolution.intersect_surface(&axial).unwrap_err(),
            GeometryError::UnsupportedIntersection
        );
    }

    #[test]
    fn coaxial_spline_revolutions_retain_exact_meridian_contacts() {
        let profile = Curve3::nurbs(
            1,
            vec![p(2, 0, 0), p(3, 0, 1), p(4, 0, 0)],
            vec![r(1), r(1), r(1)],
            vec![r(0), r(0), r(1), r(2), r(2)],
        )
        .unwrap();
        let first = Surface::revolution(profile.clone(), Point3::origin(), Vector3::z()).unwrap();
        let second = Surface::revolution(
            Curve3::line(p(2, 0, 1), p(4, 0, 1)).unwrap(),
            Point3::origin(),
            Vector3::z(),
        )
        .unwrap();
        let SurfaceSurfaceIntersection::Curve(section) = first.intersect_surface(&second).unwrap()
        else {
            panic!("one represented knot contact must lift to one retained latitude");
        };
        assert_points_equal(&section.curve().start().unwrap(), &p(3, 0, 1));
        for parameter in [Real::zero(), (Real::pi() / r(2)).unwrap()] {
            let spatial = section.curve().evaluate_real(&parameter).unwrap();
            let first_parameter = section
                .first_pcurve()
                .point_at(&Real::clone(&parameter).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap();
            let second_parameter = section
                .second_pcurve()
                .point_at(&Real::clone(&parameter).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap();
            assert_eq!(
                compare_reals(&first_parameter.y, &r(1), crate::STRICT_PREDICATES).value(),
                Some(Ordering::Equal)
            );
            assert_eq!(
                compare_reals(&second_parameter.y, &q(1, 2), crate::STRICT_PREDICATES).value(),
                Some(Ordering::Equal)
            );
            assert_points_equal(&first.evaluate_real(&first_parameter).unwrap(), &spatial);
            assert_points_equal(&second.evaluate_real(&second_parameter).unwrap(), &spatial);
        }

        let SurfaceSurfaceIntersection::Curve(swapped) = second.intersect_surface(&first).unwrap()
        else {
            panic!("operand reversal must preserve the retained spline latitude");
        };
        let parameter = (Real::pi() / r(2)).unwrap();
        let spatial = swapped.curve().evaluate_real(&parameter).unwrap();
        assert_points_equal(
            &second
                .evaluate_real(
                    &swapped
                        .first_pcurve()
                        .point_at(&Real::clone(&parameter).into())
                        .map(crate::geometry::represented_test_surface_parameter)
                        .unwrap(),
                )
                .unwrap(),
            &spatial,
        );
        assert_points_equal(
            &first
                .evaluate_real(
                    &swapped
                        .second_pcurve()
                        .point_at(&Real::clone(&parameter).into())
                        .map(crate::geometry::represented_test_surface_parameter)
                        .unwrap(),
                )
                .unwrap(),
            &spatial,
        );

        let coincident = Surface::revolution(profile, p(0, 0, 5), Vector3::z()).unwrap();
        assert!(matches!(
            first.intersect_surface(&coincident).unwrap(),
            SurfaceSurfaceIntersection::Coincident
        ));

        let mirrored = Surface::revolution(
            Curve3::line(p(2, 0, 1), p(4, 0, 1)).unwrap(),
            p(0, 0, 3),
            -Vector3::z(),
        )
        .unwrap();
        let SurfaceSurfaceIntersection::Curve(mirrored_section) =
            first.intersect_surface(&mirrored).unwrap()
        else {
            panic!("counteroriented coaxial frames must retain a mirrored pcurve");
        };
        let parameter = (Real::pi() / r(2)).unwrap();
        let mirrored_parameter = mirrored_section
            .second_pcurve()
            .point_at(&Real::clone(&parameter).into())
            .map(crate::geometry::represented_test_surface_parameter)
            .unwrap();
        assert_eq!(
            compare_reals(
                &mirrored_parameter.x,
                &(Real::tau() - parameter.clone()),
                crate::STRICT_PREDICATES
            )
            .value(),
            Some(Ordering::Equal)
        );
        assert_points_equal(
            &mirrored.evaluate_real(&mirrored_parameter).unwrap(),
            &mirrored_section.curve().evaluate_real(&parameter).unwrap(),
        );

        let rotated = Surface::revolution(
            Curve3::line(p(0, 2, 1), p(0, 4, 1)).unwrap(),
            Point3::origin(),
            Vector3::z(),
        )
        .unwrap();
        let SurfaceSurfaceIntersection::Circle(circle) = first.intersect_surface(&rotated).unwrap()
        else {
            panic!("rotated meridian frames must retain the exact spatial circle only");
        };
        assert_points_equal(&circle.start().unwrap(), &p(3, 0, 1));

        let disjoint = Surface::revolution(
            Curve3::line(p(2, 0, 2), p(4, 0, 2)).unwrap(),
            Point3::origin(),
            Vector3::z(),
        )
        .unwrap();
        assert!(matches!(
            first.intersect_surface(&disjoint).unwrap(),
            SurfaceSurfaceIntersection::None
        ));
    }

