        assert_eq!(
            Surface::rational_bezier(
                vec![vec![p(0, 0, 0), p(1, 0, 0)], vec![p(0, 1, 0), p(1, 1, 0)]],
                vec![vec![r(1), r(1)], vec![r(1)]],
            )
            .unwrap_err(),
            GeometryError::SurfaceWeightShapeMismatch
        );
        assert_eq!(
            Surface::extrusion(
                Curve3::line(p(0, 0, 0), p(1, 0, 0)).unwrap(),
                Vector3::zero(),
            )
            .unwrap_err(),
            GeometryError::DegenerateExtrusionDirection
        );
        assert_eq!(
            Surface::revolution(
                Curve3::line(p(1, 0, 0), p(1, 0, 1)).unwrap(),
                Point3::origin(),
                Vector3::from_xyz(r(0), r(0), r(2)),
            )
            .unwrap_err(),
            GeometryError::InvalidRevolutionAxis
        );

        let surface = Surface::rational_bezier(
            vec![vec![p(0, 0, 0), p(2, 0, 0)], vec![p(0, 4, 0), p(2, 4, 2)]],
            vec![vec![r(1), r(1)], vec![r(1), r(1)]],
        )
        .unwrap();
        let translated = surface
            .transformed(
                &TransformMetric::new(&Matrix4::affine_translation([r(3), r(-2), r(5)])),
                false,
            )
            .unwrap();
        let parameter = Point2::new(q(1, 4), q(3, 4));
        let expected =
            surface.evaluate_real(&parameter).unwrap() + Vector3::from_xyz(r(3), r(-2), r(5));
        assert_points_equal(&translated.evaluate_real(&parameter).unwrap(), &expected);

        let reflected = surface
            .transformed(
                &TransformMetric::new(&Matrix4::from_row_major([
                    r(-1),
                    r(0),
                    r(0),
                    r(0),
                    r(0),
                    r(1),
                    r(0),
                    r(0),
                    r(0),
                    r(0),
                    r(1),
                    r(0),
                    r(0),
                    r(0),
                    r(0),
                    r(1),
                ])),
                true,
            )
            .unwrap();
        let mirrored_original = surface
            .evaluate_real(&Point2::new(q(3, 4), q(3, 4)))
            .unwrap();
        let expected = Point3::new(
            -mirrored_original.x,
            mirrored_original.y,
            mirrored_original.z,
        );
        assert_points_equal(&reflected.evaluate_real(&parameter).unwrap(), &expected);
    }

