        );
    }

    #[test]
    fn v_linear_tensor_surfaces_retain_noniso_sections_and_native_domains() {
        let controls = vec![
            vec![p(0, 0, 0), p(1, 2, 0), p(2, 2, 0)],
            vec![p(0, 0, 2), p(1, 2, 2), p(2, 2, 2)],
        ];
        let weights = vec![vec![r(1), r(2), r(3)], vec![r(1), r(2), r(3)]];
        let plane = Surface::plane(
            p(2, 0, 0),
            Vector3::y(),
            Vector3::from_xyz(r(1), r(0), r(-1)),
        )
        .unwrap();
        let rational = Surface::rational_bezier(controls.clone(), weights.clone()).unwrap();
        let SurfaceSurfaceIntersection::Curve(section) =
            rational.intersect_surface(&plane).unwrap()
        else {
            panic!("v-linear rational tensor must retain its exact graph section");
        };
        assert_eq!(section.curve().kind(), Curve3Kind::RationalBezier);
        assert_eq!(
            section
                .first_pcurve()
                .point_at(&Real::clone(&q(1, 2)).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap(),
            Point2::new(q(1, 2), q(3, 8))
        );
        assert_points_equal(
            &section.curve().evaluate_real(&q(1, 2)).unwrap(),
            &rational
                .evaluate_real(&Point2::new(q(1, 2), q(3, 8)))
                .unwrap(),
        );

        let nurbs = Surface::nurbs(
            2,
            1,
            controls.clone(),
            weights.clone(),
            vec![r(2), r(2), r(2), r(5), r(5), r(5)],
            vec![r(7), r(7), r(11), r(11)],
        )
        .unwrap();
        let SurfaceSurfaceIntersection::Curve(section) = plane.intersect_surface(&nurbs).unwrap()
        else {
            panic!("v-linear NURBS tensor must retain its native graph section");
        };
        assert_eq!(section.curve().domain().represented_start().unwrap(), &r(2));
        assert_eq!(section.curve().domain().represented_end().unwrap(), &r(5));
        assert_eq!(
            section
                .second_pcurve()
                .point_at(&Real::clone(&q(7, 2)).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap(),
            Point2::new(q(7, 2), q(17, 2))
        );
        let materialized = section.second_pcurve().materialize().unwrap();
        assert_eq!(
            materialized.correspondence().affine_coefficients(),
            Some((&r(3), &r(2)))
        );
        assert_eq!(
            materialized
                .curve()
                .point_at(&q(1, 2).clone().into())
                .unwrap()
                .coordinates()
                .expect("native pcurve coordinates")
                .clone(),
            CurvePoint2::new(q(7, 2), q(17, 2))
        );

        let (rational_patch, rational_face) =
            crate::construction::rational_bezier_patch(controls.clone(), weights.clone()).unwrap();
        let rational_surface = rational_patch
            .surface(rational_patch.face(rational_face).unwrap().surface())
            .unwrap();
        let SurfaceSurfaceIntersection::Curve(rational_section) =
            rational_surface.intersect_surface(&plane).unwrap()
        else {
            panic!("v-linear rational patch must retain its graph section");
        };
        let (rational_split, _) = rational_patch
            .split_face_by_surface_curve(
                rational_face,
                &rational_section,
                SurfaceIntersectionOperand::First,
            )
            .unwrap();
        assert_eq!(rational_split.counts().faces, 2);
        let rational_json = rational_split.to_json().unwrap();
        assert_eq!(
            crate::ImportedModel::from_json(&rational_json, &crate::ArchiveLimits::default())
                .unwrap()
                .validate()
                .unwrap()
                .to_json()
                .unwrap(),
            rational_json
        );

        let (nurbs_patch, nurbs_face) = crate::construction::nurbs_patch(
            2,
            1,
            controls,
            weights,
            vec![r(2), r(2), r(2), r(5), r(5), r(5)],
            vec![r(7), r(7), r(11), r(11)],
        )
        .unwrap();
        let nurbs_surface = nurbs_patch
            .surface(nurbs_patch.face(nurbs_face).unwrap().surface())
            .unwrap();
        let SurfaceSurfaceIntersection::Curve(nurbs_section) =
            nurbs_surface.intersect_surface(&plane).unwrap()
        else {
            panic!("v-linear NURBS patch must retain its native graph section");
        };
        let (nurbs_split, _) = nurbs_patch
            .split_face_by_surface_curve(
                nurbs_face,
                &nurbs_section,
                SurfaceIntersectionOperand::First,
            )
            .unwrap();
        assert_eq!(nurbs_split.counts().faces, 2);
        let nurbs_json = nurbs_split.to_json().unwrap();
        assert_eq!(
            crate::ImportedModel::from_json(&nurbs_json, &crate::ArchiveLimits::default())
                .unwrap()
                .validate()
                .unwrap()
                .to_json()
                .unwrap(),
            nurbs_json
        );
    }

    #[test]
    fn rational_tensor_graph_sections_split_and_revalidate_trimmed_topology() {
        let controls = vec![
            vec![p(0, 0, 0), p(2, 0, 0)],
            vec![p(0, 2, 1), p(2, 2, 1)],
            vec![p(0, 2, 2), p(2, 2, 2)],
        ];
        let weights = vec![vec![r(1), r(1)], vec![r(2), r(2)], vec![r(3), r(3)]];
        let (patch, face) = crate::construction::rational_bezier_patch(controls, weights).unwrap();
        let surface = patch.surface(patch.face(face).unwrap().surface()).unwrap();
        let plane = Surface::plane(
            p(2, 0, 0),
            Vector3::y(),
            Vector3::from_xyz(r(1), r(0), r(-1)),
        )
        .unwrap();
        let SurfaceSurfaceIntersection::Curve(section) = surface.intersect_surface(&plane).unwrap()
        else {
            panic!("translation tensor must retain one exact graph section");
        };
        let (split, record) = patch
            .split_face_by_surface_curve(face, &section, SurfaceIntersectionOperand::First)
            .unwrap();
        assert_eq!(split.counts().faces, 2);
        assert_eq!(record.first_face(), face);
        let graph_use = split
            .edge_use(record.open().unwrap().face.edge_uses[0])
            .unwrap();
        let graph_pcurve = split.pcurve(graph_use.pcurve()).unwrap();
        let Some(CurveGeometry2::RationalBezier(graph)) = graph_pcurve.curve().geometry() else {
            panic!("split tensor section must retain one rational graph pcurve");
        };
        let mut forged_controls = graph.affine_control_points().unwrap().to_vec();
        forged_controls[1] = CurvePoint2::new(
            forged_controls[1].x().clone() + Real::one(),
            forged_controls[1].y().clone(),
        );
        let forged = Pcurve::new(Curve2::from(
            RationalBezier2::try_new(forged_controls, graph.weights().to_vec()).unwrap(),
        ));
        let mut edit = split.edit();
        edit.replace_pcurve(graph_use.pcurve(), forged).unwrap();
        assert!(
            edit.commit().is_err(),
            "endpoint-preserving graph forgery must fail full control-net validation"
        );
        let json = split.to_json().unwrap();
        assert_eq!(
            crate::ImportedModel::from_json(&json, &crate::ArchiveLimits::default())
                .unwrap()
                .validate()
                .unwrap()
                .to_json()
                .unwrap(),
            json
        );
    }

    #[test]
    fn polynomial_bilinear_plane_sections_are_exact_clipped_and_replayable() {
        let controls = vec![vec![p(0, 0, 0), p(2, 0, 0)], vec![p(0, 2, 0), p(2, 2, 1)]];
        let weights = vec![vec![r(1), r(1)], vec![r(1), r(1)]];
        let surface = Surface::rational_bezier(controls.clone(), weights.clone()).unwrap();
        let section_plane = Surface::plane(
            p(1, 0, 0),
            Vector3::y(),
            Vector3::from_xyz(r(2), r(0), r(-1)),
        )
        .unwrap();
        let SurfaceSurfaceIntersection::Curve(section) =
            surface.intersect_surface(&section_plane).unwrap()
        else {
            panic!("polynomial bilinear patch must retain one exact rational section");
        };
        assert_eq!(section.curve().kind(), Curve3Kind::RationalBezier);
        assert_eq!(
            section
                .first_pcurve()
                .point_at(&Real::clone(&q(1, 2)).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap(),
            Point2::new(q(1, 3), q(1, 2))
        );
        assert_points_equal(
            &section.curve().evaluate_real(&q(1, 2)).unwrap(),
            &Point3::new(q(2, 3), r(1), q(1, 6)),
        );
        // Both sides are rational quartics. Nine distinct exact parameters
        // certify the complete cross-multiplied degree-eight identity
        // independently of the construction's control-net arithmetic.
        for numerator in 0_i64..=8 {
            let parameter = q(numerator, 8);
            let surface_parameter = section
                .first_pcurve()
                .point_at(&Real::clone(&parameter).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap();
            assert_points_equal(
                &section.curve().evaluate_real(&parameter).unwrap(),
                &surface
                    .evaluate_real(&Point2::new(
                        surface_parameter.x.clone(),
                        surface_parameter.y.clone(),
                    ))
                    .unwrap(),
            );
        }

        let SurfaceSurfaceIntersection::Curve(swapped) =
            section_plane.intersect_surface(&surface).unwrap()
        else {
            panic!("operand reversal must retain the same exact rational section");
        };
        assert_eq!(
            swapped
                .second_pcurve()
                .point_at(&Real::clone(&q(1, 2)).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap(),
            Point2::new(q(1, 3), q(1, 2))
        );
        assert_points_equal(
            &swapped.curve().evaluate_real(&q(1, 2)).unwrap(),
            &section.curve().evaluate_real(&q(1, 2)).unwrap(),
        );

        let u_graph_plane = Surface::plane(
            p(0, 1, 0),
            Vector3::x(),
            Vector3::from_xyz(r(0), r(2), r(-1)),
        )
        .unwrap();
        let SurfaceSurfaceIntersection::Curve(u_graph_section) =
            surface.intersect_surface(&u_graph_plane).unwrap()
        else {
            panic!("bilinear plane section must solve through either parameter axis");
        };
        assert_eq!(
            u_graph_section
                .first_pcurve()
                .point_at(&Real::clone(&q(1, 2)).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap(),
            Point2::new(q(1, 2), q(1, 3))
        );
        assert_points_equal(
            &u_graph_section.curve().evaluate_real(&q(1, 2)).unwrap(),
            &Point3::new(r(1), q(2, 3), q(1, 6)),
        );

        let clipping_plane = Surface::plane(
            p(3, 0, 0),
            Vector3::y(),
            Vector3::from_xyz(r(2), r(0), r(-1)),
        )
        .unwrap();
        let SurfaceSurfaceIntersection::Curve(clipped) =
            surface.intersect_surface(&clipping_plane).unwrap()
        else {
            panic!("rectangle clipping must retain the represented section fragment");
        };
        assert_eq!(clipped.curve().domain().represented_start().unwrap(), &r(0));
        assert_eq!(clipped.curve().domain().represented_end().unwrap(), &r(1));
        assert_eq!(
            clipped
                .first_pcurve()
                .point_at(&Real::clone(&r(0)).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap(),
            Point2::new(r(1), q(1, 2))
        );
        assert_eq!(
            clipped
                .first_pcurve()
                .point_at(&Real::clone(&r(1)).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap(),
            Point2::new(q(3, 4), r(1))
        );
        assert_points_equal(
            &clipped.curve().evaluate_real(&r(0)).unwrap(),
            &Point3::new(r(2), r(1), q(1, 2)),
        );
        assert_points_equal(
            &clipped.curve().evaluate_real(&r(1)).unwrap(),
            &Point3::new(q(3, 2), r(2), q(3, 4)),
        );

        let disjoint_plane = Surface::plane(
            p(5, 0, 0),
            Vector3::y(),
            Vector3::from_xyz(r(2), r(0), r(-1)),
        )
        .unwrap();
        assert!(matches!(
            surface.intersect_surface(&disjoint_plane).unwrap(),
            SurfaceSurfaceIntersection::None
        ));
        let pole_plane =
            Surface::plane(Point3::new(r(0), r(0), q(1, 4)), Vector3::x(), Vector3::y()).unwrap();
        let SurfaceSurfaceIntersection::Curve(pole_branch) =
            surface.intersect_surface(&pole_plane).unwrap()
        else {
            panic!("retained polynomial bilinear pole branch must be exact");
        };
        assert_eq!(
            pole_branch
                .first_pcurve()
                .point_at(&Real::clone(&r(0)).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap(),
            Point2::new(r(1), q(1, 4))
        );
        assert_eq!(
            pole_branch
                .first_pcurve()
                .point_at(&Real::clone(&r(1)).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap(),
            Point2::new(q(1, 4), r(1))
        );
        assert_points_equal(
            &pole_branch.curve().evaluate_real(&r(0)).unwrap(),
            &Point3::new(r(2), q(1, 2), q(1, 4)),
        );
        assert_points_equal(
            &pole_branch.curve().evaluate_real(&r(1)).unwrap(),
            &Point3::new(q(1, 2), r(2), q(1, 4)),
        );

        let off_domain_pole_surface = Surface::rational_bezier(
            vec![
                vec![
                    Point3::new(r(0), r(0), q(-3, 2)),
                    Point3::new(r(2), r(0), r(-2)),
                ],
                vec![p(0, 2, -1), p(2, 2, 1)],
            ],
            vec![vec![r(2), r(1)], vec![r(1), r(1)]],
        )
        .unwrap();
        let coordinate_plane =
            Surface::plane(Point3::origin(), Vector3::x(), Vector3::y()).unwrap();
        let SurfaceSurfaceIntersection::Curve(pole_clipped) = off_domain_pole_surface
            .intersect_surface(&coordinate_plane)
            .unwrap()
        else {
            panic!("UV clipping must precede weighted spatial composition");
        };
        assert_eq!(
            pole_clipped
                .first_pcurve()
                .point_at(&Real::clone(&r(0)).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap(),
            Point2::new(r(1), q(2, 3))
        );
        assert_eq!(
