        let u_graph_plane = Surface::plane(
            p(0, 1, 0),
            Vector3::x(),
            Vector3::from_xyz(r(0), r(2), r(-1)),
        )
        .unwrap();
        let SurfaceSurfaceIntersection::Curve(u_graph_section) =
