    #[test]
    fn bilinear_poles_partition_into_exact_bounded_branches() {
        let controls = vec![
            vec![
                Point3::new(r(0), r(0), q(3, 16)),
                Point3::new(r(2), r(0), q(-5, 16)),
            ],
            vec![
                Point3::new(r(0), r(2), q(-5, 16)),
                Point3::new(r(2), r(2), q(3, 16)),
            ],
        ];
        let weights = vec![vec![r(1), r(1)], vec![r(1), r(1)]];
        let surface = Surface::rational_bezier(controls.clone(), weights.clone()).unwrap();
        let plane = Surface::plane(Point3::origin(), Vector3::x(), Vector3::y()).unwrap();
        let SurfaceSurfaceIntersection::Curves(branches) =
            surface.intersect_surface(&plane).unwrap()
        else {
            panic!("checkerboard bilinear section must retain two bounded pole branches");
        };
        assert_eq!(branches.len(), 2);
        for (branch, expected_start, expected_end, spatial_start, spatial_end) in [
            (
                &branches[0],
                Point2::new(q(3, 8), r(0)),
                Point2::new(r(0), q(3, 8)),
                Point3::new(q(3, 4), r(0), r(0)),
                Point3::new(r(0), q(3, 4), r(0)),
            ),
            (
                &branches[1],
                Point2::new(r(1), q(5, 8)),
                Point2::new(q(5, 8), r(1)),
                Point3::new(r(2), q(5, 4), r(0)),
                Point3::new(q(5, 4), r(2), r(0)),
            ),
        ] {
            assert_eq!(
                branch
                    .first_pcurve()
                    .point_at(&Real::clone(&r(0)).into())
                    .map(crate::geometry::represented_test_surface_parameter)
                    .unwrap(),
                expected_start
            );
            assert_eq!(
                branch
                    .first_pcurve()
                    .point_at(&Real::clone(&r(1)).into())
                    .map(crate::geometry::represented_test_surface_parameter)
                    .unwrap(),
                expected_end
            );
            assert_points_equal(
                &branch.curve().evaluate_real(&r(0)).unwrap(),
                &spatial_start,
            );
            assert_points_equal(&branch.curve().evaluate_real(&r(1)).unwrap(), &spatial_end);
            for numerator in 0_i64..=8 {
                let parameter = q(numerator, 8);
                let surface_parameter = branch
                    .first_pcurve()
                    .point_at(&Real::clone(&parameter).into())
                    .map(crate::geometry::represented_test_surface_parameter)
                    .unwrap();
                assert_points_equal(
                    &branch.curve().evaluate_real(&parameter).unwrap(),
                    &surface.evaluate_real(&surface_parameter).unwrap(),
                );
            }
        }

        let SurfaceSurfaceIntersection::Curves(swapped) =
            plane.intersect_surface(&surface).unwrap()
        else {
            panic!("pole branches must survive operand reversal");
        };
        assert_eq!(swapped.len(), 2);
        for (original, reversed_operands) in branches.iter().zip(&swapped) {
            assert_eq!(
                original
                    .first_pcurve()
                    .point_at(&Real::clone(&q(1, 2)).into())
                    .map(crate::geometry::represented_test_surface_parameter)
                    .unwrap(),
                reversed_operands
                    .second_pcurve()
                    .point_at(&Real::clone(&q(1, 2)).into())
                    .map(crate::geometry::represented_test_surface_parameter)
                    .unwrap()
            );
            assert_points_equal(
                &original.curve().evaluate_real(&q(1, 2)).unwrap(),
                &reversed_operands.curve().evaluate_real(&q(1, 2)).unwrap(),
            );
        }

        let endpoint_pole_surface = Surface::rational_bezier(
            vec![vec![p(0, 0, 1), p(2, 0, -1)], vec![p(0, 2, 1), p(2, 2, 1)]],
            weights.clone(),
        )
        .unwrap();
        let SurfaceSurfaceIntersection::Curve(endpoint_branch) =
            endpoint_pole_surface.intersect_surface(&plane).unwrap()
        else {
            panic!("a branch leaving the patch before an endpoint pole must be retained");
        };
        assert_eq!(
            endpoint_branch
                .first_pcurve()
                .point_at(&Real::clone(&r(0)).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap(),
            Point2::new(q(1, 2), r(0))
        );
        assert_eq!(
            endpoint_branch
                .first_pcurve()
                .point_at(&Real::clone(&r(1)).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap(),
            Point2::new(r(1), q(1, 2))
        );

        let factorized_controls = vec![
            vec![
                Point3::new(r(0), r(0), q(1, 4)),
                Point3::new(r(2), r(0), q(-1, 4)),
            ],
            vec![
                Point3::new(r(0), r(2), q(-1, 4)),
                Point3::new(r(2), r(2), q(1, 4)),
            ],
        ];
        let factorized =
            Surface::rational_bezier(factorized_controls.clone(), weights.clone()).unwrap();
        let SurfaceSurfaceIntersection::Curves(factorized_lines) =
            factorized.intersect_surface(&plane).unwrap()
        else {
            panic!("factorized bilinear relation must retain both exact iso-lines");
        };
        assert_eq!(factorized_lines.len(), 2);
        assert_eq!(
            factorized_lines[0]
                .first_pcurve()
                .point_at(&Real::clone(&r(0)).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap(),
            Point2::new(r(0), q(1, 2))
        );
        assert_eq!(
            factorized_lines[0]
                .first_pcurve()
                .point_at(&Real::clone(&r(1)).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap(),
            Point2::new(r(1), q(1, 2))
        );
        assert_eq!(
            factorized_lines[1]
                .first_pcurve()
                .point_at(&Real::clone(&r(0)).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap(),
            Point2::new(q(1, 2), r(0))
        );
        assert_eq!(
            factorized_lines[1]
                .first_pcurve()
                .point_at(&Real::clone(&r(1)).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap(),
            Point2::new(q(1, 2), r(1))
        );
        let (factorized_patch, factorized_face) =
            crate::construction::rational_bezier_patch(factorized_controls, weights.clone())
                .unwrap();
        let (factorized_partition, factorized_record) = factorized_patch
            .split_face_by_surface_curves(
                factorized_face,
                &factorized_lines,
                SurfaceIntersectionOperand::First,
            )
            .unwrap();
        assert_eq!(factorized_record.faces.len(), 4);
        assert_eq!(factorized_partition.counts().faces, 4);
        let factorized_json = factorized_partition.to_json().unwrap();
        assert_eq!(
            crate::ImportedModel::from_json(&factorized_json, &crate::ArchiveLimits::default())
                .unwrap()
                .validate()
                .unwrap()
                .to_json()
                .unwrap(),
            factorized_json
        );

        let boundary_surface = |heights: [[i32; 2]; 2]| {
            Surface::rational_bezier(
                vec![
                    vec![p(0, 0, heights[0][0]), p(2, 0, heights[0][1])],
                    vec![p(0, 2, heights[1][0]), p(2, 2, heights[1][1])],
                ],
                vec![vec![r(1), r(1)], vec![r(1), r(1)]],
            )
            .unwrap()
        };
        let SurfaceSurfaceIntersection::Point(single_corner) = boundary_surface([[0, 1], [1, 1]])
            .intersect_surface(&plane)
            .unwrap()
        else {
            panic!("one zero Bernstein corner must be one exact point");
        };
        assert_eq!(single_corner.try_coordinates().unwrap(), &p(0, 0, 0));

        let opposite_corners = boundary_surface([[0, 1], [1, 0]]);
        let SurfaceSurfaceIntersection::Points(points) =
            opposite_corners.intersect_surface(&plane).unwrap()
        else {
            panic!("opposite zero Bernstein corners must be two exact points");
        };
        assert_eq!(
            points
                .iter()
                .map(|p| p.try_coordinates().unwrap())
                .collect::<Vec<_>>(),
            vec![&p(0, 0, 0), &p(2, 2, 0)]
        );
        let SurfaceSurfaceIntersection::Points(swapped_points) =
            plane.intersect_surface(&opposite_corners).unwrap()
        else {
            panic!("multiple exact points must survive operand reversal");
        };
        assert_eq!(
            swapped_points
                .iter()
                .map(|p| p.try_coordinates().unwrap())
                .collect::<Vec<_>>(),
            points
                .iter()
                .map(|p| p.try_coordinates().unwrap())
                .collect::<Vec<_>>()
        );

        let SurfaceSurfaceIntersection::Curve(boundary_edge) = boundary_surface([[0, 0], [1, 1]])
            .intersect_surface(&plane)
            .unwrap()
        else {
            panic!("two adjacent zero Bernstein corners must retain their boundary iso-line");
        };
        assert_eq!(
            boundary_edge
                .first_pcurve()
                .point_at(&Real::clone(&r(0)).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap(),
            Point2::new(r(0), r(0))
        );
        assert_eq!(
            boundary_edge
                .first_pcurve()
                .point_at(&Real::clone(&r(1)).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap(),
            Point2::new(r(1), r(0))
        );

        let SurfaceSurfaceIntersection::Curves(boundary_pair) = boundary_surface([[1, 0], [0, 0]])
            .intersect_surface(&plane)
            .unwrap()
        else {
            panic!("three zero Bernstein corners must retain both opposite boundary iso-lines");
        };
        assert_eq!(boundary_pair.len(), 2);
        assert_eq!(
            boundary_pair[0]
                .first_pcurve()
                .point_at(&Real::clone(&r(0)).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap(),
            Point2::new(r(0), r(1))
        );
        assert_eq!(
            boundary_pair[0]
                .first_pcurve()
                .point_at(&Real::clone(&r(1)).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap(),
            Point2::new(r(1), r(1))
        );
        assert_eq!(
            boundary_pair[1]
                .first_pcurve()
                .point_at(&Real::clone(&r(0)).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap(),
            Point2::new(r(1), r(0))
        );
        assert_eq!(
            boundary_pair[1]
                .first_pcurve()
                .point_at(&Real::clone(&r(1)).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap(),
            Point2::new(r(1), r(1))
        );

        let planar_controls = vec![vec![p(0, 0, 0), p(2, 0, 0)], vec![p(0, 2, 0), p(2, 2, 0)]];
        let planar_weights = vec![vec![r(1), r(2)], vec![r(3), r(4)]];
        let planar = Surface::rational_bezier(planar_controls.clone(), planar_weights).unwrap();
        assert!(matches!(
            plane.intersect_surface(&planar).unwrap(),
            SurfaceSurfaceIntersection::ContainedSurface(SurfaceIntersectionOperand::Second)
        ));
        assert!(matches!(
            planar.intersect_surface(&plane).unwrap(),
            SurfaceSurfaceIntersection::ContainedSurface(SurfaceIntersectionOperand::First)
        ));
        let containment_translation = Matrix4::affine_translation([r(3), r(-2), r(5)]);
        assert!(matches!(
            plane
                .transformed(&TransformMetric::new(&containment_translation), false)
                .unwrap()
                .intersect_surface(
                    &planar
                        .transformed(&TransformMetric::new(&containment_translation), false)
                        .unwrap()
                )
                .unwrap(),
            SurfaceSurfaceIntersection::ContainedSurface(SurfaceIntersectionOperand::Second)
        ));

        let (planar_patch, planar_face) = crate::construction::rational_bezier_patch(
            planar_controls,
            vec![vec![r(1), r(1)], vec![r(1), r(1)]],
        )
        .unwrap();
        let patch_surface = planar_patch
            .surface(planar_patch.face(planar_face).unwrap().surface())
            .unwrap();
        let (cube, cube_solid) = crate::construction::cuboid(p(-1, -1, 0), p(3, 3, 1)).unwrap();
        let cube_faces = cube
            .shell(cube.solid(cube_solid).unwrap().outer())
            .unwrap()
            .faces();
        let containing_face = cube_faces
            .iter()
            .copied()
            .find(|cube_face| {
                let cube_surface = cube
                    .surface(cube.face(*cube_face).unwrap().surface())
                    .unwrap();
                matches!(
                    patch_surface.intersect_surface(cube_surface),
                    Ok(SurfaceSurfaceIntersection::ContainedSurface(
                        SurfaceIntersectionOperand::First
                    ))
                )
            })
            .expect("one cuboid cap plane must contain the complete tensor carrier");
        let face_pair = crate::boolean_kernel::intersect_faces(
            &planar_patch,
            planar_face,
            &cube,
            containing_face,
        )
        .unwrap()
        .expect("contained tensor/plane carriers must retain an exact face relation");
        assert!(matches!(
            face_pair.relation(),
            crate::FacePairRelation::Exact(SurfaceSurfaceIntersection::ContainedSurface(
                SurfaceIntersectionOperand::First
            ))
        ));
        let crate::FacePairTrim::SurfaceRegion {
            parameterized_on: SurfaceIntersectionOperand::Second,
            region,
            covers_contained_face,
        } = face_pair.trim()
        else {
            panic!("contained tensor/plane faces must retain an exact two-dimensional trim");
        };
        assert!(!region.is_empty());
        assert!(*covers_contained_face);
        assert!(matches!(
            crate::error::classified(region.loop_role_counts()).unwrap(),
            hypercurve::Classification::Decided((1, 0))
        ));
        let complete_plane_traces = crate::boolean_kernel::contained_face_boundary_traces_on_plane(
            &planar_patch,
            planar_face,
            &cube,
            containing_face,
        )
        .unwrap()
        .expect("represented contained-face boundary must transfer to plane traces");
        assert_eq!(complete_plane_traces.len(), 4);
        let (partitioned_cube, complete_partition) = cube
            .split_face_by_curves(containing_face, &complete_plane_traces)
            .unwrap();
        assert_eq!(complete_partition.faces.len(), 9);
        assert_eq!(partitioned_cube.counts().faces, cube.counts().faces + 8);

        let partial_points = [
            CurvePoint2::new(r(1), r(-1)),
            CurvePoint2::new(r(3), r(-1)),
            CurvePoint2::new(r(3), r(3)),
            CurvePoint2::new(r(1), r(3)),
        ];
        let partial_outline = hypercurve::CurvePath2::try_new(
            (0..4)
                .map(|index| {
                    Curve2::from(
                        LineSeg2::try_new(
                            partial_points[index].clone(),
                            partial_points[(index + 1) % 4].clone(),
                        )
                        .unwrap(),
                    )
                })
                .collect(),
        )
        .unwrap();
        let (partial_plane, partial_face) = crate::construction::planar_face(
            &partial_outline,
            &[],
            p(0, 0, 0),
            Vector3::from_xyz(r(1), r(0), r(0)),
            Vector3::from_xyz(r(0), r(1), r(0)),
        )
        .unwrap();
        let partial_plane_traces = crate::boolean_kernel::contained_face_boundary_traces_on_plane(
            &planar_patch,
            planar_face,
            &partial_plane,
            partial_face,
        )
        .unwrap()
        .expect("represented partial contained-face boundary must transfer to plane traces");
        assert_eq!(partial_plane_traces.len(), 3);
        let (partitioned_partial_plane, partial_partition) = partial_plane
            .split_face_by_curves(partial_face, &partial_plane_traces)
            .unwrap();
        assert_eq!(partial_partition.faces.len(), 6);
        assert_eq!(
            partitioned_partial_plane.counts().faces,
            partial_plane.counts().faces + 5
        );
        for (pair, expected_parameter_operand) in [
            (
                crate::boolean_kernel::intersect_faces(
                    &planar_patch,
                    planar_face,
                    &partial_plane,
                    partial_face,
                )
                .unwrap()
                .unwrap(),
                SurfaceIntersectionOperand::Second,
            ),
            (
                crate::boolean_kernel::intersect_faces(
                    &partial_plane,
                    partial_face,
                    &planar_patch,
                    planar_face,
                )
                .unwrap()
                .unwrap(),
                SurfaceIntersectionOperand::First,
            ),
        ] {
            let crate::FacePairTrim::SurfaceRegion {
                parameterized_on,
                region,
                covers_contained_face,
            } = pair.trim()
            else {
                panic!("partial tensor/plane overlap must retain its exact region");
            };
            assert_eq!(*parameterized_on, expected_parameter_operand);
            assert!(!covers_contained_face);
            assert!(matches!(
                region
                    .filled_area()
                    .unwrap()
                    ,
                Some(area)
                    if compare_reals(&area, &r(2), crate::STRICT_PREDICATES).value()
                        == Some(Ordering::Equal)
            ));
        }

        let rectangle_path = |min_x: i32, min_y: i32, max_x: i32, max_y: i32| {
            let points = [
                CurvePoint2::new(r(min_x), r(min_y)),
                CurvePoint2::new(r(max_x), r(min_y)),
                CurvePoint2::new(r(max_x), r(max_y)),
                CurvePoint2::new(r(min_x), r(max_y)),
            ];
            hypercurve::CurvePath2::try_new(
                (0..4)
                    .map(|index| {
                        Curve2::from(
                            LineSeg2::try_new(
                                points[index].clone(),
                                points[(index + 1) % 4].clone(),
                            )
                            .unwrap(),
                        )
                    })
                    .collect(),
            )
            .unwrap()
        };
        let excluded_outer = rectangle_path(-2, -2, 4, 4);
        let excluded_hole = rectangle_path(-1, -1, 3, 3);
        let (excluded_plane, excluded_face) = crate::construction::planar_face(
            &excluded_outer,
            &[excluded_hole],
            p(0, 0, 0),
            Vector3::from_xyz(r(1), r(0), r(0)),
            Vector3::from_xyz(r(0), r(1), r(0)),
        )
        .unwrap();
        let excluded = crate::boolean_kernel::intersect_faces(
            &planar_patch,
            planar_face,
            &excluded_plane,
            excluded_face,
        )
        .unwrap()
        .expect("overlapping face bounds must reach exact contained-surface trimming");
        assert!(matches!(excluded.trim(), crate::FacePairTrim::NoContact));

        let translation = Matrix4::affine_translation([r(3), r(-2), r(5)]);
        let translated_surface = surface
            .transformed(&TransformMetric::new(&translation), false)
            .unwrap();
        let translated_plane = plane
            .transformed(&TransformMetric::new(&translation), false)
            .unwrap();
        let SurfaceSurfaceIntersection::Curves(translated) = translated_surface
            .intersect_surface(&translated_plane)
            .unwrap()
        else {
            panic!("translated pole branches must retain their exact construction");
        };
        assert_eq!(translated.len(), 2);
        for (original, translated) in branches.iter().zip(&translated) {
            let expected = original.curve().evaluate_real(&q(1, 2)).unwrap()
                + Vector3::from_xyz(r(3), r(-2), r(5));
            assert_points_equal(
                &translated.curve().evaluate_real(&q(1, 2)).unwrap(),
                &expected,
            );
        }

        let (patch, face) = crate::construction::rational_bezier_patch(controls, weights).unwrap();
        let patch_surface = patch.surface(patch.face(face).unwrap().surface()).unwrap();
        let SurfaceSurfaceIntersection::Curves(patch_branches) =
            patch_surface.intersect_surface(&plane).unwrap()
        else {
            panic!("pole-branch patch must retain two topology-ready curves");
        };
        let (partitioned, partition) = patch
            .split_face_by_surface_curves(face, &patch_branches, SurfaceIntersectionOperand::First)
            .unwrap();
        assert_eq!(partition.faces.len(), 3);
        assert_eq!(partition.traces.len(), 2);
        assert_eq!(partitioned.counts().faces, 3);
        let mut caller_reversed = patch_branches.clone();
        caller_reversed.reverse();
        let (reverse_partitioned, _) = patch
            .split_face_by_surface_curves(face, &caller_reversed, SurfaceIntersectionOperand::First)
            .unwrap();
        assert_eq!(
            reverse_partitioned.to_json().unwrap(),
            partitioned.to_json().unwrap()
        );
        let json = partitioned.to_json().unwrap();
        assert_eq!(
            crate::ImportedModel::from_json(&json, &crate::ArchiveLimits::default())
                .unwrap()
                .validate()
                .unwrap()
                .to_json()
                .unwrap(),
            json
        );
    }

    #[test]
    fn single_span_nurbs_tensor_graph_sections_retain_native_domain_through_topology() {
        let controls = vec![
            vec![p(0, 0, 0), p(2, 0, 0)],
            vec![p(0, 2, 1), p(2, 2, 1)],
            vec![p(0, 2, 2), p(2, 2, 2)],
        ];
        let weights = vec![vec![r(1), r(1)], vec![r(2), r(2)], vec![r(3), r(3)]];
        let (patch, face) = crate::construction::nurbs_patch(
            1,
            2,
            controls,
            weights,
            vec![r(7), r(7), r(11), r(11)],
            vec![r(2), r(2), r(2), r(5), r(5), r(5)],
        )
        .unwrap();
        let surface = patch.surface(patch.face(face).unwrap().surface()).unwrap();
        let plane = Surface::plane(
            p(2, 0, 0),
            Vector3::y(),
            Vector3::from_xyz(r(1), r(0), r(-1)),
        )
        .unwrap();
        let SurfaceSurfaceIntersection::Curve(section) = surface.intersect_surface(&plane).unwrap()
        else {
            panic!("single-span NURBS tensor must retain one graph section");
        };
        assert_eq!(section.curve().domain().represented_start().unwrap(), &r(2));
        assert_eq!(section.curve().domain().represented_end().unwrap(), &r(5));
        let materialized = section.first_pcurve().materialize().unwrap();
        assert_eq!(
            materialized.correspondence().affine_coefficients(),
            Some((&r(3), &r(2)))
        );
        assert_eq!(
            materialized
                .curve()
                .point_at(&q(1, 2).clone().into())
                .unwrap()
                .coordinates()
                .expect("native pcurve coordinates")
                .clone(),
            CurvePoint2::new(q(17, 2), q(7, 2))
        );
        let (split, _) = patch
            .split_face_by_surface_curve(face, &section, SurfaceIntersectionOperand::First)
            .unwrap();
        assert_eq!(split.counts().faces, 2);
        let json = split.to_json().unwrap();
        assert_eq!(
            crate::ImportedModel::from_json(&json, &crate::ArchiveLimits::default())
                .unwrap()
                .validate()
                .unwrap()
                .to_json()
                .unwrap(),
            json
        );
    }

    #[test]
    fn multi_span_nurbs_tensor_graph_sections_materialize_split_and_replay_exactly() {
        let controls = vec![
            vec![p(0, 0, 0), p(2, 0, 0)],
            vec![p(0, 2, 1), p(2, 2, 1)],
            vec![p(0, 3, 1), p(2, 3, 1)],
            vec![p(0, 1, 2), p(2, 1, 2)],
        ];
        let weights = vec![
            vec![r(1), r(1)],
            vec![r(2), r(2)],
            vec![r(3), r(3)],
            vec![r(1), r(1)],
        ];
        let (patch, face) = crate::construction::nurbs_patch(
            1,
            2,
            controls,
            weights,
            vec![r(7), r(7), r(11), r(11)],
            vec![r(2), r(2), r(2), r(3), r(5), r(5), r(5)],
        )
        .unwrap();
        let surface = patch.surface(patch.face(face).unwrap().surface()).unwrap();
        let plane = Surface::plane(
            p(2, 0, 0),
            Vector3::y(),
            Vector3::from_xyz(r(1), r(0), r(-1)),
        )
        .unwrap();
        let SurfaceSurfaceIntersection::Curve(section) = surface.intersect_surface(&plane).unwrap()
        else {
            panic!("multi-span NURBS tensor must retain one graph section");
        };
        assert_eq!(section.curve().domain().represented_start().unwrap(), &r(2));
        assert_eq!(section.curve().domain().represented_end().unwrap(), &r(5));
        let materialized = section.first_pcurve().materialize().unwrap();
        assert_eq!(materialized.curve().family(), CurveFamily2::Nurbs);
        assert_eq!(
            materialized.correspondence().affine_coefficients(),
            Some((&r(1), &r(0)))
        );
        for parameter in [r(2), r(3), r(4), r(5)] {
            let surface_parameter = materialized
                .curve()
                .point_at(&parameter.clone().into())
                .unwrap()
                .coordinates()
                .expect("native pcurve coordinates")
                .clone();
            assert_points_equal(
                &section.curve().evaluate_real(&parameter).unwrap(),
                &surface
                    .evaluate_real(&Point2::new(
                        surface_parameter.x().clone(),
                        surface_parameter.y().clone(),
                    ))
                    .unwrap(),
            );
        }
        let (split, record) = patch
            .split_face_by_surface_curve(face, &section, SurfaceIntersectionOperand::First)
            .unwrap();
        assert_eq!(split.counts().faces, 2);
        let graph_use = split
            .edge_use(record.open().unwrap().face.edge_uses[0])
            .unwrap();
        let graph_pcurve = split.pcurve(graph_use.pcurve()).unwrap();
        let Some(CurveGeometry2::Nurbs(graph)) = graph_pcurve.curve().geometry() else {
            panic!("multi-span tensor split must retain one NURBS graph pcurve");
        };
        let mut forged_controls = graph.affine_control_points().unwrap().to_vec();
        forged_controls[1] = CurvePoint2::new(
            forged_controls[1].x().clone() + Real::one(),
            forged_controls[1].y().clone(),
        );
        let forged = Pcurve::new(
            Curve2::try_nurbs(
                graph.degree(),
                forged_controls,
                graph.weights().to_vec(),
                graph.knots().to_vec(),
            )
            .unwrap(),
        );
        let mut edit = split.edit();
        edit.replace_pcurve(graph_use.pcurve(), forged).unwrap();
        assert!(
            edit.commit().is_err(),
            "endpoint-preserving NURBS graph forgery must fail full control-net validation"
        );
        let json = split.to_json().unwrap();
        assert_eq!(
            crate::ImportedModel::from_json(&json, &crate::ArchiveLimits::default())
                .unwrap()
                .validate()
                .unwrap()
                .to_json()
                .unwrap(),
            json
        );

        let (v_patch, v_face) = crate::construction::nurbs_patch(
            2,
            1,
            vec![
                vec![p(0, 0, 0), p(1, 2, 0), p(1, 3, 0), p(2, 1, 0)],
                vec![p(0, 0, 2), p(1, 2, 2), p(1, 3, 2), p(2, 1, 2)],
            ],
            vec![vec![r(1), r(2), r(3), r(1)], vec![r(1), r(2), r(3), r(1)]],
            vec![r(2), r(2), r(2), r(3), r(5), r(5), r(5)],
            vec![r(7), r(7), r(11), r(11)],
        )
        .unwrap();
        let v_surface = v_patch
            .surface(v_patch.face(v_face).unwrap().surface())
            .unwrap();
        let SurfaceSurfaceIntersection::Curve(v_section) =
            v_surface.intersect_surface(&plane).unwrap()
        else {
            panic!("multi-span v-linear NURBS tensor must retain one graph section");
        };
        let v_materialized = v_section.first_pcurve().materialize().unwrap();
        assert_eq!(v_materialized.curve().family(), CurveFamily2::Nurbs);
        assert_eq!(
            v_materialized.correspondence().affine_coefficients(),
            Some((&r(1), &r(0)))
        );
        let (v_split, _) = v_patch
            .split_face_by_surface_curve(v_face, &v_section, SurfaceIntersectionOperand::First)
            .unwrap();
        assert_eq!(v_split.counts().faces, 2);
        let v_json = v_split.to_json().unwrap();
        assert_eq!(
            crate::ImportedModel::from_json(&v_json, &crate::ArchiveLimits::default())
                .unwrap()
                .validate()
                .unwrap()
                .to_json()
                .unwrap(),
            v_json
        );
    }

    #[test]
    fn extrusion_surfaces_intersect_planes_in_exact_native_curves_and_lines() {
        let profile = Curve3::rational_bezier(
            vec![p(0, 0, 0), p(1, 2, 0), p(2, 0, 0)],
            vec![r(1), r(2), r(1)],
        )
        .unwrap();
        let extrusion = Surface::extrusion(profile.clone(), Vector3::z()).unwrap();
        let oblique = Surface::plane(
            Point3::origin(),
            Vector3::from_xyz(r(1), r(0), r(1)),
            Vector3::y(),
        )
        .unwrap();
        let SurfaceSurfaceIntersection::Curve(section) =
            extrusion.intersect_surface(&oblique).unwrap()
        else {
            panic!("transverse plane must retain the projected native profile");
        };
        assert_eq!(section.curve().kind(), Curve3Kind::RationalBezier);
        let parameter = q(1, 2);
        let profile_point = profile.evaluate_real(&parameter).unwrap();
        let expected = Point3::new(profile_point.x.clone(), profile_point.y, profile_point.x);
        assert_points_equal(
            &section.curve().evaluate_real(&parameter).unwrap(),
            &expected,
        );
        assert_eq!(
            section
                .first_pcurve()
                .point_at(&Real::clone(&parameter).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap(),
            Point2::new(parameter.clone(), expected.z.clone())
        );
        let extrusion_clip = section
            .first_pcurve()
            .clipping_carriers()
            .unwrap()
            .expect("rational extrusion section has an exact planar carrier")
            .pop()
            .expect("one rational extrusion span");
        let extrusion_parameter = extrusion_clip
            .curve
            .point_at(&parameter.clone().into())
            .unwrap()
            .coordinates()
            .expect("native pcurve coordinates")
            .clone();
        assert_eq!(
            compare_reals(
                extrusion_parameter.x(),
                &parameter,
                crate::STRICT_PREDICATES
            )
            .value(),
            Some(Ordering::Equal)
        );
        assert_eq!(
            compare_reals(
                extrusion_parameter.y(),
                &expected.z,
                crate::STRICT_PREDICATES
            )
            .value(),
            Some(Ordering::Equal)
        );
        let plane_clip = section
            .second_pcurve()
            .clipping_carriers()
            .unwrap()
            .expect("projected rational section has an exact planar carrier")
            .pop()
            .expect("one projected rational span");
        let plane_parameter = plane_clip
            .curve
            .point_at(&parameter.clone().into())
            .unwrap()
            .coordinates()
            .expect("native pcurve coordinates")
            .clone();
        let retained_plane_parameter = section
            .second_pcurve()
            .point_at(&Real::clone(&parameter).into())
            .map(crate::geometry::represented_test_surface_parameter)
            .unwrap();
        assert_eq!(
            compare_reals(
                plane_parameter.x(),
                &retained_plane_parameter.x,
                crate::STRICT_PREDICATES
            )
            .value(),
            Some(Ordering::Equal)
        );
        assert_eq!(
            compare_reals(
                plane_parameter.y(),
                &retained_plane_parameter.y,
                crate::STRICT_PREDICATES
            )
            .value(),
            Some(Ordering::Equal)
        );

        let nurbs_profile = Curve3::nurbs(
            1,
            vec![p(0, 0, 0), p(1, 2, 0), p(2, 0, 0)],
            vec![r(1), r(2), r(1)],
            vec![r(2), r(2), r(3), r(4), r(4)],
        )
        .unwrap();
        let nurbs_extrusion = Surface::extrusion(nurbs_profile.clone(), Vector3::z()).unwrap();
        let SurfaceSurfaceIntersection::Curve(nurbs_section) =
            nurbs_extrusion.intersect_surface(&oblique).unwrap()
        else {
            panic!("transverse NURBS extrusion must retain one exact section");
        };
        let carriers = nurbs_section
            .first_pcurve()
            .clipping_carriers()
            .unwrap()
            .expect("NURBS extrusion section decomposes into rational trim carriers");
        assert_eq!(carriers.len(), 2);
        for carrier in &carriers {
            for local in [Real::zero(), Real::one()] {
                let spatial_parameter = carrier
                    .spatial_parameter_at(&local.clone().into())
                    .unwrap()
                    .try_real()
                    .unwrap()
                    .clone();
                let materialized = carrier
                    .curve
                    .point_at(&local.clone().into())
                    .unwrap()
                    .coordinates()
                    .expect("native pcurve coordinates")
                    .clone();
                let retained = nurbs_section
                    .first_pcurve()
                    .point_at(&Real::clone(&spatial_parameter).into())
                    .map(crate::geometry::represented_test_surface_parameter)
                    .unwrap();
                assert_eq!(
                    compare_reals(materialized.x(), &retained.x, crate::STRICT_PREDICATES).value(),
                    Some(Ordering::Equal)
                );
                assert_eq!(
                    compare_reals(materialized.y(), &retained.y, crate::STRICT_PREDICATES).value(),
                    Some(Ordering::Equal)
                );
            }
        }
        let trim_points = [
            CurvePoint2::new(q(5, 2), r(-100)),
            CurvePoint2::new(q(7, 2), r(-100)),
            CurvePoint2::new(q(7, 2), r(100)),
            CurvePoint2::new(q(5, 2), r(100)),
        ];
        let trim_contour = hypercurve::Contour2::try_new(
            (0..trim_points.len())
                .map(|index| {
                    LineSeg2::try_new(
                        trim_points[index].clone(),
                        trim_points[(index + 1) % trim_points.len()].clone(),
                    )
                    .map(Segment2::Line)
                })
                .collect::<Result<Vec<_>, _>>()
                .unwrap(),
        )
        .unwrap();
        let trim_region =
            CurveRegion2::try_from_native_material_contours(vec![trim_contour]).unwrap();
        let mut retained_ranges = Vec::new();
        for carrier in &carriers {
            for fragment in carrier
                .curve
                .trim_inside_region_with_parameters(&trim_region)
                .unwrap()
            {
                let (local_start, local_end) = fragment
                    .represented_parameter_range()
                    .expect("linear region contacts have represented parameters");
                retained_ranges.push((
                    carrier
                        .spatial_parameter_at(&local_start.into())
                        .unwrap()
                        .try_real()
                        .unwrap()
                        .clone(),
                    carrier
                        .spatial_parameter_at(&local_end.into())
                        .unwrap()
                        .try_real()
                        .unwrap()
                        .clone(),
                ));
            }
        }
        assert_eq!(retained_ranges.len(), 2);
        for ((actual_start, actual_end), (expected_start, expected_end)) in retained_ranges
            .into_iter()
            .zip([(q(5, 2), r(3)), (r(3), q(7, 2))])
        {
            assert_eq!(
                compare_reals(&actual_start, &expected_start, crate::STRICT_PREDICATES).value(),
                Some(Ordering::Equal)
            );
            assert_eq!(
                compare_reals(&actual_end, &expected_end, crate::STRICT_PREDICATES).value(),
                Some(Ordering::Equal)
            );
        }

        let ruled = Surface::extrusion(Curve3::line(p(0, 0, 0), p(2, 0, 0)).unwrap(), Vector3::z())
            .unwrap();
        let x_one = Surface::plane(p(1, 0, 0), Vector3::y(), Vector3::z()).unwrap();
        let SurfaceSurfaceIntersection::Line(line) = x_one.intersect_surface(&ruled).unwrap()
        else {
            panic!("parallel plane/profile point must lift to one extrusion line");
        };
        assert_points_equal(&line.point, &p(1, 0, 0));
        assert_points_equal(&Point3::from(line.direction), &Point3::from(Vector3::z()));
        assert!(matches!(
            ruled
                .intersect_surface(&Surface::plane(p(0, 1, 0), Vector3::x(), Vector3::z()).unwrap())
                .unwrap(),
            SurfaceSurfaceIntersection::None
        ));
        assert_eq!(
            ruled
                .intersect_surface(
                    &Surface::plane(Point3::origin(), Vector3::x(), Vector3::z()).unwrap()
                )
                .unwrap_err(),
            GeometryError::UnsupportedIntersection
        );
    }

