            Point3::origin(),
            Vector3::x(),
            Vector3::y(),
            r(1),
            Real::zero(),
            Real::tau(),
        )
        .unwrap();
        assert!(matches!(
            sphere.intersect_curve(&inside).unwrap(),
            CurveSurfaceIntersection::None
        ));
    }

