        };
        let sqrt_five = r(5).sqrt().unwrap();
        assert_points_equal(
            &circles[0].curve().start().unwrap(),
            &Point3::new(r(2), Real::zero(), sqrt_five.clone()),
        );
        assert_points_equal(
            &circles[1].curve().start().unwrap(),
            &Point3::new(r(2), Real::zero(), -sqrt_five),
        );
        for circle in &circles {
            let parameter = Real::pi();
            let spatial = circle.curve().evaluate_real(&parameter).unwrap();
            let sphere_point = sphere
                .evaluate_real(
                    &circle
                        .first_pcurve()
                        .point_at(&Real::clone(&parameter).into())
                        .map(crate::geometry::represented_test_surface_parameter)
                        .unwrap(),
                )
                .unwrap();
            let cylinder_point = cylinder
                .evaluate_real(
                    &circle
                        .second_pcurve()
                        .point_at(&Real::clone(&parameter).into())
                        .map(crate::geometry::represented_test_surface_parameter)
                        .unwrap(),
                )
                .unwrap();
            assert_points_equal(&sphere_point, &spatial);
            assert_points_equal(&cylinder_point, &spatial);
            assert!(circle.first_pcurve().materialize().is_ok());
            assert!(circle.second_pcurve().materialize().is_ok());
        }
        let SurfaceSurfaceIntersection::Curves(swapped) =
            cylinder.intersect_surface(&sphere).unwrap()
        else {
            panic!("operand reversal must retain the same two exact circles");
        };
        let parameter = Real::pi();
        assert_points_equal(
            &cylinder
                .evaluate_real(
                    &swapped[0]
                        .first_pcurve()
                        .point_at(&Real::clone(&parameter).into())
                        .map(crate::geometry::represented_test_surface_parameter)
                        .unwrap(),
                )
                .unwrap(),
            &swapped[0].curve().evaluate_real(&parameter).unwrap(),
        );
        assert_points_equal(
            &sphere
                .evaluate_real(
                    &swapped[0]
                        .second_pcurve()
                        .point_at(&Real::clone(&parameter).into())
                        .map(crate::geometry::represented_test_surface_parameter)
                        .unwrap(),
                )
                .unwrap(),
            &swapped[0].curve().evaluate_real(&parameter).unwrap(),
        );
        let rotated_parameters = Surface::sphere(
            Point3::origin(),
            Vector3::y(),
            -Vector3::x(),
            Vector3::z(),
            r(3),
        )
        .unwrap();
        assert!(matches!(
            cylinder.intersect_surface(&rotated_parameters).unwrap(),
            SurfaceSurfaceIntersection::Circles(_)
        ));
        let mirrored_cylinder = Surface::cylinder(
            Point3::origin(),
            Vector3::x(),
            -Vector3::y(),
            -Vector3::z(),
            r(2),
        )
        .unwrap();
        let SurfaceSurfaceIntersection::Curves(mirrored_circles) =
            sphere.intersect_surface(&mirrored_cylinder).unwrap()
        else {
            panic!("mirrored coaxial cylinder parameters must retain both circles");
        };
        assert_eq!(mirrored_circles.len(), 2);
        let mirrored_parameter = q(1, 3);
        for mirrored_circle in &mirrored_circles {
            let spatial = mirrored_circle
                .curve()
                .evaluate_real(&mirrored_parameter)
                .unwrap();
            assert_points_equal(
                &mirrored_cylinder
                    .evaluate_real(
                        &mirrored_circle
                            .second_pcurve()
                            .point_at(&Real::clone(&mirrored_parameter).into())
                            .map(crate::geometry::represented_test_surface_parameter)
                            .unwrap(),
                    )
                    .unwrap(),
                &spatial,
            );
            let cylinder_pcurve = mirrored_circle.second_pcurve().materialize().unwrap();
            assert_eq!(
                cylinder_pcurve
                    .curve()
                    .start()
                    .coordinates()
                    .expect("native fixture endpoint")
                    .x(),
                &Real::tau()
            );
            assert_eq!(
                cylinder_pcurve
                    .curve()
                    .end()
                    .coordinates()
                    .expect("native fixture endpoint")
                    .x(),
                &Real::zero()
            );
        }

        let tangent = Surface::sphere(
            Point3::origin(),
            Vector3::x(),
            Vector3::y(),
            Vector3::z(),
            r(2),
        )
        .unwrap();
        let SurfaceSurfaceIntersection::Curve(circle) =
            cylinder.intersect_surface(&tangent).unwrap()
        else {
            panic!("equal-radius aligned carriers must retain one tangent circle");
        };
        assert_points_equal(&circle.curve().start().unwrap(), &p(2, 0, 0));
        assert!(circle.first_pcurve().materialize().is_ok());
        assert!(circle.second_pcurve().materialize().is_ok());
        let contained = Surface::sphere(
            Point3::origin(),
            Vector3::x(),
            Vector3::y(),
            Vector3::z(),
            r(1),
        )
        .unwrap();
        assert!(matches!(
            cylinder.intersect_surface(&contained).unwrap(),
            SurfaceSurfaceIntersection::None
        ));
        let off_axis =
            Surface::sphere(p(1, 0, 0), Vector3::x(), Vector3::y(), Vector3::z(), r(3)).unwrap();
        assert_eq!(
            cylinder.intersect_surface(&off_axis).unwrap_err(),
            GeometryError::UnsupportedIntersection
        );
    }

