            assert_points_equal(
                &two_circle_sphere
                    .evaluate_real(
                        &circle
                            .first_pcurve()
                            .point_at(&Real::clone(&parameter).into())
                            .map(crate::geometry::represented_test_surface_parameter)
                            .unwrap(),
                    )
                    .unwrap(),
                &spatial,
            );
            assert_points_equal(
                &cone
                    .evaluate_real(
                        &circle
                            .second_pcurve()
                            .point_at(&Real::clone(&parameter).into())
                            .map(crate::geometry::represented_test_surface_parameter)
                            .unwrap(),
                    )
                    .unwrap(),
