        }

        let tangent =
            Surface::sphere(p(0, 0, 5), Vector3::x(), Vector3::y(), Vector3::z(), r(3)).unwrap();
        let SurfaceSurfaceIntersection::Curve(tangent_circle) =
            tangent.intersect_surface(&cone).unwrap()
        else {
            panic!("zero discriminant must retain one tangent latitude circle");
        };
        assert_points_equal(
            &tangent_circle.curve().start().unwrap(),
            &Point3::new(q(12, 5), Real::zero(), q(16, 5)),
        );

        let separated =
            Surface::sphere(p(0, 0, 5), Vector3::x(), Vector3::y(), Vector3::z(), r(2)).unwrap();
        assert!(matches!(
            separated.intersect_surface(&cone).unwrap(),
            SurfaceSurfaceIntersection::None
        ));
        let apex_only =
            Surface::sphere(p(0, 0, -5), Vector3::x(), Vector3::y(), Vector3::z(), r(5)).unwrap();
        let SurfaceSurfaceIntersection::Point(point) = apex_only.intersect_surface(&cone).unwrap()
        else {
            panic!("the lower coaxial sphere must retain its isolated apex contact");
        };
        assert_points_equal(
            point
                .try_coordinates()
                .expect("represented analytic contact"),
            &Point3::origin(),
        );

        let mixed_dimension =
            Surface::sphere(p(0, 0, 5), Vector3::x(), Vector3::y(), Vector3::z(), r(5)).unwrap();
        let SurfaceSurfaceIntersection::Components(components) =
            mixed_dimension.intersect_surface(&cone).unwrap()
        else {
            panic!("apex-plus-circle contact must retain both exact dimensions");
        };
        assert_eq!(components.points().len(), 1);
        assert_points_equal(
            components.points()[0]
                .try_coordinates()
                .expect("represented analytic contact"),
            &Point3::origin(),
        );
        assert!(components.curves().is_empty());
        assert_eq!(components.surface_curves().len(), 1);
        let mixed_circle = &components.surface_curves()[0];
        assert_points_equal(
            &mixed_circle.curve().start().unwrap(),
            &Point3::new(q(24, 5), Real::zero(), q(32, 5)),
        );
        for parameter in [Real::zero(), Real::pi()] {
            let spatial = mixed_circle.curve().evaluate_real(&parameter).unwrap();
            assert_points_equal(
                &mixed_dimension
                    .evaluate_real(
                        &mixed_circle
                            .first_pcurve()
                            .point_at(&Real::clone(&parameter).into())
                            .map(crate::geometry::represented_test_surface_parameter)
                            .unwrap(),
                    )
                    .unwrap(),
                &spatial,
            );
            assert_points_equal(
                &cone
                    .evaluate_real(
                        &mixed_circle
                            .second_pcurve()
                            .point_at(&Real::clone(&parameter).into())
                            .map(crate::geometry::represented_test_surface_parameter)
                            .unwrap(),
                    )
                    .unwrap(),
                &spatial,
            );
        }
        let SurfaceSurfaceIntersection::Components(swapped) =
            cone.intersect_surface(&mixed_dimension).unwrap()
        else {
            panic!("operand reversal must retain both exact dimensions");
        };
        assert_eq!(swapped.points().len(), 1);
        assert!(swapped.curves().is_empty());
        assert_eq!(swapped.surface_curves().len(), 1);
        let swapped_circle = &swapped.surface_curves()[0];
        let parameter = q(1, 3);
        let spatial = swapped_circle.curve().evaluate_real(&parameter).unwrap();
        assert_points_equal(
            &cone
                .evaluate_real(
                    &swapped_circle
                        .first_pcurve()
                        .point_at(&Real::clone(&parameter).into())
                        .map(crate::geometry::represented_test_surface_parameter)
                        .unwrap(),
                )
                .unwrap(),
            &spatial,
        );
        assert_points_equal(
            &mixed_dimension
                .evaluate_real(
                    &swapped_circle
                        .second_pcurve()
                        .point_at(&Real::clone(&parameter).into())
                        .map(crate::geometry::represented_test_surface_parameter)
                        .unwrap(),
                )
                .unwrap(),
            &spatial,
        );
        let off_axis =
            Surface::sphere(p(1, 0, 0), Vector3::x(), Vector3::y(), Vector3::z(), r(2)).unwrap();
        assert_eq!(
            off_axis.intersect_surface(&cone).unwrap_err(),
            GeometryError::UnsupportedIntersection
        );

        let rotated_parameters =
            Surface::sphere(p(0, 0, 5), Vector3::y(), -Vector3::x(), Vector3::z(), r(5)).unwrap();
        let SurfaceSurfaceIntersection::Components(rotated) =
            cone.intersect_surface(&rotated_parameters).unwrap()
        else {
            panic!("rotated parameters must retain the exact spatial components");
        };
        assert_eq!(rotated.points().len(), 1);
        assert_eq!(rotated.curves().len(), 1);
        assert!(rotated.surface_curves().is_empty());
        assert_points_equal(
            rotated.points()[0]
                .try_coordinates()
                .expect("represented analytic contact"),
            &Point3::origin(),
        );
        assert_points_equal(
            &rotated.curves()[0].start().unwrap(),
            &Point3::new(q(24, 5), Real::zero(), q(32, 5)),
        );

        let mirrored_centered = Surface::sphere(
            Point3::origin(),
            Vector3::x(),
            -Vector3::y(),
            -Vector3::z(),
            r(2),
        )
        .unwrap();
        let SurfaceSurfaceIntersection::Curve(mirrored_circle) =
            mirrored_centered.intersect_surface(&cone).unwrap()
        else {
            panic!("mirrored sphere/cone frames must retain both exact pcurves");
        };
        let sphere_pcurve = mirrored_circle.first_pcurve().materialize().unwrap();
        assert_eq!(
            sphere_pcurve
                .curve()
                .start()
                .coordinates()
                .expect("native fixture endpoint")
                .x(),
            &Real::tau()
        );
        assert_eq!(
            sphere_pcurve
                .curve()
                .end()
                .coordinates()
                .expect("native fixture endpoint")
                .x(),
            &Real::zero()
        );
        let parameter = q(2, 3);
        let spatial = mirrored_circle.curve().evaluate_real(&parameter).unwrap();
        assert_points_equal(
            &mirrored_centered
                .evaluate_real(
                    &mirrored_circle
                        .first_pcurve()
                        .point_at(&Real::clone(&parameter).into())
                        .map(crate::geometry::represented_test_surface_parameter)
                        .unwrap(),
                )
                .unwrap(),
            &spatial,
        );
    }

