    #[test]
    fn coaxial_cone_intersections_retain_native_slant_circle() {
        let wide_angle = Real::one().atan().unwrap();
        let narrow_angle = q(1, 2).atan().unwrap();
        let wide = Surface::cone(
            Point3::origin(),
            Vector3::x(),
            Vector3::y(),
            Vector3::z(),
