            assert_points_equal(
                &wide
                    .evaluate_real(
                        &circle
                            .first_pcurve()
                            .point_at(&Real::clone(&parameter).into())
                            .map(crate::geometry::represented_test_surface_parameter)
                            .unwrap(),
                    )
                    .unwrap(),
