            assert_points_equal(
                &narrow
                    .evaluate_real(
                        &circle
                            .second_pcurve()
                            .point_at(&Real::clone(&parameter).into())
                            .map(crate::geometry::represented_test_surface_parameter)
                            .unwrap(),
                    )
                    .unwrap(),
                &spatial,
            );
        }
        let SurfaceSurfaceIntersection::Curve(swapped) = narrow.intersect_surface(&wide).unwrap()
        else {
            panic!("operand reversal must retain the same exact cone circle");
        };
        let parameter = q(1, 3);
        let spatial = swapped.curve().evaluate_real(&parameter).unwrap();
        assert_points_equal(
            &narrow
                .evaluate_real(
                    &swapped
                        .first_pcurve()
                        .point_at(&Real::clone(&parameter).into())
                        .map(crate::geometry::represented_test_surface_parameter)
                        .unwrap(),
                )
                .unwrap(),
            &spatial,
        );
        assert_points_equal(
            &wide
                .evaluate_real(
                    &swapped
                        .second_pcurve()
                        .point_at(&Real::clone(&parameter).into())
                        .map(crate::geometry::represented_test_surface_parameter)
                        .unwrap(),
                )
                .unwrap(),
            &spatial,
        );

        let shared_apex = Surface::cone(
            Point3::origin(),
            Vector3::x(),
            Vector3::y(),
            Vector3::z(),
            narrow_angle.clone(),
        )
