    #[test]
    fn plane_sphere_and_sphere_sphere_intersections_retain_exact_circles() {
        let sphere = Surface::sphere(
            Point3::origin(),
            Vector3::x(),
            Vector3::y(),
            Vector3::z(),
            r(2),
        )
        .unwrap();
        let equator = Surface::plane(Point3::origin(), Vector3::x(), Vector3::y()).unwrap();
        let SurfaceSurfaceIntersection::Curve(circle) = equator.intersect_surface(&sphere).unwrap()
        else {
            panic!("equatorial plane must retain a circle with both exact pcurves");
        };
        assert_eq!(circle.curve().kind(), Curve3Kind::CircleArc);
        assert_points_equal(&circle.curve().start().unwrap(), &p(2, 0, 0));
        assert_eq!(
            circle
                .first_pcurve()
                .materialize()
                .unwrap()
                .curve()
                .family(),
            CurveFamily2::CircularArc
        );
        assert_eq!(
            circle
                .second_pcurve()
                .materialize()
                .unwrap()
                .curve()
                .family(),
            CurveFamily2::Line
        );
        let SurfaceSurfaceIntersection::Curve(swapped) =
            sphere.intersect_surface(&equator).unwrap()
        else {
            panic!("operand reversal must retain the same exact sphere latitude");
        };
        assert_eq!(
            swapped
                .first_pcurve()
                .materialize()
                .unwrap()
                .curve()
                .family(),
            CurveFamily2::Line
        );
        assert_eq!(
            swapped
                .second_pcurve()
                .materialize()
                .unwrap()
                .curve()
                .family(),
            CurveFamily2::CircularArc
        );

        let tangent_plane = Surface::plane(p(0, 0, 2), Vector3::x(), Vector3::y()).unwrap();
        let SurfaceSurfaceIntersection::Point(point) =
            sphere.intersect_surface(&tangent_plane).unwrap()
        else {
            panic!("tangent plane must produce one point");
        };
        assert_points_equal(
            point
                .try_coordinates()
                .expect("represented analytic contact"),
            &p(0, 0, 2),
        );
        let disjoint_plane = Surface::plane(p(0, 0, 3), Vector3::x(), Vector3::y()).unwrap();
        assert!(matches!(
            sphere.intersect_surface(&disjoint_plane).unwrap(),
            SurfaceSurfaceIntersection::None
        ));

        let second =
            Surface::sphere(p(2, 0, 0), Vector3::x(), Vector3::y(), Vector3::z(), r(2)).unwrap();
        let SurfaceSurfaceIntersection::Circle(circle) = sphere.intersect_surface(&second).unwrap()
        else {
            panic!("overlapping spheres must produce a circle");
        };
        let point = circle.start().unwrap();
        assert_eq!(
            compare_reals(&point.x, &r(1), crate::STRICT_PREDICATES).value(),
            Some(Ordering::Equal)
        );
        let first_radius_squared = Vector3::from(point.clone()).norm_squared();
        let second_radius_squared = (&point - &p(2, 0, 0)).norm_squared();
        assert_eq!(
            compare_reals(&first_radius_squared, &r(4), crate::STRICT_PREDICATES).value(),
            Some(Ordering::Equal)
        );
        assert_eq!(
            compare_reals(&second_radius_squared, &r(4), crate::STRICT_PREDICATES).value(),
            Some(Ordering::Equal)
        );

        let axial_second =
            Surface::sphere(p(0, 0, 2), Vector3::x(), Vector3::y(), Vector3::z(), r(2)).unwrap();
        let SurfaceSurfaceIntersection::Curve(axial_circle) =
            sphere.intersect_surface(&axial_second).unwrap()
        else {
            panic!("authored-axis sphere centers must retain both latitude pcurves");
        };
        assert_points_equal(
            &axial_circle.curve().start().unwrap(),
            &Point3::new(r(3).sqrt().unwrap(), Real::zero(), Real::one()),
        );
        for parameter in [Real::zero(), Real::pi()] {
            let spatial = axial_circle.curve().evaluate_real(&parameter).unwrap();
            assert_points_equal(
                &sphere
                    .evaluate_real(
                        &axial_circle
                            .first_pcurve()
                            .point_at(&Real::clone(&parameter).into())
                            .map(crate::geometry::represented_test_surface_parameter)
                            .unwrap(),
                    )
                    .unwrap(),
                &spatial,
            );
            assert_points_equal(
                &axial_second
                    .evaluate_real(
                        &axial_circle
                            .second_pcurve()
                            .point_at(&Real::clone(&parameter).into())
                            .map(crate::geometry::represented_test_surface_parameter)
                            .unwrap(),
                    )
                    .unwrap(),
                &spatial,
            );
        }

        let mirrored_second =
            Surface::sphere(p(0, 0, 2), Vector3::x(), -Vector3::y(), -Vector3::z(), r(2)).unwrap();
        let SurfaceSurfaceIntersection::Curve(mirrored_circle) =
            sphere.intersect_surface(&mirrored_second).unwrap()
        else {
            panic!("mirrored sphere frames must retain reversed longitude");
        };
        let second_pcurve = mirrored_circle.second_pcurve().materialize().unwrap();
        assert_eq!(
            second_pcurve
                .curve()
                .start()
                .coordinates()
                .expect("native fixture endpoint")
                .x(),
            &Real::tau()
        );
        assert_eq!(
            second_pcurve
                .curve()
                .end()
                .coordinates()
                .expect("native fixture endpoint")
                .x(),
            &Real::zero()
        );
        for parameter in [Real::zero(), Real::pi()] {
            let spatial = mirrored_circle.curve().evaluate_real(&parameter).unwrap();
            assert_points_equal(
                &mirrored_second
                    .evaluate_real(
                        &mirrored_circle
                            .second_pcurve()
                            .point_at(&Real::clone(&parameter).into())
                            .map(crate::geometry::represented_test_surface_parameter)
                            .unwrap(),
                    )
                    .unwrap(),
                &spatial,
            );
        }

        let rotated_second =
            Surface::sphere(p(0, 0, 2), Vector3::y(), -Vector3::x(), Vector3::z(), r(2)).unwrap();
        assert!(matches!(
            sphere.intersect_surface(&rotated_second).unwrap(),
            SurfaceSurfaceIntersection::Circle(_)
        ));

        let tangent =
            Surface::sphere(p(4, 0, 0), Vector3::x(), Vector3::y(), Vector3::z(), r(2)).unwrap();
        let SurfaceSurfaceIntersection::Point(point) = sphere.intersect_surface(&tangent).unwrap()
        else {
            panic!("tangent spheres must produce one point");
        };
        assert_points_equal(
            point
                .try_coordinates()
                .expect("represented analytic contact"),
            &p(2, 0, 0),
        );
        assert!(matches!(
            sphere.intersect_surface(&sphere).unwrap(),
            SurfaceSurfaceIntersection::Coincident
        ));
    }

    #[test]
    fn analytic_surfaces_use_exact_domains_evaluation_and_partials() {
        let cylinder =
            Surface::cylinder(p(1, 2, 3), Vector3::x(), Vector3::y(), Vector3::z(), r(2)).unwrap();
        assert_eq!(cylinder.kind(), SurfaceKind::Cylinder);
        assert_points_equal(
            &cylinder.evaluate_real(&Point2::new(r(0), r(5))).unwrap(),
            &p(3, 2, 8),
        );
        let partials = cylinder
            .partials_at(&hypercurve::Point2::new(r(0), r(5)).into())
            .unwrap();
        assert_points_equal(
            &Point3::from(partials.u().try_coordinates().unwrap().clone()),
            &p(0, 2, 0),
        );
        assert_points_equal(
            &Point3::from(partials.v().try_coordinates().unwrap().clone()),
            &p(0, 0, 1),
        );

        let sphere = Surface::sphere(
            Point3::origin(),
            Vector3::x(),
            Vector3::y(),
            Vector3::z(),
            r(2),
        )
        .unwrap();
        assert_points_equal(
            &sphere.evaluate_real(&Point2::new(r(0), r(0))).unwrap(),
            &p(2, 0, 0),
        );
        let partials = sphere
            .partials_at(&hypercurve::Point2::new(r(0), r(0)).into())
            .unwrap();
        assert_points_equal(
            &Point3::from(partials.u().try_coordinates().unwrap().clone()),
            &p(0, 2, 0),
        );
        assert_points_equal(
            &Point3::from(partials.v().try_coordinates().unwrap().clone()),
            &p(0, 0, 2),
        );
        assert_points_equal(
            &Point3::from(
                sphere
                    .normal_at(&hypercurve::Point2::new(r(0), r(0)).into())
                    .unwrap()
                    .try_coordinates()
                    .unwrap()
                    .clone(),
            ),
            &p(1, 0, 0),
        );
        assert_eq!(
            sphere
                .normal_at(&hypercurve::Point2::new(r(0), (Real::pi() / r(2)).unwrap()).into())
                .unwrap_err(),
            GeometryError::SingularSurfaceParameter
        );
        assert_eq!(
            sphere
                .evaluate_real(&Point2::new(r(0), Real::pi()))
                .unwrap_err(),
            GeometryError::SurfaceParameterOutsideDomain
        );

        let cone = Surface::cone(
            p(1, 2, 3),
            Vector3::x(),
            Vector3::y(),
            Vector3::z(),
            (Real::pi() / r(4)).unwrap(),
        )
        .unwrap();
        assert_points_equal(
            &cone.evaluate_real(&Point2::new(r(7), r(0))).unwrap(),
            &p(1, 2, 3),
        );
        assert_eq!(
            cone.normal_at(&hypercurve::Point2::new(r(7), r(0)).into())
                .unwrap_err(),
            GeometryError::SingularSurfaceParameter
        );
        assert_eq!(
            cone.evaluate_real(&Point2::new(r(0), r(-1))).unwrap_err(),
            GeometryError::SurfaceParameterOutsideDomain
        );

        let torus = Surface::torus(
            Point3::origin(),
            Vector3::x(),
            Vector3::y(),
            Vector3::z(),
            r(4),
            r(1),
        )
        .unwrap();
        assert_points_equal(
            &torus.evaluate_real(&Point2::new(r(0), r(0))).unwrap(),
            &p(5, 0, 0),
        );
    }

    #[test]
    fn analytic_surface_constructors_reject_invalid_exact_geometry() {
        assert_eq!(
            Surface::cylinder(
                Point3::origin(),
                Vector3::x(),
                Vector3::x(),
                Vector3::z(),
                r(1),
            )
            .unwrap_err(),
            GeometryError::InvalidSurfaceFrame
        );
        assert_eq!(
            Surface::sphere(
                Point3::origin(),
                Vector3::x(),
                Vector3::y(),
                Vector3::z(),
                r(0),
            )
            .unwrap_err(),
            GeometryError::InvalidRadius
        );
        assert_eq!(
            Surface::torus(
                Point3::origin(),
                Vector3::x(),
                Vector3::y(),
                Vector3::z(),
                r(2),
                r(2),
            )
            .unwrap_err(),
            GeometryError::InvalidTorusRadii
        );
    }

    #[test]
    fn named_circle_and_ellipse_arcs_retain_exact_angle_semantics() {
        let half_pi = (Real::pi() / r(2)).unwrap();
        let circle = Curve3::circle_arc(
            Point3::origin(),
            Vector3::x(),
            Vector3::y(),
            r(2),
            Real::zero(),
            half_pi.clone(),
        )
        .unwrap();
        assert_eq!(circle.kind(), Curve3Kind::CircleArc);
        assert_points_equal(&circle.start().unwrap(), &p(2, 0, 0));
        assert_points_equal(&circle.end().unwrap(), &p(0, 2, 0));
        assert_points_equal(
            &Point3::from(
                circle
                    .derivative_at(&Real::zero().into(), 1)
                    .unwrap()
                    .try_coordinates()
                    .unwrap()
                    .clone(),
            ),
            &p(0, 2, 0),
        );
        let reversed = circle.reversed().unwrap();
        assert_points_equal(&reversed.start().unwrap(), &circle.end().unwrap());
        assert_points_equal(&reversed.end().unwrap(), &circle.start().unwrap());
        let split = (half_pi.clone() / r(2)).unwrap();
        let (left, right) = circle.split_at(&split).unwrap();
        assert!(left.shares_parameterization(&circle));
        assert!(right.shares_parameterization(&circle));
        assert!(left.has_certified_same_parameterization(&right));
        assert_points_equal(&left.end().unwrap(), &right.start().unwrap());
        let retained = circle.subcurve(&split, &half_pi).unwrap();
        assert!(retained.shares_parameterization(&circle));
        let independently_constructed = Curve3::circle_arc(
            Point3::origin(),
            Vector3::x(),
            Vector3::y(),
            r(2),
            Real::zero(),
            (Real::pi() / r(2)).unwrap(),
        )
        .unwrap();
        assert!(circle.has_certified_same_parameterization(&independently_constructed));

        let ellipse = Curve3::ellipse_arc(
            Point3::origin(),
            Vector3::x(),
            Vector3::y(),
            r(3),
            r(2),
            Real::zero(),
            half_pi,
        )
        .unwrap();
        assert_eq!(ellipse.kind(), Curve3Kind::EllipseArc);
        assert_points_equal(&ellipse.start().unwrap(), &p(3, 0, 0));
        assert_points_equal(&ellipse.end().unwrap(), &p(0, 2, 0));

        assert_eq!(
            Curve3::circle_arc(
                Point3::origin(),
                Vector3::x(),
                Vector3::y(),
                r(1),
                Real::zero(),
                r(3) * Real::pi(),
            )
            .unwrap_err(),
            GeometryError::InvalidArcSweep
        );
    }
}

