    // Assertions compare independently constructed exact representations. Keep
    // production predicates strict while allowing the test oracle to finish a
    // comparison when structural certification alone cannot normalize them.
    fn compare_reals(
        left: &Real,
        right: &Real,
        _policy: hyperlimit::PredicatePolicy,
    ) -> hyperlimit::PredicateOutcome<Ordering> {
        hyperlimit::compare_reals(left, right, crate::TEST_ORACLE_PREDICATES)
    }

    fn point3_equal(
        left: &Point3,
        right: &Point3,
        _policy: hyperlimit::PredicatePolicy,
    ) -> hyperlimit::PredicateOutcome<bool> {
        hyperlimit::point3_equal(left, right, crate::TEST_ORACLE_PREDICATES)
    }

    fn p(x: i32, y: i32, z: i32) -> Point3 {
        Point3::new(Real::from(x), Real::from(y), Real::from(z))
    }

    #[test]
    fn prism_frame_requires_exactly_parallel_axes() {
        let (model, solid) = crate::construction::cylinder(Real::from(1), Real::from(6)).unwrap();
        let rotation = |t: Real| {
            let denominator = Real::one() + &t * &t;
            let c = ((Real::one() - &t * &t) / &denominator).unwrap();
            let s = (Real::from(2) * t / denominator).unwrap();
            Matrix4::from_row_major([
                Real::one(),
                Real::zero(),
                Real::zero(),
                Real::zero(),
                Real::zero(),
                c.clone(),
                -&s,
                Real::zero(),
                Real::zero(),
                s,
                c,
                Real::zero(),
                Real::zero(),
                Real::zero(),
                Real::zero(),
                Real::one(),
            ])
        };
        let first_frame = rotation((Real::one() / Real::from(2)).unwrap());
        let first = model.transformed(&first_frame).unwrap();
        let tiny = (Real::one() / Real::from(1_000_000_000_000_i64)).unwrap();
        for second_frame in [Matrix4::identity(), first_frame * rotation(tiny)] {
            let second = model.transformed(&second_frame).unwrap();
            assert!(
                oriented_prism_boolean(&first, solid, &second, solid, BooleanOp::Difference)
                    .unwrap()
                    .is_none()
            );
        }
    }

    #[test]
    fn prism_frame_rejects_skew_extrusion_as_a_vertical_product() {
        let uv = |x: i32, y: i32| hypercurve::Point2::new(Real::from(x), Real::from(y));
        let path = CurvePath2::try_new(
            [((1, 0), (-1, 0)), ((-1, 0), (1, 0))]
                .into_iter()
                .map(|(a, b)| {
                    Curve2::from(
                        hypercurve::CircularArc2::try_from_center(
                            uv(a.0, a.1),
                            uv(b.0, b.1),
                            uv(0, 0),
                            false,
                        )
                        .unwrap(),
                    )
                })
                .collect(),
        )
        .unwrap();
        let (model, solid) =
            crate::construction::extrude_path(&path, Real::zero(), Real::from(6)).unwrap();
        let shear = Matrix4::from_row_major([
            Real::one(),
            Real::zero(),
            Real::one(),
            Real::zero(),
            Real::zero(),
            Real::one(),
            Real::zero(),
            Real::zero(),
            Real::zero(),
            Real::zero(),
            Real::one(),
            Real::zero(),
            Real::zero(),
            Real::zero(),
            Real::zero(),
            Real::one(),
        ]);
        let skew = model.transformed(&shear).unwrap();
        let witness = Point3::new(
            (Real::from(-1) / Real::from(2)).unwrap(),
            Real::zero(),
            (Real::one() / Real::from(10)).unwrap(),
        );
        assert_eq!(
            skew.classify_point(solid, &witness).unwrap(),
            SolidPointLocation::Inside
        );
        assert!(skew.certified_right_prism_frame(solid).unwrap().is_none());
        assert!(skew.certified_z_prism_profile(solid).unwrap().is_none());
        for map in [
            shear.clone(),
            Matrix4::from_row_major([
                -Real::one(),
                0.into(),
                (-1).into(),
                0.into(),
                0.into(),
                1.into(),
                0.into(),
                0.into(),
                0.into(),
                0.into(),
                1.into(),
                0.into(),
                0.into(),
                0.into(),
                0.into(),
                1.into(),
            ]),
        ] {
            let moved = model.transformed(&map).unwrap();
            let text = moved.to_json().unwrap();
            let cold = crate::ImportedModel::from_json(&text, &crate::ArchiveLimits::default())
                .unwrap()
                .validate()
                .unwrap();
            assert_eq!(cold.to_json().unwrap(), text);
            assert_eq!(
                exact_order(
                    &cold.solid_volume(solid).unwrap(),
                    &(Real::from(6) * Real::pi())
                )
                .unwrap(),
                Ordering::Equal
            );
            let inside = map.transform_point3(&p(0, 0, 3)).unwrap();
            assert_eq!(
                cold.classify_point(solid, &inside).unwrap(),
                SolidPointLocation::Inside
            );
        }
    }

    #[test]
    fn prepared_circle_contacts_retain_actual_brep_edges() {
        let (model, _) = crate::construction::cylinder(Real::from(5), Real::from(6)).unwrap();
        let mut count = 0;
        for (face_id, face) in model.faces() {
            if face_surface(&model, face_id).kind() != crate::SurfaceKind::Plane {
                continue;
            }
            let region = planar_face_region(&model, face_id).unwrap();
            for &edge_use in model.wire(face.outer().unwrap()).unwrap().edge_uses() {
                let pcurve = model
                    .pcurve(model.edge_use(edge_use).unwrap().pcurve())
                    .unwrap();
                for fragment in pcurve
                    .curve()
                    .trim_inside_region_with_parameters(&region)
                    .unwrap()
                {
                    for contacts in [
                        fragment.start_boundary_contacts(),
                        fragment.end_boundary_contacts(),
                    ] {
                        let retained = model_boundary_contacts(&model, face_id, contacts, None)
                            .unwrap()
                            .unwrap();
                        assert!(!retained.is_empty());
                        for contact in retained {
                            let replay =
                                contact.curve().evaluate_real(contact.parameter()).unwrap();
                            assert_eq!(
                                hyperlimit::point3_equal(
                                    &replay,
                                    contact.spatial_point(),
                                    crate::STRICT_PREDICATES
                                )
                                .value(),
                                Some(true)
                            );
                            count += 1;
                        }
                    }
                }
            }
        }
        assert!(count >= 8);
    }

    fn assert_surface_fragment_replays(
        fragment: &SurfaceIntersectionCurve,
        first_surface: &Surface,
        second_surface: &Surface,
    ) {
        for pcurve in [fragment.first_pcurve(), fragment.second_pcurve()] {
            assert_eq!(
                compare_reals(
                    pcurve.domain().represented_start().unwrap(),
                    fragment.curve().domain().represented_start().unwrap(),
                    crate::STRICT_PREDICATES
                )
                .value(),
                Some(Ordering::Equal)
            );
            assert_eq!(
                compare_reals(
                    pcurve.domain().represented_end().unwrap(),
                    fragment.curve().domain().represented_end().unwrap(),
                    crate::STRICT_PREDICATES
                )
                .value(),
                Some(Ordering::Equal)
            );
            let materialized = pcurve.materialize().unwrap();
            let curve_domain = materialized.curve().parameter_domain();
            let curve_parameter = ((curve_domain.start().scalar().unwrap()
                + curve_domain.end().scalar().unwrap())
                / Real::from(2))
            .unwrap();
            let spatial_parameter = materialized
                .spatial_parameter_at(&curve_parameter.clone().into())
                .unwrap()
                .try_real()
                .unwrap()
                .clone();
            let retained_point = pcurve
                .point_at(&Real::clone(&spatial_parameter).into())
                .map(crate::geometry::represented_test_surface_parameter)
                .unwrap();
            let materialized_point = materialized
                .curve()
                .point_at(&curve_parameter.clone().into())
                .unwrap()
                .coordinates()
                .expect("native pcurve coordinates")
                .clone();
            assert_eq!(
                compare_reals(
                    &retained_point.x,
                    materialized_point.x(),
                    crate::STRICT_PREDICATES
                )
                .value(),
                Some(Ordering::Equal)
            );
            assert_eq!(
                compare_reals(
                    &retained_point.y,
                    materialized_point.y(),
                    crate::STRICT_PREDICATES
                )
                .value(),
                Some(Ordering::Equal)
            );
        }
        let parameter = ((fragment.curve().domain().represented_start().unwrap()
            + fragment.curve().domain().represented_end().unwrap())
            / Real::from(2))
        .unwrap();
        let spatial = fragment.curve().evaluate_real(&parameter).unwrap();
        let first = first_surface
            .evaluate_real(
                &fragment
                    .first_pcurve()
                    .point_at(&Real::clone(&parameter).into())
                    .map(crate::geometry::represented_test_surface_parameter)
                    .unwrap(),
            )
            .unwrap();
        let second = second_surface
            .evaluate_real(
                &fragment
                    .second_pcurve()
                    .point_at(&Real::clone(&parameter).into())
                    .map(crate::geometry::represented_test_surface_parameter)
                    .unwrap(),
            )
            .unwrap();
        assert_eq!(
            point3_equal(&spatial, &first, crate::STRICT_PREDICATES).value(),
            Some(true)
        );
        assert_eq!(
            point3_equal(&spatial, &second, crate::STRICT_PREDICATES).value(),
            Some(true)
        );
    }

    fn unit_affine_tensor_cap(nurbs: bool) -> (ArenaModel, SolidId, FaceId) {
        let (source, solid) =
            crate::construction::cuboid(p(0, 0, 0), p(1, 1, 1)).expect("unit cuboid");
        let (face, surface, origin, u, v) = source
            .faces()
            .find_map(|(face_id, face)| {
                let surface = source.surface(face.surface()).expect("validated surface");
                let SurfaceExactData::Plane { origin, u, v } = surface.exact_data() else {
                    return None;
                };
                (compare_reals(&origin.z, &Real::one(), crate::STRICT_PREDICATES).value()
                    == Some(Ordering::Equal))
                .then(|| {
                    (
                        face_id,
                        face.surface(),
                        origin.clone(),
                        u.clone(),
                        v.clone(),
                    )
                })
            })
            .expect("unit cuboid has an upper cap");
        let control_points = vec![
            vec![origin.clone(), origin.clone() + u.clone()],
            vec![origin.clone() + v.clone(), origin + u + v],
        ];
        let weights = vec![vec![Real::one(), Real::one()]; 2];
        let tensor = if nurbs {
            let knots = vec![Real::zero(), Real::zero(), Real::one(), Real::one()];
            Surface::nurbs(1, 1, control_points, weights, knots.clone(), knots)
                .expect("affine NURBS tensor cap")
        } else {
            Surface::rational_bezier(control_points, weights).expect("affine rational tensor cap")
        };
        let mut edit = source.edit();
        edit.replace_surface(surface, tensor)
            .expect("replace cap surface");
        (edit.commit().expect("certified tensor cap"), solid, face)
    }

    #[test]
    fn partial_surface_region_partitions_contained_affine_tensor_from_exact_pcurves() {
        let (tensor, solid, tensor_face) = unit_affine_tensor_cap(false);
