                let SurfaceExactData::Plane { origin, .. } = cutter
                    .surface(face.surface())
                    .expect("validated cutter surface")
                    .exact_data()
                else {
                    return None;
                };
                (compare_reals(&origin.z, &Real::one(), crate::STRICT_PREDICATES).value()
                    == Some(Ordering::Equal))
                .then_some(face_id)
            })
            .expect("cutter has an upper coplanar cap");
        let pair = intersect_faces(&tensor, tensor_face, &cutter, cutter_face)
            .unwrap()
            .expect("partial tensor/cutter caps intersect");
        let graph = ArenaSolidIntersectionGraph {
            first_model: tensor.clone(),
            first_solid: solid,
            second_model: cutter,
            second_solid: cutter_solid,
            candidate_pairs: 1,
            broad_phase_rejections: 0,
            exact_disjoint_pairs: 0,
            exact_intersection_pairs: 1,
            unsupported_pairs: 0,
            trimmed_curve_fragments: 0,
            unresolved_trim_pairs: 0,
            intersections: vec![pair],
        };
        let (partitioned, partitions) = graph.partition_first_faces().unwrap();
        let tensor_partition = partitions
            .iter()
            .find(|partition| partition.source_face == tensor_face)
            .expect("graph partitions the partial contained tensor face");
        assert_eq!(tensor_partition.faces.len(), 2);
        assert_eq!(
            compare_reals(
                &partitioned.solid_volume(solid).unwrap(),
                &Real::one(),
                crate::STRICT_PREDICATES
            )
            .value(),
            Some(Ordering::Equal)
        );
        partitioned
            .clone()
            .edit()
            .commit()
            .expect("graph partition result revalidates");
    }

    fn unit_affine_tensor_cap_with_holes(
        holes: &[Vec<crate::Point2>],
    ) -> (ArenaModel, SolidId, FaceId) {
        let outer = [
            crate::Point2::new(Real::zero(), Real::zero()),
            crate::Point2::new(Real::one(), Real::zero()),
            crate::Point2::new(Real::one(), Real::one()),
            crate::Point2::new(Real::zero(), Real::one()),
        ];
        let (source, solid) =
            crate::construction::extrude_region(&outer, holes, Real::zero(), Real::one()).unwrap();
        let (face, surface, origin, u, v) = source
            .faces()
            .find_map(|(face_id, face)| {
                let surface = source.surface(face.surface()).expect("validated surface");
                let SurfaceExactData::Plane { origin, u, v } = surface.exact_data() else {
                    return None;
                };
                (compare_reals(&origin.z, &Real::one(), crate::STRICT_PREDICATES).value()
                    == Some(Ordering::Equal))
                .then(|| {
                    (
                        face_id,
                        face.surface(),
                        origin.clone(),
                        u.clone(),
                        v.clone(),
                    )
                })
            })
            .expect("unit extrusion has an upper cap");
        let tensor = Surface::rational_bezier(
            vec![
                vec![origin.clone(), origin.clone() + u.clone()],
                vec![origin.clone() + v.clone(), origin + u + v],
            ],
            vec![vec![Real::one(), Real::one()]; 2],
        )
        .expect("affine tensor cap");
        let mut edit = source.edit();
        edit.replace_surface(surface, tensor)
            .expect("replace holed cap surface");
        (
            edit.commit().expect("certified holed tensor cap"),
            solid,
            face,
        )
    }

    fn unit_holed_affine_tensor_cap() -> (ArenaModel, SolidId, FaceId) {
        let quarter = (Real::one() / Real::from(4)).unwrap();
        let three_quarters = (Real::from(3) / Real::from(4)).unwrap();
        let hole = vec![
            crate::Point2::new(quarter.clone(), quarter.clone()),
            crate::Point2::new(three_quarters.clone(), quarter.clone()),
            crate::Point2::new(three_quarters.clone(), three_quarters.clone()),
            crate::Point2::new(quarter, three_quarters),
        ];
        unit_affine_tensor_cap_with_holes(&[hole])
    }

