    #[test]
    fn curved_region_partitions_mobius_reparameterized_affine_tensor_exactly() {
        let (tensor, tensor_face) = crate::construction::rational_bezier_patch(
            vec![vec![p(0, 0, 1), p(1, 0, 1)], vec![p(0, 1, 1), p(1, 1, 1)]],
