            .transformed(&Matrix4::affine_nonuniform_scale([
                Real::one(),
                -Real::one(),
                Real::one(),
            ]))
            .unwrap();
        let reflected_volume = standard_solids
            .iter()
            .map(|solid| reflected.solid_volume(*solid).unwrap())
