            assert_eq!(solids.len(), 1);
            assert_eq!(
                compare_reals(
                    &model.solid_volume(solids[0]).unwrap(),
                    &expected_volume,
                    crate::STRICT_PREDICATES
                )
                .value(),
                Some(Ordering::Equal)
            );
            crate::ImportedModel::from_json(
                &model.to_json().unwrap(),
                &crate::ArchiveLimits::default(),
            )
            .unwrap()
            .validate()
            .unwrap();
        }

        let (disjoint, disjoint_solid) =
            crate::construction::cuboid(p(4, 0, 0), p(6, 2, 2)).unwrap();
        let disjoint_graph =
            intersection_graph(&first, first_solid, &disjoint, disjoint_solid).unwrap();
        assert!(matches!(
            disjoint_graph
                .stitch_selected_faces(BooleanOperation::Intersection)
                .unwrap(),
            ArenaBooleanResult::Empty
        ));
        let ArenaBooleanResult::Solids { model, solids } = disjoint_graph
            .stitch_selected_faces(BooleanOperation::Union)
            .unwrap()
        else {
            panic!("disjoint union must retain two connected solids");
        };
        assert_eq!(solids.len(), 2);
        assert_eq!(
            compare_reals(
                &(model.solid_volume(solids[0]).unwrap() + model.solid_volume(solids[1]).unwrap()),
                &Real::from(16),
                crate::STRICT_PREDICATES
            )
            .value(),
            Some(Ordering::Equal)
        );

        let identical_graph = intersection_graph(&first, first_solid, &first, first_solid).unwrap();
        assert!(matches!(
            identical_graph
                .stitch_selected_faces(BooleanOperation::Difference)
                .unwrap(),
            ArenaBooleanResult::Empty
        ));
    }

