//! Exact model measure operations.

use crate::topology::*;

impl ArenaModel {
    /// Returns the exact area of a supported validated face.
    ///
    /// Whole spheres and periodic latitude caps use analytic spherical area.
    /// Other active carriers integrate their exact parameter-space boundary
    /// and Jacobian without tessellation.
    pub fn face_area(&self, id: FaceId) -> Result<Real, QueryError> {
        crate::context::strict(|| {
            let face = self.face(id).ok_or(QueryError::InvalidReference {
                kind: EntityKind::Face,
                index: id.index(),
            })?;
            let surface = self
                .surface(face.surface)
                .expect("validated face surface ID");
            if let SurfaceExactData::Sphere { radius, .. } = surface.exact_data() {
                if face.is_whole_surface() {
                    return Ok(Real::from(4) * Real::pi() * &radius * radius);
                }
                let outer = face.outer().ok_or(GeometryError::UnsupportedMeasurement)?;
                if let [upper_wire] = face.inner() {
                    let lower = self
                        .pcurve(
                            self.edge_use(self.wire(outer).expect("validated wire").edge_uses[0])
                                .expect("validated use")
                                .pcurve,
                        )
                        .expect("validated pcurve")
                        .line_segment()
                        .ok_or(GeometryError::UnsupportedPcurveContour)?
                        .start()
                        .y()
                        .clone();
                    let upper = self
                        .pcurve(
                            self.edge_use(
                                self.wire(*upper_wire).expect("validated wire").edge_uses[0],
                            )
                            .expect("validated use")
                            .pcurve,
                        )
                        .expect("validated pcurve")
                        .line_segment()
                        .ok_or(GeometryError::UnsupportedPcurveContour)?
                        .start()
                        .y()
                        .clone();
                    return Ok(Real::tau() * &radius * radius * (upper.sin() - lower.sin()));
                }
                let wire = self.wire(outer).expect("validated spherical face wire");
                let mut latitude_cap = true;
                for edge_use in &wire.edge_uses {
                    let edge_use = self.edge_use(*edge_use).expect("validated spherical use");
                    let line = self
                        .pcurve(edge_use.pcurve)
                        .expect("validated spherical pcurve")
                        .line_segment()
                        .ok_or(GeometryError::UnsupportedPcurveContour)?;
                    if !real_values_equal(line.start().y(), line.end().y())
                        .map_err(build_error_geometry)?
                    {
                        latitude_cap = false;
                        break;
                    }
                }
                if !latitude_cap {
                    return Ok(self.signed_sphere_wire_area(outer, &radius)?.abs());
                }
                let first_use = self
                    .edge_use(wire.edge_uses[0])
                    .expect("validated spherical edge use");
                let pcurve = self
                    .pcurve(first_use.pcurve)
                    .expect("validated spherical pcurve");
                let line = pcurve
                    .line_segment()
                    .ok_or(GeometryError::UnsupportedMeasurement)?;
                let increasing = decided_model_order(compare_reals(
                    line.end().x(),
                    line.start().x(),
                    crate::STRICT_PREDICATES,
                ))? == std::cmp::Ordering::Greater;
                let upper = match face.orientation {
                    Orientation::Forward => increasing,
                    Orientation::Reversed => !increasing,
                };
                let sine = line.start().y().clone().sin();
                let height_factor = if upper {
                    Real::one() - sine
                } else {
                    Real::one() + sine
                };
                return Ok(Real::from(2) * Real::pi() * &radius * radius * height_factor);
            }
            let outer = face.outer().ok_or(GeometryError::UnsupportedMeasurement)?;
            if let SurfaceExactData::Torus {
                major_radius,
                minor_radius,
                ..
            } = surface.exact_data()
            {
                let magnitude = |wire| -> Result<Real, GeometryError> {
                    let signed = self.signed_torus_wire_area(wire, &major_radius, &minor_radius)?;
                    Ok(area_magnitude(signed))
                };
                let mut area = magnitude(outer)?;
                for inner in face.inner() {
                    area -= magnitude(*inner)?;
                }
                return Ok(area);
            }
            if let SurfaceExactData::Cone { semi_angle, .. } = surface.exact_data() {
                let mut area = area_magnitude(self.signed_cone_wire_area(outer, &semi_angle)?);
                for inner in face.inner() {
                    area -= area_magnitude(self.signed_cone_wire_area(*inner, &semi_angle)?);
                }
                return Ok(area);
            }
            if let SurfaceExactData::Revolution {
                profile,
                axis_origin,
                axis,
            } = surface.exact_data()
            {
                if !face.inner().is_empty() {
                    return Err(GeometryError::UnsupportedMeasurement.into());
                }
                let profile = Curve3::from_exact_data(*profile)?;
                let wire = self.wire(outer).expect("validated revolution face wire");
                if wire.edge_uses.len() != 4 {
                    return Err(GeometryError::UnsupportedMeasurement.into());
                }
                let mut u_values = Vec::with_capacity(2);
                let mut v_values = Vec::with_capacity(2);
                for use_id in &wire.edge_uses {
                    let pcurve = self
                        .pcurve(
                            self.edge_use(*use_id)
                                .expect("validated revolution edge use")
                                .pcurve,
                        )
                        .expect("validated revolution pcurve");
                    let segment = pcurve
                        .line_segment()
                        .ok_or(GeometryError::UnsupportedMeasurement)?;
                    if !real_values_equal(segment.start().x(), segment.end().x())
                        .map_err(build_error_geometry)?
                        && !real_values_equal(segment.start().y(), segment.end().y())
                            .map_err(build_error_geometry)?
                    {
                        return Err(GeometryError::UnsupportedMeasurement.into());
                    }
                    insert_sorted_real(&mut u_values, segment.start().x())
                        .map_err(build_error_geometry)?;
                    insert_sorted_real(&mut u_values, segment.end().x())
                        .map_err(build_error_geometry)?;
                    insert_sorted_real(&mut v_values, segment.start().y())
                        .map_err(build_error_geometry)?;
                    insert_sorted_real(&mut v_values, segment.end().y())
                        .map_err(build_error_geometry)?;
                }
                if u_values.len() != 2 || v_values.len() != 2 {
                    return Err(GeometryError::UnsupportedMeasurement.into());
                }
                let profile = profile.subcurve(&v_values[0], &v_values[1])?;
                let radial_at = |point: &Point3| {
                    let relative = point - &axis_origin;
                    let axial = axis.dot(&relative);
                    relative - axis.clone() * axial
                };
                let angular_span = &u_values[1] - &u_values[0];
                let line_image_area = || -> Result<Real, QueryError> {
                    let start = profile.evaluate_real(profile.domain().represented_start()?)?;
                    let end = profile.evaluate_real(profile.domain().represented_end()?)?;
                    let start_radial = radial_at(&start);
                    let end_radial = radial_at(&end);
                    if decided_model_order(compare_reals(
                        &start_radial.cross(&end_radial).norm_squared(),
                        &Real::zero(),
                        crate::STRICT_PREDICATES,
                    ))? != std::cmp::Ordering::Equal
                        || decided_model_order(compare_reals(
                            &start_radial.dot(&end_radial),
                            &Real::zero(),
                            crate::STRICT_PREDICATES,
                        ))? != std::cmp::Ordering::Greater
                    {
                        return Err(GeometryError::UnsupportedMeasurement.into());
                    }
                    let start_radius = start_radial
                        .norm_squared()
                        .sqrt()
                        .map_err(GeometryError::Numeric)?;
                    let end_radius = end_radial
                        .norm_squared()
                        .sqrt()
                        .map_err(GeometryError::Numeric)?;
                    let profile_length = (&end - &start)
                        .norm_squared()
                        .sqrt()
                        .map_err(GeometryError::Numeric)?;
                    (angular_span.clone() * profile_length * (start_radius + end_radius)
                        / Real::from(2))
                    .map_err(GeometryError::Numeric)
                    .map_err(QueryError::from)
                };
                return match profile.exact_data() {
                    Curve3ExactData::Line(_) => line_image_area(),
                    Curve3ExactData::RationalBezier { .. } | Curve3ExactData::Nurbs { .. }
                        if certified_monotone_line_curve_image(&profile)
                            .map_err(build_error_geometry)? =>
                    {
                        line_image_area()
                    }
                    Curve3ExactData::EllipseArc(data) if data.circle => {
                        let start_point =
                            profile.evaluate_real(profile.domain().represented_start()?)?;
                        let start_radial = radial_at(&start_point);
                        let start_radius = start_radial
                            .norm_squared()
                            .sqrt()
                            .map_err(GeometryError::Numeric)?;
                        let radial_unit =
                            (start_radial / &start_radius).map_err(GeometryError::Numeric)?;
                        let center_radial = radial_unit.dot(&radial_at(&data.center));
                        let x_radial = radial_unit.dot(&data.x);
                        let y_radial = radial_unit.dot(&data.y);
                        let start_angle = &data.angle_at_start
                            + Real::from(data.direction)
                                * (profile.domain().represented_start()? - &data.domain_start);
                        let end_angle = &data.angle_at_start
                            + Real::from(data.direction)
                                * (profile.domain().represented_end()? - &data.domain_start);
                        let direction = Real::from(data.direction);
                        let integral_cos =
                            &direction * (end_angle.clone().sin() - start_angle.clone().sin());
                        let integral_sin =
                            direction * (start_angle.clone().cos() - end_angle.clone().cos());
                        let parameter_span = profile.domain().represented_end()?
                            - profile.domain().represented_start()?;
                        let radial_integral = center_radial * parameter_span
                            + &data.x_radius * (x_radial * integral_cos + y_radial * integral_sin);
                        Ok(angular_span * data.x_radius * radial_integral)
                    }
                    _ => Err(GeometryError::UnsupportedMeasurement.into()),
                };
            }
            if let SurfaceExactData::Plane { origin, u, v } = surface.exact_data()
                && let Some(area) = self.analytic_planar_face_area(face, &origin, &u, &v)?
            {
                return Ok(area);
            }
            let mut parameter_area = area_magnitude(self.signed_model_wire_double_area(outer)?);
            for inner in face.inner() {
                parameter_area -= area_magnitude(self.signed_model_wire_double_area(*inner)?);
            }
            let surface_scale = match surface.exact_data() {
                SurfaceExactData::Plane { u, v, .. } => u
                    .cross(&v)
                    .norm_squared()
                    .sqrt()
                    .map_err(GeometryError::Numeric)?,
                SurfaceExactData::Cylinder { radius, .. } => radius,
                SurfaceExactData::Extrusion { profile, direction } => {
                    let profile = Curve3::from_exact_data(*profile)?;
                    return self.extrusion_face_area(
                        face,
                        outer,
                        &profile,
                        &direction,
                        &parameter_area,
                    );
                }
                data @ (SurfaceExactData::RationalBezier { .. }
                | SurfaceExactData::Nurbs { .. }) => {
                    return affine_tensor_face_area(&data, &parameter_area)
                        .map_err(build_error_geometry)?
                        .ok_or(GeometryError::UnsupportedMeasurement)
                        .map_err(QueryError::from);
                }
                _ => return Err(GeometryError::UnsupportedMeasurement.into()),
            };
            let double_area = parameter_area * surface_scale;
            (double_area / Real::from(2))
                .map_err(GeometryError::Numeric)
                .map_err(QueryError::from)
        })
    }

    pub(in crate::topology) fn extrusion_face_area(
        &self,
        face: &Face,
        outer: WireId,
        profile: &Curve3,
        direction: &Vector3,
        parameter_double_area: &Real,
    ) -> Result<Real, QueryError> {
        if let Some(scale) =
            extrusion_constant_area_scale(profile, direction).map_err(build_error_geometry)?
        {
            return (parameter_double_area * scale / Real::from(2))
                .map_err(GeometryError::Numeric)
                .map_err(QueryError::from);
        }
        if !face.inner().is_empty()
            || !(certified_monotone_line_curve_image(profile).map_err(build_error_geometry)?
                || certified_monotone_planar_extrusion_image(profile, direction)
                    .map_err(build_error_geometry)?)
        {
            return Err(GeometryError::UnsupportedMeasurement.into());
        }
        let Some((u_min, u_max, v_min, v_max)) = self.axis_aligned_parameter_rectangle(outer)?
        else {
            return Err(GeometryError::UnsupportedMeasurement.into());
        };
        let rectangle_double_area = Real::from(2) * (&u_max - &u_min) * (&v_max - &v_min);
        if !real_values_equal(parameter_double_area, &rectangle_double_area)
            .map_err(build_error_geometry)?
            || !profile.domain().contains_real(&u_min)?
            || !profile.domain().contains_real(&u_max)?
        {
            return Err(GeometryError::UnsupportedMeasurement.into());
        }
        let restricted = profile.subcurve(&u_min, &u_max)?;
        let start = restricted.evaluate_real(restricted.domain().represented_start()?)?;
        let end = restricted.evaluate_real(restricted.domain().represented_end()?)?;
        let swept_area = (&end - &start)
            .cross(direction)
            .norm_squared()
            .sqrt()
            .map_err(GeometryError::Numeric)?
            * (v_max - v_min);
        Ok(swept_area)
    }

    pub(in crate::topology) fn axis_aligned_parameter_rectangle(
        &self,
        wire: WireId,
    ) -> Result<Option<(Real, Real, Real, Real)>, GeometryError> {
        let wire = self.wire(wire).expect("validated wire ID");
        if wire.edge_uses.len() != 4 {
            return Ok(None);
        }
        let mut u_values = Vec::with_capacity(2);
        let mut v_values = Vec::with_capacity(2);
        for edge_use in &wire.edge_uses {
            let edge_use = self.edge_use(*edge_use).expect("validated edge-use ID");
            let pcurve = self.pcurve(edge_use.pcurve).expect("validated pcurve ID");
            let Some(line) = pcurve.line_segment() else {
                return Ok(None);
            };
            let constant_u = real_values_equal(line.start().x(), line.end().x())
                .map_err(build_error_geometry)?;
            let constant_v = real_values_equal(line.start().y(), line.end().y())
                .map_err(build_error_geometry)?;
            if constant_u == constant_v {
                return Ok(None);
            }
            insert_sorted_real(&mut u_values, line.start().x()).map_err(build_error_geometry)?;
            insert_sorted_real(&mut u_values, line.end().x()).map_err(build_error_geometry)?;
            insert_sorted_real(&mut v_values, line.start().y()).map_err(build_error_geometry)?;
            insert_sorted_real(&mut v_values, line.end().y()).map_err(build_error_geometry)?;
        }
        if u_values.len() != 2 || v_values.len() != 2 {
            return Ok(None);
        }
        Ok(Some((
            u_values.remove(0),
            u_values.remove(0),
            v_values.remove(0),
            v_values.remove(0),
        )))
    }

    fn analytic_planar_face_area(
        &self,
        face: &Face,
        origin: &Point3,
        u: &Vector3,
        v: &Vector3,
    ) -> Result<Option<Real>, GeometryError> {
        let wires = || face.outer().into_iter().chain(face.inner().iter().copied());
        let mut has_arc = false;
        for wire in wires() {
            for use_id in &self.wire(wire).expect("validated wire").edge_uses {
                let edge_use = self.edge_use(*use_id).expect("validated use");
                let edge = self.edge(edge_use.edge).expect("validated edge");
                if edge.domain.start().try_real().is_none()
                    || edge.domain.end().try_real().is_none()
                {
                    return Ok(None);
                }
                match self.curve(edge.curve).expect("validated curve").kind() {
                    Curve3Kind::Line => {}
                    Curve3Kind::CircleArc | Curve3Kind::EllipseArc => has_arc = true,
                    _ => return Ok(None),
                }
            }
        }
        // Pure polygons keep the existing native exact product-sum path.
        if !has_arc {
            return Ok(None);
        }
        let normal = u.cross(v).normalize().map_err(GeometryError::Numeric)?;
        let mut area = Real::zero();
        for (index, wire) in wires().enumerate() {
            let edge_uses = &self.wire(wire).expect("validated wire").edge_uses;
            // A closed line integral is translation invariant. Centering it
            // on a retained conic avoids introducing large translated endpoint
            // terms that must cancel again after subdivision and replay.
            let origin = edge_uses
                .iter()
                .find_map(|use_id| {
                    let edge_use = self.edge_use(*use_id).expect("validated use");
                    let edge = self.edge(edge_use.edge).expect("validated edge");
                    self.curve(edge.curve)
                        .expect("validated curve")
                        .analytic_area_origin()
                })
                .unwrap_or(origin);
            let mut doubled = Real::zero();
            for use_id in edge_uses {
                let edge_use = self.edge_use(*use_id).expect("validated use");
                let edge = self.edge(edge_use.edge).expect("validated edge");
                let contribution = self
                    .curve(edge.curve)
                    .expect("validated curve")
                    .analytic_area_vector(
                        edge.domain.represented_start()?,
                        edge.domain.represented_end()?,
                        origin,
                    )?
                    .ok_or(GeometryError::UnsupportedMeasurement)?
                    .dot(&normal);
                match edge_use.direction {
                    Direction::Forward => doubled += contribution,
                    Direction::Reversed => doubled -= contribution,
                }
            }
            let magnitude = area_magnitude(doubled);
            if index == 0 {
                area += magnitude;
            } else {
                area -= magnitude;
            }
        }
        Ok(Some(
            (area / Real::from(2)).map_err(GeometryError::Numeric)?,
        ))
    }

    pub(in crate::topology) fn signed_model_wire_double_area(
        &self,
        wire: WireId,
    ) -> Result<Real, GeometryError> {
        match self.signed_wire_double_area(wire) {
            Ok(area) => Ok(area),
            Err(GeometryError::UnsupportedPcurveContour) => {
                let area = crate::error::classified(
                    self.build_model_wire_curve_path(wire)?
                        .boundary_loop()
                        .map_err(GeometryError::from)?
                        .signed_area(),
                )
                .map_err(GeometryError::from)?;
                let area = resolve_planar_classification(area)?
                    .ok_or(GeometryError::UnsupportedMeasurement)?;
                Ok(Real::from(2) * area)
            }
            Err(error) => Err(error),
        }
    }

    /// Returns the exact volume of a validated solid.
    pub fn solid_volume(&self, id: SolidId) -> Result<Real, QueryError> {
        crate::context::strict(|| {
            let solid = self.solid(id).ok_or(QueryError::InvalidReference {
                kind: EntityKind::Solid,
                index: id.index(),
            })?;
            if let Some(cylinder) = &self.data.certified_cylinders[id.index()] {
                let volume = Real::pi()
                    * &cylinder.radius
                    * &cylinder.radius
                    * (&cylinder.v_max - &cylinder.v_min);
                let Some(subtraction) = &cylinder.sphere_subtraction else {
                    return Ok(volume);
                };
                let excluded = match subtraction {
                    CertifiedCylinderSphereSubtraction::Void { radius, .. } => {
                        sphere_volume(radius)?
                    }
                    CertifiedCylinderSphereSubtraction::Component {
                        center,
                        radius,
                        side,
                    } => {
                        let center_parameter = (center - &cylinder.origin).dot(&cylinder.axis);
                        let antiderivative = |height: &Real| -> Result<Real, GeometryError> {
                            let cubic = (height * height * height / Real::from(3))
                                .map_err(GeometryError::Numeric)?;
                            Ok(Real::pi() * (radius * radius * height - cubic))
                        };
                        match side {
                            CertifiedCylinderSphereComponentSide::Lower => {
                                let upper = &cylinder.v_max - &center_parameter;
                                antiderivative(&upper)? - antiderivative(&-radius.clone())?
                            }
                            CertifiedCylinderSphereComponentSide::Upper => {
                                let lower = &cylinder.v_min - &center_parameter;
                                antiderivative(radius)? - antiderivative(&lower)?
                            }
                        }
                    }
                };
                return Ok(volume - excluded);
            }
            if let Some(sphere) = &self.data.certified_spheres[id.index()] {
                if let CertifiedSphereRegion::Axial(clip) = &sphere.region {
                    let antiderivative = |height: &Real| -> Result<Real, GeometryError> {
                        let cubic = (height * height * height / Real::from(3))
                            .map_err(GeometryError::Numeric)?;
                        Ok(Real::pi() * (&sphere.radius * &sphere.radius * height - cubic))
                    };
                    return Ok(antiderivative(&clip.max)? - antiderivative(&clip.min)?);
                }
                if let CertifiedSphereRegion::Radial(clip) = &sphere.region {
                    let axial_half_height = (&sphere.radius * &sphere.radius
                        - &clip.radius * &clip.radius)
                        .sqrt()
                        .map_err(GeometryError::Numeric)?;
                    let axial_cubic = &axial_half_height * &axial_half_height * axial_half_height;
                    let retained_cubic = match clip.side {
                        CertifiedSphereRadialSide::Inside => {
                            &sphere.radius * &sphere.radius * &sphere.radius - axial_cubic
                        }
                        CertifiedSphereRadialSide::Outside => axial_cubic,
                    };
                    return (Real::from(4) * Real::pi() * retained_cubic / Real::from(3))
                        .map_err(GeometryError::Numeric)
                        .map_err(QueryError::from);
                }
                if let CertifiedSphereRegion::FiniteCylinder(region) = &sphere.region {
                    let cylinder_volume = Real::pi()
                        * &region.radius
                        * &region.radius
                        * (&region.v_max - &region.v_min);
                    let sphere_volume = sphere_volume(&sphere.radius)?;
                    let overlap = sphere_finite_cylinder_overlap_volume(sphere, region)?;
                    return Ok(match region.operation {
                        CertifiedSphereFiniteCylinderOperation::Union => {
                            sphere_volume + cylinder_volume - overlap
                        }
                        CertifiedSphereFiniteCylinderOperation::Intersection => overlap,
                        CertifiedSphereFiniteCylinderOperation::Difference => {
                            sphere_volume - overlap
                        }
                    });
                }
                let mut volume = sphere_volume(&sphere.radius)?;
                for void in &sphere.voids {
                    volume -= match void {
                        CertifiedSphereVoid::Sphere { radius, .. } => sphere_volume(radius)?,
                        CertifiedSphereVoid::Cylinder(cylinder) => {
                            Real::pi()
                                * &cylinder.radius
                                * &cylinder.radius
                                * (&cylinder.v_max - &cylinder.v_min)
                        }
                    };
                }
                return Ok(volume);
            }
            if let Some(pair) = &self.data.certified_sphere_pairs[id.index()] {
                let first_volume = sphere_volume(&pair.first_radius)?;
                let second_volume = sphere_volume(&pair.second_radius)?;
                let overlap = sphere_pair_intersection_volume(pair)?;
                return Ok(match pair.kind {
                    CertifiedSpherePairKind::Union => first_volume + second_volume - overlap,
                    CertifiedSpherePairKind::Intersection => overlap,
                    CertifiedSpherePairKind::Difference => first_volume - overlap,
                });
            }
            if let Some(torus) = &self.data.certified_tori[id.index()] {
                return match &torus.region {
                    CertifiedTorusRegion::Whole => Ok(Real::from(2)
                        * Real::pi()
                        * Real::pi()
                        * &torus.major_radius
                        * &torus.minor_radius
                        * &torus.minor_radius),
                    CertifiedTorusRegion::Axial { min, max }
                    | CertifiedTorusRegion::SectorBand { min, max, .. } => {
                        let antiderivative = |height: &Real| -> Result<Real, GeometryError> {
                            // Normalize before taking the square root. The
                            // dimensionless disk segment is invariant under a
                            // similarity, avoiding newly mixed radicals in a
                            // scaled body's exact volume certificate.
                            let normalized =
                                (height / &torus.minor_radius).map_err(GeometryError::Numeric)?;
                            let normalized =
                                normalized.compact_quadratic_tower().unwrap_or(normalized);
                            let radial = (Real::one() - &normalized * &normalized)
                                .sqrt()
                                .map_err(GeometryError::Numeric)?;
                            let angle =
                                normalized.clone().asin().map_err(GeometryError::Numeric)?;
                            Ok(Real::from(2)
                                * Real::pi()
                                * &torus.major_radius
                                * &torus.minor_radius
                                * &torus.minor_radius
                                * (normalized * radial + angle))
                        };
                        let volume = antiderivative(max)? - antiderivative(min)?;
                        if let CertifiedTorusRegion::SectorBand { angular, .. } = &torus.region {
                            (volume * &angular.sweep / Real::tau())
                                .map_err(GeometryError::Numeric)
                                .map_err(QueryError::from)
                        } else {
                            Ok(volume)
                        }
                    }
                    CertifiedTorusRegion::LongitudinalHalf { .. } => Ok(Real::pi()
                        * Real::pi()
                        * &torus.major_radius
                        * &torus.minor_radius
                        * &torus.minor_radius),
                };
            }
            if let Some(frustum) = &self.data.certified_cone_frustums[id.index()] {
                let sine = frustum.semi_angle.clone().sin();
                let cosine = frustum.semi_angle.clone().cos();
                let min_radius = &frustum.v_min * &sine;
                let max_radius = &frustum.v_max * sine;
                let height = (&frustum.v_max - &frustum.v_min) * cosine;
                let volume = (Real::pi()
                    * height
                    * (&min_radius * &min_radius
                        + &min_radius * &max_radius
                        + &max_radius * &max_radius)
                    / Real::from(3))
                .map_err(GeometryError::Numeric)
                .map_err(QueryError::from)?;
                return match &frustum.region {
                    CertifiedConeFrustumRegion::Whole => Ok(volume),
                    CertifiedConeFrustumRegion::LongitudinalHalf { .. } => (volume / Real::from(2))
                        .map_err(GeometryError::Numeric)
                        .map_err(QueryError::from),
                    CertifiedConeFrustumRegion::Sector(angular) => (volume * &angular.sweep
                        / Real::tau())
                    .map_err(GeometryError::Numeric)
                    .map_err(QueryError::from),
                };
            }
            if let Some(revolution) = &self.data.certified_revolutions[id.index()] {
                let mut first_moment = revolution
                    .profile
                    .signed_x_first_moment()?
                    .ok_or(GeometryError::UnsupportedMeasurement)?;
                for void in &revolution.voids {
                    first_moment -= void
                        .signed_x_first_moment()?
                        .ok_or(GeometryError::UnsupportedMeasurement)?;
                }
                return Ok(Real::from(2) * Real::pi() * first_moment);
            }
            if let Some(loft) = &self.data.certified_lofts[id.index()] {
                let jacobian = loft.u.dot(&loft.v.cross(&loft.height_axis)).abs();
                return Ok(jacobian * &loft.parameter_volume);
            }
            if let Some(sweep) = &self.data.certified_curve_sweeps[id.index()] {
                let mut area = sweep
                    .profile
                    .signed_area()
                    .map_err(GeometryError::from)?
                    .ok_or(GeometryError::UnsupportedMeasurement)?
                    .abs();
                for hole in &sweep.holes {
                    area -= hole
                        .signed_area()
                        .map_err(GeometryError::from)?
                        .ok_or(GeometryError::UnsupportedMeasurement)?
                        .abs();
                }
                let path_start = sweep
                    .path
                    .evaluate_real(sweep.path.domain().represented_start()?)?;
                let path_end = sweep
                    .path
                    .evaluate_real(sweep.path.domain().represented_end()?)?;
                let u = Vector3::from(
                    sweep
                        .u_path
                        .evaluate_real(sweep.u_path.domain().represented_start()?)?,
                );
                let v = Vector3::from(
                    sweep
                        .v_path
                        .evaluate_real(sweep.v_path.domain().represented_start()?)?,
                );
                let progress = u.cross(&v).dot(&(path_end - path_start)).abs();
                return Ok(area * progress * &sweep.area_scale_integral);
            }
            if let Some(prism) = &self.data.certified_prisms[id.index()] {
                let area = match &prism.profile {
                    CertifiedPrismProfile::Paths { area, .. }
                    | CertifiedPrismProfile::CurveRegion { area, .. } => {
                        area.clone().ok_or(GeometryError::UnsupportedMeasurement)?
                    }
                };
                let jacobian = prism.u.dot(&prism.v.cross(&prism.extrusion)).abs();
                return Ok(area * jacobian * (&prism.parameter_max - &prism.parameter_min));
            }
            if let Some(axial) = &self.data.certified_axial_shells[id.index()] {
                let mut volume = Real::zero();
                for (band, heights) in axial.bands.iter().zip(axial.heights.windows(2)) {
                    volume += &band.area * (&heights[1] - &heights[0]);
                }
                return Ok(volume * axial.u.dot(&axial.v.cross(&axial.axis)).abs());
            }
            let signed_six_volume = std::iter::once(&solid.outer)
                .chain(solid.voids.iter())
                .map(|shell| self.signed_shell_six_volume(*shell))
                .try_fold(Real::zero(), |sum, volume| {
                    volume.map(|volume| sum + volume)
                })?;
            (signed_six_volume / Real::from(6))
                .map_err(GeometryError::Numeric)
                .map_err(QueryError::from)
        })
    }

    pub(in crate::topology) fn signed_wire_double_area(
        &self,
        wire: WireId,
    ) -> Result<Real, GeometryError> {
        self.build_model_wire_contour(wire)?
            .signed_area()
            .map_err(GeometryError::from)?
            .map(|area| Real::from(2) * area)
            .ok_or(GeometryError::UnsupportedMeasurement)
    }

    pub(in crate::topology) fn signed_torus_wire_area(
        &self,
        wire: WireId,
        major_radius: &Real,
        minor_radius: &Real,
    ) -> Result<Real, GeometryError> {
        let wire = self.wire(wire).expect("validated wire ID");
        let mut area = Real::zero();
        for edge_use_id in &wire.edge_uses {
            let edge_use = self.edge_use(*edge_use_id).expect("validated edge-use ID");
            let pcurve = self.pcurve(edge_use.pcurve).expect("validated pcurve ID");
            let line = pcurve
                .line_segment()
                .ok_or(GeometryError::UnsupportedMeasurement)?;
            let u_constant = real_values_equal(line.start().x(), line.end().x())
                .map_err(build_error_geometry)?;
            let v_constant = real_values_equal(line.start().y(), line.end().y())
                .map_err(build_error_geometry)?;
            if u_constant == v_constant {
                return Err(GeometryError::UnsupportedMeasurement);
            }
            if u_constant {
                let delta_v = line.end().y() - line.start().y();
                let delta_sin = line.end().y().clone().sin() - line.start().y().clone().sin();
                area += line.start().x().clone()
                    * minor_radius
                    * (major_radius * delta_v + minor_radius * delta_sin);
            }
        }
        Ok(area)
    }

    pub(in crate::topology) fn signed_sphere_wire_area(
        &self,
        wire: WireId,
        radius: &Real,
    ) -> Result<Real, GeometryError> {
        let wire = self.wire(wire).expect("validated wire ID");
        let mut area = Real::zero();
        for edge_use_id in &wire.edge_uses {
            let edge_use = self.edge_use(*edge_use_id).expect("validated edge-use ID");
            let line = self
                .pcurve(edge_use.pcurve)
                .expect("validated pcurve ID")
                .line_segment()
                .ok_or(GeometryError::UnsupportedMeasurement)?;
            if real_values_equal(line.start().y(), line.end().y()).map_err(build_error_geometry)? {
                area += radius
                    * radius
                    * line.start().y().clone().sin()
                    * (line.end().x() - line.start().x());
            } else if !real_values_equal(line.start().x(), line.end().x())
                .map_err(build_error_geometry)?
            {
                return Err(GeometryError::UnsupportedMeasurement);
            }
        }
        Ok(area)
    }

    pub(in crate::topology) fn signed_cone_wire_area(
        &self,
        wire: WireId,
        semi_angle: &Real,
    ) -> Result<Real, GeometryError> {
        let wire = self.wire(wire).expect("validated wire ID");
        let mut doubled_area = Real::zero();
        for edge_use_id in &wire.edge_uses {
            let edge_use = self.edge_use(*edge_use_id).expect("validated edge-use ID");
            let pcurve = self.pcurve(edge_use.pcurve).expect("validated pcurve ID");
            let line = pcurve
                .line_segment()
                .ok_or(GeometryError::UnsupportedMeasurement)?;
            let u_constant = real_values_equal(line.start().x(), line.end().x())
                .map_err(build_error_geometry)?;
            let v_constant = real_values_equal(line.start().y(), line.end().y())
                .map_err(build_error_geometry)?;
            if u_constant == v_constant {
                return Err(GeometryError::UnsupportedMeasurement);
            }
            if u_constant {
                doubled_area += line.start().x().clone()
                    * semi_angle.clone().sin()
                    * (line.end().y() * line.end().y() - line.start().y() * line.start().y());
            }
        }
        (doubled_area / Real::from(2)).map_err(GeometryError::Numeric)
    }

    pub(in crate::topology) fn signed_shell_six_volume(
        &self,
        shell: ShellId,
    ) -> Result<Real, GeometryError> {
        let mut sum = Real::zero();
        for face_id in &self.shell(shell).expect("validated shell ID").faces {
            let face = self.face(*face_id).expect("validated face ID");
            for wire_id in face.boundary_wires() {
                let wire = self.wire(*wire_id).expect("validated wire ID");
                let points = wire.edge_uses.iter().map(|edge_use| {
                    let start = self.directed_vertices(*edge_use).0;
                    Ok::<_, GeometryError>(self.vertex(start).expect("validated vertex ID").point())
                });
                sum += match wire_geometry::scalar_fan_six_volume(points)? {
                    Some(volume) => volume,
                    None => wire_geometry::planar_wire_six_volume(
                        self.surface(face.surface).expect("validated surface ID"),
                        &self.build_model_wire_curve_path(*wire_id)?,
                    )?,
                };
            }
        }
        Ok(sum)
    }
}

/// Consume a strict sign before introducing sqrt(area^2), which can obscure
/// cancellation between small analytic patches. Compact only through the
/// native scalar recognizer. An unavailable proof preserves the original
/// exact absolute value; it never selects an orientation by approximation.
fn area_magnitude(signed: Real) -> Real {
    let signed = signed.compact_pi_laurent().unwrap_or(signed);
    match compare_reals(&signed, &Real::zero(), crate::STRICT_PREDICATES) {
        PredicateOutcome::Decided {
            value: std::cmp::Ordering::Less,
            ..
        } => -signed,
        PredicateOutcome::Decided {
            value: std::cmp::Ordering::Equal,
            ..
        } => Real::zero(),
        PredicateOutcome::Decided {
            value: std::cmp::Ordering::Greater,
            ..
        } => signed,
        PredicateOutcome::Unknown { .. } => signed.abs(),
    }
}

crates/hyperbrep/src/topology/wire_geome:
//! Shared exact boundary-image proofs for validation and queries.

use crate::topology::*;

/// A derived contour may reuse an exact endpoint-segment image without
/// replacing its authored edge/pcurve chart. The fit proves the complete
/// image lies on the segment, not merely endpoint coincidence. Any internal
/// retracing cancels in this oriented line chain; the original parameter
/// correspondence and topology remain on the immutable model.
pub(super) fn segment_image(curve: &Curve2) -> Result<Segment2, GeometryError> {
    let relation = match curve.geometry() {
        Some(CurveGeometry2::Line(line)) => return Ok(Segment2::Line(line.clone())),
        Some(CurveGeometry2::CircularArc(arc)) => return Ok(Segment2::Arc(arc.clone())),
        Some(CurveGeometry2::QuadraticBezier(source)) => source.fit_exact_line_image(),
        Some(CurveGeometry2::CubicBezier(source)) => source.fit_exact_line_image(),
        Some(CurveGeometry2::RationalQuadraticBezier(source)) => source.fit_exact_line_image(),
        Some(CurveGeometry2::RationalBezier(source)) => source.fit_exact_line_image(),
        _ => return Err(GeometryError::UnsupportedPcurveContour),
    };
    match crate::error::classified(relation)? {
        Classification::Decided(hypercurve::BezierLineImageFitRelation::Fit(fit)) => {
            Ok(Segment2::Line(fit.line().clone()))
        }
        _ => Err(GeometryError::UnsupportedPcurveContour),
    }
}

/// Scalar fast path for the signed triangle fan. `None` asks the caller to
/// integrate the retained boundary; it never substitutes selected coordinates.
pub(super) fn scalar_fan_six_volume<'a, E>(
    mut points: impl Iterator<Item = Result<&'a GeometricPoint3, E>>,
) -> Result<Option<Real>, E> {
    let Some(anchor) = points.next().transpose()? else {
        return Ok(Some(Real::zero()));
    };
    let Some(anchor) = anchor.try_coordinates() else {
        return Ok(None);
    };
    let Some(first) = points.next().transpose()? else {
        return Ok(Some(Real::zero()));
    };
    let Some(mut first) = first.try_coordinates() else {
        return Ok(None);
    };
    let mut sum = Real::zero();
    for second in points {
        let Some(second) = second?.try_coordinates() else {
            return Ok(None);
        };
        sum += Vector3::from(anchor.clone())
            .dot(&Vector3::from(first.clone()).cross(&Vector3::from(second.clone())));
        first = second;
    }
    Ok(Some(sum))
}

/// Divergence theorem for P(s,t) = origin + u*s + v*t:
/// 6V = 2 * (origin dot (u cross v)) * signed_UV_area.
/// The boundary winding includes face orientation and hole subtraction.
pub(super) fn planar_wire_six_volume(
    surface: &Surface,
    path: &CurvePath2,
) -> Result<Real, GeometryError> {
    let Some(origin) = surface.plane_origin() else {
        return Err(GeometryError::UnsupportedMeasurement);
    };
    let (u, v) = surface
        .plane_directions()
        .expect("plane origin implies plane directions");
    Ok(Real::from(2)
        * Vector3::from(origin.clone()).dot(&u.cross(v))
        * curve_path_signed_area(path)?)
}

/// Consecutive intervals of one source cover their union exactly once. Keep
/// the original topology; reuse a simpler image for its region/area proofs.
pub(super) fn coalesce_restrictions(input: Vec<Curve2>) -> Result<Vec<Curve2>, GeometryError> {
    if !input
        .iter()
        .any(|curve| curve.source_restriction().is_some() || curve.analytic_parallel().is_some())
    {
        return Ok(input);
    }
    let mut curves = Vec::with_capacity(input.len());
    for curve in input {
        if let Some(last) = curves.last_mut()
            && let Some(joined) = join_source_restrictions(last, &curve)?
        {
            *last = joined;
        } else {
            curves.push(curve);
        }
    }
    while curves.len() > 1 {
        let Some(joined) = join_source_restrictions(curves.last().expect("nonempty"), &curves[0])?
        else {
            break;
        };
        curves.pop();
        curves[0] = joined;
    }
    Ok(curves)
}

/// Exact subdivision identity: adjacent oriented intervals of the same authored
/// source cover their union once. This supplies validation evidence, never a
/// geometry repair or a topology edit.
fn join_source_restrictions(
    first: &Curve2,
    second: &Curve2,
) -> Result<Option<Curve2>, GeometryError> {
    if let (Some(first_view), Some(second_view)) =
        (first.analytic_parallel(), second.analytic_parallel())
    {
        if first_view.parallel() != second_view.parallel()
            || first_view.is_reversed() != second_view.is_reversed()
            || first
                .parameter_endpoints()
                .1
                .compare(second.parameter_endpoints().0)?
                != std::cmp::Ordering::Equal
        {
            return Ok(None);
        }
        let (Some(start), Some(end)) = (
            first.parameter_endpoints().0.as_bezier_parameter(),
            second.parameter_endpoints().1.as_bezier_parameter(),
        ) else {
            return Ok(None);
        };
        let joined = match Curve2::try_analytic_parallel(
            first_view.parallel().clone(),
            hypercurve::BezierParameterRange2::try_new(start.clone(), end.clone())?,
        ) {
            Ok(joined) => joined,
            // Adjacent regular pieces can meet at a cusp. Failure to prove
            // their joined range leaves both original pieces in the proof.
            Err(hypercurve::ExactCurveError::Blocked(blocker))
                if blocker.reason() != hypercurve::UncertaintyReason::BudgetExhausted =>
            {
                return Ok(None);
            }
            Err(hypercurve::ExactCurveError::Invalid {
                cause: hypercurve::CurveError::Topology(_),
                ..
            }) => return Ok(None),
            Err(error) => return Err(error.into()),
        };
        return Ok(joined.has_certified_injective_image()?.then_some(joined));
    }
    let (Some((source, first_range, reversed)), Some((other, second_range, other_reversed))) =
        (first.source_restriction(), second.source_restriction())
    else {
        return Ok(None);
    };
    if source != other || reversed != other_reversed {
        return Ok(None);
    }
    // Removing an internal boundary from a simplicity proof must not hide
    // a self-contact inside the reassembled source. Lines are injective by
    // construction. Other sources need a complete image certificate, including
    // exact span joins and a common monotone coordinate for multi-span splines.
    if !matches!(source.geometry(), Some(CurveGeometry2::Line(_)))
        && !source.has_certified_injective_image()?
    {
        return Ok(None);
    }
    if first
        .parameter_endpoints()
        .1
        .compare(second.parameter_endpoints().0)
        .map_err(GeometryError::from)?
        != std::cmp::Ordering::Equal
    {
        return Ok(None);
    }
    let (start, end) = if reversed {
        (second_range.start(), first_range.end())
    } else {
        (first_range.start(), second_range.end())
    };
    let range = hypercurve::CurveParameterRange2::try_new(start.clone(), end.clone())
        .map_err(GeometryError::from)?;
    let joined = source.restrict_source(range).map_err(GeometryError::from)?;
    Ok(Some(if reversed {
        joined.reversed().map_err(GeometryError::from)?
    } else {
        joined
    }))
}

#[cfg(test)]
mod tests {
    use super::*;
    use hypercurve::CurveParameterRange2;

    #[test]
    fn parallel_reassembly_preserves_direction_source_and_adjacency() {
        let parallel = hypercurve::QuadraticBezier2::new(
            CurvePoint2::from_values(0, 0),
            CurvePoint2::from_values(2, 2),
            CurvePoint2::from_values(4, 0),
        )
        .parallel_left(Real::one())
        .unwrap();
        let curve = Curve2::try_analytic_parallel(
            parallel,
            hypercurve::BezierParameterRange2::try_new(
                hypercurve::BezierParameter2::Exact(0.into()),
                hypercurve::BezierParameter2::Exact(1.into()),
            )
            .unwrap(),
        )
        .unwrap();
        for curve in [curve.clone(), curve.reversed().unwrap()] {
            let half = (Real::one() / Real::from(2)).unwrap();
            let (a, b) = curve.split_at(half.into()).unwrap();
            let joined = coalesce_restrictions(vec![a.clone(), b.clone()]).unwrap();
            assert_eq!(joined.len(), 1);
            assert_eq!(
                joined[0].analytic_parallel().unwrap().parallel(),
                curve.analytic_parallel().unwrap().parallel()
            );
            assert_eq!(joined[0].parameter_endpoints(), curve.parameter_endpoints());
            assert_eq!(
                coalesce_restrictions(vec![b.clone(), a.reversed().unwrap()])
                    .unwrap()
                    .len(),
                2
            );
        }
    }

    #[test]
    fn parallel_reassembly_keeps_an_interior_cusp_split() {
        let half = (Real::one() / Real::from(2)).unwrap();
        let parallel = hypercurve::QuadraticBezier2::new(
            CurvePoint2::from_values(0, 0),
            CurvePoint2::new(half, 0.into()),
            CurvePoint2::from_values(1, 1),
        )
        .parallel_left(Real::one())
        .unwrap();
        let analysis = parallel
            .singularity_analysis(&CurveParameterRange2::unit())
            .unwrap();
        let [cusp] = analysis.parallel_cusps() else {
            panic!("one cusp")
        };
        let parts = [
            (hypercurve::BezierParameter2::Exact(0.into()), cusp.clone()),
            (cusp.clone(), hypercurve::BezierParameter2::Exact(1.into())),
        ]
        .into_iter()
        .map(|(a, b)| {
            Curve2::try_analytic_parallel(
                parallel.clone(),
                hypercurve::BezierParameterRange2::try_new(a, b).unwrap(),
            )
            .unwrap()
        })
        .collect();
        assert_eq!(coalesce_restrictions(parts).unwrap().len(), 2);
    }

    #[test]
    fn reassembly_does_not_hide_a_source_without_injectivity_evidence() {
        let uv = |x, y| CurvePoint2::new(Real::from(x), Real::from(y));
        let source = Curve2::from(
            RationalBezier2::try_new(
                vec![uv(0, 0), uv(2, 3), uv(-2, 3), uv(0, 0)],
                vec![Real::one(); 4],
            )
            .unwrap(),
        );
        let half = (Real::one() / Real::from(2)).unwrap();
        let first = source
            .restrict_source(
                CurveParameterRange2::try_new(Real::zero().into(), half.clone().into()).unwrap(),
            )
            .unwrap();
        let second = source
            .restrict_source(
                CurveParameterRange2::try_new(half.into(), Real::one().into()).unwrap(),
            )
            .unwrap();
        assert_eq!(coalesce_restrictions(vec![first, second]).unwrap().len(), 2);
    }
}

crates/hyperbrep/src/topology/correspond:
//! Exact edge and pcurve parameter correspondence.

use super::*;

/// Exact relation from a face-local pcurve parameterization to an edge curve.
///
/// A BREP edge has one canonical 3D parameterization while each incident face
/// owns a pcurve parameterization. Those parameterizations need not be
/// affinely related: a native rational circular pcurve on a planar cap and an
/// angle-parameterized spatial circle are the canonical example.
#[derive(Clone, Debug)]
pub enum ParameterCorrespondence {
    /// `edge_parameter = scale * coordinate(pcurve(t)) + offset`.
    /// Whole-image admission proves an injective straight pcurve and its
    /// surface image; its parameter may be a retained point-order parameter.
    Coordinate {
        /// Face-local coordinate used by the relation.
        axis: hypercurve::Axis2,
        /// Nonzero exact scale.
        scale: Real,
        /// Exact offset.
        offset: Real,
    },
    /// `edge_parameter = scale * pcurve_parameter + offset`.
    Affine {
        /// Nonzero exact scale.
        scale: Real,
        /// Exact offset.
        offset: Real,
    },
    /// The pcurve's directed angular sweep fraction spans the directed edge
    /// domain.
    ///
    /// This relation is valid only for a native circular-arc pcurve and a
    /// spatial circular arc. ArenaModel validation certifies the complete image,
    /// support frame, orientation, and sweep before publication.
    AngularSweep,
}

impl ParameterCorrespondence {
    /// Relates an edge parameter to one coordinate on a straight iso pcurve.
    pub fn coordinate(
        axis: hypercurve::Axis2,
        scale: Real,
        offset: Real,
    ) -> Result<Self, BuildError> {
        Self::affine(scale.clone(), offset.clone())?;
        Ok(Self::Coordinate {
            axis,
            scale,
            offset,
        })
    }
    /// Constructs `edge_parameter = scale * pcurve_parameter + offset`.
    pub fn affine(scale: Real, offset: Real) -> Result<Self, BuildError> {
        crate::context::strict(|| {
            match compare_reals(&scale, &Real::zero(), crate::STRICT_PREDICATES) {
                PredicateOutcome::Decided {
                    value: std::cmp::Ordering::Equal,
                    ..
                } => Err(BuildError::DegenerateParameterCorrespondence),
                PredicateOutcome::Decided { .. } => Ok(Self::Affine { scale, offset }),
                PredicateOutcome::Unknown { needed, stage } => {
                    Err(BuildError::Geometry(GeometryError::PredicateUnresolved {
                        needed,
                        stage,
                    }))
                }
            }
        })
    }

    /// Returns the identity parameter correspondence.
    pub fn identity() -> Self {
        Self::Affine {
            scale: Real::one(),
            offset: Real::zero(),
        }
    }

    /// Relates a native circular pcurve's directed sweep to the edge domain.
    pub const fn angular_sweep() -> Self {
        Self::AngularSweep
    }

    /// Returns affine coefficients, or `None` for a non-affine relation.
    pub const fn affine_coefficients(&self) -> Option<(&Real, &Real)> {
        match self {
            Self::Affine { scale, offset, .. } => Some((scale, offset)),
            Self::AngularSweep | Self::Coordinate { .. } => None,
        }
    }

    pub(in crate::topology) fn edge_parameter(
        &self,
        pcurve: &Pcurve,
        edge_domain: &ParameterRange,
        direction: Direction,
        pcurve_parameter: &Parameter,
    ) -> Result<Parameter, GeometryError> {
        if let Self::Coordinate {
            axis,
            scale,
            offset,
        } = self
        {
            let point = pcurve.point_at(pcurve_parameter)?;
            let (a, b) = match axis {
                hypercurve::Axis2::X => (scale.clone(), Real::zero()),
                hypercurve::Axis2::Y => (Real::zero(), scale.clone()),
            };
            return Parameter::from_curve(&point.affine_form(a, b, offset.clone()).parameter()?);
        }
        if let Self::Affine { scale, offset } = self {
            if let Some(value) = pcurve_parameter.try_real() {
                return Ok(Parameter::from_real(scale * value + offset));
            }
            return pcurve_parameter.affine_image(scale, offset);
        }
        let (directed_start, directed_end) = match direction {
            Direction::Forward => (edge_domain.start(), edge_domain.end()),
            Direction::Reversed => (edge_domain.end(), edge_domain.start()),
        };
        if pcurve_parameter.compare(&pcurve.domain_start()?)? == std::cmp::Ordering::Equal {
            return Ok(directed_start.clone());
        }
        if pcurve_parameter.compare(&pcurve.domain_end()?)? == std::cmp::Ordering::Equal {
            return Ok(directed_end.clone());
        }
        let arc = pcurve
            .circular_arc()
            .ok_or(GeometryError::UnsupportedPcurveContour)?;
        let value = pcurve_parameter
            .try_real()
            .ok_or(GeometryError::UnrepresentableParameter)?;
        let point = pcurve.evaluate_real(value)?;
        let point = CurvePoint2::new(point.x, point.y);
        let fraction = match crate::error::classified(arc.sweep_fraction(&point))? {
            Classification::Decided(fraction) => fraction,
            Classification::Uncertain(reason) => {
                return Err(GeometryError::PlanarClassificationUnresolved(reason));
            }
        };
        let start = directed_start
            .try_real()
            .ok_or(GeometryError::UnrepresentableParameter)?;
        let end = directed_end
            .try_real()
            .ok_or(GeometryError::UnrepresentableParameter)?;
        Ok(Parameter::from_real(start + &((end - start) * fraction)))
    }

    pub(in crate::topology) fn pcurve_parameter(
        &self,
        pcurve: &Pcurve,
        edge_domain: &ParameterRange,
        direction: Direction,
        edge_parameter: &Parameter,
    ) -> Result<Parameter, GeometryError> {
        if let Self::Coordinate {
            axis,
            scale,
            offset,
        } = self
        {
            let inverse = (Real::one() / scale).map_err(GeometryError::Numeric)?;
            let value = edge_parameter.affine_image(&inverse, &(-offset * &inverse))?;
            let first = pcurve.curve().start();
            let last = pcurve.curve().end();
            let (a, b) = match axis {
                hypercurve::Axis2::X => (Real::zero(), Real::one()),
                hypercurve::Axis2::Y => (Real::one(), Real::zero()),
            };
            let constant = first
                .affine_form(a.clone(), b.clone(), Real::zero())
                .parameter()?;
            if pcurve.kind() != CurveFamily2::Line
                || constant.compare(&last.affine_form(a, b, Real::zero()).parameter()?)?
                    != std::cmp::Ordering::Equal
            {
                return Err(GeometryError::UnsupportedPcurveContour);
            }
            let point = match (axis, value.try_real(), constant.scalar()) {
                (hypercurve::Axis2::X, _, Some(v)) => value.curve_parameter().affine_point(
                    Real::one(),
                    Real::zero(),
                    Real::zero(),
                    v.clone(),
                )?,
                (hypercurve::Axis2::Y, Some(v), _) => {
                    constant.affine_point(Real::one(), Real::zero(), Real::zero(), v.clone())?
                }
                (hypercurve::Axis2::Y, _, Some(u)) => value.curve_parameter().affine_point(
                    Real::zero(),
                    u.clone(),
                    Real::one(),
                    Real::zero(),
                )?,
                (hypercurve::Axis2::X, Some(u), _) => {
                    constant.affine_point(Real::zero(), u.clone(), Real::one(), Real::zero())?
                }
                _ => return Err(GeometryError::UnsupportedSelectedEvaluation),
            };
            return match pcurve.curve().point_locations(&point)? {
                hypercurve::CurvePointLocations2::Locations(locations) if locations.len() == 1 => {
                    Parameter::from_curve(&locations[0].parameter()?)
                }
                _ => Err(GeometryError::ParameterOutsideDomain),
            };
        }
        if let Self::Affine { scale, offset } = self {
            if let Some(value) = edge_parameter.try_real() {
                return ((value - offset) / scale)
                    .map(Parameter::from_real)
                    .map_err(GeometryError::Numeric);
            }
            let inverse = (Real::one() / scale).map_err(GeometryError::Numeric)?;
            return edge_parameter.affine_image(&inverse, &(-offset * &inverse));
        }
        let (directed_start, directed_end) = match direction {
            Direction::Forward => (edge_domain.start(), edge_domain.end()),
            Direction::Reversed => (edge_domain.end(), edge_domain.start()),
        };
        if edge_parameter.compare(directed_start)? == std::cmp::Ordering::Equal {
            return pcurve.domain_start();
        }
        if edge_parameter.compare(directed_end)? == std::cmp::Ordering::Equal {
            return pcurve.domain_end();
        }
        let arc = pcurve
            .circular_arc()
            .ok_or(GeometryError::UnsupportedPcurveContour)?;
        let value = edge_parameter
            .try_real()
            .ok_or(GeometryError::UnrepresentableParameter)?;
        let start = directed_start
            .try_real()
            .ok_or(GeometryError::UnrepresentableParameter)?;
        let end = directed_end
            .try_real()
            .ok_or(GeometryError::UnrepresentableParameter)?;
        let fraction = ((value - start) / (end - start)).map_err(GeometryError::Numeric)?;
        match crate::error::classified(arc.parameter_at_sweep_fraction(&fraction))? {
            Classification::Decided(parameter) => Ok(parameter.into()),
            Classification::Uncertain(reason) => {
                Err(GeometryError::PlanarClassificationUnresolved(reason))
            }
        }
    }

    pub(crate) fn reflected_and_reversed_pcurve(
        &self,
        pcurve: &Pcurve,
        sum: &Real,
    ) -> Result<Self, GeometryError> {
        if let Self::Coordinate {
            axis: hypercurve::Axis2::X,
            scale,
            offset,
        } = self
        {
            return Ok(Self::Coordinate {
                axis: hypercurve::Axis2::X,
                scale: -scale,
                offset: offset + scale * sum,
            });
        }
        self.reversed_pcurve(pcurve)
    }

    pub(crate) fn reversed_pcurve(&self, pcurve: &Pcurve) -> Result<Self, GeometryError> {
        // Generated restrictions reverse traversal in their existing chart.
        if pcurve.curve().geometry().is_none() {
            return Ok(self.clone());
        }
        Ok(match self {
            Self::Affine { scale, offset } => Self::Affine {
                scale: -scale.clone(),
                offset: scale * (pcurve.represented_start()? + pcurve.represented_end()?) + offset,
            },
            Self::AngularSweep => Self::AngularSweep,
            Self::Coordinate { .. } => self.clone(),
        })
    }

    pub(crate) fn remapped_edge(
        &self,
        source: &ParameterDomain,
        target: &ParameterDomain,
        reversed: bool,
    ) -> Result<Self, GeometryError> {
        match self {
            Self::Affine { scale, offset } | Self::Coordinate { scale, offset, .. } => {
                let factor = ((target.end() - target.start()) / (source.end() - source.start()))
                    .map_err(GeometryError::Numeric)?;
                let (scale, offset) = if reversed {
                    (
                        -(&factor * scale),
                        target.end() - &factor * (offset - source.start()),
                    )
                } else {
                    (
                        &factor * scale,
                        target.start() + factor * (offset - source.start()),
                    )
                };
                Ok(match self {
                    Self::Coordinate { axis, .. } => Self::Coordinate {
                        axis: *axis,
                        scale,
                        offset,
                    },
                    _ => Self::Affine { scale, offset },
                })
            }
            Self::AngularSweep => Ok(Self::AngularSweep),
        }
    }
}

crates/hyperbrep/src/topology/query.rs:
//! Certified classification and retained family queries.

use super::*;

impl CertifiedAngularSector {
    fn classify_offset(&self, offset: &Vector3) -> Result<SolidPointLocation, QueryError> {
        let mut boundary = false;
        for normal in &self.interior_normals {
            match decided_model_order(compare_reals(
                &offset.dot(normal),
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))? {
                std::cmp::Ordering::Less => return Ok(SolidPointLocation::Outside),
                std::cmp::Ordering::Equal => boundary = true,
                std::cmp::Ordering::Greater => {}
            }
        }
        Ok(if boundary {
            SolidPointLocation::Boundary
        } else {
            SolidPointLocation::Inside
        })
    }
}

impl ArenaModel {
    /// Classifies a point against a validated planar line-bounded solid.
    ///
    /// Face contours are materialized once from retained pcurves. Ray
    /// directions that hit an edge or vertex are discarded and retried; if
    /// every deterministic direction is degenerate, the result stays an
    /// explicit unresolved error.
    pub fn classify_point(
        &self,
        solid: SolidId,
        point: &Point3,
    ) -> Result<SolidPointLocation, QueryError> {
        crate::context::strict(|| {
            let solid_id = solid;
            let solid = self.solid(solid_id).ok_or(QueryError::InvalidReference {
                kind: EntityKind::Solid,
                index: solid_id.index(),
            })?;
            if let Some(cylinder) = &self.data.certified_cylinders[solid_id.index()] {
                return self.classify_point_against_cylinder(cylinder, point);
            }
            if let Some(sphere) = &self.data.certified_spheres[solid_id.index()] {
                return self.classify_point_against_sphere(sphere, point);
            }
            if let Some(pair) = &self.data.certified_sphere_pairs[solid_id.index()] {
                return self.classify_point_against_sphere_pair(pair, point);
            }
            if let Some(torus) = &self.data.certified_tori[solid_id.index()] {
                return self.classify_point_against_torus(torus, point);
            }
            if let Some(frustum) = &self.data.certified_cone_frustums[solid_id.index()] {
                return self.classify_point_against_cone_frustum(frustum, point);
            }
            if let Some(revolution) = &self.data.certified_revolutions[solid_id.index()] {
                return self.classify_point_against_revolution(revolution, point);
            }
            if let Some(loft) = &self.data.certified_lofts[solid_id.index()] {
                return self.classify_point_against_loft(loft, point);
            }
            if let Some(sweep) = &self.data.certified_curve_sweeps[solid_id.index()] {
                return self.classify_point_against_curve_sweep(sweep, point);
            }
            if let Some(prism) = &self.data.certified_prisms[solid_id.index()] {
                return self.classify_point_against_prism(prism, point);
            }
            if let Some(axial) = &self.data.certified_axial_shells[solid_id.index()] {
                return Self::classify_point_against_axial(axial, point);
            }
            for shell in std::iter::once(&solid.outer).chain(solid.voids.iter()) {
                for face in &self.shell(*shell).expect("validated shell ID").faces {
                    let signed = self.face_plane_value(*face, point)?;
                    if decided_model_order(compare_reals(
                        &signed,
                        &Real::zero(),
                        crate::STRICT_PREDICATES,
                    ))? == std::cmp::Ordering::Equal
                    {
                        match self.classify_point_on_face(*face, point)? {
                            Classification::Decided(ContourPointLocation::Inside)
                            | Classification::Decided(ContourPointLocation::Boundary) => {
                                return Ok(SolidPointLocation::Boundary);
                            }
                            Classification::Decided(ContourPointLocation::Outside) => {}
                            Classification::Uncertain(reason) => {
                                return Err(
                                    GeometryError::PlanarClassificationUnresolved(reason).into()
                                );
                            }
                        }
                    }
                }
            }

            if self.classify_point_against_shell(solid.outer, point)? == SolidPointLocation::Outside
            {
                return Ok(SolidPointLocation::Outside);
            }
            for void_shell in &solid.voids {
                if self.classify_point_against_shell(*void_shell, point)?
                    == SolidPointLocation::Inside
                {
                    return Ok(SolidPointLocation::Outside);
                }
            }
            Ok(SolidPointLocation::Inside)
        })
    }

    pub(in crate::topology) fn classify_point_against_cylinder(
        &self,
        cylinder: &CertifiedCylinderShell,
        point: &Point3,
    ) -> Result<SolidPointLocation, QueryError> {
        let offset = point - &cylinder.origin;
        let axial = offset.dot(&cylinder.axis);
        let below = decided_model_order(compare_reals(
            &axial,
            &cylinder.v_min,
            crate::STRICT_PREDICATES,
        ))? == std::cmp::Ordering::Less;
        let above = decided_model_order(compare_reals(
            &axial,
            &cylinder.v_max,
            crate::STRICT_PREDICATES,
        ))? == std::cmp::Ordering::Greater;
        if below || above {
            return Ok(SolidPointLocation::Outside);
        }
        let radial = offset - cylinder.axis.clone() * &axial;
        let radial_squared = radial.norm_squared();
        let radius_squared = &cylinder.radius * &cylinder.radius;
        let radial_order = decided_model_order(compare_reals(
            &radial_squared,
            &radius_squared,
            crate::STRICT_PREDICATES,
        ))?;
        if radial_order == std::cmp::Ordering::Greater {
            return Ok(SolidPointLocation::Outside);
        }
        if let Some(subtraction) = &cylinder.sphere_subtraction {
            let (center, radius) = match subtraction {
                CertifiedCylinderSphereSubtraction::Void { center, radius }
                | CertifiedCylinderSphereSubtraction::Component { center, radius, .. } => {
                    (center, radius)
                }
            };
            match decided_model_order(compare_reals(
                &(point - center).norm_squared(),
                &(radius * radius),
                crate::STRICT_PREDICATES,
            ))? {
                std::cmp::Ordering::Less => return Ok(SolidPointLocation::Outside),
                std::cmp::Ordering::Equal => return Ok(SolidPointLocation::Boundary),
                std::cmp::Ordering::Greater => {}
            }
        }
        let on_cap = decided_model_order(compare_reals(
            &axial,
            &cylinder.v_min,
            crate::STRICT_PREDICATES,
        ))? == std::cmp::Ordering::Equal
            || decided_model_order(compare_reals(
                &axial,
                &cylinder.v_max,
                crate::STRICT_PREDICATES,
            ))? == std::cmp::Ordering::Equal;
        if on_cap || radial_order == std::cmp::Ordering::Equal {
            Ok(SolidPointLocation::Boundary)
        } else {
            Ok(SolidPointLocation::Inside)
        }
    }

    pub(in crate::topology) fn classify_point_against_revolution(
        &self,
        revolution: &CertifiedRevolutionShell,
        point: &Point3,
    ) -> Result<SolidPointLocation, QueryError> {
        let offset = point - &revolution.axis_origin;
        let axial = offset.dot(&revolution.axis);
        let radial = offset - revolution.axis.clone() * &axial;
        let radius = radial
            .norm_squared()
            .sqrt()
            .map_err(GeometryError::Numeric)?;
        let profile_point = CurvePoint2::new(radius, axial);
        let location = match revolution.profile.classify_point(&profile_point)? {
            Classification::Decided(location) => location,
            Classification::Uncertain(reason) => {
                return Err(GeometryError::PlanarClassificationUnresolved(reason).into());
            }
        };
        match location {
            ContourPointLocation::Outside => return Ok(SolidPointLocation::Outside),
            ContourPointLocation::Boundary => return Ok(SolidPointLocation::Boundary),
            ContourPointLocation::Inside => {}
        }
        for void in &revolution.voids {
            match void.classify_point(&profile_point)? {
                Classification::Decided(ContourPointLocation::Inside) => {
                    return Ok(SolidPointLocation::Outside);
                }
                Classification::Decided(ContourPointLocation::Boundary) => {
                    return Ok(SolidPointLocation::Boundary);
                }
                Classification::Decided(ContourPointLocation::Outside) => {}
                Classification::Uncertain(reason) => {
                    return Err(GeometryError::PlanarClassificationUnresolved(reason).into());
                }
            }
        }
        Ok(SolidPointLocation::Inside)
    }

    pub(in crate::topology) fn classify_point_against_loft(
        &self,
        loft: &CertifiedLoftShell,
        point: &Point3,
    ) -> Result<SolidPointLocation, QueryError> {
        let displacement = point - &loft.origin;
        let determinant = loft.u.dot(&loft.v.cross(&loft.height_axis));
        let parameter_u = (displacement.dot(&loft.v.cross(&loft.height_axis)) / &determinant)
            .map_err(GeometryError::Numeric)?;
        let parameter_v = (loft.u.dot(&displacement.cross(&loft.height_axis)) / &determinant)
            .map_err(GeometryError::Numeric)?;
        let parameter_t = (loft.u.dot(&loft.v.cross(&displacement)) / determinant)
            .map_err(GeometryError::Numeric)?;
        let t_order_min = decided_model_order(compare_reals(
            &parameter_t,
            &Real::zero(),
            crate::STRICT_PREDICATES,
        ))?;
        let t_order_max = decided_model_order(compare_reals(
            &parameter_t,
            &Real::one(),
            crate::STRICT_PREDICATES,
        ))?;
        if t_order_min == std::cmp::Ordering::Less || t_order_max == std::cmp::Ordering::Greater {
            return Ok(SolidPointLocation::Outside);
        }
        let mut selected_span = None;
        for span in &loft.spans {
            let at_or_above = decided_model_order(compare_reals(
                &parameter_t,
                &span.start,
                crate::STRICT_PREDICATES,
            ))? != std::cmp::Ordering::Less;
            let at_or_below = decided_model_order(compare_reals(
                &parameter_t,
                &span.end,
                crate::STRICT_PREDICATES,
            ))? != std::cmp::Ordering::Greater;
            if at_or_above && at_or_below {
                selected_span = Some(span);
                break;
            }
        }
        let span = selected_span.ok_or(GeometryError::InvalidParameterDomain)?;
        let span_width = &span.end - &span.start;
        let local_parameter =
            ((&parameter_t - &span.start) / span_width).map_err(GeometryError::Numeric)?;
        let profile_point = CurvePoint2::new(parameter_u, parameter_v);
        let profile_location = match &span.interpolation {
            CertifiedLoftInterpolation::Homothetic {
                profile,
                scale,
                translation,
            } => {
                let factor = Real::one() + &local_parameter * (scale - Real::one());
                let normalized = CurvePoint2::new(
                    ((profile_point.x() - &local_parameter * translation.x()) / &factor)
                        .map_err(GeometryError::Numeric)?,
                    ((profile_point.y() - &local_parameter * translation.y()) / factor)
                        .map_err(GeometryError::Numeric)?,
                );
                match crate::error::classified(profile.classify_point(&normalized))
                    .map_err(GeometryError::from)?
                {
                    Classification::Decided(location) => location,
                    Classification::Uncertain(reason) => {
                        return Err(GeometryError::PlanarClassificationUnresolved(reason).into());
                    }
                }
            }
            CertifiedLoftInterpolation::ConvexCorresponding { lower, upper } => {
                classify_convex_loft_section(lower, upper, &local_parameter, &profile_point)?
            }
        };
        match profile_location {
            ContourPointLocation::Outside => Ok(SolidPointLocation::Outside),
            ContourPointLocation::Boundary => Ok(SolidPointLocation::Boundary),
            ContourPointLocation::Inside
                if t_order_min == std::cmp::Ordering::Equal
                    || t_order_max == std::cmp::Ordering::Equal =>
            {
                Ok(SolidPointLocation::Boundary)
            }
            ContourPointLocation::Inside => Ok(SolidPointLocation::Inside),
        }
    }

    pub(in crate::topology) fn classify_point_against_curve_sweep(
        &self,
        sweep: &CertifiedCurveSweepShell,
        point: &Point3,
    ) -> Result<SolidPointLocation, QueryError> {
        let start = sweep
            .path
            .evaluate_real(sweep.path.domain().represented_start()?)?;
        let end = sweep
            .path
            .evaluate_real(sweep.path.domain().represented_end()?)?;
        let start_u = Vector3::from(
            sweep
                .u_path
                .evaluate_real(sweep.u_path.domain().represented_start()?)?,
        );
        let start_v = Vector3::from(
            sweep
                .v_path
                .evaluate_real(sweep.v_path.domain().represented_start()?)?,
        );
        let (lower_order, upper_order, profile_point) = match sweep.progress {
            SweepProgress::Affine => {
                let normal = start_u.cross(&start_v);
                let progress = normal.dot(&(end - &start));
                let parameter = (normal.dot(&(point - &start)) / &progress)
                    .map_err(|problem| QueryError::from(GeometryError::Numeric(problem)))?;
                let lower_order = decided_model_order(compare_reals(
                    &parameter,
                    &Real::zero(),
                    crate::STRICT_PREDICATES,
                ))?;
                let upper_order = decided_model_order(compare_reals(
                    &parameter,
                    &Real::one(),
                    crate::STRICT_PREDICATES,
                ))?;
                if lower_order == std::cmp::Ordering::Less
                    || upper_order == std::cmp::Ordering::Greater
                {
                    return Ok(SolidPointLocation::Outside);
                }
                let path_point = sweep.path.evaluate_real(&parameter)?;
                let u = Vector3::from(sweep.u_path.evaluate_real(&parameter)?);
                let v = Vector3::from(sweep.v_path.evaluate_real(&parameter)?);
                let profile_point = project_point_to_plane_frame(point, &path_point, &u, &v)
                    .map_err(build_error_geometry)?;
                (lower_order, upper_order, profile_point.into())
            }
            SweepProgress::Monotone => {
                let Some(section) =
                    monotone_sweep_section(sweep, point, &start, &end, &start_u, &start_v)?
                else {
                    return Ok(SolidPointLocation::Outside);
                };
                section
            }
        };
        let classify = |contour: &Contour2| -> Result<_, QueryError> {
            let classified = match profile_point.coordinates() {
                Some(coordinates) => crate::error::classified(contour.classify_point(coordinates)),
                // A selected section point keeps its root; Hypercurve's
                // retained-point classifier decides it on the same boundary.
                None => crate::error::classified(
                    CurvePath2::try_new(
                        contour
                            .segments()
                            .iter()
                            .cloned()
                            .map(curve2_from_segment)
                            .collect(),
                    )
                    .map_err(GeometryError::from)?
                    .classify_point(&profile_point),
                ),
            };
            Ok(classified.map_err(GeometryError::from)?)
        };
        let location = match classify(&sweep.profile)? {
            Classification::Decided(location) => location,
            Classification::Uncertain(reason) => {
                return Err(GeometryError::PlanarClassificationUnresolved(reason).into());
            }
        };
        match location {
            ContourPointLocation::Outside => return Ok(SolidPointLocation::Outside),
            ContourPointLocation::Boundary => return Ok(SolidPointLocation::Boundary),
            ContourPointLocation::Inside => {}
        }
        for hole in &sweep.holes {
            match classify(hole)? {
                Classification::Decided(ContourPointLocation::Inside) => {
                    return Ok(SolidPointLocation::Outside);
                }
                Classification::Decided(ContourPointLocation::Boundary) => {
                    return Ok(SolidPointLocation::Boundary);
                }
                Classification::Decided(ContourPointLocation::Outside) => {}
                Classification::Uncertain(reason) => {
                    return Err(GeometryError::PlanarClassificationUnresolved(reason).into());
                }
            }
        }
        if lower_order == std::cmp::Ordering::Equal || upper_order == std::cmp::Ordering::Equal {
            Ok(SolidPointLocation::Boundary)
        } else {
            Ok(SolidPointLocation::Inside)
        }
    }

    pub(in crate::topology) fn classify_point_against_sphere(
        &self,
        sphere: &CertifiedSphereShell,
        point: &Point3,
    ) -> Result<SolidPointLocation, QueryError> {
        if let CertifiedSphereRegion::FiniteCylinder(region) = &sphere.region {
            return self.classify_point_against_sphere_finite_cylinder(sphere, region, point);
        }
        let radial_boundary = if let CertifiedSphereRegion::Radial(clip) = &sphere.region {
            let offset = point - &sphere.center;
            let axial = offset.dot(&clip.axis);
            let radial = offset - clip.axis.clone() * axial;
            let radial_order = decided_model_order(compare_reals(
                &radial.norm_squared(),
                &(&clip.radius * &clip.radius),
                crate::STRICT_PREDICATES,
            ))?;
            if matches!(
                (clip.side, radial_order),
                (
                    CertifiedSphereRadialSide::Inside,
                    std::cmp::Ordering::Greater
                ) | (CertifiedSphereRadialSide::Outside, std::cmp::Ordering::Less)
            ) {
                return Ok(SolidPointLocation::Outside);
            }
            match radial_order {
                std::cmp::Ordering::Equal => true,
                std::cmp::Ordering::Less | std::cmp::Ordering::Greater => false,
            }
        } else {
            false
        };
        let clip_orders = if let CertifiedSphereRegion::Axial(clip) = &sphere.region {
            let height = (point - &sphere.center).dot(&clip.axis);
            let min =
                decided_model_order(compare_reals(&height, &clip.min, crate::STRICT_PREDICATES))?;
            let max =
                decided_model_order(compare_reals(&height, &clip.max, crate::STRICT_PREDICATES))?;
            if min == std::cmp::Ordering::Less || max == std::cmp::Ordering::Greater {
                return Ok(SolidPointLocation::Outside);
            }
            Some((min, max))
        } else {
            None
        };
        let distance_squared = (point - &sphere.center).norm_squared();
        let radius_squared = &sphere.radius * &sphere.radius;
        match decided_model_order(compare_reals(
            &distance_squared,
            &radius_squared,
            crate::STRICT_PREDICATES,
        ))? {
            std::cmp::Ordering::Greater => return Ok(SolidPointLocation::Outside),
            std::cmp::Ordering::Equal => return Ok(SolidPointLocation::Boundary),
            std::cmp::Ordering::Less => {}
        }
        if radial_boundary
            || clip_orders.is_some_and(|(min, max)| {
                min == std::cmp::Ordering::Equal || max == std::cmp::Ordering::Equal
            })
        {
            return Ok(SolidPointLocation::Boundary);
        }
        for void in &sphere.voids {
            let location = match void {
                CertifiedSphereVoid::Sphere { center, radius } => {
                    match decided_model_order(compare_reals(
                        &(point - center).norm_squared(),
                        &(radius * radius),
                        crate::STRICT_PREDICATES,
                    ))? {
                        std::cmp::Ordering::Less => SolidPointLocation::Inside,
                        std::cmp::Ordering::Equal => SolidPointLocation::Boundary,
                        std::cmp::Ordering::Greater => SolidPointLocation::Outside,
                    }
                }
                CertifiedSphereVoid::Cylinder(cylinder) => {
                    let offset = point - &cylinder.origin;
                    let axial = offset.dot(&cylinder.axis);
                    let min = decided_model_order(compare_reals(
                        &axial,
                        &cylinder.v_min,
                        crate::STRICT_PREDICATES,
                    ))?;
                    let max = decided_model_order(compare_reals(
                        &axial,
                        &cylinder.v_max,
                        crate::STRICT_PREDICATES,
                    ))?;
                    if min == std::cmp::Ordering::Less || max == std::cmp::Ordering::Greater {
                        SolidPointLocation::Outside
                    } else {
                        let radial = offset - cylinder.axis.clone() * &axial;
                        match decided_model_order(compare_reals(
                            &radial.norm_squared(),
                            &(&cylinder.radius * &cylinder.radius),
                            crate::STRICT_PREDICATES,
                        ))? {
                            std::cmp::Ordering::Greater => SolidPointLocation::Outside,
                            std::cmp::Ordering::Equal => SolidPointLocation::Boundary,
                            std::cmp::Ordering::Less
                                if min == std::cmp::Ordering::Equal
                                    || max == std::cmp::Ordering::Equal =>
                            {
                                SolidPointLocation::Boundary
                            }
                            std::cmp::Ordering::Less => SolidPointLocation::Inside,
                        }
                    }
                }
            };
            match location {
                SolidPointLocation::Inside => return Ok(SolidPointLocation::Outside),
                SolidPointLocation::Boundary => return Ok(SolidPointLocation::Boundary),
                SolidPointLocation::Outside => {}
            }
        }
        Ok(SolidPointLocation::Inside)
    }

    pub(in crate::topology) fn classify_point_against_sphere_finite_cylinder(
        &self,
        sphere: &CertifiedSphereShell,
        cylinder: &CertifiedSphereFiniteCylinderRegion,
        point: &Point3,
    ) -> Result<SolidPointLocation, QueryError> {
        let sphere_order = decided_model_order(compare_reals(
            &(point - &sphere.center).norm_squared(),
            &(&sphere.radius * &sphere.radius),
            crate::STRICT_PREDICATES,
        ))?;
        let offset = point - &cylinder.origin;
        let axial = offset.dot(&cylinder.axis);
        let axial_min = decided_model_order(compare_reals(
            &axial,
            &cylinder.v_min,
            crate::STRICT_PREDICATES,
        ))?;
        let axial_max = decided_model_order(compare_reals(
            &axial,
            &cylinder.v_max,
            crate::STRICT_PREDICATES,
        ))?;
        let cylinder_location =
            if axial_min == std::cmp::Ordering::Less || axial_max == std::cmp::Ordering::Greater {
                SolidPointLocation::Outside
            } else {
                let radial = offset - cylinder.axis.clone() * &axial;
                match decided_model_order(compare_reals(
                    &radial.norm_squared(),
                    &(&cylinder.radius * &cylinder.radius),
                    crate::STRICT_PREDICATES,
                ))? {
                    std::cmp::Ordering::Greater => SolidPointLocation::Outside,
                    std::cmp::Ordering::Equal => SolidPointLocation::Boundary,
                    std::cmp::Ordering::Less
                        if axial_min == std::cmp::Ordering::Equal
                            || axial_max == std::cmp::Ordering::Equal =>
                    {
                        SolidPointLocation::Boundary
                    }
                    std::cmp::Ordering::Less => SolidPointLocation::Inside,
                }
            };
        let sphere_location = match sphere_order {
            std::cmp::Ordering::Less => SolidPointLocation::Inside,
            std::cmp::Ordering::Equal => SolidPointLocation::Boundary,
            std::cmp::Ordering::Greater => SolidPointLocation::Outside,
        };
        Ok(match cylinder.operation {
            CertifiedSphereFiniteCylinderOperation::Union => {
                match (sphere_location, cylinder_location) {
                    (SolidPointLocation::Inside, _) | (_, SolidPointLocation::Inside) => {
                        SolidPointLocation::Inside
                    }
                    (SolidPointLocation::Boundary, _) | (_, SolidPointLocation::Boundary) => {
                        SolidPointLocation::Boundary
                    }
                    (SolidPointLocation::Outside, SolidPointLocation::Outside) => {
                        SolidPointLocation::Outside
                    }
                }
            }
            CertifiedSphereFiniteCylinderOperation::Intersection => {
                match (sphere_location, cylinder_location) {
                    (SolidPointLocation::Outside, _) | (_, SolidPointLocation::Outside) => {
                        SolidPointLocation::Outside
                    }
                    (SolidPointLocation::Boundary, _) | (_, SolidPointLocation::Boundary) => {
                        SolidPointLocation::Boundary
                    }
                    (SolidPointLocation::Inside, SolidPointLocation::Inside) => {
                        SolidPointLocation::Inside
                    }
                }
            }
            CertifiedSphereFiniteCylinderOperation::Difference => {
                match (sphere_location, cylinder_location) {
                    (SolidPointLocation::Outside, _) | (_, SolidPointLocation::Inside) => {
                        SolidPointLocation::Outside
                    }
                    (SolidPointLocation::Boundary, _)
                    | (SolidPointLocation::Inside, SolidPointLocation::Boundary) => {
                        SolidPointLocation::Boundary
                    }
                    (SolidPointLocation::Inside, SolidPointLocation::Outside) => {
                        SolidPointLocation::Inside
                    }
                }
            }
        })
    }

    pub(in crate::topology) fn classify_point_against_sphere_pair(
        &self,
        pair: &CertifiedSpherePairShell,
        point: &Point3,
    ) -> Result<SolidPointLocation, QueryError> {
        let first = decided_model_order(compare_reals(
            &(point - &pair.first_center).norm_squared(),
            &(&pair.first_radius * &pair.first_radius),
            crate::STRICT_PREDICATES,
        ))?;
        let second = decided_model_order(compare_reals(
            &(point - &pair.second_center).norm_squared(),
            &(&pair.second_radius * &pair.second_radius),
            crate::STRICT_PREDICATES,
        ))?;
        Ok(match pair.kind {
            CertifiedSpherePairKind::Union => {
                if first == std::cmp::Ordering::Less || second == std::cmp::Ordering::Less {
                    SolidPointLocation::Inside
                } else if first == std::cmp::Ordering::Equal || second == std::cmp::Ordering::Equal
                {
                    SolidPointLocation::Boundary
                } else {
                    SolidPointLocation::Outside
                }
            }
            CertifiedSpherePairKind::Intersection => {
                if first == std::cmp::Ordering::Greater || second == std::cmp::Ordering::Greater {
                    SolidPointLocation::Outside
                } else if first == std::cmp::Ordering::Equal || second == std::cmp::Ordering::Equal
                {
                    SolidPointLocation::Boundary
                } else {
                    SolidPointLocation::Inside
                }
            }
            CertifiedSpherePairKind::Difference => match (first, second) {
                (std::cmp::Ordering::Greater, _) => SolidPointLocation::Outside,
                (std::cmp::Ordering::Equal, std::cmp::Ordering::Less) => {
                    SolidPointLocation::Outside
                }
                (std::cmp::Ordering::Equal, _) => SolidPointLocation::Boundary,
                (std::cmp::Ordering::Less, std::cmp::Ordering::Less) => SolidPointLocation::Outside,
                (std::cmp::Ordering::Less, std::cmp::Ordering::Equal) => {
                    SolidPointLocation::Boundary
                }
                (std::cmp::Ordering::Less, std::cmp::Ordering::Greater) => {
                    SolidPointLocation::Inside
                }
            },
        })
    }

    pub(in crate::topology) fn classify_point_against_torus(
        &self,
        torus: &CertifiedTorusShell,
        point: &Point3,
    ) -> Result<SolidPointLocation, QueryError> {
        let offset = point - &torus.center;
        let axial = offset.dot(&torus.axis);
        let region_boundary = match &torus.region {
            CertifiedTorusRegion::Whole => false,
            CertifiedTorusRegion::Axial { min, max }
            | CertifiedTorusRegion::SectorBand { min, max, .. } => {
                let min_order =
                    decided_model_order(compare_reals(&axial, min, crate::STRICT_PREDICATES))?;
                let max_order =
                    decided_model_order(compare_reals(&axial, max, crate::STRICT_PREDICATES))?;
                if min_order == std::cmp::Ordering::Less || max_order == std::cmp::Ordering::Greater
                {
                    return Ok(SolidPointLocation::Outside);
                }
                let angular_boundary =
                    if let CertifiedTorusRegion::SectorBand { angular, .. } = &torus.region {
                        match angular.classify_offset(&offset)? {
                            SolidPointLocation::Outside => return Ok(SolidPointLocation::Outside),
                            SolidPointLocation::Inside => false,
                            SolidPointLocation::Boundary => true,
                        }
                    } else {
                        false
                    };
                angular_boundary
                    || min_order == std::cmp::Ordering::Equal
                    || max_order == std::cmp::Ordering::Equal
            }
            CertifiedTorusRegion::LongitudinalHalf { interior_normal } => {
                match decided_model_order(compare_reals(
                    &offset.dot(interior_normal),
                    &Real::zero(),
                    crate::STRICT_PREDICATES,
                ))? {
                    std::cmp::Ordering::Less => return Ok(SolidPointLocation::Outside),
                    std::cmp::Ordering::Equal => true,
                    std::cmp::Ordering::Greater => false,
                }
            }
        };
        let radial = offset - torus.axis.clone() * &axial;
        let radial_squared = radial.norm_squared();
        let major_squared = &torus.major_radius * &torus.major_radius;
        let minor_squared = &torus.minor_radius * &torus.minor_radius;
        let implicit_base = &radial_squared + &axial * &axial + &major_squared - &minor_squared;
        let left = &implicit_base * &implicit_base;
        let right = Real::from(4) * major_squared * radial_squared;
        Ok(
            match decided_model_order(compare_reals(&left, &right, crate::STRICT_PREDICATES))? {
                std::cmp::Ordering::Less if region_boundary => SolidPointLocation::Boundary,
                std::cmp::Ordering::Less => SolidPointLocation::Inside,
                std::cmp::Ordering::Equal => SolidPointLocation::Boundary,
                std::cmp::Ordering::Greater => SolidPointLocation::Outside,
            },
        )
    }

    fn classify_point_against_axial(
        axial: &CertifiedAxialShell,
        point: &Point3,
    ) -> Result<SolidPointLocation, QueryError> {
        let offset = point - &axial.origin;
        let determinant = axial.u.dot(&axial.v.cross(&axial.axis));
        let x = (offset.dot(&axial.v.cross(&axial.axis)) / &determinant)
            .map_err(GeometryError::Numeric)?;
        let y = (axial.u.dot(&offset.cross(&axial.axis)) / &determinant)
            .map_err(GeometryError::Numeric)?;
        let height =
            (axial.u.dot(&axial.v.cross(&offset)) / determinant).map_err(GeometryError::Numeric)?;
        let point = hypercurve::CurvePoint2::from(CurvePoint2::new(x, y));
        let classify = |index: Option<usize>| -> Result<SolidPointLocation, QueryError> {
            let Some(band) = index.and_then(|i| axial.bands.get(i)) else {
                return Ok(SolidPointLocation::Outside);
            };
            Ok(
                match band
                    .region
                    .classify_point(&point)
                    .map_err(GeometryError::from)?
                {
                    RegionPointLocation::Inside => SolidPointLocation::Inside,
                    RegionPointLocation::Outside => SolidPointLocation::Outside,
                    RegionPointLocation::Boundary => SolidPointLocation::Boundary,
                },
            )
        };
        for (index, event) in axial.heights.iter().enumerate() {
            match decided_model_order(compare_reals(&height, event, crate::STRICT_PREDICATES))? {
                std::cmp::Ordering::Less => return classify(index.checked_sub(1)),
                std::cmp::Ordering::Equal => {
                    let a = classify(index.checked_sub(1))?;
                    let b = classify(Some(index))?;
                    return Ok(if a == b {
                        a
                    } else {
                        SolidPointLocation::Boundary
                    });
                }
                std::cmp::Ordering::Greater => {}
            }
        }
        Ok(SolidPointLocation::Outside)
    }

    pub(in crate::topology) fn classify_point_against_prism(
        &self,
        prism: &CertifiedPrismShell,
        point: &Point3,
    ) -> Result<SolidPointLocation, QueryError> {
        let displacement = point - &prism.origin;
        let determinant = prism.u.dot(&prism.v.cross(&prism.extrusion));
        let planar_u = (displacement.dot(&prism.v.cross(&prism.extrusion)) / &determinant)
            .map_err(GeometryError::Numeric)?;
        let planar_v = (prism.u.dot(&displacement.cross(&prism.extrusion)) / &determinant)
            .map_err(GeometryError::Numeric)?;
        let extrusion_parameter = (prism.u.dot(&prism.v.cross(&displacement)) / determinant)
            .map_err(GeometryError::Numeric)?;
        let min_order = decided_model_order(compare_reals(
            &extrusion_parameter,
            &prism.parameter_min,
            crate::STRICT_PREDICATES,
        ))?;
        let max_order = decided_model_order(compare_reals(
            &extrusion_parameter,
            &prism.parameter_max,
            crate::STRICT_PREDICATES,
        ))?;
        if min_order == std::cmp::Ordering::Less || max_order == std::cmp::Ordering::Greater {
            return Ok(SolidPointLocation::Outside);
        }
        let planar = hypercurve::CurvePoint2::from(CurvePoint2::new(planar_u, planar_v));
        let planar_location = match &prism.profile {
            CertifiedPrismProfile::Paths { outer, holes, .. } => {
                match crate::error::classified(outer.classify_point(&planar))
                    .map_err(GeometryError::from)?
                {
                    Classification::Decided(ContourPointLocation::Outside) => {
                        RegionPointLocation::Outside
                    }
                    Classification::Decided(ContourPointLocation::Boundary) => {
                        RegionPointLocation::Boundary
                    }
                    Classification::Decided(ContourPointLocation::Inside) => {
                        let mut location = RegionPointLocation::Inside;
                        for hole in holes {
                            match crate::error::classified(hole.classify_point(&planar))
                                .map_err(GeometryError::from)?
                            {
                                Classification::Decided(ContourPointLocation::Inside) => {
                                    location = RegionPointLocation::Outside;
                                    break;
                                }
                                Classification::Decided(ContourPointLocation::Boundary) => {
                                    location = RegionPointLocation::Boundary;
                                    break;
                                }
                                Classification::Decided(ContourPointLocation::Outside) => {}
                                Classification::Uncertain(reason) => {
                                    return Err(GeometryError::PlanarClassificationUnresolved(
                                        reason,
                                    )
                                    .into());
                                }
                            }
                        }
                        location
                    }
                    Classification::Uncertain(reason) => {
                        return Err(GeometryError::PlanarClassificationUnresolved(reason).into());
                    }
                }
            }
            CertifiedPrismProfile::CurveRegion { region, .. } => {
                match crate::error::classified(region.classify_point(&planar))
                    .map_err(GeometryError::from)?
                {
                    Classification::Decided(location) => location,
                    Classification::Uncertain(reason) => {
                        return Err(GeometryError::PlanarClassificationUnresolved(reason).into());
                    }
                }
            }
        };
        match planar_location {
            RegionPointLocation::Outside => return Ok(SolidPointLocation::Outside),
            RegionPointLocation::Boundary => return Ok(SolidPointLocation::Boundary),
            RegionPointLocation::Inside => {}
        }
        if min_order == std::cmp::Ordering::Equal || max_order == std::cmp::Ordering::Equal {
            Ok(SolidPointLocation::Boundary)
        } else {
            Ok(SolidPointLocation::Inside)
        }
    }

    /// Maps one face-local pcurve parameter to the shared edge's canonical
    /// curve parameter.
    ///
    /// The result is exact for both affine relations and native circular
    /// angular-sweep relations. No inverse floating-point projection or
    /// tolerance search is performed.
    pub fn edge_parameter_at(
        &self,
        edge_use: EdgeUseId,
        pcurve_parameter: &Parameter,
    ) -> Result<Parameter, QueryError> {
        crate::context::strict(|| {
            let edge_use_record = self
                .edge_use(edge_use)
                .ok_or(QueryError::InvalidReference {
                    kind: EntityKind::EdgeUse,
                    index: edge_use.index(),
                })?;
            let edge = self
                .edge(edge_use_record.edge)
                .expect("validated edge-use edge ID");
            let pcurve = self
                .pcurve(edge_use_record.pcurve)
                .expect("validated edge-use pcurve ID");
            edge_use_record
                .parameter_correspondence
                .edge_parameter(
                    pcurve,
                    &edge.domain,
                    edge_use_record.direction,
                    pcurve_parameter,
                )
                .map_err(QueryError::from)
        })
    }

    /// Maps one shared edge parameter back to a face-local pcurve parameter.
    ///
    /// Native circular pcurves replay directed angular fraction through
    /// Hypercurve's exact rational-conic inverse; no sampled projection is
    /// used.
    pub fn pcurve_parameter_at(
        &self,
        edge_use: EdgeUseId,
        edge_parameter: &Parameter,
    ) -> Result<Parameter, QueryError> {
        crate::context::strict(|| {
            let edge_use_record = self
                .edge_use(edge_use)
                .ok_or(QueryError::InvalidReference {
                    kind: EntityKind::EdgeUse,
                    index: edge_use.index(),
                })?;
            let edge = self
                .edge(edge_use_record.edge)
                .expect("validated edge-use edge ID");
            let pcurve = self
                .pcurve(edge_use_record.pcurve)
                .expect("validated edge-use pcurve ID");
            edge_use_record
                .parameter_correspondence
                .pcurve_parameter(
                    pcurve,
                    &edge.domain,
                    edge_use_record.direction,
                    edge_parameter,
                )
                .map_err(QueryError::from)
        })
    }

    pub(in crate::topology) fn classify_point_with_ray(
        &self,
        shell: ShellId,
        point: &Point3,
        direction: &Vector3,
    ) -> Result<Option<SolidPointLocation>, QueryError> {
        let mut crossings = 0_usize;
        for face_id in &self.shell(shell).expect("validated shell ID").faces {
            let (_, u, v) = self.face_plane(*face_id)?;
            let denominator = u.cross(v).dot(direction);
            if decided_model_order(compare_reals(
                &denominator,
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))? == std::cmp::Ordering::Equal
            {
                continue;
            }
            let plane_value = self.face_plane_value(*face_id, point)?;
            let parameter = ((-plane_value) / denominator).map_err(GeometryError::Numeric)?;
            match decided_model_order(compare_reals(
                &parameter,
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))? {
                std::cmp::Ordering::Less | std::cmp::Ordering::Equal => continue,
                std::cmp::Ordering::Greater => {}
            }
            let intersection = point.clone() + direction.clone() * parameter;
            match self.classify_point_on_face(*face_id, &intersection)? {
                Classification::Decided(ContourPointLocation::Inside) => crossings += 1,
                Classification::Decided(ContourPointLocation::Outside) => {}
                Classification::Decided(ContourPointLocation::Boundary)
                | Classification::Uncertain(hypercurve::UncertaintyReason::Boundary) => {
                    return Ok(None);
                }
                Classification::Uncertain(reason) => {
                    return Err(GeometryError::PlanarClassificationUnresolved(reason).into());
                }
            }
        }
        Ok(Some(if crossings.is_multiple_of(2) {
            SolidPointLocation::Outside
        } else {
            SolidPointLocation::Inside
        }))
    }

    pub(in crate::topology) fn classify_point_against_shell(
        &self,
        shell: ShellId,
        point: &Point3,
    ) -> Result<SolidPointLocation, QueryError> {
        let directions = [
            Vector3::x(),
            Vector3::y(),
            Vector3::z(),
            Vector3::from_xyz(Real::one(), Real::from(2), Real::from(4)),
        ];
        for direction in directions {
            if let Some(location) = self.classify_point_with_ray(shell, point, &direction)? {
                return Ok(location);
            }
        }
        Err(
            GeometryError::PlanarClassificationUnresolved(hypercurve::UncertaintyReason::Boundary)
                .into(),
        )
    }

    pub(in crate::topology) fn classify_point_against_cone_frustum(
        &self,
        frustum: &CertifiedConeFrustumShell,
        point: &Point3,
    ) -> Result<SolidPointLocation, QueryError> {
        let offset = point - &frustum.apex;
        let axial = offset.dot(&frustum.axis);
        let cosine = frustum.semi_angle.clone().cos();
        let v = (&axial / cosine).map_err(GeometryError::Numeric)?;
        let min_order =
            decided_model_order(compare_reals(&v, &frustum.v_min, crate::STRICT_PREDICATES))?;
        let max_order =
            decided_model_order(compare_reals(&v, &frustum.v_max, crate::STRICT_PREDICATES))?;
        if min_order == std::cmp::Ordering::Less || max_order == std::cmp::Ordering::Greater {
            return Ok(SolidPointLocation::Outside);
        }
        let radial = offset.clone() - frustum.axis.clone() * axial;
        let radius = v * frustum.semi_angle.clone().sin();
        let radial_order = decided_model_order(compare_reals(
            &radial.norm_squared(),
            &(&radius * &radius),
            crate::STRICT_PREDICATES,
        ))?;
        if radial_order == std::cmp::Ordering::Greater {
            return Ok(SolidPointLocation::Outside);
        }
        let region_boundary = match &frustum.region {
            CertifiedConeFrustumRegion::Whole => false,
            CertifiedConeFrustumRegion::Sector(angular) => {
                match angular.classify_offset(&offset)? {
                    SolidPointLocation::Outside => return Ok(SolidPointLocation::Outside),
                    SolidPointLocation::Inside => false,
                    SolidPointLocation::Boundary => true,
                }
            }
            CertifiedConeFrustumRegion::LongitudinalHalf { interior_normal } => {
                match decided_model_order(compare_reals(
                    &offset.dot(interior_normal),
                    &Real::zero(),
                    crate::STRICT_PREDICATES,
                ))? {
                    std::cmp::Ordering::Less => return Ok(SolidPointLocation::Outside),
                    std::cmp::Ordering::Equal => true,
                    std::cmp::Ordering::Greater => false,
                }
            }
        };
        if radial_order == std::cmp::Ordering::Equal
            || min_order == std::cmp::Ordering::Equal
            || max_order == std::cmp::Ordering::Equal
            || region_boundary
        {
            Ok(SolidPointLocation::Boundary)
        } else {
            Ok(SolidPointLocation::Inside)
        }
    }

    // The generic point classifier below casts rays against planar faces.
    // Solids with curved faces are classified by their certified family
    // records; any other curved face is an unsupported intersection, not an
    // invariant that admission guarantees.
    fn face_plane(&self, face: FaceId) -> Result<(&Point3, &Vector3, &Vector3), GeometryError> {
        let face = self.face(face).expect("validated face ID");
        let surface = self.surface(face.surface).expect("validated surface ID");
        match (surface.plane_origin(), surface.plane_directions()) {
            (Some(origin), Some((u, v))) => Ok((origin, u, v)),
            _ => Err(GeometryError::UnsupportedIntersection),
        }
    }

    pub(in crate::topology) fn face_plane_value(
        &self,
        face: FaceId,
        point: &Point3,
    ) -> Result<Real, GeometryError> {
        let (origin, u, v) = self.face_plane(face)?;
        Ok(u.cross(v).dot(&(point - origin)))
    }

    pub(in crate::topology) fn classify_point_on_face(
        &self,
        face: FaceId,
        point: &Point3,
    ) -> Result<Classification<ContourPointLocation>, GeometryError> {
        let (origin, u, v) = self.face_plane(face)?;
        let displacement = point - origin;
        let uu = u.dot(u);
        let uv = u.dot(v);
        let vv = v.dot(v);
        let du = displacement.dot(u);
        let dv = displacement.dot(v);
        let determinant = &uu * &vv - &uv * &uv;
        let parameter_u =
            ((&du * &vv - &dv * &uv) / &determinant).map_err(GeometryError::Numeric)?;
        let parameter_v =
            ((&dv * &uu - &du * &uv) / determinant).map_err(GeometryError::Numeric)?;
        let point = CurvePoint2::new(parameter_u, parameter_v);
        self.classify_surface_parameter_on_face(face, &point.into())
    }

    pub(crate) fn face_contours(&self, face: FaceId) -> Result<&[Contour2], GeometryError> {
        crate::cache::get_or_try_init(&self.data.face_contours[face.index()], || {
            self.build_face_contours(face)
        })
        .map(Vec::as_slice)
    }

    pub(in crate::topology) fn build_face_contours(
        &self,
        face: FaceId,
    ) -> Result<Vec<Contour2>, GeometryError> {
        let face = self.face(face).expect("validated face ID");
        face.boundary_wires()
            .map(|wire| self.build_model_wire_contour(*wire))
            .collect()
    }

    pub(in crate::topology) fn build_model_wire_contour(
        &self,
        wire: WireId,
    ) -> Result<Contour2, GeometryError> {
        let native = self
            .wire(wire)
            .expect("validated wire ID")
            .edge_uses
            .iter()
            .map(|edge_use| {
                let edge_use = self.edge_use(*edge_use).expect("validated edge-use ID");
                self.pcurve(edge_use.pcurve)
                    .expect("validated pcurve ID")
                    .segment()
            })
            .collect::<Result<Vec<_>, _>>();
        match native {
            Ok(segments) => return Contour2::try_new(segments).map_err(GeometryError::from),
            Err(GeometryError::UnsupportedPcurveContour) => {}
            Err(error) => return Err(error),
        }
        let segments = self
            .model_wire_curves(wire)?
            .into_iter()
            .map(|curve| crate::topology::wire_geometry::segment_image(&curve))
            .collect::<Result<Vec<_>, _>>()?;
        Contour2::try_new(segments).map_err(GeometryError::from)
    }

    pub(in crate::topology) fn build_model_wire_curve_path(
        &self,
        wire: WireId,
    ) -> Result<CurvePath2, GeometryError> {
        CurvePath2::try_new(self.model_wire_curves(wire)?).map_err(GeometryError::from)
    }

    fn model_wire_curves(&self, wire: WireId) -> Result<Vec<Curve2>, GeometryError> {
        let wire = self.wire(wire).expect("validated wire ID");
        let curves = wire
            .edge_uses
            .iter()
            .map(|edge_use| {
                let edge_use = self.edge_use(*edge_use).expect("validated edge-use ID");
                self.pcurve(edge_use.pcurve)
                    .expect("validated pcurve ID")
                    .curve()
                    .clone()
            })
            .collect();
        crate::topology::wire_geometry::coalesce_restrictions(curves)
    }

    pub(crate) fn classify_surface_parameter_on_face(
        &self,
        face: FaceId,
        point: &hypercurve::CurvePoint2,
    ) -> Result<Classification<ContourPointLocation>, GeometryError> {
        let face = self.face(face).expect("validated face ID");
        let FaceBoundary::Trimmed { outer, inner } = &face.boundary else {
            return Ok(Classification::Decided(ContourPointLocation::Inside));
        };
        match crate::error::classified(
            self.build_model_wire_curve_path(*outer)?
                .classify_point(point),
        )
        .map_err(GeometryError::from)?
        {
            Classification::Decided(ContourPointLocation::Outside) => {
                return Ok(Classification::Decided(ContourPointLocation::Outside));
            }
            Classification::Decided(ContourPointLocation::Boundary) => {
                return Ok(Classification::Decided(ContourPointLocation::Boundary));
            }
            Classification::Uncertain(reason) => {
                return Ok(Classification::Uncertain(reason));
            }
            Classification::Decided(ContourPointLocation::Inside) => {}
        }
        for wire in inner {
            match crate::error::classified(
                self.build_model_wire_curve_path(*wire)?
                    .classify_point(point),
            )
            .map_err(GeometryError::from)?
            {
                Classification::Decided(ContourPointLocation::Inside) => {
                    return Ok(Classification::Decided(ContourPointLocation::Outside));
                }
                Classification::Decided(ContourPointLocation::Boundary) => {
                    return Ok(Classification::Decided(ContourPointLocation::Boundary));
                }
                Classification::Decided(ContourPointLocation::Outside) => {}
                Classification::Uncertain(reason) => {
                    return Ok(Classification::Uncertain(reason));
                }
            }
        }
        Ok(Classification::Decided(ContourPointLocation::Inside))
    }

    /// A validated right-prism axis, including holes and native cylinder solids.
    /// This is a view of admission evidence, not recognition from sampled bounds.
    pub(crate) fn certified_right_prism_frame(
        &self,
        solid_id: SolidId,
    ) -> Result<Option<(Point3, Vector3)>, GeometryError> {
        let Some(solid) = self.solid(solid_id) else {
            return Ok(None);
        };
        if !solid.voids.is_empty() {
            return Ok(None);
        }
        if let Some(prism) = self
            .data
            .certified_prisms
            .get(solid_id.index())
            .and_then(Option::as_ref)
        {
            for direction in [&prism.u, &prism.v] {
                if decided_model_order(compare_reals(
                    &direction.dot(&prism.extrusion),
                    &Real::zero(),
                    crate::STRICT_PREDICATES,
                ))? != std::cmp::Ordering::Equal
                {
                    return Ok(None);
                }
            }
            return Ok(Some((
                prism.origin.clone(),
                prism
                    .extrusion
                    .clone()
                    .normalize_checked()
                    .map_err(GeometryError::Numeric)?,
            )));
        }
        Ok(self
            .certified_cylinder_profile(solid_id)
            .map(|cylinder| (cylinder.origin, cylinder.axis)))
    }

    pub(crate) fn certified_z_prism_profile(
        &self,
        solid_id: SolidId,
    ) -> Result<Option<CertifiedZPrismProfile>, GeometryError> {
        let Some(solid) = self.solid(solid_id) else {
            return Ok(None);
        };
        if !solid.voids.is_empty() {
            return Ok(None);
        }
        let shell = self
            .shell(solid.outer)
            .expect("validated solid shell reference");
        let certified_translation_family = self
            .data
            .certified_prisms
            .get(solid_id.index())
            .is_some_and(Option::is_some)
            || self
                .data
                .certified_cylinders
                .get(solid_id.index())
                .and_then(Option::as_ref)
                .is_some_and(|cylinder| cylinder.sphere_subtraction.is_none())
            || shell.faces.iter().all(|face| {
                matches!(
                    self.surface(self.face(*face).expect("validated shell face").surface())
                        .expect("validated face surface")
                        .kind(),
                    SurfaceKind::Plane | SurfaceKind::Extrusion
                )
            });
        if !certified_translation_family {
            return Ok(None);
        }
        let prism = self
            .data
            .certified_prisms
            .get(solid_id.index())
            .and_then(Option::as_ref);
        // Cold admission derives complete cap paths, while construction may
        // retain a CurveRegion directly. Both are shell certificates; neither
        // may be replaced by an endpoint polygon when a cap is nonlinear.
        let certified_region = || -> Result<Option<CurveRegion2>, GeometryError> {
            let Some(CertifiedPrismShell {
                profile,
                origin,
                u,
                v,
                extrusion,
                ..
            }) = prism
            else {
                return Ok(None);
            };
            let zero = Real::zero();
            let horizontal_profile =
                decided_model_order(compare_reals(&u.0[2], &zero, crate::STRICT_PREDICATES))?
                    == std::cmp::Ordering::Equal
                    && decided_model_order(compare_reals(
                        &v.0[2],
                        &zero,
                        crate::STRICT_PREDICATES,
                    ))? == std::cmp::Ordering::Equal;
            let vertical_extrusion = decided_model_order(compare_reals(
                &extrusion.0[0],
                &zero,
                crate::STRICT_PREDICATES,
            ))? == std::cmp::Ordering::Equal
                && decided_model_order(compare_reals(
                    &extrusion.0[1],
                    &zero,
                    crate::STRICT_PREDICATES,
                ))? == std::cmp::Ordering::Equal;
            if horizontal_profile && vertical_extrusion {
                let region = match profile {
                    CertifiedPrismProfile::CurveRegion { region, .. } => {
                        std::borrow::Cow::Borrowed(region)
                    }
                    CertifiedPrismProfile::Paths { outer, holes, .. } => {
                        let paths = std::iter::once(outer)
                            .chain(holes)
                            .cloned()
                            .collect::<Vec<_>>();
                        let roles = std::iter::once(hypercurve::CurveRegionLoopRole::Material)
                            .chain(std::iter::repeat_n(
                                hypercurve::CurveRegionLoopRole::Hole,
                                holes.len(),
                            ))
                            .collect::<Vec<_>>();
                        std::borrow::Cow::Owned(
                            CurveRegion2::try_from_boundary_paths_with_loop_semantics(
                                &paths,
                                &roles,
                                &vec![hypercurve::FillRule::NonZero; paths.len()],
                            )
                            .map_err(GeometryError::from)?,
                        )
                    }
                };
                let region = region
                    .transform_affine(&u.0[0], &v.0[0], &u.0[1], &v.0[1], &origin.x, &origin.y)
                    .map_err(GeometryError::from)?;
                return Ok(Some(region));
            }
            Ok(None)
        };
        let mut vertex_ids = HashSet::new();
        for face_id in &shell.faces {
            let face = self.face(*face_id).expect("validated shell face");
            for wire_id in face.boundary_wires() {
                let wire = self.wire(*wire_id).expect("validated face wire");
                for edge_use_id in &wire.edge_uses {
                    let edge_use = self
                        .edge_use(*edge_use_id)
                        .expect("validated wire edge use");
                    let edge = self.edge(edge_use.edge).expect("validated edge reference");
                    vertex_ids.insert(edge.start);
                    vertex_ids.insert(edge.end);
                    if edge_use.direction == Direction::Forward {
                        let endpoints = [edge.start, edge.end]
                            .map(|vertex| self.vertex(vertex).expect("validated vertex").point());
                        if endpoints
                            .iter()
                            .any(|point| point.try_coordinates().is_none())
                        {
                            // The complete admitted prism, its horizontal frame
                            // and vertical extrusion prove R x [z0,z1]. Selected
                            // cap subdivisions need no independent vertex scalars.
                            let (Some(prism), Some(region)) = (prism, certified_region()?) else {
                                return Ok(None);
                            };
                            let z0 = prism.origin.z.clone();
                            let z1 = &z0 + &prism.extrusion.0[2];
                            let (z_min, z_max) = match decided_model_order(compare_reals(
                                &z0,
                                &z1,
                                crate::STRICT_PREDICATES,
                            ))? {
                                std::cmp::Ordering::Less => (z0, z1),
                                std::cmp::Ordering::Greater => (z1, z0),
                                std::cmp::Ordering::Equal => return Ok(None),
                            };
                            return Ok(Some(CertifiedZPrismProfile {
                                region,
                                z_min,
                                z_max,
                            }));
                        }
                        let start = self
                            .vertex(edge.start)
                            .expect("validated vertex")
                            .represented_point()?;
                        let end = self
                            .vertex(edge.end)
                            .expect("validated vertex")
                            .represented_point()?;
                        // Two endpoint levels alone also describe a skew prism.
                        // A world-Z product requires its connecting edges to
                        // retain x/y, in addition to the admitted shell proof.
                        if !real_values_equal(&start.z, &end.z).map_err(build_error_geometry)?
                            && (!real_values_equal(&start.x, &end.x)
                                .map_err(build_error_geometry)?
                                || !real_values_equal(&start.y, &end.y)
                                    .map_err(build_error_geometry)?)
                        {
                            return Ok(None);
                        }
                    }
                }
            }
        }
        let Some(first_id) = vertex_ids.iter().next() else {
            return Ok(None);
        };
        let first = self
            .vertex(*first_id)
            .expect("validated vertex")
            .represented_point()?;
        let mut z_min = first.z.clone();
        let mut z_max = first.z.clone();
        for vertex_id in &vertex_ids {
            let z = &self
                .vertex(*vertex_id)
                .expect("validated vertex")
                .represented_point()?
                .z;
            if decided_model_order(compare_reals(z, &z_min, crate::STRICT_PREDICATES))?
                == std::cmp::Ordering::Less
            {
                z_min = z.clone();
            }
            if decided_model_order(compare_reals(z, &z_max, crate::STRICT_PREDICATES))?
                == std::cmp::Ordering::Greater
            {
                z_max = z.clone();
            }
        }
        if decided_model_order(compare_reals(&z_min, &z_max, crate::STRICT_PREDICATES))?
            != std::cmp::Ordering::Less
        {
            return Ok(None);
        }
        for vertex_id in &vertex_ids {
            let z = &self
                .vertex(*vertex_id)
                .expect("validated vertex")
                .represented_point()?
                .z;
            let at_min = decided_model_order(compare_reals(z, &z_min, crate::STRICT_PREDICATES))?
                == std::cmp::Ordering::Equal;
            let at_max = decided_model_order(compare_reals(z, &z_max, crate::STRICT_PREDICATES))?
                == std::cmp::Ordering::Equal;
            if !at_min && !at_max {
                return Ok(None);
            }
        }

        if prism
            .is_some_and(|prism| matches!(prism.profile, CertifiedPrismProfile::CurveRegion { .. }))
            && let Some(region) = certified_region()?
        {
            return Ok(Some(CertifiedZPrismProfile {
                region,
                z_min,
                z_max,
            }));
        }

        let mut top_region = None::<CurveRegion2>;
        for face_id in &shell.faces {
            let face = self.face(*face_id).expect("validated shell face");
            let mut profiles = Vec::with_capacity(face.inner().len() + 1);
            let mut is_top = true;
            for wire_id in face.boundary_wires() {
                let wire = self.wire(*wire_id).expect("validated cap wire");
                let mut segments = Vec::with_capacity(wire.edge_uses.len());
                for edge_use_id in &wire.edge_uses {
                    let (start, end) = self.directed_vertices(*edge_use_id);
                    let point = self
                        .vertex(start)
                        .expect("validated vertex")
                        .represented_point()?;
                    let endpoint = self
                        .vertex(end)
                        .expect("validated vertex")
                        .represented_point()?;
                    // A reversed side can start at the top cap. Reject its
                    // axial edge before projection could collapse it to a point.
                    if decided_model_order(compare_reals(
                        &point.z,
                        &z_max,
                        crate::STRICT_PREDICATES,
                    ))? != std::cmp::Ordering::Equal
                        || decided_model_order(compare_reals(
                            &endpoint.z,
                            &z_max,
                            crate::STRICT_PREDICATES,
                        ))? != std::cmp::Ordering::Equal
                    {
                        is_top = false;
                        break;
                    }
                    let segment = self.projected_model_cap_segment(*edge_use_id, point, endpoint);
                    match segment {
                        Ok(segment) => segments.push(segment),
                        Err(GeometryError::UnsupportedPcurveContour) => {
                            let region = certified_region()?
                                .ok_or(GeometryError::UnsupportedPcurveContour)?;
                            return Ok(Some(CertifiedZPrismProfile {
                                region,
                                z_min,
                                z_max,
                            }));
                        }
                        Err(error) => return Err(error),
                    }
                }
                if !is_top {
                    break;
                }
                profiles.push(Contour2::try_new(segments).map_err(GeometryError::from)?);
            }
            if is_top && !profiles.is_empty() {
                let outer = profiles.remove(0);
                let region = CurveRegion2::try_from_native_contours(vec![outer], profiles)
                    .map_err(GeometryError::from)?;
                // A shape-preserving partition can split a cap into several
                // faces. The profile is their complete material cover, not
                // whichever face happens to occur first in the arena.
                top_region = Some(match top_region {
                    None => region,
                    Some(previous) => previous
                        .boolean_region(&region, BooleanOp::Union)
                        .map_err(GeometryError::from)?,
                });
            }
        }
        Ok(top_region.map(|region| CertifiedZPrismProfile {
            region,
            z_min,
            z_max,
        }))
    }

    pub(crate) fn certified_sphere_profile(
        &self,
        solid: SolidId,
