            .and_then(Option::as_ref)
            .filter(|sphere| {
                sphere.voids.is_empty() && matches!(sphere.region, CertifiedSphereRegion::Whole)
            })
            .map(|sphere| CertifiedSphereProfile {
                center: sphere.center.clone(),
                radius: sphere.radius.clone(),
            })
    }

