            .get(solid.index())
            .and_then(Option::as_ref)?;
        Some(CertifiedRevolutionProfile {
            axis_origin: revolution.axis_origin.clone(),
            axis: revolution.axis.clone(),
            profile: revolution.profile.clone(),
            holes: revolution.voids.clone(),
        })
    }

    pub(in crate::topology) fn projected_model_cap_segment(
        &self,
        edge_use_id: EdgeUseId,
        start: &Point3,
        end: &Point3,
    ) -> Result<Segment2, GeometryError> {
        let edge_use = self
            .edge_use(edge_use_id)
            .expect("validated cap edge-use reference");
        let edge = self.edge(edge_use.edge).expect("validated cap edge");
        let curve = self.curve(edge.curve).expect("validated cap curve");
        match curve.kind() {
            Curve3Kind::Line => Ok(Segment2::Line(LineSeg2::try_new(
                CurvePoint2::new(start.x.clone(), start.y.clone()),
                CurvePoint2::new(end.x.clone(), end.y.clone()),
            )?)),
            Curve3Kind::CircleArc => {
                let Curve3ExactData::EllipseArc(data) = curve.exact_data() else {
                    unreachable!("circle kind carries ellipse-arc exact data");
                };
                let parameter = match edge_use.direction {
                    Direction::Forward => edge.domain.start(),
                    Direction::Reversed => edge.domain.end(),
                };
                let mut tangent = curve
                    .derivative_at(parameter, 1)?
                    .require_coordinates()?
                    .clone();
                if edge_use.direction == Direction::Reversed {
                    tangent = -tangent;
                }
                let radial_x = &start.x - &data.center.x;
                let radial_y = &start.y - &data.center.y;
                let cross = radial_x * &tangent.0[1] - radial_y * &tangent.0[0];
                let clockwise = match decided_model_order(compare_reals(
                    &cross,
                    &Real::zero(),
                    crate::STRICT_PREDICATES,
                ))? {
                    std::cmp::Ordering::Less => true,
                    std::cmp::Ordering::Greater => false,
                    std::cmp::Ordering::Equal => return Err(GeometryError::InvalidArcSweep),
                };
                Ok(Segment2::Arc(CircularArc2::try_from_center(
                    CurvePoint2::new(start.x.clone(), start.y.clone()),
                    CurvePoint2::new(end.x.clone(), end.y.clone()),
                    CurvePoint2::new(data.center.x, data.center.y),
                    clockwise,
                )?))
            }
            _ => Err(GeometryError::UnsupportedPcurveContour),
        }
    }
}

/// Orders of a point's section parameter against the domain ends, and the
/// point's profile coordinates in that section.
type SweepSection = (
    std::cmp::Ordering,
    std::cmp::Ordering,
    hypercurve::CurvePoint2,
);

/// Section orders and profile point of `point` in a monotone-progress sweep.
///
/// Plane progress is strictly monotone along the path, so the plane through
/// `point` parallel to the caps meets the path exactly once when the point's
/// level lies between the cap levels; `None` means the point is outside that
/// slab. A represented contact keeps the scalar profile projection. A
/// selected contact keeps its root: the profile point is the same root's image
/// on the path's exact control projection into the fixed profile frame.
fn monotone_sweep_section(
    sweep: &CertifiedCurveSweepShell,
    point: &Point3,
    start: &Point3,
    end: &Point3,
    u: &Vector3,
    v: &Vector3,
) -> Result<Option<SweepSection>, QueryError> {
    let normal = u.cross(v);
    let level = normal.dot(&Vector3::from(point.clone()));
    // A reflected model keeps its path; its progress then descends.
    let ascending = decided_model_order(compare_reals(
        &normal.dot(&(end - start)),
        &Real::zero(),
        crate::STRICT_PREDICATES,
    ))? == std::cmp::Ordering::Greater;
    let order = |cap: &Point3| -> Result<std::cmp::Ordering, QueryError> {
        let order = decided_model_order(compare_reals(
            &level,
            &normal.dot(&Vector3::from(cap.clone())),
            crate::STRICT_PREDICATES,
        ))?;
        Ok(if ascending { order } else { order.reverse() })
    };
    let lower_order = order(start)?;
    let upper_order = order(end)?;
    if lower_order == std::cmp::Ordering::Less || upper_order == std::cmp::Ordering::Greater {
        return Ok(None);
    }
    let path_point = if lower_order == std::cmp::Ordering::Equal {
        start.clone()
    } else if upper_order == std::cmp::Ordering::Equal {
        end.clone()
    } else {
        let section = Surface::plane(point.clone(), u.clone(), v.clone())?;
        let crate::CurveSurfaceIntersection::Points(contacts) =
            section.intersect_curve(&sweep.path)?
        else {
            return Err(GeometryError::UnsupportedIntersection.into());
        };
        // The progress certificate excludes any second contact.
        let [contact] = contacts.as_slice() else {
            return Err(GeometryError::UnsupportedIntersection.into());
        };
        match contact.point.try_coordinates() {
            Some(coordinates) => coordinates.clone(),
            None => {
                let Curve3ExactData::RationalBezier {
                    control_points,
                    weights,
                } = sweep.path.exact_data()
                else {
                    return Err(GeometryError::UnsupportedSelectedEvaluation.into());
                };
                let projected = control_points
                    .iter()
                    .map(|control| project_point_to_plane_frame(point, control, u, v))
                    .collect::<Result<Vec<_>, _>>()
                    .map_err(build_error_geometry)?;
                let image = Curve2::from(
                    RationalBezier2::try_new(projected, weights).map_err(GeometryError::from)?,
                );
                let profile_point = image
                    .point_at(&contact.parameter.curve_parameter())
                    .map_err(GeometryError::from)?;
                return Ok(Some((lower_order, upper_order, profile_point)));
            }
        }
    };
    let profile_point =
        project_point_to_plane_frame(point, &path_point, u, v).map_err(build_error_geometry)?;
    Ok(Some((lower_order, upper_order, profile_point.into())))
}

crates/hyperbrep/src/geometry/pcurve.rs:
//! Retained surface-parameter images and their exact spatial correspondence.

use super::*;

impl SurfaceIntersectionPcurve {
    pub(crate) fn materializes_native_boundary_segment(&self) -> bool {
        self.materializes_native_line()
            || match &self.mapping {
                SurfaceIntersectionPcurveMapping::PlaneProjection { spatial, .. } => {
                    spatial.kind() == Curve3Kind::CircleArc
                }
                SurfaceIntersectionPcurveMapping::RetainedCurve { curve } => {
                    matches!(curve.geometry(), Some(CurveGeometry2::CircularArc(_)))
                }
                _ => false,
            }
    }

    /// Whether materialization uses a native line carrier. This describes the
    /// retained representation, not a geometric straightness classification:
    /// rational/spline mappings retain their families even when collinear.
    pub(crate) fn materializes_native_line(&self) -> bool {
        match &self.mapping {
            SurfaceIntersectionPcurveMapping::TensorIsoU { .. }
            | SurfaceIntersectionPcurveMapping::TensorIsoV { .. } => {
                self.domain.try_real_endpoints().is_some()
            }
            SurfaceIntersectionPcurveMapping::PlaneProjection { spatial, .. } => {
                spatial.kind() == Curve3Kind::Line
            }
            SurfaceIntersectionPcurveMapping::LinearPlaneSection { profile, .. } => {
                profile.kind() == Curve3Kind::Line
            }
            SurfaceIntersectionPcurveMapping::RetainedCurve { curve } => {
                matches!(curve.geometry(), Some(CurveGeometry2::Line(_)))
            }
            SurfaceIntersectionPcurveMapping::Unsupported => false,
        }
    }

    pub(crate) fn is_iso_parameter_line(&self) -> bool {
        matches!(
            self.mapping,
            SurfaceIntersectionPcurveMapping::TensorIsoU { .. }
                | SurfaceIntersectionPcurveMapping::TensorIsoV { .. }
        )
    }

    pub(super) fn unsupported(domain: impl Into<ParameterRange>) -> Self {
        Self {
            domain: domain.into(),
            source_scale: Real::one(),
            source_offset: Real::zero(),
            mapping: SurfaceIntersectionPcurveMapping::Unsupported,
        }
    }

    pub(super) fn retained_curve(curve: Curve2) -> GeometryResult<Self> {
        let curve_domain = curve.parameter_domain();
        Ok(Self {
            domain: ParameterRange::new(
                Parameter::from_curve(curve_domain.start())?,
                Parameter::from_curve(curve_domain.end())?,
            )?,
            source_scale: Real::one(),
            source_offset: Real::zero(),
            mapping: SurfaceIntersectionPcurveMapping::RetainedCurve { curve },
        })
    }

    pub(super) fn plane_projection(curve: Curve3, plane: &PlaneSurface) -> Self {
        Self {
            domain: curve.domain().clone(),
            source_scale: Real::one(),
            source_offset: Real::zero(),
            mapping: SurfaceIntersectionPcurveMapping::PlaneProjection {
                spatial: curve,
                origin: plane.origin.clone(),
                u: plane.u.clone(),
                v: plane.v.clone(),
            },
        }
    }

    pub(super) fn linear_plane_section(
        profile: Curve3,
        plane: &PlaneSurface,
        denominator: Real,
        profile_axis: TensorAxis,
        coefficient_scale: Real,
        coefficient_offset: Real,
    ) -> Self {
        Self {
            domain: profile.domain().clone(),
            source_scale: Real::one(),
            source_offset: Real::zero(),
            mapping: SurfaceIntersectionPcurveMapping::LinearPlaneSection {
                profile,
                plane_origin: plane.origin.clone(),
                plane_normal: plane.u.cross(&plane.v),
                denominator,
                profile_axis,
                coefficient_scale,
                coefficient_offset,
            },
        }
    }

    pub(super) fn tensor_iso_v(domain: impl Into<ParameterRange>, constant: Real) -> Self {
        Self {
            domain: domain.into(),
            source_scale: Real::one(),
            source_offset: Real::zero(),
            mapping: SurfaceIntersectionPcurveMapping::TensorIsoV { constant },
        }
    }

    pub(super) fn tensor_iso(
        domain: impl Into<ParameterRange>,
        constant: Real,
        profile_axis: TensorAxis,
        coefficient_scale: Real,
        coefficient_offset: Real,
    ) -> Self {
        Self {
            domain: domain.into(),
            source_scale: coefficient_scale,
            source_offset: coefficient_offset,
            mapping: match profile_axis {
                TensorAxis::U => SurfaceIntersectionPcurveMapping::TensorIsoU { constant },
                TensorAxis::V => SurfaceIntersectionPcurveMapping::TensorIsoV { constant },
            },
        }
    }

    /// Returns the pcurve's parameter domain, shared exactly with the spatial
    /// intersection curve.
    pub const fn domain(&self) -> &ParameterRange {
        &self.domain
    }

    pub(crate) fn is_available(&self) -> bool {
        !matches!(self.mapping, SurfaceIntersectionPcurveMapping::Unsupported)
    }

    /// Evaluates the retained UV image at one spatial-curve parameter.
    ///
    /// Selected parameters and point images keep their source evidence. A
    /// stored coordinate view is optional, not a prerequisite for evaluation.
    /// Membership is checked before applying the source map. Native rational
    /// projections and section spans retain their charts; planar procedural
    /// projections require an admitted similarity of their source chart.
    pub fn point_at(&self, parameter: &Parameter) -> GeometryResult<hypercurve::CurvePoint2> {
        crate::context::strict(|| {
            if !self.domain.contains(parameter)? {
                return Err(GeometryError::ParameterOutsideDomain);
            }
            let source = parameter.affine_image(&self.source_scale, &self.source_offset)?;
            match &self.mapping {
                SurfaceIntersectionPcurveMapping::Unsupported => {
                    Err(GeometryError::UnsupportedIntersection)
                }
                SurfaceIntersectionPcurveMapping::RetainedCurve { curve } => {
                    Ok(curve.point_at(&source.curve_parameter())?)
                }
                SurfaceIntersectionPcurveMapping::PlaneProjection {
                    spatial,
                    origin,
                    u,
                    v,
                } => {
                    let point = spatial.point_at(&source)?;
                    if let Some(point) = point.try_coordinates() {
                        let uv = project_point_to_plane_frame(origin, u, v, point)?;
                        return Ok(CurvePoint2::new(uv.x, uv.y).into());
                    }
                    if let CurveGeometry3::PlanarImage(image) = &spatial.data.geometry {
                        let projected = image.materialize_plane_projection(origin, u, v)?;
                        let local =
                            source.affine_image(&image.source_scale, &image.source_offset)?;
                        return Ok(projected.curve.point_at(&local.curve_parameter())?);
                    }
                    let projected = project_curve_to_plane_frame(spatial, origin, u, v)?
                        .ok_or(GeometryError::UnsupportedSelectedEvaluation)?;
                    Ok(projected.point_at(&source.curve_parameter())?)
                }
                SurfaceIntersectionPcurveMapping::LinearPlaneSection {
                    profile,
                    plane_origin,
                    plane_normal,
                    denominator,
                    profile_axis,
                    coefficient_scale,
                    coefficient_offset,
                } => {
                    if let Some(parameter) = source.try_real() {
                        let profile_point = profile.evaluate_real(parameter)?;
                        let normalized = (plane_normal.dot(&(plane_origin - &profile_point))
                            / denominator)
                            .map_err(GeometryError::Numeric)?;
                        let coefficient = coefficient_offset + coefficient_scale * normalized;
                        return Ok(section_parameter_point(
                            parameter.clone(),
                            coefficient,
                            *profile_axis,
                        )
                        .into());
                    }
                    let carriers = linear_section_pcurve_carriers(
                        profile,
                        plane_origin,
                        plane_normal,
                        denominator,
                        *profile_axis,
                        coefficient_scale,
                        coefficient_offset,
                    )?
                    .ok_or(GeometryError::UnsupportedSelectedEvaluation)?;
                    for carrier in carriers {
                        let (scale, offset) = carrier
                            .correspondence
                            .affine_coefficients()
                            .ok_or(GeometryError::UnsupportedPcurveContour)?;
                        let inverse = (Real::one() / scale).map_err(GeometryError::Numeric)?;
                        let local = source
                            .affine_image(&inverse, &(-offset * &inverse))?
                            .curve_parameter();
                        let domain = carrier.curve.parameter_domain();
                        if local.compare(domain.start())? != Ordering::Less
                            && local.compare(domain.end())? != Ordering::Greater
                        {
                            return Ok(carrier.curve.point_at(&local)?);
                        }
                    }
                    Err(GeometryError::ParameterOutsideDomain)
                }
                SurfaceIntersectionPcurveMapping::TensorIsoV { constant } => Ok(source
                    .curve_parameter()
                    .affine_point(Real::one(), Real::zero(), Real::zero(), constant.clone())?),
                SurfaceIntersectionPcurveMapping::TensorIsoU { constant } => Ok(source
                    .curve_parameter()
                    .affine_point(Real::zero(), constant.clone(), Real::one(), Real::zero())?),
            }
        })
    }

    /// Restricts this exact surface-parameter mapping without changing its
    /// authoritative spatial-curve parameterization.
    /// Selected endpoints keep their defining relation and source chart.
    pub fn subcurve(&self, start: &Parameter, end: &Parameter) -> GeometryResult<Self> {
        crate::context::strict(|| {
            if !self.domain.contains(start)? || !self.domain.contains(end)? {
                return Err(GeometryError::ParameterOutsideDomain);
            }
            Ok(Self {
                domain: ParameterRange::new(start.clone(), end.clone())?,
                source_scale: self.source_scale.clone(),
                source_offset: self.source_offset.clone(),
                mapping: self.mapping.clone(),
            })
        })
    }

    /// Returns the same exact parameter-space image with reversed traversal.
    pub fn reversed(&self) -> GeometryResult<Self> {
        crate::context::strict(|| {
            let domain_sum = self
                .domain
                .try_real_endpoints()
                .map_or_else(Real::zero, |(a, b)| a + b);
            Ok(Self {
                domain: self.domain.affine_image(&-Real::one(), &domain_sum)?,
                source_scale: -self.source_scale.clone(),
                source_offset: &self.source_scale * domain_sum + &self.source_offset,
                mapping: self.mapping.clone(),
            })
        })
    }

    /// Materializes this retained mapping as one exact Hypercurve carrier.
    ///
    /// The returned correspondence maps native pcurve parameters to spatial
    /// parameters, including angular sweep correspondence for circular arcs.
    /// A mapping that cannot be represented by one Hypercurve carrier remains
    /// explicitly unsupported.
    pub fn materialize(&self) -> GeometryResult<MaterializedSurfacePcurve> {
        crate::context::strict(|| {
            if let Some(carrier) = self.materialize_selected_chart()? {
                return Ok(carrier);
            }
            if let SurfaceIntersectionPcurveMapping::PlaneProjection {
                spatial,
                origin,
                u,
                v,
            } = &self.mapping
                && let CurveGeometry3::PlanarImage(image) = &spatial.data.geometry
            {
                let range = self
                    .domain
                    .affine_image(&self.source_scale, &self.source_offset)?;
                let projected = image
                    .restricted_to(&range)?
                    .materialize_plane_projection(origin, u, v)?;
                let SurfacePcurveCorrespondence::Affine { scale, offset } =
                    projected.correspondence
                else {
                    unreachable!("planar projection retains an affine source chart");
                };
                return orient_affine_surface_pcurve(
                    projected.curve,
                    (scale / &self.source_scale).map_err(GeometryError::Numeric)?,
                    ((offset - &self.source_offset) / &self.source_scale)
                        .map_err(GeometryError::Numeric)?,
                    &self.domain,
                );
            }
            let source_start =
                &self.source_scale * self.domain.represented_start()? + &self.source_offset;
            let source_end =
                &self.source_scale * self.domain.represented_end()? + &self.source_offset;
            let source_order = decided_order(compare_reals(
                &source_start,
                &source_end,
                crate::STRICT_PREDICATES,
            ))?;
            if source_order == Ordering::Equal {
                return Err(GeometryError::InvalidParameterDomain);
            }
            let descending = source_order == Ordering::Greater;
            let (ordered_source_start, ordered_source_end) = if descending {
                (&source_end, &source_start)
            } else {
                (&source_start, &source_end)
            };
            let orient_curve = |curve: Curve2| -> GeometryResult<Curve2> {
                if descending {
                    curve.reversed().map_err(GeometryError::from)
                } else {
                    Ok(curve)
                }
            };
            // Materialized iso coordinates become boundary coefficients and
            // are interpolated by later edits. Preserve scalar-proven compact
            // angular forms before that expansion; no recognition limit or
            // spatial parameter correspondence changes.
            let compact =
                |value: &Real| value.compact_pi_laurent().unwrap_or_else(|| value.clone());
            match &self.mapping {
                SurfaceIntersectionPcurveMapping::Unsupported => {
                    Err(GeometryError::UnsupportedIntersection)
                }
                SurfaceIntersectionPcurveMapping::RetainedCurve { curve } => {
                    let domain = curve.parameter_domain();
                    let restricted = if decided_order(compare_reals(
                        ordered_source_start,
                        (domain.start())
                            .scalar()
                            .ok_or(GeometryError::UnsupportedPcurveContour)?,
                        crate::STRICT_PREDICATES,
                    ))? == Ordering::Equal
                        && decided_order(compare_reals(
                            ordered_source_end,
                            (domain.end())
                                .scalar()
                                .ok_or(GeometryError::UnsupportedPcurveContour)?,
                            crate::STRICT_PREDICATES,
                        ))? == Ordering::Equal
                    {
                        curve.clone()
                    } else {
                        curve.subcurve(
                            ordered_source_start.clone().into(),
                            ordered_source_end.clone().into(),
                        )?
                    };
                    materialized_surface_pcurve_from_matching_domains(
                        orient_curve(restricted)?,
                        &self.domain.represented_domain()?,
                    )
                }
                SurfaceIntersectionPcurveMapping::PlaneProjection {
                    spatial,
                    origin,
                    u,
                    v,
                } => {
                    let source_curve =
                        spatial.subcurve(ordered_source_start, ordered_source_end)?;
                    let curve = orient_curve(
                        project_curve_to_plane_frame(&source_curve, origin, u, v)?
                            .ok_or(GeometryError::UnsupportedIntersection)?,
                    )?;
                    if curve.family() == CurveFamily2::CircularArc {
                        Ok(MaterializedSurfacePcurve {
                            curve,
                            correspondence: SurfacePcurveCorrespondence::AngularSweep {
                                spatial_start: self.domain.represented_start()?.clone(),
                                spatial_end: self.domain.represented_end()?.clone(),
                            },
                        })
                    } else {
                        materialized_surface_pcurve_from_matching_domains(
                            curve,
                            &self.domain.represented_domain()?,
                        )
                    }
                }
                SurfaceIntersectionPcurveMapping::LinearPlaneSection { .. } => {
                    let mut carriers = self
                        .clipping_carriers()?
                        .ok_or(GeometryError::UnsupportedIntersection)?;
                    if carriers.len() == 1 {
                        return Ok(carriers.remove(0));
                    }
                    let mut curves = Vec::with_capacity(carriers.len());
                    let mut boundaries = Vec::with_capacity(carriers.len() + 1);
                    for carrier in carriers {
                        let domain = carrier.curve.parameter_domain();
                        let (start, end) = domain
                            .scalar_endpoints()
                            .ok_or(GeometryError::UnsupportedPcurveContour)?;
                        if boundaries.is_empty() {
                            boundaries.push(
                                carrier
                                    .spatial_parameter_at(&start.clone().into())?
                                    .try_real()
                                    .cloned()
                                    .ok_or(GeometryError::UnrepresentableParameter)?,
                            );
                        }
                        boundaries.push(
                            carrier
                                .spatial_parameter_at(&end.clone().into())?
                                .try_real()
                                .cloned()
                                .ok_or(GeometryError::UnrepresentableParameter)?,
                        );
                        curves.push(carrier.curve);
                    }
                    materialized_surface_pcurve_from_matching_domains(
                        concatenate_rational_bezier_spans_as_nurbs(&curves, &boundaries)?,
                        &self.domain.represented_domain()?,
                    )
                }
                SurfaceIntersectionPcurveMapping::TensorIsoV { constant } => {
                    let curve = orient_curve(Curve2::from(LineSeg2::try_new(
                        CurvePoint2::new(compact(ordered_source_start), compact(constant)),
                        CurvePoint2::new(compact(ordered_source_end), compact(constant)),
                    )?))?;
                    materialized_surface_pcurve_from_matching_domains(
                        curve,
                        &self.domain.represented_domain()?,
                    )
                }
                SurfaceIntersectionPcurveMapping::TensorIsoU { constant } => {
                    let curve = orient_curve(Curve2::from(LineSeg2::try_new(
                        CurvePoint2::new(compact(constant), compact(ordered_source_start)),
                        CurvePoint2::new(compact(constant), compact(ordered_source_end)),
                    )?))?;
                    materialized_surface_pcurve_from_matching_domains(
                        curve,
                        &self.domain.represented_domain()?,
                    )
                }
            }
        })
    }

    /// A selected interval keeps its source chart: dividing its endpoints to
    /// force a unit interval would discard their common root authority.
    fn materialize_selected_chart(&self) -> GeometryResult<Option<MaterializedSurfacePcurve>> {
        if !matches!(
            self.mapping,
            SurfaceIntersectionPcurveMapping::RetainedCurve { .. }
                | SurfaceIntersectionPcurveMapping::TensorIsoU { .. }
                | SurfaceIntersectionPcurveMapping::TensorIsoV { .. }
        ) {
            return Ok(None);
        }
        let selected = self.domain.try_real_endpoints().is_none()
            || matches!(&self.mapping, SurfaceIntersectionPcurveMapping::RetainedCurve { curve }
                if curve.parameter_domain().scalar_endpoints().is_none());
        if !selected {
            return Ok(None);
        }
        let range = self
            .domain
            .affine_image(&self.source_scale, &self.source_offset)?;
        let range = hypercurve::CurveParameterRange2::try_new(
            range.start().curve_parameter(),
            range.end().curve_parameter(),
        )?;
        let curve = match &self.mapping {
            SurfaceIntersectionPcurveMapping::RetainedCurve { curve } => {
                let domain = curve.parameter_domain();
                if range.start().compare(domain.start())? == Ordering::Equal
                    && range.end().compare(domain.end())? == Ordering::Equal
                {
                    curve.clone()
                } else {
                    curve.restrict_source(range)?
                }
            }
            SurfaceIntersectionPcurveMapping::TensorIsoU { constant }
            | SurfaceIntersectionPcurveMapping::TensorIsoV { constant } => {
                let constant = constant
                    .compact_pi_laurent()
                    .unwrap_or_else(|| constant.clone());
                let point = |t| match &self.mapping {
                    SurfaceIntersectionPcurveMapping::TensorIsoU { .. } => {
                        CurvePoint2::new(constant.clone(), t)
                    }
                    _ => CurvePoint2::new(t, constant.clone()),
                };
                // Enclosures choose a finite authored support, never the
                // retained endpoints. A degree-one spline has the original
                // source coordinate as its knot parameter, including exterior
                // values, without another normalized selected-root chart.
                // Hypercurve checks the exact restriction; SourceRange replays it.
                let lower = range
                    .start()
                    .scalar_bounds()
                    .ok_or(GeometryError::UnrepresentableParameter)?
                    .0
                    .clone();
                let upper = range
                    .end()
                    .scalar_bounds()
                    .ok_or(GeometryError::UnrepresentableParameter)?
                    .1
                    .clone();
                let span = &upper - &lower;
                require_positive(&span, GeometryError::InvalidParameterDomain)?;
                Curve2::from(hypercurve::NurbsCurve2::try_new(
                    1,
                    vec![point(lower.clone()), point(upper.clone())],
                    vec![Real::one(); 2],
                    vec![lower.clone(), lower, upper.clone(), upper],
                )?)
                .restrict_source(range)?
            }
            _ => return Ok(None),
        };
        let scale = (Real::one() / &self.source_scale).map_err(GeometryError::Numeric)?;
        orient_affine_surface_pcurve(
            curve,
            scale.clone(),
            -&self.source_offset * scale,
            &self.domain,
        )
        .map(Some)
    }

    pub(super) fn reparameterized_subcurve(
        &self,
        start: &Real,
        end: &Real,
        target_domain: &ParameterDomain,
    ) -> GeometryResult<Self> {
        if !self.domain.contains_real(start)? || !self.domain.contains_real(end)? {
            return Err(GeometryError::ParameterOutsideDomain);
        }
        let source_start = &self.source_scale * start + &self.source_offset;
        let source_end = &self.source_scale * end + &self.source_offset;
        let target_span = target_domain.end() - target_domain.start();
        let source_scale =
            ((&source_end - &source_start) / target_span).map_err(GeometryError::Numeric)?;
        let source_offset = source_start - &source_scale * target_domain.start();
        Ok(Self {
            domain: target_domain.clone().into(),
            source_scale,
            source_offset,
            mapping: self.mapping.clone(),
        })
    }

    pub(crate) fn clipping_carriers(
        &self,
    ) -> GeometryResult<Option<Vec<MaterializedSurfacePcurve>>> {
        let SurfaceIntersectionPcurveMapping::LinearPlaneSection {
            profile,
            plane_origin,
            plane_normal,
            denominator,
            profile_axis,
            coefficient_scale,
            coefficient_offset,
        } = &self.mapping
        else {
            return match self.materialize() {
                Ok(carrier) => Ok(Some(vec![carrier])),
                Err(GeometryError::UnsupportedIntersection) => Ok(None),
                Err(error) => Err(error),
            };
        };
        // Keep the native rational spans available to the trimming kernel.
        // Restriction and reversal must transport both their geometry and
        // parameters; the source profile's domain need not equal this trace's.
        let Some(carriers) = linear_section_pcurve_carriers(
            profile,
            plane_origin,
            plane_normal,
            denominator,
            *profile_axis,
            coefficient_scale,
            coefficient_offset,
        )?
        else {
            return Ok(None);
        };
        let source_start =
            &self.source_scale * self.domain.represented_start()? + &self.source_offset;
        let source_end = &self.source_scale * self.domain.represented_end()? + &self.source_offset;
        let descending = decided_order(compare_reals(
            &source_start,
            &source_end,
            crate::STRICT_PREDICATES,
        ))? == Ordering::Greater;
        let (source_start, source_end) = if descending {
            (source_end, source_start)
        } else {
            (source_start, source_end)
        };
        let mut result = Vec::with_capacity(carriers.len());
        for carrier in carriers {
            let (scale, offset) = carrier
                .correspondence
                .affine_coefficients()
                .ok_or(GeometryError::UnsupportedPcurveContour)?;
            let domain = carrier.curve.parameter_domain();
            let (local_start, local_end) = domain
                .scalar_endpoints()
                .ok_or(GeometryError::UnsupportedPcurveContour)?;
            let carrier_start = scale * local_start + offset;
            let carrier_end = scale * local_end + offset;
            let overlap_start = if decided_order(compare_reals(
                &source_start,
                &carrier_start,
                crate::STRICT_PREDICATES,
            ))? == Ordering::Greater
            {
                source_start.clone()
            } else {
                carrier_start
            };
            let overlap_end = if decided_order(compare_reals(
                &source_end,
                &carrier_end,
                crate::STRICT_PREDICATES,
            ))? == Ordering::Less
            {
                source_end.clone()
            } else {
                carrier_end
            };
            if decided_order(compare_reals(
                &overlap_start,
                &overlap_end,
                crate::STRICT_PREDICATES,
            ))? != Ordering::Less
            {
                continue;
            }
            let start = ((&overlap_start - offset) / scale).map_err(GeometryError::Numeric)?;
            let end = ((&overlap_end - offset) / scale).map_err(GeometryError::Numeric)?;
            let mut curve =
                if decided_order(compare_reals(&start, local_start, crate::STRICT_PREDICATES))?
                    == Ordering::Equal
                    && decided_order(compare_reals(&end, local_end, crate::STRICT_PREDICATES))?
                        == Ordering::Equal
                {
                    carrier.curve
                } else {
                    carrier.curve.subcurve(start.into(), end.into())?
                };
            let mut spatial_start = ((overlap_start - &self.source_offset) / &self.source_scale)
                .map_err(GeometryError::Numeric)?;
            let mut spatial_end = ((overlap_end - &self.source_offset) / &self.source_scale)
                .map_err(GeometryError::Numeric)?;
            if descending {
                curve = curve.reversed()?;
                std::mem::swap(&mut spatial_start, &mut spatial_end);
            }
            result.push(materialized_surface_pcurve_from_matching_domains(
                curve,
                &ParameterDomain::new(spatial_start, spatial_end)?,
            )?);
        }
        if descending {
            result.reverse();
        }
        Ok(Some(result))
    }
}

impl MaterializedSurfacePcurve {
    /// Returns the exact Hypercurve carrier.
    pub const fn curve(&self) -> &Curve2 {
        &self.curve
    }

    /// Returns the exact pcurve-to-spatial parameter correspondence.
    pub const fn correspondence(&self) -> &SurfacePcurveCorrespondence {
        &self.correspondence
    }

    /// Maps an incident pcurve parameter to the authoritative spatial parameter.
    ///
    /// Affine correspondence retains selected roots and their source evidence.
    /// Out-of-domain queries fail before applying the map. Angular endpoints
    /// preserve the two seam identities; an interior angular image still needs
    /// represented coordinates and otherwise fails with a typed blocker.
    pub fn spatial_parameter_at(
        &self,
        parameter: &hypercurve::CurveParameter2,
    ) -> GeometryResult<Parameter> {
        crate::context::strict(|| {
            let domain = self.curve.parameter_domain();
            if parameter.compare(domain.start())? == Ordering::Less
                || parameter.compare(domain.end())? == Ordering::Greater
            {
                return Err(GeometryError::ParameterOutsideDomain);
            }
            match &self.correspondence {
                SurfacePcurveCorrespondence::Affine { scale, offset } => {
                    Parameter::from_curve(parameter)?.affine_image(scale, offset)
                }
                SurfacePcurveCorrespondence::AngularSweep {
                    spatial_start,
                    spatial_end,
                } => {
                    // A periodic seam has two parameter identities even though
                    // its endpoint coordinates agree. Preserve the selected end
                    // before recovering an angle from the point's position.
                    if parameter.compare(domain.start())? == Ordering::Equal {
                        return Ok(spatial_start.clone().into());
                    }
                    if parameter.compare(domain.end())? == Ordering::Equal {
                        return Ok(spatial_end.clone().into());
                    }
                    let Some(CurveGeometry2::CircularArc(arc)) = self.curve.geometry() else {
                        return Err(GeometryError::UnsupportedPcurveContour);
                    };
                    let point = self.curve.point_at(parameter)?;
                    let point = point
                        .coordinates()
                        .ok_or(GeometryError::UnsupportedPcurveContour)?;
                    let fraction = match crate::error::classified(arc.sweep_fraction(point))? {
                        Classification::Decided(fraction) => fraction,
                        Classification::Uncertain(reason) => {
                            return Err(GeometryError::PlanarClassificationUnresolved(reason));
                        }
                    };
                    Ok((spatial_start + (spatial_end - spatial_start) * fraction).into())
                }
            }
        })
    }
}

crates/hyperbrep/src/persistence/selecti:
//! Untrusted selected-root and source graphs. No serialized proof flags.

use std::collections::HashMap;

use hypercurve::{
    BezierAlgebraicParameter2, BezierParameter2, BezierParameterInterval, BezierParameterPolynomial,
};

use super::*;
use crate::{GeometricPoint3, Parameter};

#[derive(Clone, Debug, Deserialize, Serialize)]
pub(super) enum RawParameter {
    Scalar(Real),
    Selected(usize),
}

#[derive(Clone, Debug, Deserialize, Serialize)]
pub(super) enum RawVertex {
    Coordinates([Real; 3]),
    SurfaceImage(Box<RawSurfacePoint>),
    CurveImage {
        source: RawPointSource,
        parameter: RawParameter,
    },
}

#[derive(Clone, Debug, Deserialize, Serialize)]
pub(super) enum RawPointSource {
    Model(usize),
    Detached(usize),
}

#[derive(Clone, Debug, Deserialize, Serialize)]
pub(super) enum RawSelection {
    PlanarPoint(Box<RawPlanarPoint>),
    Chord(Box<[RawPlanarPoint; 2]>),
    RationalForm {
        point: Box<RawPlanarPoint>,
        numerator: Vec<Vec<Real>>,
        denominator: Vec<Vec<Real>>,
    },
    AffineForm {
        point: Box<RawPlanarPoint>,
        coefficients: [Real; 3],
    },
    Root {
        polynomial: Vec<Real>,
        interval: [Real; 2],
    },
    Image {
        root: usize,
        numerator: [Real; 2],
        denominator: [Real; 2],
    },
}

#[derive(Clone, Debug, Default, Deserialize, Serialize)]
pub(super) struct RawSelectionGraph {
    parameters: Vec<RawSelection>,
    point_sources: Vec<RawCurve3>,
    pcurve_sources: Vec<RawPcurve>,
    pub(super) polynomial_sources: Vec<RawPolynomialSource>,
}

/// References are inserted in traversal order; hash iteration never affects bytes.
#[derive(Default)]
pub(super) struct GraphEncoder {
    pub(super) raw: RawSelectionGraph,
    selections: HashMap<String, usize>,
    point_sources: HashMap<usize, RawPointSource>,
    pcurve_sources: HashMap<String, usize>,
    pub(super) polynomial_sources: HashMap<String, usize>,
    pub(super) planar_points: Vec<(hypercurve::CurvePoint2, usize)>,
}

impl GraphEncoder {
    pub(super) fn new(model: &ArenaModel) -> Self {
        Self {
            point_sources: model
                .curves()
                .map(|(id, curve)| (curve.identity_address(), RawPointSource::Model(id.index())))
                .collect(),
            ..Self::default()
        }
    }

    pub(super) fn finish(self) -> RawSelectionGraph {
        self.raw
    }

    pub(super) fn parameter(
        &mut self,
        parameter: &Parameter,
    ) -> Result<RawParameter, PersistenceError> {
        self.curve_parameter(&parameter.curve_parameter())
    }

    pub(super) fn curve_parameter(
        &mut self,
        parameter: &hypercurve::CurveParameter2,
    ) -> Result<RawParameter, PersistenceError> {
        super::grow_stack(|| self.curve_parameter_unbounded(parameter))
    }

    fn curve_parameter_unbounded(
        &mut self,
        parameter: &hypercurve::CurveParameter2,
    ) -> Result<RawParameter, PersistenceError> {
        if let Some(form) = parameter.rational_form_source() {
            let point = Box::new(self.planar_point(form.source())?);
            return Ok(RawParameter::Selected(self.selection(
                RawSelection::RationalForm {
                    point,
                    numerator: form.numerator().coefficients.clone(),
                    denominator: form.denominator().coefficients.clone(),
                },
            )?));
        }
        if let Some(form) = parameter.affine_form_source() {
            let point = Box::new(self.planar_point(form.source())?);
            return Ok(RawParameter::Selected(self.selection(
                RawSelection::AffineForm {
                    point,
                    coefficients: form.coefficients().clone(),
                },
            )?));
        }
        match parameter
            .as_bezier_parameter()
            .ok_or(GeometryError::UnsupportedPcurveContour)?
        {
            BezierParameter2::Exact(value) => Ok(RawParameter::Scalar(value.clone())),
            BezierParameter2::Algebraic(root) => {
                let selected = match root.source_chart() {
                    None => self.root(root)?,
                    Some((source, numerator, denominator)) => {
                        let root = self.root(source)?;
                        // Inverse affine transports can retain an identity chart
                        // in memory. Its canonical archive reference is the root
                        // itself, just as checked replay will reconstruct it.
                        if numerator[0].zero_status() == hyperreal::ZeroKnowledge::Zero
                            && denominator[1].zero_status() == hyperreal::ZeroKnowledge::Zero
                            && (&numerator[1] - &denominator[0]).zero_status()
                                == hyperreal::ZeroKnowledge::Zero
                        {
                            root
                        } else {
                            self.selection(RawSelection::Image {
                                root,
                                numerator: numerator.clone(),
                                denominator: denominator.clone(),
                            })?
                        }
                    }
                };
                Ok(RawParameter::Selected(selected))
            }
        }
    }

    fn root(&mut self, root: &BezierAlgebraicParameter2) -> Result<usize, PersistenceError> {
        self.selection(RawSelection::Root {
            polynomial: root.polynomial().coefficients().to_vec(),
            interval: [
                root.interval().start().clone(),
                root.interval().end().clone(),
            ],
        })
    }

    pub(super) fn selection(&mut self, raw: RawSelection) -> Result<usize, PersistenceError> {
        let key = serde_json::to_string(&raw)
            .map_err(|error| PersistenceError::Json(error.to_string()))?;
        if let Some(index) = self.selections.get(&key) {
            return Ok(*index);
        }
        let index = self.raw.parameters.len();
        self.raw.parameters.push(raw);
        self.selections.insert(key, index);
        Ok(index)
    }

    pub(super) fn point(&mut self, point: &GeometricPoint3) -> Result<RawVertex, PersistenceError> {
        if let Some(point) = point.try_coordinates() {
            return Ok(RawVertex::Coordinates(point_array(point)));
        }
        if let Some((source, parameter)) = point.surface_source() {
            return Ok(RawVertex::SurfaceImage(Box::new(
                self.surface_point(source, parameter)?,
            )));
        }
        let (curve, parameter) = point
            .curve_source()
            .ok_or(GeometryError::UnrepresentablePoint)?;
        let source = if let Some(source) = self.point_sources.get(&curve.identity_address()) {
            source.clone()
        } else {
            let raw = raw_curve3(curve.exact_data(), self)?;
            let source = RawPointSource::Detached(self.raw.point_sources.len());
            self.raw.point_sources.push(raw);
            self.point_sources
                .insert(curve.identity_address(), source.clone());
            source
        };
        Ok(RawVertex::CurveImage {
            source,
            parameter: self.parameter(parameter)?,
        })
    }

    pub(super) fn pcurve(&mut self, curve: &Curve2) -> Result<RawPcurve, PersistenceError> {
        if let Some(branch) = curve.polynomial_branch() {
            return self.polynomial_branch(curve, branch);
        }
        if curve.family() == CurveFamily2::Line
            && curve.geometry().is_none()
            && curve.source_restriction().is_none()
        {
            let endpoints = [
                self.planar_point(&curve.start())?,
                self.planar_point(&curve.end())?,
            ];
            return Ok(RawPcurve::ChordReference(
                self.selection(RawSelection::Chord(Box::new(endpoints)))?,
            ));
        }
        if let Some(view) = curve.analytic_parallel() {
            return Ok(RawPcurve::AnalyticParallel(Box::new(RawParallelPcurve {
                source: raw_parallel_source(view.parallel().source()),
                distance: view.parallel().distance().clone(),
                range: [
                    self.curve_parameter(view.range().start())?,
                    self.curve_parameter(view.range().end())?,
                ],
                reversed: view.is_reversed(),
            })));
        }
        if let Some((source, range, reversed)) = curve.source_restriction() {
            let raw = raw_native_pcurve(source)?;
            let key = serde_json::to_string(&raw)
                .map_err(|error| PersistenceError::Json(error.to_string()))?;
            let source = *self.pcurve_sources.entry(key).or_insert_with(|| {
                let index = self.raw.pcurve_sources.len();
                self.raw.pcurve_sources.push(raw);
                index
            });
            Ok(RawPcurve::SourceRange {
                source,
                range: [
                    self.curve_parameter(range.start())?,
                    self.curve_parameter(range.end())?,
                ],
                reversed,
            })
        } else {
            raw_native_pcurve(curve)
        }
    }
}

enum SelectedGeometry {
    Parameter(hypercurve::CurveParameter2),
    Point(hypercurve::CurvePoint2),
    Chord(Curve2),
}

pub(super) struct SelectionGraph {
    definitions: Vec<SelectedGeometry>,
    point_sources: Vec<Curve3>,
    pub(super) pcurve_sources: Vec<Curve2>,
    pub(super) polynomial_sources: Vec<hypercurve::PolynomialCurveSet2>,
}

impl SelectionGraph {
    pub(super) fn validate(raw: RawSelectionGraph) -> Result<Self, PersistenceError> {
        let mut graph = Self {
            definitions: Vec::with_capacity(raw.parameters.len()),
            point_sources: Vec::new(),
            pcurve_sources: Vec::new(),
            polynomial_sources: raw
                .polynomial_sources
                .into_iter()
                .map(RawPolynomialSource::into_curves)
                .collect::<Result<_, _>>()?,
        };
        let mut roots = Vec::with_capacity(raw.parameters.len());
        for selection in raw.parameters {
            let is_root = matches!(&selection, RawSelection::Root { .. });
            let value = match selection {
                RawSelection::PlanarPoint(point) => {
                    let point = graph.planar_point(*point)?;
                    graph.definitions.push(SelectedGeometry::Point(point));
                    roots.push(false);
                    continue;
                }
                RawSelection::Chord(points) => {
                    let [start, end] = *points;
                    let chord =
                        Curve2::try_line(graph.planar_point(start)?, graph.planar_point(end)?)
                            .map_err(GeometryError::from)?;
                    graph.definitions.push(SelectedGeometry::Chord(chord));
                    roots.push(false);
                    continue;
                }
                RawSelection::Root {
                    polynomial,
                    interval: [start, end],
                } => {
                    let polynomial = BezierParameterPolynomial::try_new_power_basis(polynomial)
                        .map_err(GeometryError::from)?;
                    let interval = BezierParameterInterval::try_new(start, end)
                        .map_err(GeometryError::from)?;
                    hypercurve::CurveParameter2::from(BezierParameter2::Algebraic(
                        BezierAlgebraicParameter2::try_isolate(polynomial, interval)
                            .map_err(GeometryError::from)?,
                    ))
                }
                RawSelection::Image {
                    root,
                    numerator,
                    denominator,
                } => {
                    // Flat source graph: forward references, cycles and chart chains are invalid.
                    if roots.get(root) != Some(&true) {
                        return Err(PersistenceError::InvalidReference {
                            kind: "selected root",
                            index: root,
                        });
                    }
                    graph
                        .curve_parameter(RawParameter::Selected(root))?
                        .as_bezier_parameter()
                        .ok_or(GeometryError::UnrepresentableParameter)?
                        .projective_image(&numerator, &denominator)
                        .map_err(GeometryError::from)?
                        .into()
                }
                RawSelection::RationalForm {
                    point,
                    numerator,
                    denominator,
                } => graph
                    .planar_point(*point)?
                    .rational_form(
                        hypersolve::BivariatePolynomial::new(numerator),
                        hypersolve::BivariatePolynomial::new(denominator),
                    )
                    .map_err(GeometryError::from)?
                    .parameter()
                    .map_err(GeometryError::from)?,
                RawSelection::AffineForm {
                    point,
                    coefficients: [a, b, c],
                } => graph
                    .planar_point(*point)?
                    .affine_form(a, b, c)
                    .parameter()
                    .map_err(GeometryError::from)?,
            };
            graph.definitions.push(SelectedGeometry::Parameter(value));
            roots.push(is_root);
        }
        for raw in raw.pcurve_sources {
            // Source records cannot be nested restrictions.
            if let RawPcurve::SourceRange { source, .. } = raw {
                return Err(PersistenceError::InvalidReference {
                    kind: "authored pcurve source",
                    index: source,
                });
            }
            graph.pcurve_sources.push(pcurve(raw, &graph)?);
        }
        // Planar definitions depend only on the already validated parameter
        // graph. Spatial point sources can then depend on those definitions;
        // neither layer may refer back to the point-source graph.
        graph.point_sources = raw
            .point_sources
            .into_iter()
            .map(|raw| curve3(raw, &graph))
            .collect::<Result<_, _>>()?;
        Ok(graph)
    }

    pub(super) fn point_reference(
        &self,
        index: usize,
    ) -> Result<hypercurve::CurvePoint2, PersistenceError> {
        match self.definitions.get(index) {
            Some(SelectedGeometry::Point(point)) => Ok(point.clone()),
            _ => Err(PersistenceError::InvalidReference {
                kind: "planar point",
                index,
            }),
        }
    }

    pub(super) fn chord_reference(&self, index: usize) -> Result<Curve2, PersistenceError> {
        match self.definitions.get(index) {
            Some(SelectedGeometry::Chord(curve)) => Ok(curve.clone()),
            _ => Err(PersistenceError::InvalidReference {
                kind: "chord",
                index,
            }),
        }
    }

    pub(super) fn parameter(&self, raw: RawParameter) -> Result<Parameter, PersistenceError> {
        Ok(Parameter::from_curve(&self.curve_parameter(raw)?)?)
    }

    pub(super) fn curve_parameter(
        &self,
        raw: RawParameter,
    ) -> Result<hypercurve::CurveParameter2, PersistenceError> {
        super::grow_stack(|| self.curve_parameter_unbounded(raw))
    }

    fn curve_parameter_unbounded(
        &self,
        raw: RawParameter,
    ) -> Result<hypercurve::CurveParameter2, PersistenceError> {
        match raw {
            RawParameter::Scalar(value) => Ok(value.into()),
            RawParameter::Selected(index) => self
                .definitions
                .get(index)
                .and_then(|value| match value {
                    SelectedGeometry::Parameter(value) => Some(value.clone()),
                    _ => None,
                })
                .ok_or(PersistenceError::InvalidReference {
                    kind: "selected parameter",
                    index,
                }),
        }
    }

    pub(super) fn bezier_parameter(
        &self,
        raw: RawParameter,
    ) -> Result<BezierParameter2, PersistenceError> {
        self.curve_parameter(raw)?
            .as_bezier_parameter()
            .cloned()
            .ok_or_else(|| GeometryError::UnrepresentableParameter.into())
    }

    pub(super) fn point(
        &self,
        raw: RawVertex,
        curves: &[Curve3],
    ) -> Result<GeometricPoint3, PersistenceError> {
        match raw {
            RawVertex::Coordinates(point) => Ok(point3(point).into()),
            RawVertex::SurfaceImage(point) => self.surface_point(*point),
            RawVertex::CurveImage { source, parameter } => {
                let (sources, index) = match source {
                    RawPointSource::Model(index) => (curves, index),
                    RawPointSource::Detached(index) => (self.point_sources.as_slice(), index),
                };
                let curve = sources
                    .get(index)
                    .ok_or(PersistenceError::InvalidReference {
                        kind: "point source",
                        index,
                    })?;
                Ok(curve.point_at(&self.parameter(parameter)?)?)
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn graph_replays_projective_images_and_interns_one_source_root() {
        let root = BezierParameter2::Algebraic(
            BezierAlgebraicParameter2::try_isolate(
                BezierParameterPolynomial::try_new_power_basis(
                    [-1, -2, 0, 0, 0, 32].map(Real::from).to_vec(),
                )
                .unwrap(),
                BezierParameterInterval::try_new(Real::zero(), Real::one()).unwrap(),
            )
            .unwrap(),
        );
        let mapped = root
            .projective_image(&[Real::one(), Real::one()], &[Real::from(2), Real::one()])
            .unwrap();
        let original = Parameter::from_bezier(root);
        let mapped = Parameter::from_bezier(mapped);
        let mut encoder = GraphEncoder::default();
        let original_raw = encoder.parameter(&original).unwrap();
        let mapped_raw = encoder.parameter(&mapped).unwrap();
        let duplicate_raw = encoder.parameter(&mapped).unwrap();
        assert_eq!(encoder.raw.parameters.len(), 2);
        let json = serde_json::to_string(&encoder.raw).unwrap();
        let graph = SelectionGraph::validate(serde_json::from_str(&json).unwrap()).unwrap();
        let original_replay = graph.parameter(original_raw).unwrap();
        let mapped_replay = graph.parameter(mapped_raw).unwrap();
        assert_eq!(
            original.compare(&original_replay).unwrap(),
            std::cmp::Ordering::Equal
        );
        assert_eq!(
            mapped.compare(&mapped_replay).unwrap(),
            std::cmp::Ordering::Equal
        );
        assert_eq!(
            mapped_replay
                .compare(&graph.parameter(duplicate_raw).unwrap())
                .unwrap(),
            std::cmp::Ordering::Equal
        );
        assert!(mapped_replay.try_real().is_none());
        let mut replay_encoder = GraphEncoder::default();
        replay_encoder.parameter(&original_replay).unwrap();
        replay_encoder.parameter(&mapped_replay).unwrap();
        assert_eq!(serde_json::to_string(&replay_encoder.raw).unwrap(), json);
    }
}

crates/hyperbrep/src/topology/validation:
//! Validated construction: validation wire.

use crate::topology::*;

impl ArenaModelBuilder {
    pub(in crate::topology) fn validate_wire_orientation(
        &self,
        wire: WireId,
        orientation: Orientation,
        outer: bool,
        surface: SurfaceId,
    ) -> Result<(), BuildError> {
        let signed_area_order = match self.signed_wire_double_area(wire) {
            Ok(signed_double_area) => decided_model_order(compare_reals(
                &signed_double_area,
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))?,
            Err(BuildError::Geometry(GeometryError::UnsupportedPcurveContour)) => {
                let path = self.build_wire_curve_path(wire)?;
                let area = crate::error::classified(
                    path.boundary_loop()
                        .map_err(GeometryError::from)?
                        .signed_area(),
                )
                .map_err(GeometryError::from)?;
                let area = resolve_planar_classification(area)?;
                match area {
                    Some(area) => decided_model_order(compare_reals(
                        &area,
                        &Real::zero(),
                        crate::STRICT_PREDICATES,
                    ))?,
                    None => match self.tensor_graph_wire_orientation(wire, surface) {
                        Ok(order) => order,
                        Err(BuildError::Geometry(GeometryError::UnsupportedPcurveContour)) => {
                            curve_path_orientation(&path)?
                        }
                        Err(error) => return Err(error),
                    },
                }
            }
            Err(error) => return Err(error),
        };
        match signed_area_order {
            std::cmp::Ordering::Equal => Err(BuildError::DegenerateWireArea(wire)),
            value => {
                let expected = match (orientation, outer) {
                    (Orientation::Forward, true) | (Orientation::Reversed, false) => {
                        std::cmp::Ordering::Greater
                    }
                    (Orientation::Reversed, true) | (Orientation::Forward, false) => {
                        std::cmp::Ordering::Less
                    }
                };
                if value == expected {
                    Ok(())
                } else {
                    Err(BuildError::InconsistentWireOrientation(wire))
                }
            }
        }
    }

    pub(in crate::topology) fn tensor_graph_wire_orientation(
        &self,
        wire: WireId,
        surface: SurfaceId,
    ) -> Result<std::cmp::Ordering, BuildError> {
        let surface = self.surface_ref(surface)?;
        if !matches!(
            surface.kind(),
            SurfaceKind::RationalBezier | SurfaceKind::Nurbs
        ) {
            return Err(GeometryError::UnsupportedPcurveContour.into());
        }
        let SurfaceParameterDomain::Closed(u_domain) = surface.domain().u() else {
            return Err(GeometryError::UnsupportedPcurveContour.into());
        };
        let SurfaceParameterDomain::Closed(v_domain) = surface.domain().v() else {
            return Err(GeometryError::UnsupportedPcurveContour.into());
        };
        let wire = self.wire_ref(wire)?;
        let mut graph_endpoints = None;
        let mut has_left_boundary = false;
        let mut has_right_boundary = false;
        let mut has_bottom_boundary = false;
        let mut has_top_boundary = false;
        for edge_use in &wire.edge_uses {
            let pcurve = self.pcurve_ref(self.edge_use_ref(*edge_use)?.pcurve)?;
            match pcurve.curve().geometry() {
                Some(CurveGeometry2::RationalBezier(_)) | Some(CurveGeometry2::Nurbs(_)) => {
                    if graph_endpoints.is_some() {
                        return Err(GeometryError::UnsupportedPcurveContour.into());
                    }
                    let start = pcurve.curve().start();
                    let end = pcurve.curve().end();
                    graph_endpoints = Some((
                        start.clone(),
                        end.clone(),
                        decided_model_order(compare_reals(
                            (end)
                                .coordinates()
                                .ok_or(GeometryError::UnsupportedPcurveContour)?
                                .x(),
                            (start)
                                .coordinates()
                                .ok_or(GeometryError::UnsupportedPcurveContour)?
                                .x(),
                            crate::STRICT_PREDICATES,
                        ))?,
                        decided_model_order(compare_reals(
                            (end)
                                .coordinates()
                                .ok_or(GeometryError::UnsupportedPcurveContour)?
                                .y(),
                            (start)
                                .coordinates()
                                .ok_or(GeometryError::UnsupportedPcurveContour)?
                                .y(),
                            crate::STRICT_PREDICATES,
                        ))?,
                    ));
                }
                Some(CurveGeometry2::Line(line))
                    if real_values_equal(line.start().x(), line.end().x())? =>
                {
                    has_left_boundary |=
                        real_values_equal(line.start().x(), u_domain.represented_start()?)?;
                    has_right_boundary |=
                        real_values_equal(line.start().x(), u_domain.represented_end()?)?;
                }
                Some(CurveGeometry2::Line(line))
                    if real_values_equal(line.start().y(), line.end().y())? =>
                {
                    has_bottom_boundary |=
                        real_values_equal(line.start().y(), v_domain.represented_start()?)?;
                    has_top_boundary |=
                        real_values_equal(line.start().y(), v_domain.represented_end()?)?;
                }
                Some(CurveGeometry2::Line(_)) => {
                    return Err(GeometryError::UnsupportedPcurveContour.into());
                }
                _ => return Err(GeometryError::UnsupportedPcurveContour.into()),
            }
        }
        let (graph_start, graph_end, graph_u_direction, graph_v_direction) =
            graph_endpoints.ok_or(GeometryError::UnsupportedPcurveContour)?;
        let mut candidates = Vec::with_capacity(2);
        let graph_on_left = real_values_equal(
            (graph_start)
                .coordinates()
                .ok_or(GeometryError::UnsupportedPcurveContour)?
                .x(),
            u_domain.represented_start()?,
        )? && real_values_equal(
            (graph_end)
                .coordinates()
                .ok_or(GeometryError::UnsupportedPcurveContour)?
                .x(),
            u_domain.represented_start()?,
        )?;
        let graph_on_right = real_values_equal(
            (graph_start)
                .coordinates()
                .ok_or(GeometryError::UnsupportedPcurveContour)?
                .x(),
            u_domain.represented_end()?,
        )? && real_values_equal(
            (graph_end)
                .coordinates()
                .ok_or(GeometryError::UnsupportedPcurveContour)?
                .x(),
            u_domain.represented_end()?,
        )?;
        let effective_left = if graph_on_left != graph_on_right {
            Some(if graph_on_left {
                !has_right_boundary
            } else {
                has_left_boundary
            })
        } else if has_left_boundary != has_right_boundary {
            Some(has_left_boundary)
        } else {
            None
        };
        if graph_v_direction != std::cmp::Ordering::Equal
            && let Some(effective_left) = effective_left
        {
            candidates.push(match (graph_v_direction, effective_left) {
                (std::cmp::Ordering::Greater, true) | (std::cmp::Ordering::Less, false) => {
                    std::cmp::Ordering::Greater
                }
                (std::cmp::Ordering::Less, true) | (std::cmp::Ordering::Greater, false) => {
                    std::cmp::Ordering::Less
                }
                (std::cmp::Ordering::Equal, _) => unreachable!("equal graph span rejected"),
            });
        }
        let graph_on_bottom = real_values_equal(
            (graph_start)
                .coordinates()
                .ok_or(GeometryError::UnsupportedPcurveContour)?
                .y(),
            v_domain.represented_start()?,
        )? && real_values_equal(
            (graph_end)
                .coordinates()
                .ok_or(GeometryError::UnsupportedPcurveContour)?
                .y(),
            v_domain.represented_start()?,
        )?;
        let graph_on_top = real_values_equal(
            (graph_start)
                .coordinates()
                .ok_or(GeometryError::UnsupportedPcurveContour)?
                .y(),
            v_domain.represented_end()?,
        )? && real_values_equal(
            (graph_end)
                .coordinates()
                .ok_or(GeometryError::UnsupportedPcurveContour)?
                .y(),
            v_domain.represented_end()?,
        )?;
        let effective_bottom = if graph_on_bottom != graph_on_top {
            Some(if graph_on_bottom {
                !has_top_boundary
            } else {
                has_bottom_boundary
            })
        } else if has_bottom_boundary != has_top_boundary {
            Some(has_bottom_boundary)
        } else {
            None
        };
        if graph_u_direction != std::cmp::Ordering::Equal
            && let Some(effective_bottom) = effective_bottom
        {
            candidates.push(match (graph_u_direction, effective_bottom) {
                (std::cmp::Ordering::Less, true) | (std::cmp::Ordering::Greater, false) => {
                    std::cmp::Ordering::Greater
                }
                (std::cmp::Ordering::Greater, true) | (std::cmp::Ordering::Less, false) => {
                    std::cmp::Ordering::Less
                }
                (std::cmp::Ordering::Equal, _) => unreachable!("equal graph span rejected"),
            });
        }
        let Some(first) = candidates.first().copied() else {
            return Err(GeometryError::UnsupportedPcurveContour.into());
        };
        if candidates.iter().any(|candidate| *candidate != first) {
            return Err(GeometryError::UnsupportedPcurveContour.into());
        }
        Ok(first)
    }

    pub(in crate::topology) fn validate_spherical_trim(
        &self,
        wire: WireId,
        _orientation: Orientation,
    ) -> Result<(), BuildError> {
        let wire_record = self.wire_ref(wire)?;
        let mut first_u = None;
        let mut previous_u = None;
        let mut latitude = None;
        let mut direction = None;
        for edge_use_id in &wire_record.edge_uses {
            let edge_use = self.edge_use_ref(*edge_use_id)?;
            let pcurve = self.pcurve_ref(edge_use.pcurve)?;
            let Some(line) = pcurve.line_segment() else {
                return Err(BuildError::UnsupportedSphericalTrim(wire));
            };
            if !real_values_equal(line.start().y(), line.end().y())? {
                return Err(BuildError::UnsupportedSphericalTrim(wire));
            }
            if let Some(expected) = &latitude {
                if !real_values_equal(line.start().y(), expected)? {
                    return Err(BuildError::UnsupportedSphericalTrim(wire));
                }
            } else {
                latitude = Some(line.start().y().clone());
            }
            if let Some(previous) = &previous_u {
                if !real_values_equal(line.start().x(), previous)? {
                    return Err(BuildError::InvalidSphericalTrim(wire));
                }
            } else {
                first_u = Some(line.start().x().clone());
            }
            let segment_direction = decided_model_order(compare_reals(
                line.end().x(),
                line.start().x(),
                crate::STRICT_PREDICATES,
            ))?;
            if !matches!(
                segment_direction,
                std::cmp::Ordering::Less | std::cmp::Ordering::Greater
            ) || direction.is_some_and(|expected| expected != segment_direction)
            {
                return Err(BuildError::InvalidSphericalTrim(wire));
            }
            direction = Some(segment_direction);
            previous_u = Some(line.end().x().clone());
        }
        let latitude = latitude.ok_or(BuildError::UnsupportedSphericalTrim(wire))?;
        let half_pi = (Real::pi() / Real::from(2)).map_err(GeometryError::Numeric)?;
        if decided_model_order(compare_reals(
            &latitude,
            &-half_pi.clone(),
            crate::STRICT_PREDICATES,
        ))? != std::cmp::Ordering::Greater
            || decided_model_order(compare_reals(&latitude, &half_pi, crate::STRICT_PREDICATES))?
                != std::cmp::Ordering::Less
        {
            return Err(BuildError::InvalidSphericalTrim(wire));
        }
        let total = previous_u.expect("nonempty wire") - first_u.expect("nonempty wire");
        let expected = match direction.expect("nonempty wire") {
            std::cmp::Ordering::Greater => Real::tau(),
            std::cmp::Ordering::Less => -Real::tau(),
            std::cmp::Ordering::Equal => unreachable!("zero spans rejected"),
        };
        if !real_values_equal(&total, &expected)? {
            return Err(BuildError::InvalidSphericalTrim(wire));
        }
        Ok(())
    }

    pub(in crate::topology) fn spherical_trim_coordinates(
        &self,
        wire_id: WireId,
    ) -> Result<(Real, std::cmp::Ordering), BuildError> {
        let wire = self.wire_ref(wire_id)?;
        let first = self.pcurve_ref(self.edge_use_ref(wire.edge_uses[0])?.pcurve)?;
        let last = self.pcurve_ref(
            self.edge_use_ref(*wire.edge_uses.last().expect("validated nonempty wire"))?
                .pcurve,
        )?;
        let first = first
            .line_segment()
            .ok_or(BuildError::UnsupportedSphericalTrim(wire_id))?;
        let last = last
            .line_segment()
            .ok_or(BuildError::UnsupportedSphericalTrim(wire_id))?;
        Ok((
            first.start().y().clone(),
            decided_model_order(compare_reals(
                last.end().x(),
                first.start().x(),
                crate::STRICT_PREDICATES,
            ))?,
        ))
    }

    pub(in crate::topology) fn validate_wire_nesting(
        &self,
        outer: WireId,
        inner: &[WireId],
    ) -> Result<(), BuildError> {
        if inner.is_empty() {
            return Ok(());
        }
        let outer_path = self.build_wire_curve_path(outer)?;
        for wire in inner {
            let path = self.build_wire_curve_path(*wire)?;
            let intersection = outer_path
                .intersect_path(&path)
                .map_err(GeometryError::from)?;
            if !intersection.is_disjoint() {
                return Err(BuildError::IntersectingFaceWires {
                    first: outer,
                    second: *wire,
                });
            }
            match crate::error::classified(outer_path.classify_point(&path.start()))
                .map_err(GeometryError::from)?
            {
                Classification::Decided(ContourPointLocation::Inside) => {}
                Classification::Decided(_) => return Err(BuildError::InnerWireOutside(*wire)),
                Classification::Uncertain(reason) => {
                    return Err(BuildError::Geometry(
                        GeometryError::PlanarClassificationUnresolved(reason),
                    ));
                }
            }
        }
        for (index, first) in inner.iter().enumerate() {
            let first_path = self.build_wire_curve_path(*first)?;
            for second in &inner[(index + 1)..] {
                let second_path = self.build_wire_curve_path(*second)?;
                let intersection = first_path
                    .intersect_path(&second_path)
                    .map_err(GeometryError::from)?;
                if !intersection.is_disjoint() {
                    return Err(BuildError::IntersectingFaceWires {
                        first: *first,
                        second: *second,
                    });
                }
                let nested = classification_is_inside(
                    crate::error::classified(first_path.classify_point(&second_path.start()))
                        .map_err(GeometryError::from)?,
                )? || classification_is_inside(
                    crate::error::classified(second_path.classify_point(&first_path.start()))
                        .map_err(GeometryError::from)?,
                )?;
                if nested {
                    return Err(BuildError::NestedInnerWires {
                        first: *first,
                        second: *second,
                    });
                }
            }
        }
        Ok(())
    }

    pub(in crate::topology) fn validate_wire_simplicity(
        &self,
        wire: WireId,
    ) -> Result<(), BuildError> {
        if self.wire_ref(wire)?.edge_uses.iter().any(|usage| {
            let edge = &self.edges[self.edge_uses[usage.index()].edge.index()];
            self.curves[edge.curve.index()].kind() == Curve3Kind::PlanarImage
        }) {
            // A procedural support need not have an injective control hull.
            // The planar owner proves the complete original loop, including
            // individual-span injectivity, contacts and directed source charts.
            self.build_wire_curve_path(wire)?
                .simple_loop_orientation()
                .map_err(GeometryError::from)?;
            return Ok(());
        }
        if let Some(simple) = self.axis_aligned_line_wire_is_simple(wire)? {
            return if simple {
                Ok(())
            } else {
                Err(BuildError::SelfIntersectingWire(wire))
            };
        }
        if let Some(simple) = self.circular_arc_chord_wire_is_simple(wire)? {
            return if simple {
                Ok(())
            } else {
                Err(BuildError::SelfIntersectingWire(wire))
            };
        }
        if self.rational_quadratic_control_hull_wire_is_simple(wire)? == Some(true) {
            return Ok(());
        }
        self.validate_curve_path_simplicity(wire)
    }

    pub(in crate::topology) fn rational_quadratic_control_hull_wire_is_simple(
        &self,
        wire: WireId,
    ) -> Result<Option<bool>, BuildError> {
        let path = self.build_wire_curve_path(wire)?;
        if path.curves().len() < 2
            || path.curves().iter().any(|curve| {
                !matches!(
                    curve.geometry(),
                    Some(CurveGeometry2::RationalQuadraticBezier(_))
                )
            })
        {
            return Ok(None);
        }

        for curve in path.curves() {
            let fragments = curve
                .native_bezier_fragments()
                .map_err(GeometryError::from)?;
            if fragments.len() != 1
                || !fragments[0]
                    .has_certified_injective_axis()
                    .map_err(GeometryError::from)?
            {
                return Ok(None);
            }
            let Some(CurveGeometry2::RationalQuadraticBezier(curve)) = curve.geometry() else {
                unreachable!("family checked above");
            };
            let mut sign = None;
            for weight in curve.weights() {
                let order = decided_model_order(compare_reals(
                    weight,
                    &Real::zero(),
                    crate::STRICT_PREDICATES,
                ))?;
                if order == std::cmp::Ordering::Equal {
                    return Ok(None);
                }
                if sign.replace(order).is_some_and(|prior| prior != order) {
                    return Ok(None);
                }
            }
        }

        let controls = path
            .curves()
            .iter()
            .map(|curve| {
                let Some(CurveGeometry2::RationalQuadraticBezier(curve)) = curve.geometry() else {
                    unreachable!("family checked above");
                };
                curve.control_points()
            })
            .collect::<Vec<_>>();
        let exact_order = |left: &Real, right: &Real| match compare_reals(
            left,
            right,
            crate::STRICT_PREDICATES,
        ) {
            PredicateOutcome::Decided { value, .. } => Some(value),
            PredicateOutcome::Unknown { .. } => None,
        };
        let strictly_separated =
            |left: &[&CurvePoint2; 3], right: &[&CurvePoint2; 3], axis: usize| {
                left.iter().all(|left| {
                    right.iter().all(|right| {
                        exact_order(
                            curve_point_coordinate(left, axis),
                            curve_point_coordinate(right, axis),
                        ) == Some(std::cmp::Ordering::Less)
                    })
                })
            };
        let separated_at_shared_endpoint =
            |left: &[&CurvePoint2; 3],
             left_endpoint: usize,
             right: &[&CurvePoint2; 3],
             right_endpoint: usize,
             axis: usize,
             left_side: std::cmp::Ordering| {
                let boundary = curve_point_coordinate(left[left_endpoint], axis);
                if exact_order(
                    boundary,
                    curve_point_coordinate(right[right_endpoint], axis),
                ) != Some(std::cmp::Ordering::Equal)
                {
                    return false;
                }
                left.iter().enumerate().all(|(index, point)| {
                    exact_order(curve_point_coordinate(point, axis), boundary)
                        == Some(if index == left_endpoint {
                            std::cmp::Ordering::Equal
                        } else {
                            left_side
                        })
                }) && right.iter().enumerate().all(|(index, point)| {
                    exact_order(curve_point_coordinate(point, axis), boundary)
                        == Some(if index == right_endpoint {
                            std::cmp::Ordering::Equal
                        } else {
                            left_side.reverse()
                        })
                })
            };
        let separated_at_distinct_extremes =
            |left: &[&CurvePoint2; 3],
             right: &[&CurvePoint2; 3],
             axis: usize,
             left_side: std::cmp::Ordering| {
                let other_axis = 1 - axis;
                for left_extreme in 0..left.len() {
                    let boundary = curve_point_coordinate(left[left_extreme], axis);
                    for right_extreme in 0..right.len() {
                        if exact_order(boundary, curve_point_coordinate(right[right_extreme], axis))
                            != Some(std::cmp::Ordering::Equal)
                        {
                            continue;
                        }
                        let left_touches_once = left.iter().enumerate().all(|(index, point)| {
                            exact_order(curve_point_coordinate(point, axis), boundary)
                                == Some(if index == left_extreme {
                                    std::cmp::Ordering::Equal
                                } else {
                                    left_side
                                })
                        });
                        let right_touches_once = right.iter().enumerate().all(|(index, point)| {
                            exact_order(curve_point_coordinate(point, axis), boundary)
                                == Some(if index == right_extreme {
                                    std::cmp::Ordering::Equal
                                } else {
                                    left_side.reverse()
                                })
                        });
                        if left_touches_once
                            && right_touches_once
                            && exact_order(
                                curve_point_coordinate(left[left_extreme], other_axis),
                                curve_point_coordinate(right[right_extreme], other_axis),
                            )
                            .is_some_and(|order| order != std::cmp::Ordering::Equal)
                        {
                            return true;
                        }
                    }
                }
                false
            };

        for first in 0..controls.len() {
            for second in (first + 1)..controls.len() {
                let adjacent = second == first + 1 || (first == 0 && second + 1 == controls.len());
                let expected_controls = if second == first + 1 {
                    Some((2_usize, 0_usize))
                } else if adjacent {
                    Some((0_usize, 2_usize))
                } else {
                    None
                };
                let mut certified = false;
                for axis in 0..2 {
                    if !adjacent
                        && (strictly_separated(&controls[first], &controls[second], axis)
                            || strictly_separated(&controls[second], &controls[first], axis)
                            || [std::cmp::Ordering::Less, std::cmp::Ordering::Greater]
                                .into_iter()
                                .any(|side| {
                                    separated_at_distinct_extremes(
                                        &controls[first],
                                        &controls[second],
                                        axis,
                                        side,
                                    )
                                }))
                    {
                        certified = true;
                        break;
                    }
                    let Some((first_endpoint, second_endpoint)) = expected_controls else {
                        continue;
                    };
                    for first_side in [std::cmp::Ordering::Less, std::cmp::Ordering::Greater] {
                        if separated_at_shared_endpoint(
                            &controls[first],
                            first_endpoint,
                            &controls[second],
                            second_endpoint,
                            axis,
                            first_side,
                        ) {
                            certified = true;
                            break;
                        }
                    }
                    if certified {
                        break;
                    }
                }
                if !certified {
                    return Ok(None);
                }
            }
        }
        Ok(Some(true))
    }

    pub(in crate::topology) fn circular_arc_chord_wire_is_simple(
        &self,
        wire: WireId,
    ) -> Result<Option<bool>, BuildError> {
        let wire = self.wire_ref(wire)?;
        let mut arcs = Vec::with_capacity(wire.edge_uses.len().saturating_sub(1));
        let mut chords = Vec::new();
        let mut endpoints = Vec::with_capacity(wire.edge_uses.len());
        for (index, edge_use_id) in wire.edge_uses.iter().enumerate() {
            let edge_use = self.edge_use_ref(*edge_use_id)?;
            let pcurve = self.pcurve_ref(edge_use.pcurve)?;
            if let Some(arc) = pcurve.circular_arc() {
                arcs.push((index, arc));
                endpoints.push((arc.start().clone(), arc.end().clone()));
            } else if let Some(line) = pcurve.line_segment() {
                chords.push((index, line));
                endpoints.push((line.start().clone(), line.end().clone()));
            } else {
                return Ok(None);
            }
        }
        let Some((_, first_arc)) = arcs.first().copied() else {
            return Ok(None);
        };
        if chords.is_empty() {
            return Ok(None);
        }
        let point_equal = |left: &CurvePoint2, right: &CurvePoint2| -> Result<bool, BuildError> {
            Ok(real_values_equal(left.x(), right.x())? && real_values_equal(left.y(), right.y())?)
        };
        for index in 0..endpoints.len() {
            if !point_equal(
                &endpoints[index].1,
                &endpoints[(index + 1) % endpoints.len()].0,
            )? {
                return Ok(Some(false));
            }
        }

        let mut total_sweep = Real::zero();
        for (_, arc) in &arcs {
            if arc.is_clockwise() != first_arc.is_clockwise()
                || !point_equal(arc.center(), first_arc.center())?
                || !real_values_equal(arc.radius_squared_ref(), first_arc.radius_squared_ref())?
            {
                // Different supports or traversal directions are outside this
                // one-disk proof, not evidence of self-intersection (an annular
                // sector has both). The complete path validator owns them.
                return Ok(None);
            }
            let sweep = match crate::error::classified(arc.directed_sweep_angle())
                .map_err(GeometryError::from)?
            {
                Classification::Decided(sweep) => sweep,
                Classification::Uncertain(_) => return Ok(None),
            };
            total_sweep += sweep.abs();
        }
        if decided_model_order(compare_reals(
            &total_sweep,
            &Real::tau(),
            crate::STRICT_PREDICATES,
        ))? != std::cmp::Ordering::Less
        {
            return Ok(Some(false));
        }

        let adjacent = |first: usize, second: usize| {
            first + 1 == second
                || second + 1 == first
                || (first == 0 && second + 1 == endpoints.len())
                || (second == 0 && first + 1 == endpoints.len())
        };
        let allowed_shared_endpoint =
            |first: usize, second: usize, point: &CurvePoint2| -> Result<bool, BuildError> {
                // A two-edge wire is adjacent at both ends. The two cyclic
                // incidence tests must be independent for an arc and chord.
                Ok(((first + 1) % endpoints.len() == second
                    && point_equal(point, &endpoints[first].1)?)
                    || ((second + 1) % endpoints.len() == first
                        && point_equal(point, &endpoints[first].0)?))
            };

        for (arc_index, arc) in &arcs {
            for (segment_index, (start, end)) in endpoints.iter().enumerate() {
                if segment_index == *arc_index {
                    continue;
                }
                for point in [start, end] {
                    let on_sweep = match crate::error::classified(arc.contains_point(point))
                        .map_err(GeometryError::from)?
                    {
                        Classification::Decided(value) => value,
                        Classification::Uncertain(_) => return Ok(None),
                    };
                    if on_sweep
                        && (!adjacent(*arc_index, segment_index)
                            || !allowed_shared_endpoint(*arc_index, segment_index, point)?)
                    {
                        return Ok(Some(false));
                    }
                }
            }
        }

        // Every chord endpoint must stay in the closed disk. Convexity then
        // proves that the chord interior cannot cross the supporting circle;
        // the explicit chord/chord checks below handle the remaining possible
        // self-intersections. Allowing strict interior endpoints is essential
        // for radial sector wires produced by concurrent circular-face splits.
        for (_, chord) in &chords {
            for endpoint in [chord.start(), chord.end()] {
                if decided_model_order(compare_reals(
                    &endpoint.distance_squared(first_arc.center()),
                    first_arc.radius_squared_ref(),
                    crate::STRICT_PREDICATES,
                ))? == std::cmp::Ordering::Greater
                {
                    // An exterior chord can avoid the retained circular arc.
                    // Only the full curve relation can decide that case.
                    return Ok(None);
                }
            }
        }
        for first in 0..chords.len() {
            for second in (first + 1)..chords.len() {
                let (first_index, first_chord) = chords[first];
                let (second_index, second_chord) = chords[second];
                match first_chord
                    .intersect_line(second_chord)
                    .map_err(GeometryError::from)?
                {
                    LineLineIntersection::None => {}
                    LineLineIntersection::Point {
                        a_param, b_param, ..
                    } if adjacent(first_index, second_index) => {
                        let (expected_first, expected_second) = if first_index + 1 == second_index {
                            (Real::one(), Real::zero())
                        } else if second_index + 1 == first_index || first_index == 0 {
                            (Real::zero(), Real::one())
                        } else {
                            (Real::one(), Real::zero())
                        };
                        if !real_values_equal(&a_param, &expected_first)?
                            || !real_values_equal(&b_param, &expected_second)?
                        {
                            return Ok(Some(false));
                        }
                    }
                    LineLineIntersection::Point { .. } | LineLineIntersection::Overlap { .. } => {
                        return Ok(Some(false));
                    }
                    LineLineIntersection::Uncertain { .. } => return Ok(None),
                }
            }
        }
        Ok(Some(true))
    }

    pub(in crate::topology) fn axis_aligned_line_wire_is_simple(
        &self,
        wire: WireId,
    ) -> Result<Option<bool>, BuildError> {
        enum AxisLine {
            Horizontal { y: Real, min: Real, max: Real },
            Vertical { x: Real, min: Real, max: Real },
        }

        let ordered = |first: &Real, second: &Real| -> Result<(Real, Real), BuildError> {
            Ok(
                if decided_model_order(compare_reals(first, second, crate::STRICT_PREDICATES))?
                    == std::cmp::Ordering::Less
                {
                    (first.clone(), second.clone())
                } else {
                    (second.clone(), first.clone())
                },
            )
        };
        let wire_record = self.wire_ref(wire)?;
        let mut lines = Vec::with_capacity(wire_record.edge_uses.len());
        for edge_use in &wire_record.edge_uses {
            let edge_use = self.edge_use_ref(*edge_use)?;
            let pcurve = self.pcurve_ref(edge_use.pcurve)?;
            let Some(line) = pcurve.line_segment() else {
                return Ok(None);
            };
            if real_values_equal(line.start().y(), line.end().y())? {
                let (min, max) = ordered(line.start().x(), line.end().x())?;
                lines.push(AxisLine::Horizontal {
                    y: line.start().y().clone(),
                    min,
                    max,
                });
            } else if real_values_equal(line.start().x(), line.end().x())? {
                let (min, max) = ordered(line.start().y(), line.end().y())?;
                lines.push(AxisLine::Vertical {
                    x: line.start().x().clone(),
                    min,
                    max,
                });
            } else {
                return Ok(None);
            }
        }

        let contains = |min: &Real, value: &Real, max: &Real| -> Result<bool, BuildError> {
            Ok(
                decided_model_order(compare_reals(min, value, crate::STRICT_PREDICATES))?
                    != std::cmp::Ordering::Greater
                    && decided_model_order(compare_reals(value, max, crate::STRICT_PREDICATES))?
                        != std::cmp::Ordering::Greater,
            )
        };
        for first in 0..lines.len() {
            for second in (first + 1)..lines.len() {
                if second == first + 1 || (first == 0 && second + 1 == lines.len()) {
                    continue;
                }
                let intersects = match (&lines[first], &lines[second]) {
                    (
                        AxisLine::Horizontal {
                            y: first_y,
                            min: first_min,
                            max: first_max,
                        },
                        AxisLine::Horizontal {
                            y: second_y,
                            min: second_min,
                            max: second_max,
                        },
                    ) => {
                        real_values_equal(first_y, second_y)?
                            && (contains(first_min, second_min, first_max)?
                                || contains(second_min, first_min, second_max)?)
                    }
                    (
                        AxisLine::Vertical {
                            x: first_x,
                            min: first_min,
                            max: first_max,
                        },
                        AxisLine::Vertical {
                            x: second_x,
                            min: second_min,
                            max: second_max,
                        },
                    ) => {
                        real_values_equal(first_x, second_x)?
                            && (contains(first_min, second_min, first_max)?
                                || contains(second_min, first_min, second_max)?)
                    }
                    (
                        AxisLine::Horizontal { y, min, max },
                        AxisLine::Vertical {
                            x,
                            min: vertical_min,
                            max: vertical_max,
                        },
                    )
                    | (
                        AxisLine::Vertical {
                            x,
                            min: vertical_min,
                            max: vertical_max,
                        },
                        AxisLine::Horizontal { y, min, max },
                    ) => contains(min, x, max)? && contains(vertical_min, y, vertical_max)?,
                };
                if intersects {
                    return Ok(Some(false));
                }
            }
        }
        Ok(Some(true))
    }

    pub(in crate::topology) fn validate_curve_path_simplicity(
        &self,
        wire: WireId,
    ) -> Result<(), BuildError> {
        let path = self.build_wire_curve_path(wire)?;
        let curves = path.curves();
        if curves.len() == 2 {
            let relation = curves[0]
                .intersect_curve(&curves[1])
                .map_err(GeometryError::from)?;
            if !relation.is_complete()
                || !relation.overlaps().is_empty()
                || relation.contacts().len() != 2
            {
                return Err(BuildError::SelfIntersectingWire(wire));
            }
            let expected = [
                (
                    curves[0].parameter_endpoints().0,
                    curves[1].parameter_endpoints().1,
                ),
                (
                    curves[0].parameter_endpoints().1,
                    curves[1].parameter_endpoints().0,
                ),
            ];
            let mut matched = [false; 2];
            for contact in relation.contacts() {
                let first_parameter = resolve_planar_classification(
                    crate::error::classified(contact.first().parameter())
                        .map_err(GeometryError::from)?,
                )?;
                let second_parameter = resolve_planar_classification(
                    crate::error::classified(contact.second().parameter())
                        .map_err(GeometryError::from)?,
                )?;
                let mut found = None;
                for (index, (expected_first, expected_second)) in expected.iter().enumerate() {
                    if !matched[index]
                        && resolve_planar_classification(
                            crate::error::classified(first_parameter.compare(expected_first))
                                .map_err(GeometryError::from)?,
                        )?
                        .is_eq()
                        && resolve_planar_classification(
                            crate::error::classified(second_parameter.compare(expected_second))
                                .map_err(GeometryError::from)?,
                        )?
                        .is_eq()
                    {
                        found = Some(index);
                        break;
                    }
                }
                let Some(index) = found else {
                    return Err(BuildError::SelfIntersectingWire(wire));
                };
                matched[index] = true;
            }
            return if matched.into_iter().all(|value| value) {
                Ok(())
            } else {
                Err(BuildError::SelfIntersectingWire(wire))
            };
        }
        for first_index in 0..curves.len() {
            for second_index in (first_index + 1)..curves.len() {
                let relation = curves[first_index]
                    .intersect_curve(&curves[second_index])
                    .map_err(GeometryError::from)?;
                if !relation.is_complete() {
                    return Err(GeometryError::UnsupportedIntersection.into());
                }
                let adjacent = second_index == first_index + 1
                    || (first_index == 0 && second_index + 1 == curves.len());
                if !relation.overlaps().is_empty() {
                    return Err(BuildError::SelfIntersectingWire(wire));
                }
                if !adjacent {
                    if !relation.contacts().is_empty() {
                        return Err(BuildError::SelfIntersectingWire(wire));
                    }
                    continue;
                }
                let (expected_first, expected_second) = if second_index == first_index + 1 {
                    (
                        curves[first_index].parameter_endpoints().1,
                        curves[second_index].parameter_endpoints().0,
                    )
                } else {
                    (
                        curves[first_index].parameter_endpoints().0,
                        curves[second_index].parameter_endpoints().1,
                    )
                };
                if relation.contacts().len() != 1 {
                    return Err(BuildError::SelfIntersectingWire(wire));
                }
                let contact = &relation.contacts()[0];
                let first_parameter = resolve_planar_classification(
                    crate::error::classified(contact.first().parameter())
                        .map_err(GeometryError::from)?,
                )?;
                let second_parameter = resolve_planar_classification(
                    crate::error::classified(contact.second().parameter())
                        .map_err(GeometryError::from)?,
                )?;
                if !resolve_planar_classification(
                    crate::error::classified(first_parameter.compare(expected_first))
                        .map_err(GeometryError::from)?,
                )?
                .is_eq()
                    || !resolve_planar_classification(
                        crate::error::classified(second_parameter.compare(expected_second))
                            .map_err(GeometryError::from)?,
                    )?
                    .is_eq()
                {
                    return Err(BuildError::SelfIntersectingWire(wire));
                }
            }
        }
        Ok(())
    }

    pub(in crate::topology) fn build_wire_curve_path(
        &self,
        wire: WireId,
    ) -> Result<CurvePath2, BuildError> {
        Ok(CurvePath2::try_new(self.wire_validation_curves(wire)?).map_err(GeometryError::from)?)
    }

    /// Reassemble contiguous restrictions only for a boundary proof. The model
    /// keeps every edge, selected vertex, source chart and incidence unchanged.
    fn wire_validation_curves(&self, wire: WireId) -> Result<Vec<Curve2>, BuildError> {
        let curves = self
            .wire_ref(wire)?
            .edge_uses
            .iter()
            .map(|edge_use| {
                Ok(self
                    .pcurve_ref(self.edge_use_ref(*edge_use)?.pcurve)?
                    .curve()
                    .clone())
            })
            .collect::<Result<Vec<_>, BuildError>>()?;
        Ok(crate::topology::wire_geometry::coalesce_restrictions(
            curves,
        )?)
    }

    pub(in crate::topology) fn build_wire_contour(
        &self,
        wire: WireId,
    ) -> Result<Contour2, BuildError> {
        let native = self
            .wire_ref(wire)?
            .edge_uses
            .iter()
            .map(|edge_use| {
                Ok(self
                    .pcurve_ref(self.edge_use_ref(*edge_use)?.pcurve)?
                    .segment()?)
            })
            .collect::<Result<Vec<_>, BuildError>>();
        match native {
            Ok(segments) => return Ok(Contour2::try_new(segments).map_err(GeometryError::from)?),
            Err(BuildError::Geometry(GeometryError::UnsupportedPcurveContour)) => {}
            Err(error) => return Err(error),
        }
        let segments = self
            .wire_validation_curves(wire)?
            .into_iter()
            .map(|curve| crate::topology::wire_geometry::segment_image(&curve))
            .collect::<Result<Vec<_>, _>>()?;
        Ok(Contour2::try_new(segments).map_err(GeometryError::from)?)
    }

    pub(in crate::topology) fn signed_wire_double_area(
        &self,
        wire: WireId,
    ) -> Result<Real, BuildError> {
        let wire_record = self.wire_ref(wire)?;
        let mut line_area = Real::zero();
        let mut all_lines = true;
        for edge_use in &wire_record.edge_uses {
            let edge_use = self.edge_use_ref(*edge_use)?;
            let pcurve = self.pcurve_ref(edge_use.pcurve)?;
            let Some(line) = pcurve.line_segment() else {
                all_lines = false;
                break;
            };
            line_area += line.start().x() * line.end().y() - line.start().y() * line.end().x();
        }
        if all_lines {
            return Ok(line_area);
        }
        self.build_wire_contour(wire)?
            .signed_area()
            .map_err(GeometryError::from)?
            .map(|area| Real::from(2) * area)
            .ok_or(BuildError::DegenerateWireArea(wire))
    }
}

//! Validated construction: validation revolution.

use crate::topology::*;

impl ArenaModelBuilder {
    /// Coordinate-chart revolution faces require complete axis clearance on
    /// the retained profile, including during untrusted archive reconstruction.
    /// An image certificate for each boundary alone does not establish this.
    pub(in crate::topology) fn validate_retained_revolution_chart(
        &self,
        wires: &[WireId],
        surface: SurfaceId,
    ) -> Result<(), BuildError> {
        let surface = self.surface_ref(surface)?;
        if surface.kind() != SurfaceKind::Revolution {
            return Ok(());
        }
        for wire in wires {
            for edge_use in &self.wire_ref(*wire)?.edge_uses {
                if matches!(
                    self.edge_use_ref(*edge_use)?.parameter_correspondence,
                    ParameterCorrespondence::Coordinate { .. }
                ) {
                    return if surface.revolution_profile_is_strictly_off_axis()? {
                        Ok(())
                    } else {
                        Err(GeometryError::SingularSurfaceParameter.into())
                    };
                }
            }
        }
        Ok(())
    }

    pub(in crate::topology) fn certified_revolution_shell(
        &self,
        shell: ShellId,
    ) -> Result<Option<CertifiedRevolutionShell>, BuildError> {
        self.certified_oriented_revolution_shell(shell, Orientation::Forward)
    }

    pub(in crate::topology) fn certified_revolution_solid(
        &self,
        solid: &Solid,
    ) -> Result<Option<CertifiedRevolutionShell>, BuildError> {
        let Some(mut certificate) =
            self.certified_oriented_revolution_shell(solid.outer, Orientation::Forward)?
        else {
            return Ok(None);
        };
        for shell in &solid.voids {
            let Some(void) =
                self.certified_oriented_revolution_shell(*shell, Orientation::Reversed)?
            else {
                return Ok(None);
            };
            if !points_equal(&certificate.axis_origin, &void.axis_origin)?
                || !vectors_equal(&certificate.axis, &void.axis)?
            {
                return Ok(None);
            }
            certificate.voids.push(void.profile);
        }
        Ok(Some(certificate))
    }

    pub(in crate::topology) fn certified_oriented_revolution_shell(
        &self,
        shell: ShellId,
        orientation: Orientation,
    ) -> Result<Option<CertifiedRevolutionShell>, BuildError> {
        let faces = &self.shell_ref(shell)?.faces;
        if faces.len() < 8 {
            return Ok(None);
        }
        // The first source seeds the retained meridian cycle and its frame.
        // Preserve arena order across independent admissions so downstream
        // Booleans receive the same source charts, not a random cycle rotation.
        let mut groups = std::collections::BTreeMap::<SurfaceId, Vec<FaceId>>::new();
        let mut planar_faces = 0;
        for face_id in faces {
            let face = self.face_ref(*face_id)?;
            match self.surface_ref(face.surface)?.kind() {
                SurfaceKind::Revolution
                    if face.orientation == orientation && face.inner().is_empty() =>
                {
                    groups.entry(face.surface).or_default().push(*face_id);
                }
                SurfaceKind::Plane => planar_faces += 1,
                _ => return Ok(None),
            }
        }
        if groups.is_empty() || groups.values().any(|group| group.len() < 4) {
            return Ok(None);
        }

        let quarter = (Real::pi() / Real::from(2)).map_err(GeometryError::Numeric)?;
        let mut axis_origin = None;
        let mut axis = None;
        let mut meridian_ray: Option<Vector3> = None;
        let mut angular_origin: Option<Real> = None;
        let mut profile_curves = Vec::with_capacity(groups.len() + planar_faces);
        for (surface_id, group) in groups {
            let SurfaceExactData::Revolution {
                profile,
                axis_origin: this_origin,
                axis: this_axis,
            } = self.surface_ref(surface_id)?.exact_data()
            else {
                unreachable!("revolution kind carries revolution data");
            };
            if let Some(expected) = &axis_origin
                && !points_equal(expected, &this_origin)?
            {
                return Ok(None);
            }
            if let Some(expected) = &axis
                && !vectors_equal(expected, &this_axis)?
            {
                return Ok(None);
            }
            axis_origin.get_or_insert_with(|| this_origin.clone());
            axis.get_or_insert_with(|| this_axis.clone());
            let profile_curve = Curve3::from_exact_data(*profile)?;
            if profile_curve.kind() == Curve3Kind::PlanarImage {
                return self.certified_retained_revolution_shell(shell, orientation);
            }
            let mut to_profile_point = |point: &Point3,
                                        require_positive: bool|
             -> Result<Option<CurvePoint2>, BuildError> {
                let relative = point - &this_origin;
                let axial = this_axis.dot(&relative);
                let radial = relative - this_axis.clone() * &axial;
                let radial_squared = radial.norm_squared();
                let radial_order = decided_model_order(compare_reals(
                    &radial_squared,
                    &Real::zero(),
                    crate::STRICT_PREDICATES,
                ))?;
                if let Some(expected) = &meridian_ray {
                    if decided_model_order(compare_reals(
                        &expected.cross(&radial).norm_squared(),
                        &Real::zero(),
                        crate::STRICT_PREDICATES,
                    ))? != std::cmp::Ordering::Equal
                    {
                        return Ok(None);
                    }
                    let radius = expected.dot(&radial);
                    if require_positive
                        && decided_model_order(compare_reals(
                            &radius,
                            &Real::zero(),
                            crate::STRICT_PREDICATES,
                        ))? != std::cmp::Ordering::Greater
                    {
                        return Ok(None);
                    }
                    return Ok(Some(CurvePoint2::new(radius, axial)));
                }
                if radial_order != std::cmp::Ordering::Greater {
                    return if require_positive {
                        Ok(None)
                    } else {
                        Ok(Some(CurvePoint2::new(Real::zero(), axial)))
                    };
                }
                let radius = radial_squared.sqrt().map_err(GeometryError::Numeric)?;
                if require_positive {
                    meridian_ray = Some((radial / &radius).map_err(GeometryError::Numeric)?);
                } else {
                    return Ok(None);
                }
                Ok(Some(CurvePoint2::new(radius, axial)))
            };
            let mut u_values = Vec::new();
            let mut v_values = Vec::new();
            let mut face_coordinates = Vec::with_capacity(group.len());
            for face_id in group {
                let outer = self
                    .face_ref(face_id)?
                    .outer()
                    .expect("trimmed revolution face");
                let wire = self.wire_ref(outer)?;
                if wire.edge_uses.len() < 4 {
                    return Ok(None);
                }
                let mut face_u = Vec::with_capacity(wire.edge_uses.len() * 2);
                let mut face_v = Vec::with_capacity(wire.edge_uses.len() * 2);
                let mut parameter_segments = Vec::with_capacity(wire.edge_uses.len());
                for use_id in &self.wire_ref(outer)?.edge_uses {
                    let pcurve = self.pcurve_ref(self.edge_use_ref(*use_id)?.pcurve)?;
                    let Some(line) = pcurve.line_segment() else {
                        return Ok(None);
                    };
                    let u_constant = real_values_equal(line.start().x(), line.end().x())?;
                    let v_constant = real_values_equal(line.start().y(), line.end().y())?;
                    if u_constant == v_constant {
                        return Ok(None);
                    }
                    face_u.extend([line.start().x().clone(), line.end().x().clone()]);
                    face_v.extend([line.start().y().clone(), line.end().y().clone()]);
                    parameter_segments.push(Segment2::Line(line.clone()));
                }
                let (u_min, u_max) = exact_real_min_max(&face_u)?;
                let (v_min, v_max) = exact_real_min_max(&face_v)?;
                let contour = Contour2::try_new(parameter_segments).map_err(GeometryError::from)?;
                let represented_area = contour
                    .signed_area()
                    .map_err(GeometryError::from)?
                    .ok_or(BuildError::DegenerateShellVolume(shell))?
                    .abs();
                let rectangle_area = (&u_max - &u_min) * (&v_max - &v_min);
                if !real_values_equal(&represented_area, &rectangle_area)? {
                    return Ok(None);
                }
                insert_sorted_real(&mut u_values, &u_min)?;
                insert_sorted_real(&mut u_values, &u_max)?;
                insert_sorted_real(&mut v_values, &v_min)?;
                insert_sorted_real(&mut v_values, &v_max)?;
                face_coordinates.push((u_min, u_max, v_min, v_max));
            }
            if u_values.len() != 5 || v_values.len() < 2 {
                return Ok(None);
            }
            for pair in u_values.windows(2) {
                if !real_values_equal(&(&pair[1] - &pair[0]), &quarter)? {
                    return Ok(None);
                }
            }
            let mut covered_cells = HashSet::new();
            for (u_min, u_max, v_min, v_max) in face_coordinates {
                let u_start = exact_real_index(&u_values, &u_min)?;
                let u_end = exact_real_index(&u_values, &u_max)?;
                let v_start = exact_real_index(&v_values, &v_min)?;
                let v_end = exact_real_index(&v_values, &v_max)?;
                if u_end != u_start + 1 || v_start >= v_end {
                    return Ok(None);
                }
                for v_cell in v_start..v_end {
                    if !covered_cells.insert((u_start, v_cell)) {
                        return Ok(None);
                    }
                }
            }
            if covered_cells.len() != (u_values.len() - 1) * (v_values.len() - 1) {
                return Ok(None);
            }
            if !real_values_equal(
                &(u_values[3].clone() + &quarter - &u_values[0]),
                &(Real::from(2) * Real::pi()),
            )? {
                return Ok(None);
            }
            if let Some(expected) = &angular_origin {
                if !real_values_equal(expected, &u_values[0])? {
                    return Ok(None);
                }
            } else {
                angular_origin = Some(u_values[0].clone());
            }

            let represented_profile = profile_curve.subcurve(
                &v_values[0],
                v_values.last().expect("revolution group has v values"),
            )?;
            let start_point = represented_profile
                .evaluate_real(represented_profile.domain().represented_start()?)?;
            let end_point = represented_profile
                .evaluate_real(represented_profile.domain().represented_end()?)?;
            let Some(start) = to_profile_point(&start_point, true)? else {
                return Ok(None);
            };
            let Some(end) = to_profile_point(&end_point, true)? else {
                return Ok(None);
            };
            let profile_curve = match represented_profile.exact_data() {
                Curve3ExactData::Line(_) => {
                    Curve2::from(LineSeg2::try_new(start, end).map_err(GeometryError::from)?)
                }
                Curve3ExactData::RationalBezier {
                    control_points,
                    weights,
                } => {
                    let controls = control_points
                        .iter()
                        .map(|point| to_profile_point(point, false))
                        .collect::<Result<Option<Vec<_>>, _>>()?;
                    let Some(controls) = controls else {
                        return Ok(None);
                    };
                    planar_rational_bezier_curve(controls, weights.clone())?
                }
                Curve3ExactData::Nurbs {
                    degree,
                    control_points,
                    weights,
                    knots,
                } => {
                    let controls = control_points
                        .iter()
                        .map(|point| to_profile_point(point, false))
                        .collect::<Result<Option<Vec<_>>, _>>()?;
                    let Some(controls) = controls else {
                        return Ok(None);
                    };
                    if weights.iter().all(|weight| weight == &weights[0]) {
                        Curve2::try_polynomial_bspline(degree, controls, knots.clone())
                            .map_err(GeometryError::from)?
                    } else {
                        Curve2::try_nurbs(degree, controls, weights.clone(), knots.clone())
                            .map_err(GeometryError::from)?
                    }
                }
                Curve3ExactData::EllipseArc(data) if data.circle => {
                    let Some(center) = to_profile_point(&data.center, false)? else {
                        return Ok(None);
                    };
                    let ray = meridian_ray
                        .as_ref()
                        .expect("positive profile endpoint establishes a meridian ray");
                    let meridian_normal = this_axis.cross(ray);
                    if decided_model_order(compare_reals(
                        &data.x.dot(&meridian_normal),
                        &Real::zero(),
                        crate::STRICT_PREDICATES,
                    ))? != std::cmp::Ordering::Equal
                        || decided_model_order(compare_reals(
                            &data.y.dot(&meridian_normal),
                            &Real::zero(),
                            crate::STRICT_PREDICATES,
                        ))? != std::cmp::Ordering::Equal
                    {
                        return Ok(None);
                    }
                    let tangent = represented_profile
                        .derivative_at(
                            &represented_profile
                                .domain()
                                .represented_start()?
                                .clone()
                                .into(),
                            1,
                        )?
                        .require_coordinates()?
                        .clone();
                    let tangent_radial = ray.dot(&tangent);
                    let tangent_axial = this_axis.dot(&tangent);
                    let turn = (start.x() - center.x()) * &tangent_axial
                        - (start.y() - center.y()) * &tangent_radial;
                    let clockwise = match decided_model_order(compare_reals(
                        &turn,
                        &Real::zero(),
                        crate::STRICT_PREDICATES,
                    ))? {
                        std::cmp::Ordering::Less => true,
                        std::cmp::Ordering::Greater => false,
                        std::cmp::Ordering::Equal => return Ok(None),
                    };
                    let arc = CircularArc2::try_from_center(start, end, center, clockwise)
                        .map_err(GeometryError::from)?;
                    let sweep = match crate::error::classified(arc.directed_sweep_angle())
                        .map_err(GeometryError::from)?
                    {
                        Classification::Decided(sweep) => sweep,
                        Classification::Uncertain(reason) => {
                            return Err(BuildError::Geometry(
                                GeometryError::PlanarClassificationUnresolved(reason),
                            ));
                        }
                    };
                    if !real_values_equal(
                        sweep,
                        &(represented_profile.domain().represented_end()?
                            - represented_profile.domain().represented_start()?),
                    )? {
                        return Ok(None);
                    }
                    Curve2::from(arc)
                }
                _ => return Ok(None),
            };
            profile_curves.push(profile_curve);
        }
        if planar_faces > 0 {
            if orientation != Orientation::Forward {
                return Ok(None);
            }
            let Some(planar_segments) = self.certified_revolution_planar_profile_segments(
                faces,
                axis_origin
                    .as_ref()
                    .expect("revolution side faces establish an axis origin"),
                axis.as_ref()
                    .expect("revolution side faces establish an axis"),
            )?
            else {
                return Ok(None);
            };
            profile_curves.extend(planar_segments.into_iter().map(curve2_from_segment));
        }

        let mut ordered = Vec::with_capacity(profile_curves.len());
        ordered.push(profile_curves.remove(0));
        while !profile_curves.is_empty() {
            let end = ordered.last().expect("seeded profile").end();
            let mut matching = None;
            for (index, curve) in profile_curves.iter().enumerate() {
                if curve_points_equal(
                    (curve.start())
                        .coordinates()
                        .ok_or(GeometryError::UnsupportedPcurveContour)?,
                    (end)
                        .coordinates()
                        .ok_or(GeometryError::UnsupportedPcurveContour)?,
                )? && matching.replace(index).is_some()
                {
                    return Ok(None);
                }
            }
            let Some(index) = matching else {
                return Ok(None);
            };
            ordered.push(profile_curves.remove(index));
        }
        if !curve_points_equal(
            (ordered.last().expect("nonempty profile").end())
                .coordinates()
                .ok_or(GeometryError::UnsupportedPcurveContour)?,
            (ordered[0].start())
                .coordinates()
                .ok_or(GeometryError::UnsupportedPcurveContour)?,
        )? {
            return Ok(None);
        }
        let profile = if ordered.iter().all(|curve| {
            matches!(
                curve.geometry(),
                Some(CurveGeometry2::Line(_)) | Some(CurveGeometry2::CircularArc(_))
            )
        }) {
            let segments = ordered
                .into_iter()
                .map(|curve| match curve.geometry() {
                    Some(CurveGeometry2::Line(line)) => Segment2::Line(line.clone()),
                    Some(CurveGeometry2::CircularArc(arc)) => Segment2::Arc(arc.clone()),
                    _ => unreachable!("native revolution profile was prefiltered"),
                })
                .collect();
            let contour = Contour2::try_new(segments).map_err(GeometryError::from)?;
            let revolution_profile_area = contour.signed_area().map_err(GeometryError::from)?;
            if !contour
                .intersect_self()
                .map_err(GeometryError::from)?
                .is_empty()
                || decided_model_order(compare_reals(
                    &revolution_profile_area.ok_or(BuildError::DegenerateShellVolume(shell))?,
                    &Real::zero(),
                    crate::STRICT_PREDICATES,
                ))? != std::cmp::Ordering::Greater
            {
                return Ok(None);
            }
            CertifiedRevolutionBoundary::Native(contour)
        } else {
            let path = CurvePath2::try_new(ordered).map_err(GeometryError::from)?;
            let area = crate::error::classified(
                path.boundary_loop()
                    .map_err(GeometryError::from)?
                    .signed_area(),
            )
            .map_err(GeometryError::from)?;
            let area = resolve_planar_classification(area)?
                .ok_or(BuildError::DegenerateShellVolume(shell))?;
            if decided_model_order(compare_reals(
                &area,
                &Real::zero(),
                crate::STRICT_PREDICATES,
            ))? != std::cmp::Ordering::Greater
            {
                return Ok(None);
            }
            CertifiedRevolutionBoundary::Curved(path)
        };
        Ok(Some(CertifiedRevolutionShell {
            axis_origin: axis_origin.expect("revolution has faces"),
            axis: axis.expect("revolution has faces"),
            profile,
            voids: Vec::new(),
        }))
    }

    pub(in crate::topology) fn certified_revolution_planar_profile_segments(
        &self,
        faces: &[FaceId],
        axis_origin: &Point3,
        axis: &Vector3,
    ) -> Result<Option<Vec<Segment2>>, BuildError> {
        let groups = self.planar_face_groups(faces)?;
        if groups.is_empty() {
            return Ok(Some(Vec::new()));
        }
        let mut segments = Vec::with_capacity(groups.len());
        for group in groups {
            let Some(boundaries) = self.cap_boundary_use_loops(faces, &group)? else {
                return Ok(None);
            };
            if boundaries.len() != 2 {
                return Ok(None);
            }
            let mut center = None;
            let mut normal_direction = None;
            for index in &group {
                let face = self.face_ref(faces[*index])?;
                let surface = self.surface_ref(face.surface)?;
                let Some(origin) = surface.plane_origin() else {
                    return Ok(None);
                };
                let Some((u, v)) = surface.plane_directions() else {
                    return Ok(None);
                };
                let normal = match face.orientation {
                    Orientation::Forward => u.cross(v),
                    Orientation::Reversed => -u.cross(v),
                };
                if decided_model_order(compare_reals(
                    &normal.cross(axis).norm_squared(),
                    &Real::zero(),
                    crate::STRICT_PREDICATES,
                ))? != std::cmp::Ordering::Equal
                {
                    return Ok(None);
                }
                let direction = decided_model_order(compare_reals(
                    &normal.dot(axis),
                    &Real::zero(),
                    crate::STRICT_PREDICATES,
                ))?;
                if !matches!(
                    direction,
                    std::cmp::Ordering::Less | std::cmp::Ordering::Greater
                ) || normal_direction.is_some_and(|expected| expected != direction)
                {
                    return Ok(None);
                }
                normal_direction = Some(direction);
                let axial = axis.dot(&(origin - axis_origin));
                let candidate = axis_origin.clone() + axis.clone() * axial;
                if let Some(expected) = &center {
                    if !points_equal(expected, &candidate)? {
                        return Ok(None);
                    }
                } else {
                    center = Some(candidate);
                }
            }
            let center = center.expect("nonempty planar face group");
            let mut radii = Vec::with_capacity(2);
            for boundary in boundaries {
                let mut radius = None;
                let mut sweep = Real::zero();
                for edge_use_id in boundary {
                    let edge_use = self.edge_use_ref(edge_use_id)?;
                    let edge = self.edge_ref(edge_use.edge)?;
                    let curve = self.curve_ref(edge.curve)?;
                    let Curve3ExactData::EllipseArc(data) = curve.exact_data() else {
                        return Ok(None);
                    };
                    if !data.circle || !points_equal(&data.center, &center)? {
                        return Ok(None);
                    }
                    if let Some(expected) = &radius {
                        if !real_values_equal(expected, &data.x_radius)?
                            || !real_values_equal(expected, &data.y_radius)?
                        {
                            return Ok(None);
                        }
                    } else if !real_values_equal(&data.x_radius, &data.y_radius)? {
                        return Ok(None);
                    } else {
                        radius = Some(data.x_radius);
                    }
                    sweep += edge.domain.represented_end()? - edge.domain.represented_start()?;
                }
                if !real_values_equal(&sweep, &Real::tau())? {
                    return Ok(None);
                }
                radii.push(radius.expect("nonempty cap boundary"));
            }
            if decided_model_order(compare_reals(
                &radii[0],
                &radii[1],
                crate::STRICT_PREDICATES,
            ))? == std::cmp::Ordering::Equal
            {
                return Ok(None);
            }
            let (inner, outer) = if decided_model_order(compare_reals(
                &radii[0],
                &radii[1],
                crate::STRICT_PREDICATES,
            ))? == std::cmp::Ordering::Less
            {
                (radii.remove(0), radii.remove(0))
            } else {
                (radii.remove(1), radii.remove(0))
            };
            let axial = axis.dot(&(&center - axis_origin));
            let (start, end) = if normal_direction.expect("cap group has an effective normal")
                == std::cmp::Ordering::Greater
            {
                (
                    CurvePoint2::new(outer, axial.clone()),
                    CurvePoint2::new(inner, axial),
                )
            } else {
                (
                    CurvePoint2::new(inner, axial.clone()),
                    CurvePoint2::new(outer, axial),
                )
            };
            segments.push(Segment2::Line(
                LineSeg2::try_new(start, end).map_err(GeometryError::from)?,
            ));
        }
        Ok(Some(segments))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn cold_revolution_admission_preserves_profile_source_order() {
        let p = |x, y| CurvePoint2::from_values(x, y);
        let polygon = crate::construction::revolve(
            &[(4, -3), (6, -3), (6, 3), (4, 3)]
                .map(|(x, y)| crate::Point2::new(x.into(), y.into())),
        )
        .unwrap();
        let spline = CurvePath2::try_new(vec![
            Curve2::from(LineSeg2::try_new(p(2, 0), p(4, 0)).unwrap()),
            Curve2::try_nurbs(
                2,
                vec![p(4, 0), p(5, 1), p(4, 2)],
                vec![Real::one(); 3],
                vec![0.into(), 0.into(), 0.into(), 1.into(), 1.into(), 1.into()],
            )
            .unwrap(),
            Curve2::from(LineSeg2::try_new(p(4, 2), p(2, 2)).unwrap()),
            Curve2::from(LineSeg2::try_new(p(2, 2), p(2, 0)).unwrap()),
        ])
        .unwrap();
        let spline = crate::construction::revolve_path(&spline).unwrap();
        for (model, solid) in [polygon, spline] {
            let source = model.to_json().unwrap();
            let expected = model
                .certified_revolution_profile(solid)
                .unwrap()
                .profile
                .as_curve_path()
                .unwrap();
            // A fresh admission gets independent map seeds. A later Boolean
            // must see the same retained source sequence on every admission.
            for _ in 0..32 {
                let cold = crate::persistence::ImportedModel::from_json(
                    &source,
                    &crate::ArchiveLimits::default(),
                )
                .unwrap()
                .validate()
                .unwrap();
                let profile = cold
                    .certified_revolution_profile(solid)
                    .unwrap()
                    .profile
                    .as_curve_path()
                    .unwrap();
                assert_eq!(profile.curves(), expected.curves());
                assert_eq!(cold.to_json().unwrap(), source);
            }
        }
    }
}

//! Validated construction: validation analytic_image.

use crate::topology::*;

/// Compare complete profiles in charts differing only by parameter origin.
/// A reflected trimmed profile has the same span as its edge but can occupy
/// the opposite end of the parent domain. Preserve every carrier coefficient
/// and move only its parameter chart before using the existing full proof.
fn profile_parameterizations_equal(actual: &Curve3, expected: &Curve3) -> Result<bool, BuildError> {
    if curve_parameterizations_equal(actual, expected)? {
        return Ok(true);
    }
    let shift = actual.domain().represented_start()? - expected.domain().represented_start()?;
    if shift.zero_status() == hyperreal::ZeroKnowledge::Zero
        || !real_values_equal(
            actual.domain().represented_end()?,
            &(expected.domain().represented_end()? + &shift),
        )?
    {
        return Ok(false);
    }
    let data = match expected.exact_data() {
        Curve3ExactData::EllipseArc(mut arc) => {
            arc.domain_start = actual.domain().represented_start()?.clone();
            arc.domain_end = actual.domain().represented_end()?.clone();
            Curve3ExactData::EllipseArc(arc)
        }
        Curve3ExactData::Nurbs {
            degree,
            control_points,
            weights,
            knots,
        } => Curve3ExactData::Nurbs {
            degree,
            control_points,
            weights,
            knots: knots.into_iter().map(|knot| knot + &shift).collect(),
        },
        _ => return Ok(false),
    };
    curve_parameterizations_equal(actual, &Curve3::from_exact_data(data)?)
}

impl ArenaModelBuilder {
    pub(in crate::topology) fn validate_coordinate_surface_image(
        &self,
        curve: &Curve3,
        edge_use: &EdgeUse,
        pcurve: &Pcurve,
        surface: &Surface,
    ) -> Result<(), BuildError> {
        let ParameterCorrespondence::Coordinate {
            axis,
            scale,
            offset,
        } = &edge_use.parameter_correspondence
        else {
            return Err(BuildError::EdgeUseSupportMismatch);
        };
        if surface.kind() == SurfaceKind::Plane {
            return self.validate_coordinate_plane_image(curve, pcurve, surface, *axis, scale, offset);
        }
        // Exact line geometry plus a constant orthogonal coordinate proves the
        // full iso image, including selected endpoints. Endpoint coincidence
        // alone does not establish either assertion.
        if pcurve.kind() != CurveFamily2::Line {
            return Err(BuildError::EdgeUseSupportMismatch);
        }
        let first = pcurve.curve().start();
        let last = pcurve.curve().end();
        let (a, b) = match axis {
            hypercurve::Axis2::X => (Real::zero(), Real::one()),
            hypercurve::Axis2::Y => (Real::one(), Real::zero()),
        };
        let constant = Parameter::from_curve(
            &first
                .affine_form(a.clone(), b.clone(), Real::zero())
                .parameter()
                .map_err(GeometryError::from)?,
        )?;
        let last_constant = Parameter::from_curve(
            &last
                .affine_form(a, b, Real::zero())
                .parameter()
                .map_err(GeometryError::from)?,
        )?;
        if constant.compare(&last_constant)? != std::cmp::Ordering::Equal {
            return Err(BuildError::EdgeUseSupportMismatch);
        }
        if surface.kind() == SurfaceKind::Revolution {
            return self.validate_coordinate_revolution_image(
                curve, *axis, scale, offset, &constant, surface,
            );
        }
        let Some((profile, direction)) = surface.extrusion_profile_and_direction() else {
            return Err(BuildError::EdgeUseSupportMismatch);
        };
        match axis {
            hypercurve::Axis2::X => {
                let v = constant
                    .try_real()
                    .ok_or(GeometryError::UnrepresentableParameter)?;
                let expected = translated_curve(profile, &(direction.clone() * v))?;
                if curve_parameterizations_equal(curve, &expected)? {
                    require_real_equal(scale, &Real::one(), BuildError::EdgeUseSupportMismatch)?;
                    require_real_equal(offset, &Real::zero(), BuildError::EdgeUseSupportMismatch)
                } else if curve_parameterizations_equal(curve, &expected.reversed()?)? {
                    require_real_equal(scale, &(-Real::one()), BuildError::EdgeUseSupportMismatch)?;
                    require_real_equal(
                        offset,
                        &expected.reversal_pivot(),
                        BuildError::EdgeUseSupportMismatch,
                    )
                } else {
                    Err(BuildError::EdgeUseSupportMismatch)
                }
            }
            hypercurve::Axis2::Y => {
                let origin = profile.point_at(&constant)?;
                let inverse = (Real::one() / scale).map_err(GeometryError::Numeric)?;
                let translation = direction.clone() * (-offset * &inverse);
                let expected_origin =
                    origin.transformed(&Matrix4::affine_translation(translation.0))?;
                let expected_displacement = direction.clone() * inverse;
                let expected = Curve3::translation(expected_origin, expected_displacement)?;
                if curve_parameterizations_equal(curve, &expected)? {
                    Ok(())
                } else {
                    Err(BuildError::EdgeUseSupportMismatch)
                }
            }
        }
    }

    /// A regular plane chart can carry an authored rational boundary progress
    /// even when its derivative vanishes. Reprove its whole image and strict
    /// traversal on replay; endpoints and serialized flags are insufficient.
    fn validate_coordinate_plane_image(
        &self,
        curve: &Curve3,
        pcurve: &Pcurve,
        surface: &Surface,
        axis: hypercurve::Axis2,
        scale: &Real,
        offset: &Real,
    ) -> Result<(), BuildError> {
        let Curve3ExactData::Line(line) = curve.exact_data() else {
            return Err(BuildError::EdgeUseSupportMismatch);
        };
        let source = pcurve.curve().source_restriction().map(|(source, _, _)| source).unwrap_or(pcurve.curve());
        let (points, weights) = match source.geometry() {
            Some(CurveGeometry2::Line(line)) => (vec![line.start().clone(), line.end().clone()], vec![Real::one(); 2]),
            Some(CurveGeometry2::RationalBezier(source)) => (
                source.affine_control_points().ok_or(BuildError::EdgeUseSupportMismatch)?.to_vec(), source.weights().to_vec(),
            ),
            _ => return Err(BuildError::EdgeUseSupportMismatch),
        };
        let origin = surface.plane_origin().expect("plane image");
        let (u, v) = surface.plane_directions().expect("plane image");
        let lifted = points.iter().map(|p| origin.clone() + u.clone() * p.x() + v.clone() * p.y()).collect::<Vec<_>>();
        let direction = &lifted[lifted.len() - 1] - &lifted[0];
        // This also validates positive denominator guards before certifying
        // the finite source's injectivity and endpoint coverage.
        Curve3::rational_bezier(lifted.clone(), weights.clone())?;
        if crate::geometry::certified_straight_sweep_image(&lifted, &weights, &direction)?.is_none() {
            return Err(BuildError::EdgeUseSupportMismatch);
        }
        for (point, lifted) in points.iter().zip(lifted) {
            let coordinate = match axis { hypercurve::Axis2::X => point.x(), hypercurve::Axis2::Y => point.y() };
            let parameter = scale * coordinate + offset;
            if !points_equal(&lifted, &line.start.lerp(&line.end, &parameter))? {
                return Err(BuildError::EdgeUseSupportMismatch);
            }
        }
        Ok(())
    }

    fn validate_coordinate_revolution_image(
        &self,
        curve: &Curve3,
        axis: hypercurve::Axis2,
        scale: &Real,
        offset: &Real,
        constant: &Parameter,
        surface: &Surface,
    ) -> Result<(), BuildError> {
        match axis {
            hypercurve::Axis2::X => {
                let direction = if real_values_equal(scale, &Real::one())? {
                    1
                } else if real_values_equal(scale, &(-Real::one()))? {
                    -1
                } else {
                    return Err(BuildError::EdgeUseSupportMismatch);
                };
                // The complete angular chart is u = direction * (edge - offset).
                let expected = surface.revolution_rotation_curve(
                    constant,
                    curve.domain().represented_domain()?,
                    direction,
                    -offset * scale,
                )?;
                if curve_parameterizations_equal(curve, &expected)? {
                    Ok(())
                } else {
                    Err(BuildError::EdgeUseSupportMismatch)
                }
            }
            hypercurve::Axis2::Y => {
                let angle = constant
                    .try_real()
                    .ok_or(GeometryError::UnrepresentableParameter)?;
                let expected = surface.revolution_meridian_curve(angle)?;
                if curve_parameterizations_equal(curve, &expected)? {
                    require_real_equal(scale, &Real::one(), BuildError::EdgeUseSupportMismatch)?;
                    require_real_equal(offset, &Real::zero(), BuildError::EdgeUseSupportMismatch)
                } else if curve_parameterizations_equal(curve, &expected.reversed()?)? {
                    require_real_equal(scale, &(-Real::one()), BuildError::EdgeUseSupportMismatch)?;
                    require_real_equal(
                        offset,
                        &expected.reversal_pivot(),
                        BuildError::EdgeUseSupportMismatch,
                    )
                } else {
                    Err(BuildError::EdgeUseSupportMismatch)
                }
            }
        }
    }

    pub(in crate::topology) fn validate_planar_curve_image(
        &self,
        curve: &Curve3,
        edge: &Edge,
        edge_use: &EdgeUse,
        pcurve: &Pcurve,
        surface: &Surface,
    ) -> Result<(), BuildError> {
        let SurfaceExactData::Plane { origin, u, v } = surface.exact_data() else {
            return Err(BuildError::EdgeUseSupportMismatch);
        };
        let ParameterCorrespondence::Affine { scale, offset, .. } =
            &edge_use.parameter_correspondence
        else {
            return Err(BuildError::EdgeUseSupportMismatch);
        };
        if pcurve.curve().polynomial_branch().is_some()
            || edge.domain.try_real_endpoints().is_none()
        {
            let Curve3ExactData::PlanarImage(actual) = curve.exact_data() else {
                return Err(BuildError::EdgeUseSupportMismatch);
            };
            // Compare the complete definitions in the spatial chart,
            // without evaluating beyond the pcurve's selected restriction.
            // Its actual endpoints and their chart correspondence were
            // checked by validate_edge_use_image. Restriction preserves this
            // identity; no independent scalar endpoint is needed.
            let expected = crate::geometry::PlanarCurve3 {
                source: pcurve.curve().clone(),
                origin,
                u,
                v,
                source_scale: (Real::one() / scale).map_err(GeometryError::Numeric)?,
                source_offset: (-offset / scale).map_err(GeometryError::Numeric)?,
            };
            return if actual.parameterization_equals(&expected)? {
                Ok(())
            } else {
                Err(BuildError::EdgeUseSupportMismatch)
            };
        };
        let (start, end) = edge
            .domain
            .try_real_endpoints()
            .expect("represented endpoints checked above");
        let expected = Curve3::from_planar_image(crate::geometry::PlanarCurve3 {
            source: pcurve.curve().clone(),
            origin,
            u,
            v,
            source_scale: ((end - start) / scale).map_err(GeometryError::Numeric)?,
            source_offset: ((start - offset) / scale).map_err(GeometryError::Numeric)?,
        })?;
        if curve_parameterizations_equal(&curve.subcurve(start, end)?, &expected)? {
            Ok(())
        } else {
            Err(BuildError::EdgeUseSupportMismatch)
        }
    }

    pub(in crate::topology) fn validate_planar_circle_image(
        &self,
        curve: &Curve3,
        edge: &Edge,
        edge_use: &EdgeUse,
        pcurve: &Pcurve,
        surface: &Surface,
    ) -> Result<(), BuildError> {
        let Curve3ExactData::EllipseArc(data) = curve.exact_data() else {
            unreachable!("circle kind carries ellipse-arc exact data");
        };
        debug_assert!(data.circle);
        let arc = pcurve
            .circular_arc()
            .ok_or(GeometryError::UnsupportedPcurveContour)?;
        let center_parameter = Point2::new(arc.center().x().clone(), arc.center().y().clone());
        let mapped_center = surface.evaluate_real(&center_parameter)?;
        require_point_equal(
            &mapped_center,
            &data.center,
            BuildError::EdgeUseSupportMismatch,
        )?;

        let mapped_start = surface.evaluate_real(&Point2::new(
            arc.start().x().clone(),
            arc.start().y().clone(),
        ))?;
        let mapped_end =
            surface.evaluate_real(&Point2::new(arc.end().x().clone(), arc.end().y().clone()))?;
        let (directed_start_vertex, directed_end_vertex) = match edge_use.direction {
            Direction::Forward => (edge.start, edge.end),
            Direction::Reversed => (edge.end, edge.start),
        };
        require_point_equal(
            &mapped_start,
            self.vertex_ref(directed_start_vertex)?
                .represented_point()?,
            BuildError::EdgeUseSupportMismatch,
        )?;
        require_point_equal(
            &mapped_end,
            self.vertex_ref(directed_end_vertex)?.represented_point()?,
            BuildError::EdgeUseSupportMismatch,
        )?;

        // A linear plane map carries a circle to the same spatial circle for
        // every angle once it carries one radial/tangent frame exactly. This
        // certifies the complete image and its traversal without asking atan
        // to reconstruct a persisted arc's authored sweep from its endpoints.
        let radial_u = arc.start().x() - arc.center().x();
        let radial_v = arc.start().y() - arc.center().y();
        let (tangent_u, tangent_v) = if arc.is_clockwise() {
            (radial_v.clone(), -radial_u.clone())
        } else {
            (-radial_v.clone(), radial_u.clone())
        };
        let (plane_u, plane_v) = surface
            .plane_directions()
            .expect("plane kind carries plane directions");
        let mapped_tangent = plane_u.clone() * tangent_u + plane_v.clone() * tangent_v;

        let spatial_radial = &mapped_start - &data.center;
        let radial_x = data.x.dot(&spatial_radial);
        let radial_y = data.y.dot(&spatial_radial);
        let mut expected_tangent = data.y.clone() * radial_x - data.x.clone() * radial_y;
        if data.direction < 0 {
            expected_tangent = -expected_tangent;
        }
        if edge_use.direction == Direction::Reversed {
            expected_tangent = -expected_tangent;
        }
        require_vector_equal(
            &mapped_tangent,
            &expected_tangent,
            BuildError::EdgeUseSupportMismatch,
        )
    }

    pub(in crate::topology) fn validate_cylinder_axial_line_image(
        &self,
        curve: &Curve3,
        edge: &Edge,
        edge_use: &EdgeUse,
        pcurve: &Pcurve,
        surface: &Surface,
    ) -> Result<(), BuildError> {
        let line = pcurve
            .line_segment()
            .ok_or(GeometryError::UnsupportedPcurveContour)?;
        require_real_equal(
            line.start().x(),
            line.end().x(),
            BuildError::EdgeUseSupportMismatch,
        )?;
        let Curve3ExactData::Line(curve_data) = curve.exact_data() else {
            unreachable!("line kind carries line exact data");
        };
        let SurfaceExactData::Cylinder {
            origin,
            x,
            y,
            axis,
            radius,
        } = surface.exact_data()
        else {
            unreachable!("cylinder kind carries cylinder exact data");
        };
        let u = line.start().x().clone();
        let expected_x = &radius * u.clone().cos();
        let expected_y = &radius * u.sin();
        for point in [&curve_data.start, &curve_data.end] {
            let offset = point - &origin;
            require_real_equal(
                &offset.dot(&x),
                &expected_x,
                BuildError::EdgeUseSupportMismatch,
            )?;
            require_real_equal(
                &offset.dot(&y),
                &expected_y,
                BuildError::EdgeUseSupportMismatch,
            )?;
        }
        for parameter in [pcurve.represented_start()?, pcurve.represented_end()?] {
            let edge_parameter = edge_use.parameter_correspondence.edge_parameter(
                pcurve,
                &edge.domain,
                edge_use.direction,
                &crate::Parameter::from_real((parameter).clone()),
            )?;
            let edge_point = curve.evaluate_real(
                edge_parameter
                    .try_real()
                    .ok_or(crate::GeometryError::UnrepresentableParameter)?,
            )?;
            let axial = (&edge_point - &origin).dot(&axis);
            let surface_parameter = pcurve.evaluate_real(parameter)?;
            require_real_equal(
                &axial,
                &surface_parameter.y,
                BuildError::EdgeUseSupportMismatch,
            )?;
        }
        Ok(())
    }

    pub(in crate::topology) fn validate_cylinder_circle_image(
        &self,
        curve: &Curve3,
        edge: &Edge,
        edge_use: &EdgeUse,
        pcurve: &Pcurve,
        surface: &Surface,
    ) -> Result<(), BuildError> {
        let line = pcurve
            .line_segment()
            .ok_or(GeometryError::UnsupportedPcurveContour)?;
        require_real_equal(
            line.start().y(),
            line.end().y(),
            BuildError::EdgeUseSupportMismatch,
        )?;
        let Curve3ExactData::EllipseArc(curve_data) = curve.exact_data() else {
            unreachable!("circle kind carries ellipse-arc exact data");
        };
        let SurfaceExactData::Cylinder {
            origin,
            x,
            y,
            axis,
            radius,
        } = surface.exact_data()
        else {
            unreachable!("cylinder kind carries cylinder exact data");
        };
        validate_circle_iso_image(
            &curve_data,
            edge,
            edge_use.direction,
            origin + axis * line.start().y(),
            [x, y],
            radius,
            [line.start().x().clone(), line.end().x().clone()],
        )
    }

    pub(in crate::topology) fn validate_sphere_circle_image(
        &self,
        curve: &Curve3,
        edge: &Edge,
        edge_use: &EdgeUse,
        pcurve: &Pcurve,
        surface: &Surface,
    ) -> Result<(), BuildError> {
        let line = pcurve
            .line_segment()
            .ok_or(GeometryError::UnsupportedPcurveContour)?;
        let u_constant = real_values_equal(line.start().x(), line.end().x())?;
        let v_constant = real_values_equal(line.start().y(), line.end().y())?;
        if u_constant == v_constant {
            return Err(BuildError::EdgeUseSupportMismatch);
        }
        let Curve3ExactData::EllipseArc(curve_data) = curve.exact_data() else {
            unreachable!("circle kind carries ellipse-arc exact data");
        };
        if !curve_data.circle {
            return Err(BuildError::EdgeUseSupportMismatch);
        }
        let SurfaceExactData::Sphere {
            center,
            x,
            y,
            axis,
            radius,
        } = surface.exact_data()
        else {
            unreachable!("sphere kind carries sphere exact data");
        };
        let (circle_center, axes, circle_radius, angles) = if v_constant {
            let latitude = line.start().y().clone();
            (
                center + axis * (&radius * latitude.clone().sin()),
                [x, y],
                radius * latitude.cos(),
                [line.start().x().clone(), line.end().x().clone()],
            )
        } else {
            let longitude = line.start().x().clone();
            let radial = x * longitude.clone().cos() + y * longitude.sin();
            (
                center,
                [radial, axis],
                radius,
                [line.start().y().clone(), line.end().y().clone()],
            )
        };
        validate_circle_iso_image(
            &curve_data,
            edge,
            edge_use.direction,
            circle_center,
            axes,
            circle_radius,
            angles,
        )
    }

    pub(in crate::topology) fn validate_torus_circle_image(
        &self,
        curve: &Curve3,
        edge: &Edge,
        edge_use: &EdgeUse,
        pcurve: &Pcurve,
        surface: &Surface,
    ) -> Result<(), BuildError> {
        let line = pcurve
            .line_segment()
            .ok_or(GeometryError::UnsupportedPcurveContour)?;
        let Curve3ExactData::EllipseArc(curve_data) = curve.exact_data() else {
            unreachable!("circle kind carries ellipse-arc exact data");
        };
        if !curve_data.circle {
            return Err(BuildError::EdgeUseSupportMismatch);
        }
        let SurfaceExactData::Torus {
            center,
            x,
            y,
            axis,
            major_radius,
            minor_radius,
        } = surface.exact_data()
        else {
            unreachable!("torus kind carries torus exact data");
        };
        let u_constant = real_values_equal(line.start().x(), line.end().x())?;
        let v_constant = real_values_equal(line.start().y(), line.end().y())?;
        if u_constant == v_constant {
            return Err(BuildError::EdgeUseSupportMismatch);
        }
        let (expected_center, expected_x, expected_y, expected_radius, first_angle, second_angle) =
            if v_constant {
                let v = line.start().y().clone();
                let center_offset = &curve_data.center - &center;
                require_real_equal(
                    &center_offset.dot(&x),
                    &Real::zero(),
                    BuildError::EdgeUseSupportMismatch,
                )?;
                require_real_equal(
                    &center_offset.dot(&y),
                    &Real::zero(),
                    BuildError::EdgeUseSupportMismatch,
                )?;
                require_real_equal(
                    &center_offset.dot(&axis),
                    &(&minor_radius * v.clone().sin()),
                    BuildError::EdgeUseSupportMismatch,
                )?;
                (
                    curve_data.center.clone(),
                    x,
                    y,
                    major_radius + &minor_radius * v.cos(),
                    line.start().x().clone(),
                    line.end().x().clone(),
                )
            } else {
                let u = line.start().x().clone();
                let sine = u.clone().sin();
                let cosine = u.cos();
                let radial = x.clone() * &cosine + y.clone() * &sine;
                let tangent = -x * sine + y * cosine;
                let center_offset = &curve_data.center - &center;
                require_real_equal(
                    &center_offset.dot(&axis),
                    &Real::zero(),
                    BuildError::EdgeUseSupportMismatch,
                )?;
                require_real_equal(
                    &center_offset.dot(&radial),
                    &major_radius,
                    BuildError::EdgeUseSupportMismatch,
                )?;
                require_real_equal(
                    &center_offset.dot(&tangent),
                    &Real::zero(),
                    BuildError::EdgeUseSupportMismatch,
                )?;
                (
                    curve_data.center.clone(),
                    radial,
                    axis,
                    minor_radius,
                    line.start().y().clone(),
                    line.end().y().clone(),
                )
            };
        validate_circle_iso_image(
            &curve_data,
            edge,
            edge_use.direction,
            expected_center,
            [expected_x, expected_y],
            expected_radius,
            [first_angle, second_angle],
        )
    }

    pub(in crate::topology) fn validate_cone_generator_image(
        &self,
        pcurve: &Pcurve,
    ) -> Result<(), BuildError> {
        let line = pcurve
            .line_segment()
            .ok_or(GeometryError::UnsupportedPcurveContour)?;
        require_real_equal(
            line.start().x(),
            line.end().x(),
            BuildError::EdgeUseSupportMismatch,
        )
    }

    pub(in crate::topology) fn validate_cone_circle_image(
        &self,
        curve: &Curve3,
        edge: &Edge,
        edge_use: &EdgeUse,
        pcurve: &Pcurve,
        surface: &Surface,
    ) -> Result<(), BuildError> {
        let line = pcurve
            .line_segment()
            .ok_or(GeometryError::UnsupportedPcurveContour)?;
        require_real_equal(
            line.start().y(),
            line.end().y(),
            BuildError::EdgeUseSupportMismatch,
        )?;
        let Curve3ExactData::EllipseArc(curve_data) = curve.exact_data() else {
            unreachable!("circle kind carries ellipse-arc exact data");
        };
        if !curve_data.circle {
            return Err(BuildError::EdgeUseSupportMismatch);
        }
        let SurfaceExactData::Cone {
            apex,
            x,
            y,
            axis,
            semi_angle,
        } = surface.exact_data()
        else {
            unreachable!("cone kind carries cone exact data");
        };
        let v = line.start().y().clone();
        validate_circle_iso_image(
            &curve_data,
            edge,
            edge_use.direction,
            apex + axis * (&v * semi_angle.clone().cos()),
            [x, y],
            v * semi_angle.sin(),
            [line.start().x().clone(), line.end().x().clone()],
        )
    }

    pub(in crate::topology) fn validate_extrusion_line_image(
        &self,
        pcurve: &Pcurve,
        surface: &Surface,
    ) -> Result<(), BuildError> {
        let line = pcurve
            .line_segment()
            .ok_or(GeometryError::UnsupportedPcurveContour)?;
        let u_constant = real_values_equal(line.start().x(), line.end().x())?;
        if u_constant {
            return Ok(());
        }
        let v_constant = real_values_equal(line.start().y(), line.end().y())?;
        let SurfaceExactData::Extrusion { profile, .. } = surface.exact_data() else {
            unreachable!("extrusion kind carries extrusion exact data");
        };
        if v_constant && matches!(*profile, Curve3ExactData::Line(_)) {
            Ok(())
        } else {
            Err(BuildError::EdgeUseSupportMismatch)
        }
    }

    pub(in crate::topology) fn validate_extrusion_profile_image(
        &self,
        curve: &Curve3,
        edge: &Edge,
        edge_use: &EdgeUse,
        pcurve: &Pcurve,
        surface: &Surface,
    ) -> Result<(), BuildError> {
        let line = pcurve
            .line_segment()
            .ok_or(GeometryError::UnsupportedPcurveContour)?;
        require_real_equal(
            line.start().y(),
            line.end().y(),
            BuildError::EdgeUseSupportMismatch,
        )?;
        if real_values_equal(line.start().x(), line.end().x())? {
            return Err(BuildError::EdgeUseSupportMismatch);
        }
        let (profile_start, profile_end) = if decided_model_order(compare_reals(
            line.start().x(),
            line.end().x(),
            crate::STRICT_PREDICATES,
        ))? == std::cmp::Ordering::Less
        {
            (line.start().x(), line.end().x())
        } else {
            (line.end().x(), line.start().x())
        };
        let (profile, direction) = surface
            .extrusion_profile_and_direction()
            .expect("extrusion kind carries extrusion geometry");
        let offset = direction.clone() * line.start().y();
        let expected = translated_curve(&profile.subcurve(profile_start, profile_end)?, &offset)?;
        let actual = curve.subcurve(
            edge.domain.represented_start()?,
            edge.domain.represented_end()?,
        )?;
        let reversed = if profile_parameterizations_equal(&actual, &expected)? {
            false
        } else if profile_parameterizations_equal(&actual, &expected.reversed()?)? {
            true
        } else {
            return Err(BuildError::EdgeUseSupportMismatch);
        };

        let edge_domain_span = edge.domain.represented_end()? - edge.domain.represented_start()?;
        let actual_span =
            actual.domain().represented_end()? - actual.domain().represented_start()?;
        let profile_span = profile_end - profile_start;
        let expected_span =
            expected.domain().represented_end()? - expected.domain().represented_start()?;
        for (pcurve_parameter, surface_parameter) in [
            (pcurve.represented_start()?, line.start().x()),
            (pcurve.represented_end()?, line.end().x()),
        ] {
            let edge_parameter = edge_use.parameter_correspondence.edge_parameter(
                pcurve,
                &edge.domain,
                edge_use.direction,
                &crate::Parameter::from_real((pcurve_parameter).clone()),
            )?;
            let actual_parameter = actual.domain().represented_start()?
                + ((edge_parameter
                    .try_real()
                    .ok_or(GeometryError::UnrepresentableParameter)?
                    - edge.domain.represented_start()?)
                    * &actual_span
                    / &edge_domain_span)
                    .map_err(GeometryError::Numeric)?;
            let offset = ((surface_parameter - profile_start) * &expected_span / &profile_span)
                .map_err(GeometryError::Numeric)?;
            let expected_parameter = actual.domain().represented_start()?
                + if reversed {
                    &expected_span - offset
                } else {
                    offset
                };
            require_real_equal(
                &actual_parameter,
                &expected_parameter,
                BuildError::EdgeUseSupportMismatch,
            )?;
        }
        Ok(())
    }

    pub(in crate::topology) fn validate_revolution_meridian_image(
        &self,
        curve: &Curve3,
        edge: &Edge,
        edge_use: &EdgeUse,
        pcurve: &Pcurve,
        surface: &Surface,
    ) -> Result<(), BuildError> {
        let line = pcurve
            .line_segment()
            .ok_or(GeometryError::UnsupportedPcurveContour)?;
        require_real_equal(
            line.start().x(),
            line.end().x(),
            BuildError::EdgeUseSupportMismatch,
        )?;
        if real_values_equal(line.start().y(), line.end().y())? {
            return Err(BuildError::EdgeUseSupportMismatch);
        }
        let (profile_start, profile_end) = if decided_model_order(compare_reals(
            line.start().y(),
            line.end().y(),
            crate::STRICT_PREDICATES,
        ))? == std::cmp::Ordering::Less
        {
            (line.start().y(), line.end().y())
        } else {
            (line.end().y(), line.start().y())
        };
        let expected = surface
            .revolution_meridian_curve(line.start().x())?
            .subcurve(profile_start, profile_end)?;
        let actual = curve.subcurve(
            edge.domain.represented_start()?,
            edge.domain.represented_end()?,
        )?;
        if !curve_parameterizations_equal(&actual, &expected)? {
            return Err(BuildError::EdgeUseSupportMismatch);
        }
        let edge_domain_span = edge.domain.represented_end()? - edge.domain.represented_start()?;
        let actual_span =
            actual.domain().represented_end()? - actual.domain().represented_start()?;
        let profile_span = profile_end - profile_start;
        let expected_span =
            expected.domain().represented_end()? - expected.domain().represented_start()?;
        for (pcurve_parameter, surface_parameter) in [
            (pcurve.represented_start()?, line.start().y()),
            (pcurve.represented_end()?, line.end().y()),
        ] {
            let edge_parameter = edge_use.parameter_correspondence.edge_parameter(
                pcurve,
                &edge.domain,
                edge_use.direction,
                &crate::Parameter::from_real((pcurve_parameter).clone()),
            )?;
            let actual_parameter = actual.domain().represented_start()?
                + ((edge_parameter
                    .try_real()
                    .ok_or(GeometryError::UnrepresentableParameter)?
                    - edge.domain.represented_start()?)
                    * &actual_span
                    / &edge_domain_span)
                    .map_err(GeometryError::Numeric)?;
            let expected_parameter = expected.domain().represented_start()?
                + ((surface_parameter - profile_start) * &expected_span / &profile_span)
                    .map_err(GeometryError::Numeric)?;
            require_real_equal(
                &actual_parameter,
                &expected_parameter,
                BuildError::EdgeUseSupportMismatch,
            )?;
        }
        Ok(())
    }

    pub(in crate::topology) fn validate_revolution_circle_image(
        &self,
        curve: &Curve3,
        edge: &Edge,
        edge_use: &EdgeUse,
        pcurve: &Pcurve,
        surface: &Surface,
    ) -> Result<(), BuildError> {
        let line = pcurve
            .line_segment()
            .ok_or(GeometryError::UnsupportedPcurveContour)?;
        require_real_equal(
            line.start().y(),
            line.end().y(),
            BuildError::EdgeUseSupportMismatch,
        )?;
        if real_values_equal(line.start().x(), line.end().x())? {
            return Err(BuildError::EdgeUseSupportMismatch);
        }
        let actual = curve.subcurve(
            edge.domain.represented_start()?,
            edge.domain.represented_end()?,
        )?;
        let actual_span =
            actual.domain().represented_end()? - actual.domain().represented_start()?;
        let first_edge_parameter = edge_use.parameter_correspondence.edge_parameter(
            pcurve,
            &edge.domain,
            edge_use.direction,
            &crate::Parameter::from_real((pcurve.represented_start()?).clone()),
        )?;
        let second_edge_parameter = edge_use.parameter_correspondence.edge_parameter(
            pcurve,
            &edge.domain,
            edge_use.direction,
            &crate::Parameter::from_real((pcurve.represented_end()?).clone()),
        )?;
        let (angle_at_start, angle_at_end) = if real_values_equal(
            first_edge_parameter
                .try_real()
                .ok_or(crate::GeometryError::UnrepresentableParameter)?,
            actual.domain().represented_start()?,
        )? {
            require_real_equal(
                second_edge_parameter
                    .try_real()
                    .ok_or(crate::GeometryError::UnrepresentableParameter)?,
                actual.domain().represented_end()?,
                BuildError::EdgeUseSupportMismatch,
            )?;
            (line.start().x(), line.end().x())
        } else {
            require_real_equal(
                first_edge_parameter
                    .try_real()
                    .ok_or(crate::GeometryError::UnrepresentableParameter)?,
                actual.domain().represented_end()?,
                BuildError::EdgeUseSupportMismatch,
            )?;
            require_real_equal(
                second_edge_parameter
                    .try_real()
                    .ok_or(crate::GeometryError::UnrepresentableParameter)?,
                actual.domain().represented_start()?,
                BuildError::EdgeUseSupportMismatch,
            )?;
            (line.end().x(), line.start().x())
        };
        let angle_delta = angle_at_end - angle_at_start;
        let expected_direction = if real_values_equal(&angle_delta, &actual_span)? {
            1
        } else if real_values_equal(&angle_delta, &(-actual_span.clone()))? {
            -1
        } else {
            return Err(BuildError::EdgeUseSupportMismatch);
        };
        let support =
            surface.revolution_latitude_curve(line.start().y(), Real::zero(), Real::one())?;
        let Curve3ExactData::EllipseArc(support) = support.exact_data() else {
            unreachable!("a nonsingular revolution latitude is a circle");
        };
        let expected =
            Curve3::from_exact_data(Curve3ExactData::EllipseArc(Box::new(EllipseArcExactData {
                domain_start: actual.domain().represented_start()?.clone(),
                domain_end: actual.domain().represented_end()?.clone(),
                angle_at_start: angle_at_start.clone(),
                direction: expected_direction,
                ..*support
            })))?;
        if !circle_parameterizations_equal(&actual, &expected)? {
            return Err(BuildError::EdgeUseSupportMismatch);
        }
        Ok(())
    }
}

/// Two orthonormal radial/tangent frames and the angular rate determine the
/// complete circle parameterization. A center and one tangent do not: a wrong
/// phase or a tilted plane can retain both while changing the radial vector.
fn validate_circle_iso_image(
    curve_data: &EllipseArcExactData,
    edge: &Edge,
    direction: Direction,
    center: Point3,
    axes: [Vector3; 2],
    radius: Real,
    angles: [Real; 2],
) -> Result<(), BuildError> {
    let edge_offset = edge.domain.represented_start()? - &curve_data.domain_start;
    let edge_angle_at_start = if curve_data.direction > 0 {
        &curve_data.angle_at_start + edge_offset
    } else {
        &curve_data.angle_at_start - edge_offset
    };
    let actual = EllipseArcExactData {
        domain_start: edge.domain.represented_start()?.clone(),
        domain_end: edge.domain.represented_end()?.clone(),
        angle_at_start: edge_angle_at_start,
        ..curve_data.clone()
    };
    let actual_span = &actual.domain_end - &actual.domain_start;
    let [first_angle, second_angle] = angles;
    let (angle_at_start, angle_at_end) = match direction {
        Direction::Forward => (first_angle, second_angle),
        Direction::Reversed => (second_angle, first_angle),
    };
    let angle_delta = &angle_at_end - &angle_at_start;
    let expected_direction = if real_values_equal(&angle_delta, &actual_span)? {
        1
    } else if real_values_equal(&angle_delta, &(-actual_span.clone()))? {
        -1
    } else {
        return Err(BuildError::EdgeUseSupportMismatch);
    };
    let [x, y] = axes;
    let expected = EllipseArcExactData {
        circle: true,
        center,
        x,
        y,
        x_radius: radius.clone(),
        y_radius: radius,
        domain_start: actual.domain_start.clone(),
        domain_end: actual.domain_end.clone(),
        angle_at_start,
        direction: expected_direction,
    };
    if circle_data_parameterizations_equal(&actual, &expected)? {
        Ok(())
    } else {
        Err(BuildError::EdgeUseSupportMismatch)
    }
}

//! Validated construction: validation image.

use crate::topology::*;

#[cfg(test)]
mod tests;

impl ArenaModelBuilder {
    pub(crate) fn validate_edge_image(
        &self,
        edge: EdgeId,
        direction: Direction,
        pcurve: PcurveId,
        parameter_correspondence: ParameterCorrespondence,
        surface: SurfaceId,
    ) -> Result<(), BuildError> {
        crate::context::strict(|| {
            let candidate = EdgeUse {
                edge,
                direction,
                pcurve,
                parameter_correspondence,
                image_certificate: false,
            };
            let edge = self.edge_ref(edge)?;
            self.validate_edge_use_image(
                self.curve_ref(edge.curve)?,
                edge,
                &candidate,
                self.pcurve_ref(pcurve)?,
                self.surface_ref(surface)?,
            )
        })
    }

    pub(in crate::topology) fn validate_wire_image(
        &self,
        wire: WireId,
        surface: SurfaceId,
    ) -> Result<(), BuildError> {
        let surface = self.surface_ref(surface)?;
        let wire = self.wire_ref(wire)?;
        for edge_use_id in &wire.edge_uses {
            let edge_use = self.edge_use_ref(*edge_use_id)?;
            let edge = self.edge_ref(edge_use.edge)?;
            let curve = self.curve_ref(edge.curve)?;
            let pcurve = self.pcurve_ref(edge_use.pcurve)?;
            self.validate_edge_use_image(curve, edge, edge_use, pcurve, surface)?;
        }
        Ok(())
    }

    fn validate_edge_use_image(
        &self,
        curve: &Curve3,
        edge: &Edge,
        edge_use: &EdgeUse,
        pcurve: &Pcurve,
        surface: &Surface,
    ) -> Result<(), BuildError> {
        let coordinate_image = matches!(
            &edge_use.parameter_correspondence,
            ParameterCorrespondence::Coordinate { .. }
        );
        // Finite planar sources use their direct whole-image proof on planes.
        // Ordinary extrusion-side affine restrictions still require the native
        // complete-source proof below, including after a selected edge split.
        let finite_planar_image =
            curve.kind() == Curve3Kind::PlanarImage && surface.kind() == SurfaceKind::Plane;
        if !edge_use.image_certificate
            && !finite_planar_image
            && !coordinate_image
            && let Some((source, _, _)) = pcurve.curve().source_restriction()
        {
            // The trim's exact endpoint map is checked independently. The
            // complete authored image is then certified by the native validator;
            // restriction cannot change that image agreement. No proof flag or
            // sampled approximation is accepted from an archive.
            let expected = match edge_use.direction {
                Direction::Forward => [edge.domain.start(), edge.domain.end()],
                Direction::Reversed => [edge.domain.end(), edge.domain.start()],
            };
            for (index, (local, expected)) in [pcurve.domain_start()?, pcurve.domain_end()?]
                .into_iter()
                .zip(expected)
                .enumerate()
            {
                let mapped = edge_use.parameter_correspondence.edge_parameter(
                    pcurve,
                    &edge.domain,
                    edge_use.direction,
                    &local,
                )?;
                if mapped.compare(expected)? != std::cmp::Ordering::Equal {
                    return Err(BuildError::ParameterCorrespondenceMismatch {
                        endpoint: if index == 0 {
                            Endpoint::Start
                        } else {
                            Endpoint::End
                        },
                    });
                }
            }
            let ParameterCorrespondence::Affine { scale, offset, .. } =
                &edge_use.parameter_correspondence
            else {
                return Err(GeometryError::UnsupportedPcurveContour.into());
            };
            let source = Pcurve::new(source.clone());
            let start: Parameter = (scale * source.represented_start()? + offset).into();
            let end: Parameter = (scale * source.represented_end()? + offset).into();
            let mut source_edge = edge.clone();
            let mut source_use = edge_use.clone();
            if start.compare(&end)? == std::cmp::Ordering::Less {
                source_edge.domain = ParameterRange::new(start, end)?;
                source_use.direction = Direction::Forward;
            } else {
                source_edge.domain = ParameterRange::new(end, start)?;
                source_use.direction = Direction::Reversed;
            }
            return self.validate_edge_use_image(
                curve,
                &source_edge,
                &source_use,
                &source,
                surface,
            );
        }
        let inherited_image = edge_use.image_certificate;
        let planar_image_proof = matches!(
            (
                curve.kind(),
                surface.kind(),
                &edge_use.parameter_correspondence
            ),
            (
                Curve3Kind::PlanarImage,
                SurfaceKind::Plane,
                ParameterCorrespondence::Affine { .. },
            )
        );
        let complete_image_certificate_subsumes_endpoint_sampling = matches!(
            (
                curve.kind(),
                pcurve.kind(),
                surface.kind(),
                &edge_use.parameter_correspondence,
            ),
            (
                Curve3Kind::CircleArc,
                CurveFamily2::Line,
                SurfaceKind::Cylinder
                    | SurfaceKind::Sphere
                    | SurfaceKind::Cone
                    | SurfaceKind::Torus,
                ParameterCorrespondence::Affine { .. },
            ) | (
                Curve3Kind::Line,
                CurveFamily2::Line,
                SurfaceKind::Cylinder,
                ParameterCorrespondence::Affine { .. },
            ) | (
                Curve3Kind::CircleArc,
                CurveFamily2::CircularArc,
                SurfaceKind::Plane,
                ParameterCorrespondence::AngularSweep,
            )
        );

        let pcurve_parameters = [pcurve.domain_start()?, pcurve.domain_end()?];
        let expected_edge_parameters = match edge_use.direction {
            Direction::Forward => [edge.domain.start(), edge.domain.end()],
            Direction::Reversed => [edge.domain.end(), edge.domain.start()],
        };
        for (index, (pcurve_parameter, expected_edge_parameter)) in pcurve_parameters
            .into_iter()
            .zip(expected_edge_parameters)
            .enumerate()
        {
            let endpoint = if index == 0 {
                Endpoint::Start
            } else {
                Endpoint::End
            };
            let edge_parameter = edge_use.parameter_correspondence.edge_parameter(
                pcurve,
                &edge.domain,
                edge_use.direction,
                &pcurve_parameter,
            )?;
            if edge_parameter.compare(expected_edge_parameter)? != std::cmp::Ordering::Equal {
                return Err(BuildError::ParameterCorrespondenceMismatch { endpoint });
            }
            if inherited_image || planar_image_proof || coordinate_image {
                // A retained planar source can have selected endpoints with no
                // scalar view. The mandatory whole-image proof below implies
                // endpoint agreement after the exact chart check above.
                continue;
            }
            let edge_point = curve.point_at(&edge_parameter)?;
            let surface_parameter = pcurve.point_at(&pcurve_parameter)?;
            let surface_point = surface.point_at(&surface_parameter)?;
            if !complete_image_certificate_subsumes_endpoint_sampling
                && !edge_point.coincides_with(&surface_point)?
            {
                return Err(BuildError::EdgeUseImageMismatch { endpoint });
            }
        }
        if inherited_image {
            return Ok(());
        }

        if coordinate_image {
            return self.validate_coordinate_surface_image(curve, edge_use, pcurve, surface);
        }

        match (
            curve.kind(),
            pcurve.kind(),
            surface.kind(),
            &edge_use.parameter_correspondence,
        ) {
            (
                Curve3Kind::PlanarImage,
                _,
                SurfaceKind::Plane,
                ParameterCorrespondence::Affine { .. },
            ) => {
                self.validate_planar_curve_image(curve, edge, edge_use, pcurve, surface)?;
            }
            (
                Curve3Kind::Line,
                CurveFamily2::Line,
                SurfaceKind::Plane,
                ParameterCorrespondence::Affine { .. },
            ) => {
                // Both composed images are affine. Exact endpoint equality
                // therefore certifies the complete interval.
            }
            (
                Curve3Kind::CircleArc,
                CurveFamily2::CircularArc,
                SurfaceKind::Plane,
                ParameterCorrespondence::AngularSweep,
            ) => {
                self.validate_planar_circle_image(curve, edge, edge_use, pcurve, surface)?;
            }
            (
                Curve3Kind::RationalBezier,
                CurveFamily2::RationalQuadraticBezier | CurveFamily2::RationalBezier,
                SurfaceKind::Plane,
                ParameterCorrespondence::Affine { .. },
            )
            | (
                Curve3Kind::Nurbs,
                CurveFamily2::Nurbs,
                SurfaceKind::Plane,
                ParameterCorrespondence::Affine { .. },
            ) => {
                self.validate_planar_spline_image(curve, edge, edge_use, pcurve, surface)?;
            }
            (
                Curve3Kind::Line,
                CurveFamily2::Line,
                SurfaceKind::Cylinder,
                ParameterCorrespondence::Affine { .. },
            ) => self.validate_cylinder_axial_line_image(curve, edge, edge_use, pcurve, surface)?,
            (
                Curve3Kind::CircleArc,
                CurveFamily2::Line,
                SurfaceKind::Cylinder,
                ParameterCorrespondence::Affine { .. },
            ) => {
                self.validate_cylinder_circle_image(curve, edge, edge_use, pcurve, surface)?;
            }
            (
                Curve3Kind::CircleArc,
                CurveFamily2::Line,
                SurfaceKind::Sphere,
                ParameterCorrespondence::Affine { .. },
            ) => {
                self.validate_sphere_circle_image(curve, edge, edge_use, pcurve, surface)?;
            }
            (
                Curve3Kind::CircleArc,
                CurveFamily2::Line,
                SurfaceKind::Torus,
                ParameterCorrespondence::Affine { .. },
            ) => {
                self.validate_torus_circle_image(curve, edge, edge_use, pcurve, surface)?;
            }
            (
                Curve3Kind::Line,
                CurveFamily2::Line,
                SurfaceKind::Cone,
                ParameterCorrespondence::Affine { .. },
            ) => self.validate_cone_generator_image(pcurve)?,
            (
                Curve3Kind::CircleArc,
                CurveFamily2::Line,
                SurfaceKind::Cone,
                ParameterCorrespondence::Affine { .. },
            ) => {
                self.validate_cone_circle_image(curve, edge, edge_use, pcurve, surface)?;
            }
            (
                Curve3Kind::Line,
                CurveFamily2::Line,
                SurfaceKind::Extrusion,
                ParameterCorrespondence::Affine { .. },
            ) => self.validate_extrusion_line_image(pcurve, surface)?,
            (
                Curve3Kind::CircleArc
                | Curve3Kind::EllipseArc
                | Curve3Kind::RationalBezier
                | Curve3Kind::Nurbs
                | Curve3Kind::PlanarImage,
                CurveFamily2::Line,
                SurfaceKind::Extrusion,
                ParameterCorrespondence::Affine { .. },
            ) => {
                self.validate_extrusion_profile_image(curve, edge, edge_use, pcurve, surface)?;
            }
            (
                Curve3Kind::Line,
                CurveFamily2::Line,
                SurfaceKind::Revolution,
                ParameterCorrespondence::Affine { .. },
            )
            | (
                Curve3Kind::EllipseArc | Curve3Kind::RationalBezier,
                CurveFamily2::Line,
                SurfaceKind::Revolution,
                ParameterCorrespondence::Affine { .. },
            )
            | (
                Curve3Kind::Nurbs,
                CurveFamily2::Line,
                SurfaceKind::Revolution,
                ParameterCorrespondence::Affine { .. },
            ) => self.validate_revolution_meridian_image(curve, edge, edge_use, pcurve, surface)?,
            (
                Curve3Kind::CircleArc,
                CurveFamily2::Line,
                SurfaceKind::Revolution,
                ParameterCorrespondence::Affine { .. },
            ) => {
                let line = pcurve
                    .line_segment()
                    .ok_or(GeometryError::UnsupportedPcurveContour)?;
                if real_values_equal(line.start().x(), line.end().x())? {
                    self.validate_revolution_meridian_image(
                        curve, edge, edge_use, pcurve, surface,
                    )?;
                } else {
                    self.validate_revolution_circle_image(curve, edge, edge_use, pcurve, surface)?;
                }
            }
            (
                Curve3Kind::RationalBezier,
                CurveFamily2::Line,
                SurfaceKind::RationalBezier,
                ParameterCorrespondence::Affine { .. },
            )
            | (
                Curve3Kind::RationalBezier,
                CurveFamily2::Line,
                SurfaceKind::Nurbs,
                ParameterCorrespondence::Affine { .. },
            )
            | (
                Curve3Kind::Line,
                CurveFamily2::Line,
                SurfaceKind::RationalBezier,
                ParameterCorrespondence::Affine { .. },
            )
            | (
                Curve3Kind::Nurbs,
                CurveFamily2::Line,
                SurfaceKind::Nurbs,
                ParameterCorrespondence::Affine { .. },
            )
            | (
                Curve3Kind::Line,
                CurveFamily2::Line,
                SurfaceKind::Nurbs,
                ParameterCorrespondence::Affine { .. },
            ) => {
                self.validate_tensor_surface_iso_image(curve, edge, edge_use, pcurve, surface)?;
            }
            (
                Curve3Kind::RationalBezier,
                CurveFamily2::RationalBezier,
                SurfaceKind::RationalBezier,
                ParameterCorrespondence::Affine { .. },
            )
            | (
                Curve3Kind::PlanarImage,
                CurveFamily2::ImplicitPolynomial,
                SurfaceKind::RationalBezier,
                ParameterCorrespondence::Affine { .. },
            ) => {
                self.validate_rational_tensor_graph_image(curve, edge, edge_use, pcurve, surface)?;
            }
            (
                Curve3Kind::RationalBezier,
                CurveFamily2::RationalBezier,
                SurfaceKind::Nurbs,
                ParameterCorrespondence::Affine { .. },
            ) => {
                self.validate_rational_tensor_graph_image(curve, edge, edge_use, pcurve, surface)?;
            }
            (
                Curve3Kind::Nurbs,
                CurveFamily2::Nurbs,
                SurfaceKind::RationalBezier,
                ParameterCorrespondence::Affine { .. },
            ) => {
                self.validate_rational_tensor_graph_image(curve, edge, edge_use, pcurve, surface)?;
            }
            (
                Curve3Kind::Nurbs,
                CurveFamily2::RationalBezier,
                SurfaceKind::Nurbs,
                ParameterCorrespondence::Affine { .. },
            )
            | (
                Curve3Kind::Nurbs,
                CurveFamily2::Nurbs,
                SurfaceKind::Nurbs,
                ParameterCorrespondence::Affine { .. },
            ) => {
                self.validate_nurbs_tensor_graph_image(curve, edge_use, pcurve, surface)?;
            }
            _ => {
                return Err(BuildError::UnsupportedEdgeUseAgreement {
                    curve: curve.kind(),
                    pcurve: pcurve.kind(),
                    surface: surface.kind(),
                });
            }
        }
        Ok(())
    }

    pub(in crate::topology) fn validate_planar_spline_image(
        &self,
        curve: &Curve3,
        edge: &Edge,
        edge_use: &EdgeUse,
        pcurve: &Pcurve,
        surface: &Surface,
    ) -> Result<(), BuildError> {
        let ParameterCorrespondence::Affine { scale, offset } = &edge_use.parameter_correspondence
        else {
            return Err(BuildError::EdgeUseSupportMismatch);
        };
        let (Some(origin), Some((u, v))) = (surface.plane_origin(), surface.plane_directions())
        else {
            return Err(BuildError::EdgeUseSupportMismatch);
        };
        let expected = crate::geometry::lift_curve_from_plane_frame_with_affine_parameter(
            pcurve.curve(),
            origin,
            u,
            v,
            scale,
            offset,
        )?
        .ok_or(BuildError::EdgeUseSupportMismatch)?;
        // Native subdivision may rebase a Bezier pcurve to [0,1], while a
        // NURBS keeps its knot chart. Compare the actual edge interval with
        // the lift in its mapped chart, not with the whole spatial source.
        // Selected restrictions reach here through their authored source and
        // the independently checked source-domain map above.
        let actual = curve.subcurve(
            edge.domain.represented_start()?,
            edge.domain.represented_end()?,
        )?;
        if curve_parameterizations_equal(&actual, &expected)? {
            Ok(())
        } else {
            Err(BuildError::EdgeUseSupportMismatch)
        }
    }
}

//! Validated construction: validation tensor.

use crate::topology::*;

impl ArenaModelBuilder {
    pub(in crate::topology) fn validate_rational_tensor_graph_image(
        &self,
        curve: &Curve3,
        edge: &Edge,
        edge_use: &EdgeUse,
        pcurve: &Pcurve,
        surface: &Surface,
    ) -> Result<(), BuildError> {
        if let Some((scale, offset)) = edge_use.parameter_correspondence.affine_coefficients()
            && surface.certifies_polynomial_section_image(curve, pcurve.curve(), scale, offset)?
        {
            return Ok(());
        }
        if self.validate_affine_bilinear_inverse_pcurve(curve, edge, edge_use, pcurve, surface)? {
            return Ok(());
        }
        if self.validate_affine_tensor_parameter_image(curve, edge_use, pcurve, surface)? {
            return Ok(());
        }
        if let SurfaceExactData::Nurbs {
            u_degree,
            v_degree,
            control_points: surface_points,
            weights: surface_weights,
            u_knots,
            v_knots,
        } = surface.exact_data()
            && u_degree == 1
            && v_degree == 1
            && surface_points.len() == 2
            && surface_points
                .iter()
                .zip(&surface_weights)
                .all(|(points, weights)| points.len() == 2 && weights.len() == 2)
        {
            let oriented_pcurve = match edge_use.direction {
                Direction::Forward => pcurve.clone(),
                Direction::Reversed => pcurve.reversed()?,
            };
            let normalized = normalize_single_span_nurbs_pcurve(
                oriented_pcurve.curve(),
                &u_knots[1],
                &u_knots[2],
                &v_knots[1],
                &v_knots[2],
            )?;
            if let Some(expected) =
                rational_bilinear_parameter_curve(&surface_points, &surface_weights, &normalized)?
                && curve_parameterizations_equal(curve, &expected)?
            {
                return Ok(());
            }
            return Err(BuildError::EdgeUseSupportMismatch);
        }
        let SurfaceExactData::RationalBezier {
            control_points: surface_points,
            weights: surface_weights,
        } = surface.exact_data()
        else {
            return Err(BuildError::EdgeUseSupportMismatch);
        };
        let Curve3ExactData::RationalBezier {
            control_points: curve_points,
            weights: curve_weights,
        } = curve.exact_data()
        else {
            return Err(BuildError::EdgeUseSupportMismatch);
        };
        let oriented_pcurve = match edge_use.direction {
            Direction::Forward => pcurve.clone(),
            Direction::Reversed => pcurve.reversed()?,
        };
        if let Some(expected) = rational_bilinear_parameter_curve(
            &surface_points,
            &surface_weights,
            oriented_pcurve.curve(),
        )? && curve_parameterizations_equal(curve, &expected)?
        {
            return Ok(());
        }
        if surface_points
            .iter()
            .zip(&surface_weights)
            .all(|(points, weights)| points.len() == 2 && weights.len() == 2)
        {
            let trimmed = self.trim_rational_tensor_profile(
                &surface_points,
                &surface_weights,
                edge_use,
                pcurve,
                SurfaceIsoAxis::V,
            )?;
            match self.validate_tensor_graph_controls(
                &curve_points,
                &curve_weights,
                &trimmed.points,
                &trimmed.weights,
                edge_use,
                pcurve,
                &trimmed.start,
                &(&trimmed.end - &trimmed.start),
                &Real::one(),
                &Real::zero(),
                SurfaceIsoAxis::V,
            ) {
                Ok(()) => return Ok(()),
                Err(BuildError::EdgeUseSupportMismatch) => {}
                Err(error) => return Err(error),
            }
        }
        let Some((transposed_points, transposed_weights)) =
            transpose_two_row_tensor(&surface_points, &surface_weights)
        else {
            return Err(BuildError::EdgeUseSupportMismatch);
        };
        let trimmed = self.trim_rational_tensor_profile(
            &transposed_points,
            &transposed_weights,
            edge_use,
            pcurve,
            SurfaceIsoAxis::U,
        )?;
        self.validate_tensor_graph_controls(
            &curve_points,
            &curve_weights,
            &trimmed.points,
            &trimmed.weights,
            edge_use,
            pcurve,
            &trimmed.start,
            &(&trimmed.end - &trimmed.start),
            &Real::one(),
            &Real::zero(),
            SurfaceIsoAxis::U,
        )
    }

    pub(in crate::topology) fn validate_affine_bilinear_inverse_pcurve(
        &self,
        curve: &Curve3,
        edge: &Edge,
        edge_use: &EdgeUse,
        pcurve: &Pcurve,
        surface: &Surface,
    ) -> Result<bool, BuildError> {
        let restricted = curve.subcurve(
            (edge.domain.start())
                .try_real()
                .ok_or(crate::GeometryError::UnrepresentableParameter)?,
            (edge.domain.end())
                .try_real()
                .ok_or(crate::GeometryError::UnrepresentableParameter)?,
        )?;
        let directed = match edge_use.direction {
            Direction::Forward => restricted,
            Direction::Reversed => restricted.reversed()?,
        };
        let Some(expected) = surface.affine_bilinear_inverse_pcurve(&directed)? else {
            return Ok(false);
        };
        validate_projective_pcurve_equal(pcurve.curve(), &expected)?;
        Ok(true)
    }

    pub(in crate::topology) fn validate_nurbs_tensor_graph_image(
        &self,
        curve: &Curve3,
        edge_use: &EdgeUse,
        pcurve: &Pcurve,
        surface: &Surface,
    ) -> Result<(), BuildError> {
        if self.validate_affine_tensor_parameter_image(curve, edge_use, pcurve, surface)? {
            return Ok(());
        }
        let SurfaceExactData::Nurbs {
            u_degree,
            v_degree,
            control_points: surface_points,
            weights: surface_weights,
            u_knots,
            v_knots,
            ..
        } = surface.exact_data()
        else {
            return Err(BuildError::EdgeUseSupportMismatch);
        };
        let Curve3ExactData::Nurbs {
            degree,
            control_points: curve_points,
            weights: curve_weights,
            knots: curve_knots,
        } = curve.exact_data()
        else {
            return Err(BuildError::EdgeUseSupportMismatch);
        };
        if u_degree == 1
            && degree == v_degree
            && !surface_points.is_empty()
            && surface_points
                .iter()
                .zip(&surface_weights)
                .all(|(points, weights)| points.len() == 2 && weights.len() == 2)
        {
            let trimmed = self.trim_nurbs_tensor_profile(
                degree,
                &v_knots,
                &surface_points,
                &surface_weights,
                edge_use,
                pcurve,
                SurfaceIsoAxis::V,
            )?;
            let coefficient_offset = u_knots[u_degree].clone();
            let coefficient_scale = &u_knots[surface_points[0].len()] - &coefficient_offset;
            if real_slices_equal(&curve_knots, &trimmed.knots)? {
                match self.validate_nurbs_tensor_graph_controls(
                    degree,
                    &trimmed.knots,
                    &curve_points,
                    &curve_weights,
                    &trimmed.points,
                    &trimmed.weights,
                    edge_use,
                    pcurve,
                    &coefficient_scale,
                    &coefficient_offset,
                    SurfaceIsoAxis::V,
                ) {
                    Ok(()) => return Ok(()),
                    Err(BuildError::EdgeUseSupportMismatch) => {}
                    Err(error) => return Err(error),
                }
            }
        }
        if v_degree != 1
            || degree != u_degree
            || surface_points.len() != 2
            || surface_points
                .iter()
                .zip(&surface_weights)
                .any(|(points, weights)| points.is_empty() || points.len() != weights.len())
        {
            return Err(BuildError::EdgeUseSupportMismatch);
        }
        let Some((transposed_points, transposed_weights)) =
            transpose_two_row_tensor(&surface_points, &surface_weights)
        else {
            return Err(BuildError::EdgeUseSupportMismatch);
        };
        let trimmed = self.trim_nurbs_tensor_profile(
            degree,
            &u_knots,
            &transposed_points,
            &transposed_weights,
            edge_use,
            pcurve,
            SurfaceIsoAxis::U,
        )?;
        if !real_slices_equal(&curve_knots, &trimmed.knots)? {
            return Err(BuildError::EdgeUseSupportMismatch);
        }
        let coefficient_offset = v_knots[v_degree].clone();
        let coefficient_scale = &v_knots[surface_points.len()] - &coefficient_offset;
        self.validate_nurbs_tensor_graph_controls(
            degree,
            &trimmed.knots,
            &curve_points,
            &curve_weights,
            &trimmed.points,
            &trimmed.weights,
            edge_use,
            pcurve,
            &coefficient_scale,
            &coefficient_offset,
            SurfaceIsoAxis::U,
        )
    }

    pub(in crate::topology) fn validate_affine_tensor_parameter_image(
        &self,
        curve: &Curve3,
        edge_use: &EdgeUse,
        pcurve: &Pcurve,
        surface: &Surface,
    ) -> Result<bool, BuildError> {
        let Some(parameter_plane) = surface.affine_parameter_plane()? else {
            return Ok(false);
        };
        let Some((scale, offset)) = edge_use.parameter_correspondence.affine_coefficients() else {
            return Ok(false);
        };
        let origin = parameter_plane
            .plane_origin()
            .expect("affine parameter certificate is a plane");
        let (u, v) = parameter_plane
            .plane_directions()
            .expect("affine parameter certificate is a plane");
        let Some(expected) = crate::geometry::lift_curve_from_plane_frame_with_affine_parameter(
            pcurve.curve(),
            origin,
            u,
            v,
            scale,
            offset,
        )?
        else {
            return Ok(false);
        };
        curve_parameterizations_equal(curve, &expected)
    }

    pub(in crate::topology) fn tensor_graph_profile_interval(
        &self,
        edge_use: &EdgeUse,
        pcurve: &Pcurve,
        profile_axis: SurfaceIsoAxis,
    ) -> Result<(Real, Real), BuildError> {
        let oriented = match edge_use.direction {
            Direction::Forward => pcurve.clone(),
            Direction::Reversed => pcurve.reversed()?,
        };
        let start = oriented.curve().start();
        let end = oriented.curve().end();
        let (start, end) = match profile_axis {
            SurfaceIsoAxis::U => (
                (start)
                    .coordinates()
                    .ok_or(GeometryError::UnsupportedPcurveContour)?
                    .x(),
                (end)
                    .coordinates()
                    .ok_or(GeometryError::UnsupportedPcurveContour)?
                    .x(),
            ),
            SurfaceIsoAxis::V => (
                (start)
                    .coordinates()
                    .ok_or(GeometryError::UnsupportedPcurveContour)?
                    .y(),
                (end)
                    .coordinates()
                    .ok_or(GeometryError::UnsupportedPcurveContour)?
                    .y(),
            ),
        };
        if decided_model_order(compare_reals(start, end, crate::STRICT_PREDICATES))?
            != std::cmp::Ordering::Less
        {
            return Err(BuildError::EdgeUseSupportMismatch);
        }
        Ok((start.clone(), end.clone()))
    }

    pub(in crate::topology) fn trim_rational_tensor_profile(
        &self,
        surface_points: &[Vec<Point3>],
        surface_weights: &[Vec<Real>],
        edge_use: &EdgeUse,
        pcurve: &Pcurve,
        profile_axis: SurfaceIsoAxis,
    ) -> Result<TrimmedRationalTensorProfile, BuildError> {
        let (start, end) = self.tensor_graph_profile_interval(edge_use, pcurve, profile_axis)?;
        let profile = Curve3::rational_bezier(
            surface_points.iter().map(|row| row[0].clone()).collect(),
            surface_weights.iter().map(|row| row[0].clone()).collect(),
        )?
        .subcurve(&start, &end)?;
        let Curve3ExactData::RationalBezier {
            control_points,
            weights,
        } = profile.exact_data()
        else {
            return Err(BuildError::EdgeUseSupportMismatch);
        };
        let direction = &surface_points[0][1] - &surface_points[0][0];
        Ok(TrimmedRationalTensorProfile {
            points: translation_tensor_rows(&control_points, &direction),
            weights: duplicated_tensor_weights(&weights),
            start,
            end,
        })
    }

    #[allow(clippy::too_many_arguments)]
